// 25 preguntas por quiz, 4 quizzes por categoria

var EPA608_QUESTIONS = [

  // ── CORE (1-100) ──────────────────────────────────────────
  { id:"epa608_1", categoria:"EPA608_CORE", pregunta:"¿En qué capa de la atmósfera se encuentra la capa de ozono que protege contra la radiación ultravioleta?", opciones:["En la tropósfera terrestre","En la mesósfera terrestre","En la estratósfera terrestre","En la termósfera terrestre"], respuesta_correcta:2, explicacion:"La capa de ozono se encuentra en la estratósfera, aproximadamente entre 15 y 35 km de altitud, donde absorbe la radiación UV-B del sol." , question: "In which layer of the atmosphere is the ozone layer that protects against ultraviolet radiation located?", options: ["In the troposphere", "In the mesosphere", "In the stratosphere", "In the thermosphere"], explanation: "The ozone layer is located in the stratosphere, approximately between 15 and 35 km in altitude, where it absorbs UV-B radiation from the sun." },
  { id:"epa608_2", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de radiación ultravioleta es filtrada principalmente por la capa de ozono estratosférica?", opciones:["Radiación UV-A de onda larga","Radiación UV-B de onda media","Radiación UV-C de onda corta","Radiación infrarroja cercana"], respuesta_correcta:1, explicacion:"La capa de ozono filtra principalmente la radiación UV-B, que es la más dañina para los seres vivos y causa cáncer de piel y cataratas." , question: "What type of ultraviolet radiation is primarily filtered by the stratospheric ozone layer?", options: ["Long-wave UV-A radiation", "Medium-wave UV-B radiation", "Short-wave UV-C radiation", "Near-infrared radiation"], explanation: "The ozone layer primarily filters UV-B radiation, which is the most harmful to living organisms and causes skin cancer and cataracts." },
  { id:"epa608_3", categoria:"EPA608_CORE", pregunta:"¿Cuál es el elemento químico presente en los refrigerantes CFC y HCFC que destruye directamente el ozono?", opciones:["El cloro liberado por fotólisis","El flúor liberado por fotólisis","El bromo liberado por fotólisis","El carbono liberado por fotólisis"], respuesta_correcta:0, explicacion:"El cloro liberado cuando los CFC y HCFC se descomponen por radiación UV en la estratósfera es el que cataliza la destrucción del ozono." , question: "What chemical element present in CFC and HCFC refrigerants directly destroys ozone?", options: ["Chlorine released by photolysis", "Fluorine released by photolysis", "Bromine released by photolysis", "Carbon released by photolysis"], explanation: "Chlorine released when CFCs and HCFCs break down from UV radiation in the stratosphere is what catalyzes ozone destruction." },
  { id:"epa608_4", categoria:"EPA608_CORE", pregunta:"¿Cuántas moléculas de ozono puede destruir un solo átomo de cloro antes de desactivarse en la estratósfera?", opciones:["Aproximadamente 1,000 moléculas","Aproximadamente 10,000 moléculas","Aproximadamente 1,000,000 moléculas","Aproximadamente 100,000 moléculas"], respuesta_correcta:3, explicacion:"Un solo átomo de cloro puede destruir hasta 100,000 moléculas de ozono mediante una reacción catalítica en cadena en la estratósfera." , question: "How many ozone molecules can a single chlorine atom destroy before becoming deactivated in the stratosphere?", options: ["Approximately 1,000 molecules", "Approximately 10,000 molecules", "Approximately 1,000,000 molecules", "Approximately 100,000 molecules"], explanation: "A single chlorine atom can destroy up to 100,000 ozone molecules through a catalytic chain reaction in the stratosphere." },
  { id:"epa608_5", categoria:"EPA608_CORE", pregunta:"¿Qué familia de refrigerantes tiene el mayor Potencial de Agotamiento del Ozono (ODP) de las siguientes opciones?", opciones:["Los refrigerantes HCFC como R-22","Los refrigerantes HFC como R-410A","Los refrigerantes CFC como el R-12","Los refrigerantes HFO como R-1234yf"], respuesta_correcta:2, explicacion:"Los CFC como el R-12 tienen el ODP más alto (1.0) porque contienen solo cloro y flúor, sin hidrógeno que acelere su descomposición en la tropósfera." , question: "Which family of refrigerants has the highest Ozone Depletion Potential (ODP) among the following options?", options: ["HCFC refrigerants such as R-22", "HFC refrigerants such as R-410A", "CFC refrigerants such as R-12", "HFO refrigerants such as R-1234yf"], explanation: "CFCs such as R-12 have the highest ODP (1.0) because they contain only chlorine and fluorine, with no hydrogen to accelerate their breakdown in the troposphere." },
  { id:"epa608_6", categoria:"EPA608_CORE", pregunta:"¿Cuál es el Potencial de Agotamiento del Ozono (ODP) de los refrigerantes HFC como el R-134a y el R-410A?", opciones:["ODP de 0.05 (muy bajo pero presente)","ODP de 0.00 (completamente cero)","ODP de 0.50 (moderado comparado)","ODP de 1.00 (igual que los CFC)"], respuesta_correcta:1, explicacion:"Los HFC tienen ODP de cero porque no contienen cloro ni bromo en su molécula, por lo que no destruyen la capa de ozono." , question: "What is the Ozone Depletion Potential (ODP) of HFC refrigerants such as R-134a and R-410A?", options: ["ODP of 0.05 (very low but present)", "ODP of 0.00 (completely zero)", "ODP of 0.50 (moderate by comparison)", "ODP of 1.00 (equal to CFCs)"], explanation: "HFCs have an ODP of zero because they contain no chlorine or bromine in their molecule, so they do not destroy the ozone layer." },
  { id:"epa608_7", categoria:"EPA608_CORE", pregunta:"¿Qué tratado internacional estableció el calendario para eliminar gradualmente la producción de sustancias que agotan el ozono?", opciones:["El Acuerdo de París de 2015 sobre clima","El Protocolo de Kioto de 1997 mundial","El Protocolo de Montreal de 1987 global","La Convención de Basilea de 1989 ambiental"], respuesta_correcta:2, explicacion:"El Protocolo de Montreal de 1987 es el tratado que estableció el calendario de eliminación de CFC, HCFC y otras sustancias que agotan el ozono." , question: "What international treaty established the schedule for gradually phasing out the production of ozone-depleting substances?", options: ["The Paris Agreement of 2015 on climate", "The Kyoto Protocol of 1997", "The Montreal Protocol of 1987", "The Basel Convention of 1989 on the environment"], explanation: "The Montreal Protocol of 1987 is the treaty that established the phase-out schedule for CFCs, HCFCs, and other ozone-depleting substances." },
  { id:"epa608_8", categoria:"EPA608_CORE", pregunta:"¿Qué enmienda al Protocolo de Montreal aborda la reducción gradual de refrigerantes HFC por su alto GWP?", opciones:["La Enmienda de Kigali del año 2016","La Enmienda de Copenhague del 1992","La Enmienda de Beijing del año 1999","La Enmienda de Londres del año 1990"], respuesta_correcta:0, explicacion:"La Enmienda de Kigali (2016) al Protocolo de Montreal establece la reducción gradual de los HFC debido a su alto potencial de calentamiento global (GWP)." , question: "What amendment to the Montreal Protocol addresses the gradual reduction of HFC refrigerants due to their high GWP?", options: ["The Kigali Amendment of 2016", "The Copenhagen Amendment of 1992", "The Beijing Amendment of 1999", "The London Amendment of 1990"], explanation: "The Kigali Amendment (2016) to the Montreal Protocol establishes the gradual phase-down of HFCs due to their high Global Warming Potential (GWP)." },
  { id:"epa608_9", categoria:"EPA608_CORE", pregunta:"¿En qué año se prohibió completamente la producción de refrigerantes CFC en los Estados Unidos según regulaciones?", opciones:["Se prohibió en el año de 1992","Se prohibió en el año de 2000","Se prohibió en el año de 2010","Se prohibió en el año de 1996"], respuesta_correcta:3, explicacion:"La producción e importación de CFC fue prohibida en EE.UU. a partir del 1 de enero de 1996, aunque su uso en equipos existentes sigue siendo legal." , question: "In what year was the production of CFC refrigerants completely banned in the United States according to regulations?", options: ["It was banned in 1992", "It was banned in 2000", "It was banned in 2010", "It was banned in 1996"], explanation: "The production and import of CFCs was banned in the U.S. as of January 1, 1996, although their use in existing equipment remains legal." },
  { id:"epa608_10", categoria:"EPA608_CORE", pregunta:"¿En qué año se completó la prohibición total de producción de refrigerantes HCFC como el R-22 en EE.UU.?", opciones:["Fue prohibido completamente en 2020","Será prohibido completamente en 2025","Fue prohibido completamente en 2030","Fue prohibido completamente en 2015"], respuesta_correcta:0, explicacion:"La producción e importación de R-22 y otros HCFC fue prohibida completamente el 1 de enero de 2020, aunque el refrigerante reciclado/reclamado aún se puede usar." , question: "In what year was the total production ban on HCFC refrigerants such as R-22 completed in the U.S.?", options: ["It was completely banned in 2020", "It will be completely banned in 2025", "It was completely banned in 2030", "It was completely banned in 2015"], explanation: "The production and import of R-22 and other HCFCs was completely banned on January 1, 2020, although recycled/reclaimed refrigerant can still be used." },
  { id:"epa608_11", categoria:"EPA608_CORE", pregunta:"¿Qué sección del Clean Air Act (Ley de Aire Limpio) de EE.UU. regula el manejo de refrigerantes y sustancias ODS?", opciones:["La Sección 606 del Clean Air Act","La Sección 610 del Clean Air Act","La Sección 612 del Clean Air Act","La Sección 608 del Clean Air Act"], respuesta_correcta:3, explicacion:"La Sección 608 del Clean Air Act regula las prácticas de refrigerantes, incluyendo recuperación, reciclaje, certificación de técnicos y prohibición de venteo." , question: "What section of the U.S. Clean Air Act regulates the handling of refrigerants and ODS substances?", options: ["Section 606 of the Clean Air Act", "Section 610 of the Clean Air Act", "Section 612 of the Clean Air Act", "Section 608 of the Clean Air Act"], explanation: "Section 608 of the Clean Air Act regulates refrigerant practices, including recovery, recycling, technician certification, and the prohibition of venting." },
  { id:"epa608_12", categoria:"EPA608_CORE", pregunta:"¿Cuál es la multa máxima por día por violar las regulaciones de la Sección 608 del Clean Air Act vigentes?", opciones:["Hasta $27,500 dólares por cada violación","Hasta $44,539 dólares por cada violación","Hasta $37,500 dólares por cada violación","Hasta $55,000 dólares por cada violación"], respuesta_correcta:1, explicacion:"La multa máxima actualizada por la EPA es de hasta $44,539 por día por cada violación a las regulaciones de la Sección 608." , question: "What is the maximum fine per day for violating current Section 608 regulations of the Clean Air Act?", options: ["Up to $27,500 per violation", "Up to $44,539 per violation", "Up to $37,500 per violation", "Up to $55,000 per violation"], explanation: "The EPA's updated maximum fine is up to $44,539 per day per violation of Section 608 regulations." },
  { id:"epa608_13", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de refrigerante es el R-22 según la clasificación de familias químicas de refrigerantes?", opciones:["Es un refrigerante tipo CFC clorofluorocarbono","Es un refrigerante tipo HFC hidrofluorocarbono puro","Es un refrigerante tipo HCFC hidroclorofluorocarbono","Es un refrigerante tipo HFO hidrofluoroolefina nueva"], respuesta_correcta:2, explicacion:"El R-22 es un HCFC (hidroclorofluorocarbono) que contiene hidrógeno, cloro, flúor y carbono. Tiene ODP reducido pero no cero." , question: "What type of refrigerant is R-22 according to the chemical family classification of refrigerants?", options: ["It is a CFC (chlorofluorocarbon) refrigerant", "It is a pure HFC (hydrofluorocarbon) refrigerant", "It is an HCFC (hydrochlorofluorocarbon) refrigerant", "It is a new HFO (hydrofluoroolefin) refrigerant"], explanation: "R-22 is an HCFC (hydrochlorofluorocarbon) that contains hydrogen, chlorine, fluorine, and carbon. It has a reduced ODP but not zero." },
  { id:"epa608_14", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de refrigerante es el R-410A según su clasificación química y composición molecular?", opciones:["Es una mezcla zeotrópica de tipo HFC","Es una mezcla azeotrópica de tipo HCFC","Es un refrigerante puro de familia CFC","Es una mezcla azeotrópica de familia HFO"], respuesta_correcta:0, explicacion:"El R-410A es una mezcla casi-azeotrópica de dos HFC (R-32 y R-125), por lo que no contiene cloro y tiene ODP de cero." , question: "What type of refrigerant is R-410A according to its chemical classification and molecular composition?", options: ["It is a near-azeotropic HFC blend", "It is an azeotropic HCFC blend", "It is a pure CFC refrigerant", "It is an azeotropic HFO blend"], explanation: "R-410A is a near-azeotropic blend of two HFCs (R-32 and R-125), so it contains no chlorine and has an ODP of zero." },
  { id:"epa608_15", categoria:"EPA608_CORE", pregunta:"¿Cuál es la principal ventaja ambiental de los refrigerantes HFO como el R-1234yf sobre los HFC tradicionales?", opciones:["Tienen mayor eficiencia energética en sistemas","Tienen un ODP más bajo que cualquier HFC","Tienen menor presión de operación en sistemas","Tienen un GWP extremadamente bajo cercano a 1"], respuesta_correcta:3, explicacion:"Los HFO tienen un GWP extremadamente bajo (R-1234yf tiene GWP de 4 vs. R-134a con GWP de 1,430), lo que reduce significativamente el impacto en el calentamiento global." , question: "What is the main environmental advantage of HFO refrigerants such as R-1234yf over traditional HFCs?", options: ["They have higher energy efficiency in systems", "They have a lower ODP than any HFC", "They have lower operating pressure in systems", "They have an extremely low GWP close to 1"], explanation: "HFOs have an extremely low GWP (R-1234yf has a GWP of 4 vs. R-134a with a GWP of 1,430), which significantly reduces the impact on global warming." },
  { id:"epa608_16", categoria:"EPA608_CORE", pregunta:"¿Qué significa la clasificación ASHRAE A1 aplicada a un refrigerante en términos de seguridad?", opciones:["Alta toxicidad y alta inflamabilidad peligrosa","Baja toxicidad y sin propagación de llama","Alta toxicidad y sin propagación de llama","Baja toxicidad y baja inflamabilidad menor"], respuesta_correcta:1, explicacion:"En la clasificación ASHRAE 34, 'A' significa baja toxicidad y '1' significa sin propagación de llama. Ejemplos: R-22, R-134a, R-410A." , question: "What does the ASHRAE A1 safety classification applied to a refrigerant mean in terms of safety?", options: ["High toxicity and high flammability", "Low toxicity and no flame propagation", "High toxicity and no flame propagation", "Low toxicity and lower flammability"], explanation: "In the ASHRAE 34 classification, 'A' means low toxicity and '1' means no flame propagation. Examples: R-22, R-134a, R-410A." },
  { id:"epa608_17", categoria:"EPA608_CORE", pregunta:"¿Qué clasificación de seguridad ASHRAE tienen los refrigerantes denominados como 'ligeramente inflamables' o A2L?", opciones:["Son de alta toxicidad y baja inflamabilidad","Son de baja toxicidad con alta inflamabilidad","Son de alta toxicidad sin propagación de llama","Son de baja toxicidad con inflamabilidad menor"], respuesta_correcta:3, explicacion:"A2L indica baja toxicidad (A) con inflamabilidad menor (2L = lower flammability). Ejemplos incluyen R-32 y R-1234yf." , question: "What ASHRAE safety classification do refrigerants designated as 'mildly flammable' or A2L have?", options: ["High toxicity and low flammability", "Low toxicity with high flammability", "High toxicity with no flame propagation", "Low toxicity with lower flammability"], explanation: "A2L indicates low toxicity (A) with lower flammability (2L = lower flammability). Examples include R-32 and R-1234yf." },
  { id:"epa608_18", categoria:"EPA608_CORE", pregunta:"¿Qué clasificación ASHRAE tienen los hidrocarburos refrigerantes como el propano R-290 y el isobutano R-600a?", opciones:["Clasificación A3 — baja toxicidad muy inflamable","Clasificación A1 — sin propagación de llama","Clasificación A2L — baja inflamabilidad menor","Clasificación B2 — toxicidad alta inflamable"], respuesta_correcta:0, explicacion:"Los hidrocarburos como R-290 (propano) y R-600a (isobutano) son clasificados A3: baja toxicidad pero altamente inflamables." , question: "What ASHRAE classification do hydrocarbon refrigerants such as propane R-290 and isobutane R-600a have?", options: ["Classification A3 — low toxicity, highly flammable", "Classification A1 — no flame propagation", "Classification A2L — lower flammability", "Classification B2 — high toxicity, flammable"], explanation: "Hydrocarbons such as R-290 (propane) and R-600a (isobutane) are classified A3: low toxicity but highly flammable." },
  { id:"epa608_19", categoria:"EPA608_CORE", pregunta:"¿Cuál es la diferencia principal entre RECUPERAR y RECICLAR refrigerante según la EPA?", opciones:["Recuperar es limpiar in situ; reciclar es enviar a un reclamador certificado tercero","Recuperar es destruir el refrigerante; reciclar es purificarlo a estándar ARI 700 puro","Recuperar es extraer y almacenar; reciclar es limpiar para reutilizar in situ mismo","Recuperar es ventear lo contaminado; reciclar es guardarlo en cilindro de recuperación"], respuesta_correcta:2, explicacion:"Recuperar significa extraer refrigerante y almacenarlo en un contenedor externo. Reciclar significa limpiarlo (filtrar, deshidratar) para reutilizarlo, generalmente in situ." , question: "What is the main difference between RECOVERING and RECYCLING refrigerant according to the EPA?", options: ["Recovery is cleaning on-site; recycling is sending to a certified third-party reclaimer", "Recovery is destroying the refrigerant; recycling is purifying it to ARI 700 standards", "Recovery is extracting and storing; recycling is cleaning for on-site reuse", "Recovery is venting contaminated refrigerant; recycling is storing it in a recovery cylinder"], explanation: "Recovery means extracting refrigerant and storing it in an external container. Recycling means cleaning it (filtering, dehydrating) for reuse, generally on-site." },
  { id:"epa608_20", categoria:"EPA608_CORE", pregunta:"¿Qué proceso devuelve el refrigerante usado a las especificaciones del estándar ARI 700 de pureza nueva?", opciones:["El proceso de recuperación en campo abierto","El proceso de reciclaje en sitio de trabajo","El proceso de regeneración en taller de servicio","El proceso de reclamación en planta certificada"], respuesta_correcta:3, explicacion:"La reclamación (reclaim) se realiza en instalaciones certificadas por la EPA y devuelve el refrigerante a las especificaciones de pureza ARI 700, equivalente a nuevo." , question: "What process returns used refrigerant to the purity specifications of the ARI 700 standard, equivalent to new?", options: ["The field recovery process", "The on-site recycling process", "The shop regeneration process", "The reclamation process at a certified facility"], explanation: "Reclamation is performed at EPA-certified facilities and returns the refrigerant to ARI 700 purity specifications, equivalent to virgin refrigerant." },
  { id:"epa608_21", categoria:"EPA608_CORE", pregunta:"¿Qué estándar establece las especificaciones de pureza que debe cumplir un refrigerante reclamado?", opciones:["El estándar ARI 700 de pureza de refrigerante","El estándar EPA 608 de certificación técnica","El estándar ASHRAE 34 de seguridad química","El estándar DOT 39 de cilindros de transporte"], respuesta_correcta:0, explicacion:"El estándar ARI 700 (ahora AHRI 700) especifica los niveles de pureza, humedad y contaminantes permitidos para refrigerante reclamado." , question: "What standard establishes the purity specifications that reclaimed refrigerant must meet?", options: ["The ARI 700 refrigerant purity standard", "The EPA 608 technician certification standard", "The ASHRAE 34 chemical safety standard", "The DOT 39 transport cylinder standard"], explanation: "The ARI 700 standard (now AHRI 700) specifies the allowable levels of purity, moisture, and contaminants for reclaimed refrigerant." },
  { id:"epa608_22", categoria:"EPA608_CORE", pregunta:"¿Está permitido ventear intencionalmente refrigerantes CFC, HCFC o HFC a la atmósfera según la EPA?", opciones:["Sí, solo si son cantidades menores a 2 libras de refrigerante total","No, está prohibido ventear cualquier cantidad de estos refrigerantes","Sí, solo durante el proceso de reparación de emergencia del sistema","No, excepto si se tiene un permiso especial emitido por la EPA local"], respuesta_correcta:1, explicacion:"La Sección 608 prohíbe ventear intencionalmente refrigerantes. Solo se permite la liberación de-minimis (mínima) que ocurre durante conexiones/desconexiones normales." , question: "Is it legal to intentionally vent CFC, HCFC, or HFC refrigerants to the atmosphere according to the EPA?", options: ["Yes, only if the amounts are less than 2 pounds total", "No, it is prohibited to vent any quantity of these refrigerants", "Yes, only during an emergency system repair", "No, unless a special permit is issued by the local EPA office"], explanation: "Section 608 prohibits intentionally venting refrigerants. Only de minimis releases that occur during normal connections/disconnections are permitted." },
  { id:"epa608_23", categoria:"EPA608_CORE", pregunta:"¿Cuál de los siguientes refrigerantes SÍ puede ventearse legalmente según las excepciones de la EPA?", opciones:["El R-22 en cantidades menores a 5 libras","El R-410A en cantidades menores a 2 libras","Sustitutos aprobados sin ODP como ciertos HFO","El R-134a durante reparaciones de emergencia"], respuesta_correcta:2, explicacion:"Algunos sustitutos con ODP y GWP muy bajos están exentos de la prohibición de venteo, pero CFC, HCFC y la mayoría de HFC nunca pueden ventearse intencionalmente." , question: "Which of the following refrigerants CAN be legally vented according to EPA exceptions?", options: ["R-22 in quantities less than 5 pounds", "R-410A in quantities less than 2 pounds", "Approved substitutes with no ODP such as certain HFOs", "R-134a during emergency repairs"], explanation: "Some substitutes with very low ODP and GWP are exempt from the venting prohibition, but CFCs, HCFCs, and most HFCs can never be intentionally vented." },
  { id:"epa608_24", categoria:"EPA608_CORE", pregunta:"¿Qué es una liberación 'de minimis' de refrigerante según las regulaciones de la Sección 608?", opciones:["Es una fuga detectada que no supera el 10% de la carga total anual","Es una ventilación autorizada cuando la presión supera los 400 psi","Es una cantidad mínima e inevitable al conectar o desconectar mangueras","Es una liberación permitida durante la recuperación si es menor a 1 libra"], respuesta_correcta:2, explicacion:"La liberación de-minimis es la cantidad pequeña e inevitable que escapa al hacer o deshacer conexiones de servicio. No se considera venteo intencional." , question: "What is a 'de minimis' release of refrigerant according to Section 608 regulations?", options: ["A detected leak that does not exceed 10% of the total annual charge", "An authorized vent when pressure exceeds 400 psi", "A minimal and unavoidable amount that escapes when connecting or disconnecting hoses", "A permitted release during recovery if it is less than 1 pound"], explanation: "A de minimis release is the small, unavoidable amount that escapes when making or breaking service connections. It is not considered intentional venting." },
  { id:"epa608_25", categoria:"EPA608_CORE", pregunta:"¿Qué método de detección de fugas utiliza un tinte fluorescente que se añade al sistema de refrigeración?", opciones:["El detector electrónico de fugas por sensor","La prueba de burbujas con agua jabonosa","El método de presurización con nitrógeno seco","El método de tinte ultravioleta con lámpara"], respuesta_correcta:3, explicacion:"El método de tinte UV consiste en agregar un tinte fluorescente al sistema y usar una lámpara ultravioleta para detectar el punto exacto de la fuga." , question: "What leak detection method uses a fluorescent dye that is added to the refrigeration system?", options: ["An electronic leak detector with sensor", "A bubble test with soapy water", "The pressurization method with dry nitrogen", "The ultraviolet dye method with a UV lamp"], explanation: "The UV dye method involves adding a fluorescent dye to the system and using an ultraviolet lamp to detect the exact location of the leak." },
  { id:"epa608_26", categoria:"EPA608_CORE", pregunta:"¿Cuál es el método más sensible para detectar fugas pequeñas de refrigerante en un sistema de A/C?", opciones:["El uso de un detector electrónico de fugas","La aplicación de agua jabonosa en uniones","La inspección visual de manchas de aceite","La prueba de presión con nitrógeno a 150 psi"], respuesta_correcta:0, explicacion:"Los detectores electrónicos de fugas son los más sensibles y pueden detectar fugas tan pequeñas como 0.1 onzas por año en algunos modelos." , question: "What is the most sensitive method for detecting small refrigerant leaks in an A/C system?", options: ["Using an electronic leak detector", "Applying soapy water to joints", "Visual inspection for oil stains", "A pressure test with nitrogen at 150 psi"], explanation: "Electronic leak detectors are the most sensitive and can detect leaks as small as 0.1 ounces per year in some models." },
  { id:"epa608_27", categoria:"EPA608_CORE", pregunta:"¿Qué gas se debe utilizar para presurizar un sistema de refrigeración al hacer una prueba de fugas?", opciones:["Oxígeno comprimido de grado industrial","Dióxido de carbono de grado alimenticio","Aire comprimido del taller de servicio","Nitrógeno seco libre de toda humedad"], respuesta_correcta:3, explicacion:"Solo se debe usar nitrógeno seco (libre de humedad) para pruebas de presión. NUNCA usar oxígeno, ya que puede causar una explosión violenta con el aceite." , question: "What gas should be used to pressurize a refrigeration system when performing a leak test?", options: ["Industrial-grade compressed oxygen", "Food-grade carbon dioxide", "Shop compressed air", "Dry nitrogen free of all moisture"], explanation: "Only dry nitrogen (moisture-free) should be used for pressure testing. NEVER use oxygen, as it can cause a violent explosion when mixed with oil." },
  { id:"epa608_28", categoria:"EPA608_CORE", pregunta:"¿Por qué NUNCA se debe usar oxígeno para presurizar un sistema de refrigeración durante una prueba?", opciones:["Porque el oxígeno puede explotar violentamente al mezclarse con aceite comprimido","Porque el oxígeno reacciona con el cobre formando óxido que obstruye tuberías","Porque el oxígeno contamina el refrigerante y reduce la eficiencia del sistema","Porque el oxígeno daña las juntas de goma y los sellos mecánicos del compresor"], respuesta_correcta:0, explicacion:"El oxígeno bajo presión mezclado con aceite refrigerante puede causar una explosión violenta. Por eso solo se usa nitrógeno seco para presurizar." , question: "Why should oxygen NEVER be used to pressurize a refrigeration system during a pressure test?", options: ["Because oxygen can violently explode when mixed with compressed oil", "Because oxygen reacts with copper forming oxide that clogs piping", "Because oxygen contaminates the refrigerant and reduces system efficiency", "Because oxygen damages rubber gaskets and mechanical seals in the compressor"], explanation: "Oxygen under pressure mixed with refrigerant oil can cause a violent explosion. That is why only dry nitrogen is used for pressurization." },
  { id:"epa608_29", categoria:"EPA608_CORE", pregunta:"¿A qué nivel de vacío se debe evacuar un sistema de refrigeración antes de cargar refrigerante nuevo?", opciones:["A un vacío de 1,000 micrones como mínimo","A un vacío de 500 micrones como mínimo ideal","A un vacío de 250 micrones como mínimo exacto","A un vacío de 100 micrones como mínimo posible"], respuesta_correcta:1, explicacion:"El estándar de la industria es evacuar a 500 micrones o menos para asegurar la eliminación de humedad y gases no condensables del sistema." , question: "To what vacuum level should a refrigeration system be evacuated before charging with new refrigerant?", options: ["To a vacuum of 1,000 microns minimum", "To a vacuum of 500 microns minimum as the ideal standard", "To a vacuum of exactly 250 microns minimum", "To a vacuum of 100 microns minimum"], explanation: "The industry standard is to evacuate to 500 microns or less to ensure the removal of moisture and non-condensable gases from the system." },
  { id:"epa608_30", categoria:"EPA608_CORE", pregunta:"Durante la evacuación, si el vacío sube rápidamente al apagar la bomba, ¿qué indica esta condición?", opciones:["Indica presencia de humedad residual en el sistema de refrigeración interno","Indica que la bomba de vacío necesita cambio de aceite de inmediato ya","Indica una fuga activa en el sistema que permite entrada de aire exterior","Indica que los gases no condensables están saliendo correctamente del sistema"], respuesta_correcta:2, explicacion:"Si el vacío sube rápidamente (presión aumenta rápido) al apagar la bomba, indica una fuga. Si sube lentamente y se estabiliza, indica humedad residual." , question: "During evacuation, if the vacuum rises rapidly when the pump is turned off, what does this condition indicate?", options: ["It indicates the presence of residual moisture inside the refrigeration system", "It indicates the vacuum pump needs an immediate oil change", "It indicates an active leak in the system allowing outside air to enter", "It indicates that non-condensable gases are exiting the system correctly"], explanation: "If the vacuum rises rapidly (pressure increases quickly) when the pump is turned off, it indicates a leak. If it rises slowly and stabilizes, it indicates residual moisture." },
  { id:"epa608_31", categoria:"EPA608_CORE", pregunta:"Durante la evacuación, si el vacío sube lentamente y luego se estabiliza, ¿qué indica este comportamiento?", opciones:["Indica que existe una fuga grande en alguna conexión","Indica presencia de humedad evaporándose dentro del sistema","Indica que la bomba de vacío está funcionando defectuosamente","Indica que los manómetros están descalibrados incorrectamente"], respuesta_correcta:1, explicacion:"Un aumento lento del vacío que se estabiliza indica humedad residual evaporándose. Se debe continuar la evacuación hasta que mantenga 500 micrones." , question: "During evacuation, if the vacuum rises slowly and then stabilizes, what does this behavior indicate?", options: ["It indicates a large leak at a connection", "It indicates the presence of moisture evaporating inside the system", "It indicates the vacuum pump is malfunctioning", "It indicates the gauges are improperly calibrated"], explanation: "A slow vacuum rise that stabilizes indicates residual moisture evaporating. Evacuation should continue until it holds at 500 microns." },
  { id:"epa608_32", categoria:"EPA608_CORE", pregunta:"¿Cuál es el propósito principal de una evacuación triple (triple evacuación) en un sistema de refrigeración?", opciones:["Verificar tres veces que no existan fugas activas en las conexiones del sistema","Limpiar el sistema de aceite contaminado mediante tres ciclos de vacío profundo","Calibrar la bomba de vacío en tres etapas antes de cargar el refrigerante nuevo","Remover humedad atrapada rompiendo vacío con nitrógeno entre cada evacuación"], respuesta_correcta:3, explicacion:"La triple evacuación usa nitrógeno seco para romper el vacío entre ciclos, lo que ayuda a liberar y remover humedad atrapada más efectivamente." , question: "What is the main purpose of a triple evacuation on a refrigeration system?", options: ["To verify three times that no active leaks exist at the system connections", "To clean the system of contaminated oil through three deep vacuum cycles", "To calibrate the vacuum pump in three stages before charging new refrigerant", "To remove trapped moisture by breaking the vacuum with nitrogen between each evacuation"], explanation: "The triple evacuation uses dry nitrogen to break the vacuum between cycles, which helps release and remove trapped moisture more effectively." },
  { id:"epa608_33", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de aceite refrigerante es compatible con los refrigerantes HFC como R-134a y R-410A?", opciones:["Aceite mineral convencional de refrigeración","Aceite polioléster sintético conocido como POE","Aceite alquilbenceno sintético de base AB","Aceite nafténico de base parafínica de grado"], respuesta_correcta:1, explicacion:"Los refrigerantes HFC requieren aceite POE (polioléster) porque no son miscibles con aceite mineral. El POE es higroscópico y absorbe humedad rápidamente." , question: "What type of refrigerant oil is compatible with HFC refrigerants such as R-134a and R-410A?", options: ["Conventional mineral oil for refrigeration", "Polyol ester (POE) synthetic oil", "Alkylbenzene (AB) synthetic oil", "Naphthenic paraffinic-base oil"], explanation: "HFC refrigerants require POE (polyol ester) oil because they are not miscible with mineral oil. POE is hygroscopic and absorbs moisture rapidly." },
  { id:"epa608_34", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de aceite se usaba tradicionalmente con refrigerantes CFC y HCFC como R-12 y R-22?", opciones:["Aceite mineral convencional de refrigeración","Aceite polioléster sintético de tipo POE","Aceite polialquilenglicol de tipo PAG","Aceite polivinil éter de tipo PVE sintético"], respuesta_correcta:0, explicacion:"Los refrigerantes CFC y HCFC son miscibles con aceite mineral. Al cambiar a HFC se debe cambiar también a aceite POE por compatibilidad." , question: "What type of oil was traditionally used with CFC and HCFC refrigerants such as R-12 and R-22?", options: ["Conventional mineral oil for refrigeration", "Polyol ester (POE) synthetic oil", "Polyalkylene glycol (PAG) oil", "Polyvinyl ether (PVE) synthetic oil"], explanation: "CFC and HCFC refrigerants are miscible with mineral oil. When switching to HFCs, the oil must also be changed to POE for compatibility." },
  { id:"epa608_35", categoria:"EPA608_CORE", pregunta:"¿Por qué es importante que el aceite POE no se exponga al aire ambiente durante mucho tiempo?", opciones:["Porque se oxida rápidamente perdiendo sus propiedades lubricantes esenciales","Porque es altamente inflamable y puede encenderse con el aire del ambiente","Porque reacciona con el nitrógeno del aire formando compuestos que son ácidos","Porque es higroscópico y absorbe humedad del aire de forma muy rápida"], respuesta_correcta:3, explicacion:"El aceite POE es extremadamente higroscópico — absorbe humedad del aire rápidamente. La humedad en el sistema causa ácidos que dañan el compresor." , question: "Why is it important that POE oil not be exposed to ambient air for an extended period?", options: ["Because it oxidizes rapidly, losing its essential lubricating properties", "Because it is highly flammable and can ignite with ambient air", "Because it reacts with nitrogen in the air forming acidic compounds", "Because it is hygroscopic and absorbs moisture from the air very rapidly"], explanation: "POE oil is extremely hygroscopic — it absorbs moisture from the air rapidly. Moisture in the system creates acids that damage the compressor." },
  { id:"epa608_36", categoria:"EPA608_CORE", pregunta:"¿Qué es el sobrecalentamiento (superheat) en un sistema de refrigeración básico?", opciones:["La temperatura del refrigerante líquido por encima de su punto de ebullición a esa presión","La temperatura del refrigerante gaseoso por encima de su punto de ebullición a esa presión","La temperatura del refrigerante líquido por debajo de su punto de condensación a esa presión","La temperatura del refrigerante gaseoso por debajo de su punto de condensación a esa presión"], respuesta_correcta:1, explicacion:"El superheat es la diferencia entre la temperatura del gas refrigerante y su temperatura de saturación (ebullición) a la presión medida en la succión." , question: "What is superheat in a basic refrigeration system?", options: ["The temperature of liquid refrigerant above its boiling point at that pressure", "The temperature of gaseous refrigerant above its boiling point at that pressure", "The temperature of liquid refrigerant below its condensation point at that pressure", "The temperature of gaseous refrigerant below its condensation point at that pressure"], explanation: "Superheat is the difference between the temperature of the refrigerant gas and its saturation (boiling) temperature at the measured suction pressure." },
  { id:"epa608_37", categoria:"EPA608_CORE", pregunta:"¿Qué es el subenfriamiento (subcooling) en un sistema de refrigeración?", opciones:["La temperatura del líquido por debajo de su punto de condensación a presión de descarga","La temperatura del vapor por encima de su punto de condensación a presión de descarga","La temperatura del líquido por encima de su punto de ebullición a presión de succión","La temperatura del vapor por debajo de su punto de ebullición a presión de succión dada"], respuesta_correcta:0, explicacion:"El subcooling es la diferencia entre la temperatura de condensación (saturación) y la temperatura real del líquido en la línea de líquido." , question: "What is subcooling in a refrigeration system?", options: ["The temperature of the liquid below its condensation point at discharge pressure", "The temperature of the vapor above its condensation point at discharge pressure", "The temperature of the liquid above its boiling point at suction pressure", "The temperature of the vapor below its boiling point at suction pressure"], explanation: "Subcooling is the difference between the condensing (saturation) temperature and the actual liquid temperature in the liquid line." },
  { id:"epa608_38", categoria:"EPA608_CORE", pregunta:"¿Qué indica un sobrecalentamiento excesivamente alto en la línea de succión de un sistema?", opciones:["El sistema tiene una sobrecarga de refrigerante en el circuito completo","La válvula de expansión está sobrealimentando el evaporador con líquido","El condensador tiene un flujo de aire bloqueado o ventilador defectuoso","El evaporador no está recibiendo suficiente refrigerante líquido actual"], respuesta_correcta:3, explicacion:"Un superheat alto indica que el evaporador está 'hambriento' de refrigerante — puede ser por baja carga, restricción, o válvula de expansión subdimensionada." , question: "What does excessively high superheat on the suction line of a system indicate?", options: ["The system has an overcharge of refrigerant in the complete circuit", "The expansion valve is overfeeding the evaporator with liquid", "The condenser has a blocked airflow or a defective fan", "The evaporator is not receiving enough liquid refrigerant"], explanation: "High superheat indicates the evaporator is 'starved' of refrigerant — it may be due to low charge, a restriction, or an undersized expansion valve." },
  { id:"epa608_39", categoria:"EPA608_CORE", pregunta:"¿Qué color tiene la manguera del lado de baja presión en un juego de manómetros manifold estándar?", opciones:["La manguera de baja presión es de color rojo","La manguera de baja presión es de color azul","La manguera de baja presión es color amarillo","La manguera de baja presión es de color verde"], respuesta_correcta:1, explicacion:"En un juego de manómetros manifold estándar: azul = lado de baja (succión/compuesto), rojo = lado de alta (descarga), amarillo = centro (servicio)." , question: "What color is the low-pressure side hose on a standard manifold gauge set?", options: ["The low-pressure hose is red", "The low-pressure hose is blue", "The low-pressure hose is yellow", "The low-pressure hose is green"], explanation: "On a standard manifold gauge set: blue = low side (suction/compound), red = high side (discharge), yellow = center (service)." },
  { id:"epa608_40", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de manómetro se usa en el lado de baja presión que puede leer presión y vacío?", opciones:["Un manómetro de alta presión tipo Bourdon","Un manómetro diferencial de doble escala","Un manómetro compuesto de baja presión","Un manómetro absoluto de presión barométrica"], respuesta_correcta:2, explicacion:"El manómetro compuesto (compound gauge) del lado de baja puede medir tanto presión positiva como vacío, por eso se llama compuesto." , question: "What type of gauge is used on the low-pressure side that can read both pressure and vacuum?", options: ["A Bourdon-type high-pressure gauge", "A dual-scale differential gauge", "A compound low-pressure gauge", "An absolute barometric pressure gauge"], explanation: "The compound gauge on the low side can measure both positive pressure and vacuum, which is why it is called a compound gauge." },
  { id:"epa608_41", categoria:"EPA608_CORE", pregunta:"¿Qué equipo de protección respiratoria se debe usar en un espacio confinado con fuga de refrigerante?", opciones:["Una mascarilla N95 contra partículas finas de aceite","Un respirador con filtro de carbón activado para vapores","Una mascarilla quirúrgica con doble capa de protección","Un aparato de respiración autónomo tipo SCBA completo"], respuesta_correcta:3, explicacion:"En espacios confinados con fuga de refrigerante se requiere SCBA (Self-Contained Breathing Apparatus) porque los refrigerantes desplazan el oxígeno." , question: "What respiratory protection equipment should be used in a confined space with a refrigerant leak?", options: ["An N95 particulate mask for fine oil particles", "A respirator with an activated carbon filter for vapors", "A double-layer surgical mask", "A self-contained breathing apparatus (SCBA)"], explanation: "In confined spaces with a refrigerant leak, an SCBA (Self-Contained Breathing Apparatus) is required because refrigerants displace oxygen." },
  { id:"epa608_42", categoria:"EPA608_CORE", pregunta:"¿Por qué los refrigerantes son peligrosos en espacios confinados o cerrados sin ventilación adecuada?", opciones:["Porque desplazan el oxígeno del aire causando asfixia sin señales previas claras","Porque son altamente tóxicos al ser inhalados en cualquier concentración posible","Porque son extremadamente inflamables y pueden generar una explosión violenta","Porque reaccionan con la humedad del aire formando un ácido corrosivo letal"], respuesta_correcta:0, explicacion:"Los refrigerantes son más pesados que el aire, se acumulan en zonas bajas y desplazan el oxígeno, causando asfixia sin que la persona lo perciba." , question: "Why are refrigerants dangerous in confined or enclosed spaces without adequate ventilation?", options: ["Because they displace oxygen in the air, causing asphyxiation without clear warning signs", "Because they are highly toxic when inhaled at any concentration", "Because they are extremely flammable and can cause a violent explosion", "Because they react with moisture in the air forming a lethal corrosive acid"], explanation: "Refrigerants are heavier than air, accumulate in low areas, and displace oxygen, causing asphyxiation without the person noticing." },
  { id:"epa608_43", categoria:"EPA608_CORE", pregunta:"¿Qué ácido peligroso se forma cuando un refrigerante halogenado se expone a una llama abierta?", opciones:["Ácido sulfúrico por descomposición térmica","Ácido carbónico por oxidación del carbono","Ácido clorhídrico y ácido fluorhídrico","Ácido nítrico por reacción con nitrógeno"], respuesta_correcta:2, explicacion:"Cuando refrigerantes halogenados se descomponen por calor de una llama, forman ácido clorhídrico (HCl) y ácido fluorhídrico (HF), ambos muy peligrosos." , question: "What dangerous acid is formed when a halogenated refrigerant is exposed to an open flame?", options: ["Sulfuric acid from thermal decomposition", "Carbonic acid from carbon oxidation", "Hydrochloric acid and hydrofluoric acid", "Nitric acid from reaction with nitrogen"], explanation: "When halogenated refrigerants decompose from the heat of a flame, they form hydrochloric acid (HCl) and hydrofluoric acid (HF), both very dangerous." },
  { id:"epa608_44", categoria:"EPA608_CORE", pregunta:"¿Qué lesión puede causar el contacto directo del refrigerante líquido con la piel humana?", opciones:["Quemaduras químicas severas por la acidez del refrigerante líquido","Quemaduras por congelamiento debido a la rápida evaporación del líquido","Reacciones alérgicas graves como dermatitis de contacto inmediata","Absorción dérmica causando toxicidad sistémica en el organismo completo"], respuesta_correcta:1, explicacion:"El refrigerante líquido al evaporarse rápidamente absorbe calor, causando quemaduras por congelamiento (frostbite) en la piel y los ojos." , question: "What injury can direct contact of liquid refrigerant with human skin cause?", options: ["Severe chemical burns from the acidity of the liquid refrigerant", "Frostbite burns due to the rapid evaporation of the liquid", "Severe allergic reactions such as immediate contact dermatitis", "Dermal absorption causing systemic toxicity throughout the body"], explanation: "Liquid refrigerant evaporates rapidly and absorbs heat, causing frostbite burns on the skin and eyes." },
  { id:"epa608_45", categoria:"EPA608_CORE", pregunta:"¿La certificación EPA 608 de un técnico tiene fecha de expiración o necesita renovación periódica?", opciones:["Sí, debe renovarse cada 3 años con un examen de actualización profesional","No, la certificación EPA 608 es permanente y no tiene fecha de vencimiento","Sí, debe renovarse cada 5 años con un curso de educación continua obligatoria","No, pero se suspende automáticamente después de 10 años sin actividad laboral"], respuesta_correcta:1, explicacion:"La certificación EPA 608 es permanente y no tiene fecha de expiración. Sin embargo, el técnico debe mantenerse actualizado con cambios regulatorios." , question: "Does the EPA Section 608 technician certification have an expiration date or require periodic renewal?", options: ["Yes, it must be renewed every 3 years with a professional update exam", "No, the EPA 608 certification is permanent and has no expiration date", "Yes, it must be renewed every 5 years with a mandatory continuing education course", "No, but it is automatically suspended after 10 years without work activity"], explanation: "The EPA 608 certification is permanent and has no expiration date. However, the technician should stay current with regulatory changes." },
  { id:"epa608_46", categoria:"EPA608_CORE", pregunta:"¿Qué sistemas requieren llevar registro de servicio de refrigerante según la EPA Sección 608?", opciones:["Solo sistemas que contengan 50 libras o más de carga total de refrigerante en uso","Todos los sistemas sin importar la cantidad de carga del refrigerante que contengan","Solo sistemas comerciales que contengan 25 libras o más de refrigerante en total","Solo sistemas industriales que contengan 100 libras o más de refrigerante en operación"], respuesta_correcta:0, explicacion:"Los propietarios de equipos con 50 libras o más de refrigerante deben mantener registros de servicio incluyendo cantidad añadida, recuperada y tipo." , question: "What systems require keeping refrigerant service records according to EPA Section 608?", options: ["Only systems containing 50 pounds or more of total refrigerant charge", "All systems regardless of refrigerant charge quantity", "Only commercial systems containing 25 pounds or more of total refrigerant", "Only industrial systems containing 100 pounds or more of operating refrigerant"], explanation: "Owners of equipment with 50 pounds or more of refrigerant must maintain service records including the amount added, recovered, and the type." },
  { id:"epa608_47", categoria:"EPA608_CORE", pregunta:"¿Cuál es la tasa máxima anual de fuga permitida para sistemas de refrigeración comercial con 50+ lbs?", opciones:["La tasa máxima de fuga permitida es del 10% de la carga total anual","La tasa máxima de fuga permitida es del 20% de la carga total anual","La tasa máxima de fuga permitida es del 40% de la carga total anual","La tasa máxima de fuga permitida es del 30% de la carga total anual"], respuesta_correcta:3, explicacion:"Los sistemas de refrigeración comercial tienen una tasa máxima de fuga del 30% anual. Los sistemas de confort (A/C) tienen un límite del 20%." , question: "What is the maximum allowable annual leak rate for commercial refrigeration systems with 50+ lbs?", options: ["The maximum allowable leak rate is 10% of the total annual charge", "The maximum allowable leak rate is 20% of the total annual charge", "The maximum allowable leak rate is 40% of the total annual charge", "The maximum allowable leak rate is 30% of the total annual charge"], explanation: "Commercial refrigeration systems have a maximum annual leak rate of 30%. Comfort cooling (A/C) systems have a limit of 20%." },
  { id:"epa608_48", categoria:"EPA608_CORE", pregunta:"¿Cuál es la tasa máxima anual de fuga permitida para sistemas de aire acondicionado de confort?", opciones:["La tasa máxima de fuga permitida es del 20% anual de la carga total completa","La tasa máxima de fuga permitida es del 10% anual de la carga total completa","La tasa máxima de fuga permitida es del 30% anual de la carga total completa","La tasa máxima de fuga permitida es del 15% anual de la carga total completa"], respuesta_correcta:0, explicacion:"Los sistemas de confort (comfort cooling) tienen un límite de fuga del 20% anual. Si se excede, se deben reparar las fugas dentro de 30 días." , question: "What is the maximum allowable annual leak rate for comfort cooling air conditioning systems?", options: ["The maximum allowable leak rate is 20% of the total annual charge", "The maximum allowable leak rate is 10% of the total annual charge", "The maximum allowable leak rate is 30% of the total annual charge", "The maximum allowable leak rate is 15% of the total annual charge"], explanation: "Comfort cooling systems have a 20% annual leak rate limit. If exceeded, leaks must be repaired within 30 days." },
  { id:"epa608_49", categoria:"EPA608_CORE", pregunta:"¿En cuántos días debe repararse una fuga detectada que excede la tasa máxima permitida según la EPA?", opciones:["Dentro de los primeros 15 días calendario después de la detección de la fuga","Dentro de los primeros 30 días calendario después de la detección de la fuga","Dentro de los primeros 45 días calendario después de la detección de la fuga","Dentro de los primeros 60 días calendario después de la detección de la fuga"], respuesta_correcta:1, explicacion:"Si un sistema excede su tasa máxima de fuga, las reparaciones deben completarse dentro de 30 días desde la detección de la fuga." , question: "Within how many days must a detected leak that exceeds the maximum allowable rate be repaired according to the EPA?", options: ["Within the first 15 calendar days after leak detection", "Within the first 30 calendar days after leak detection", "Within the first 45 calendar days after leak detection", "Within the first 60 calendar days after leak detection"], explanation: "If a system exceeds its maximum leak rate, repairs must be completed within 30 days from the date the leak was detected." },
  { id:"epa608_50", categoria:"EPA608_CORE", pregunta:"¿Cómo se deben almacenar los cilindros de refrigerante para evitar riesgos de seguridad?", opciones:["Acostados horizontalmente en piso fresco y nivelado para mayor estabilidad lateral","Suspendidos del techo en ganchos para evitar daños por inundación en el taller","En posición vertical, asegurados con cadena, lejos de calor directo y fuego abierto","Apilados uno sobre otro en estante metálico hasta un máximo de tres niveles altos"], respuesta_correcta:2, explicacion:"Los cilindros deben estar verticales, asegurados (encadenados), en áreas ventiladas, alejados de fuentes de calor, y nunca expuestos a temperaturas superiores a 125°F." , question: "How should refrigerant cylinders be stored to avoid safety hazards?", options: ["Lying horizontally on a cool, level floor for greater lateral stability", "Suspended from the ceiling on hooks to prevent flood damage in the shop", "In an upright position, secured with a chain, away from direct heat and open flame", "Stacked one on top of another on a metal rack up to a maximum of three levels high"], explanation: "Cylinders must be upright, secured (chained), in ventilated areas, away from heat sources, and never exposed to temperatures above 125 degrees F." },
  { id:"epa608_51", categoria:"EPA608_CORE", pregunta:"¿Qué NUNCA se debe hacer con un cilindro de refrigerante desechable una vez que está completamente vacío?", opciones:["Nunca se debe rellenar un cilindro desechable ya que no está diseñado para ello","Nunca se debe reciclar el metal del cilindro en un centro de reciclaje autorizado","Nunca se debe transportar el cilindro vacío en el mismo vehículo que cilindros llenos","Nunca se debe perforar el cilindro vacío antes de desecharlo para evitar presión"], respuesta_correcta:0, explicacion:"Los cilindros desechables (DOT 39) NUNCA deben rellenarse. Solo los cilindros recargables (DOT 4BA/4BW) pueden rellenarse legalmente." , question: "What should NEVER be done with a disposable refrigerant cylinder once it is completely empty?", options: ["It should never be refilled as it is not designed for that purpose", "The metal should never be recycled at an authorized recycling center", "An empty cylinder should never be transported in the same vehicle as full cylinders", "An empty cylinder should never be punctured before disposal to avoid pressure release"], explanation: "Disposable cylinders (DOT 39) must NEVER be refilled. Only refillable cylinders (DOT 4BA/4BW) can be legally refilled." },
  { id:"epa608_52", categoria:"EPA608_CORE", pregunta:"¿Cuál es la función principal de un filtro secador (filter-drier) en un sistema de refrigeración?", opciones:["Regular la presión entre el lado alto y el lado bajo del sistema de refrigeración","Medir la cantidad de refrigerante que circula por la línea de líquido del sistema","Separar el aceite del refrigerante antes de que entre al evaporador del sistema","Remover humedad, ácidos y partículas sólidas del refrigerante que está circulando"], respuesta_correcta:3, explicacion:"El filtro secador contiene desecante que absorbe humedad y un filtro que atrapa partículas y ácidos, protegiendo el compresor y la válvula de expansión." , question: "What is the primary function of a filter-drier in a refrigeration system?", options: ["To regulate the pressure between the high and low sides of the refrigeration system", "To measure the amount of refrigerant circulating through the liquid line", "To separate oil from the refrigerant before it enters the evaporator", "To remove moisture, acids, and solid particles from the circulating refrigerant"], explanation: "The filter-drier contains desiccant that absorbs moisture and a filter that traps particles and acids, protecting the compressor and expansion valve." },
  { id:"epa608_53", categoria:"EPA608_CORE", pregunta:"¿Cuándo debe reemplazarse el filtro secador de un sistema de refrigeración según buenas prácticas?", opciones:["Solo cuando el manómetro muestra presión anormal en el lado de baja presión","Cada vez que el sistema ha sido abierto para reparación o servicio completo","Únicamente cuando el visor de líquido muestra burbujas constantes en la línea","Solo durante el mantenimiento preventivo anual programado del equipo completo"], respuesta_correcta:1, explicacion:"El filtro secador debe reemplazarse cada vez que el sistema se abre a la atmósfera, después de una quemadura de compresor, o si se detecta humedad." , question: "When should the filter-drier of a refrigeration system be replaced according to best practices?", options: ["Only when the gauge shows abnormal pressure on the low-pressure side", "Every time the system has been opened for repair or complete service", "Only when the sight glass shows constant bubbles in the line", "Only during the scheduled annual preventive maintenance of the equipment"], explanation: "The filter-drier should be replaced every time the system is opened to the atmosphere, after a compressor burnout, or if moisture is detected." },
  { id:"epa608_54", categoria:"EPA608_CORE", pregunta:"¿Qué información importante se encuentra en la placa de datos (nameplate) de un equipo de refrigeración?", opciones:["Solo el número de serie y la fecha de fabricación original del equipo por el fabricante","El tipo y cantidad de refrigerante, voltaje, amperaje y modelo del equipo completo","Solo la marca y modelo del equipo con instrucciones básicas de instalación del sistema","El historial de servicio y las fechas de mantenimiento preventivo realizados al equipo"], respuesta_correcta:1, explicacion:"La placa de datos incluye tipo de refrigerante, carga de fábrica, voltaje, amperaje, modelo, número de serie y otra información crítica para el servicio." , question: "What important information is found on the nameplate (data plate) of a refrigeration unit?", options: ["Only the serial number and original manufacturing date of the equipment", "The type and quantity of refrigerant, voltage, amperage, and model of the equipment", "Only the brand and model of the equipment with basic installation instructions", "The service history and dates of preventive maintenance performed on the equipment"], explanation: "The nameplate includes the refrigerant type, factory charge, voltage, amperage, model, serial number, and other critical service information." },
  { id:"epa608_55", categoria:"EPA608_CORE", pregunta:"¿Qué son los gases no condensables en un sistema de refrigeración y cómo afectan al sistema?", opciones:["Son refrigerantes mezclados que reducen la capacidad de enfriamiento del evaporador","Son vapores de aceite que obstruyen la válvula de expansión y el filtro secador","Son gases inertes que protegen el compresor contra la corrosión ácida interna","Son gases como el aire que aumentan la presión de descarga y reducen eficiencia"], respuesta_correcta:3, explicacion:"Los gases no condensables (principalmente aire) no se condensan a presiones normales, aumentando la presión de cabeza y reduciendo la eficiencia del sistema." , question: "What are non-condensable gases in a refrigeration system and how do they affect the system?", options: ["They are mixed refrigerants that reduce the evaporator's cooling capacity", "They are oil vapors that clog the expansion valve and filter-drier", "They are inert gases that protect the compressor against internal acid corrosion", "They are gases such as air that increase discharge pressure and reduce efficiency"], explanation: "Non-condensable gases (primarily air) do not condense at normal pressures, increasing head pressure and reducing system efficiency." },
  { id:"epa608_56", categoria:"EPA608_CORE", pregunta:"¿Cuál es el efecto principal de la humedad dentro de un sistema de refrigeración?", opciones:["La humedad forma hielo en la válvula de expansión y genera ácidos corrosivos dañinos","La humedad mejora la lubricación del aceite refrigerante en el compresor del sistema","La humedad aumenta la eficiencia al mejorar la transferencia de calor en evaporador","La humedad neutraliza los ácidos formados por la descomposición térmica del aceite"], respuesta_correcta:0, explicacion:"La humedad en el sistema puede congelarse en la válvula de expansión (bloqueándola) y reaccionar con el refrigerante para formar ácidos que dañan el compresor." , question: "What is the primary effect of moisture inside a refrigeration system?", options: ["Moisture forms ice at the expansion valve and generates damaging corrosive acids", "Moisture improves the lubrication of the refrigerant oil in the compressor", "Moisture increases efficiency by improving heat transfer in the evaporator", "Moisture neutralizes acids formed by the thermal decomposition of oil"], explanation: "Moisture in the system can freeze at the expansion valve (blocking it) and react with the refrigerant to form acids that damage the compressor." },
  { id:"epa608_57", categoria:"EPA608_CORE", pregunta:"¿Qué equipo de recuperación debe estar certificado por un laboratorio aprobado por la EPA?", opciones:["Las bombas de vacío utilizadas durante la evacuación del sistema de refrigeración","Los detectores electrónicos de fugas utilizados para localizar fugas de refrigerante","Los manómetros manifold utilizados para medir presiones del sistema de trabajo","Las máquinas de recuperación y reciclaje de refrigerante usadas en el servicio"], respuesta_correcta:3, explicacion:"Todo equipo de recuperación y reciclaje debe estar certificado por un laboratorio aprobado por la EPA (como UL o ETL) para cumplir con los estándares de eficiencia." , question: "What recovery equipment must be certified by an EPA-approved laboratory?", options: ["Vacuum pumps used during system evacuation", "Electronic leak detectors used to locate refrigerant leaks", "Manifold gauges used to measure system pressures", "Refrigerant recovery and recycling machines used in service"], explanation: "All recovery and recycling equipment must be certified by an EPA-approved laboratory (such as UL or ETL) to meet efficiency standards." },
  { id:"epa608_58", categoria:"EPA608_CORE", pregunta:"¿Cuál es el nivel de vacío requerido para recuperar refrigerante de un sistema pequeño con menos de 200 lbs?", opciones:["0 psig (presión atmosférica) para todos los refrigerantes del sistema en general","10 pulgadas de Hg de vacío para CFC y HCFC; 0 psig para HFC del sistema","Depende del tipo de refrigerante y del año de fabricación del equipo de recuperación","25 pulgadas de Hg de vacío para todos los refrigerantes sin excepción alguna"], respuesta_correcta:2, explicacion:"Los niveles de vacío requeridos para recuperación varían según el tipo de refrigerante, tamaño del sistema y fecha de fabricación del equipo de recuperación." , question: "What is the required vacuum level for recovering refrigerant from a small system with less than 200 lbs?", options: ["0 psig (atmospheric pressure) for all refrigerants in the system", "10 inches of Hg vacuum for CFC and HCFC; 0 psig for HFC", "It depends on the refrigerant type and the manufacture date of the recovery equipment", "25 inches of Hg vacuum for all refrigerants without exception"], explanation: "The required vacuum levels for recovery vary depending on the refrigerant type, system size, and manufacture date of the recovery equipment." },
  { id:"epa608_59", categoria:"EPA608_CORE", pregunta:"¿A quién se debe vender refrigerante según las regulaciones de la Sección 608 de la EPA?", opciones:["A cualquier persona mayor de 18 años que presente identificación válida vigente","A cualquier contratista con licencia de construcción estatal vigente y activa","Solo a empresas registradas en la EPA que tengan un número de identificación","Solo a técnicos certificados por la EPA Sección 608 o al propietario del equipo"], respuesta_correcta:3, explicacion:"La venta de refrigerante está restringida a técnicos certificados EPA 608. Los propietarios pueden comprar para sus propios equipos bajo ciertas condiciones." , question: "To whom may refrigerant be sold according to EPA Section 608 regulations?", options: ["To any person over 18 years old who presents a valid ID", "To any contractor with an active state construction license", "Only to companies registered with the EPA that have an identification number", "Only to EPA Section 608 certified technicians or the equipment owner"], explanation: "Refrigerant sales are restricted to EPA 608 certified technicians. Owners may purchase for their own equipment under certain conditions." },
  { id:"epa608_60", categoria:"EPA608_CORE", pregunta:"¿Qué debe hacer un técnico con el refrigerante recuperado de un sistema que tuvo quemadura de compresor?", opciones:["Puede reciclarlo en sitio y reutilizarlo en el mismo sistema después de repararlo","Debe enviarlo a una instalación de reclamación certificada para ser procesado o destruido","Puede cargarlo directamente en otro sistema del mismo tipo sin necesidad de análisis","Debe ventearlo al exterior ya que está demasiado contaminado para cualquier uso posible"], respuesta_correcta:1, explicacion:"El refrigerante de un sistema con quemadura de compresor está contaminado con ácidos y partículas. Debe enviarse a reclamación, no puede reciclarse in situ." , question: "What should a technician do with refrigerant recovered from a system that had a compressor burnout?", options: ["It can be recycled on-site and reused in the same system after repair", "It must be sent to a certified reclamation facility to be processed or destroyed", "It can be charged directly into another system of the same type without analysis", "It must be vented outdoors since it is too contaminated for any use"], explanation: "Refrigerant from a system with a compressor burnout is contaminated with acids and particles. It must be sent for reclamation; it cannot be recycled on-site." },
  { id:"epa608_61", categoria:"EPA608_CORE", pregunta:"¿Qué GWP (Potencial de Calentamiento Global) aproximado tiene el refrigerante R-410A usado en A/C?", opciones:["Un GWP aproximado de 675 veces el del CO2","Un GWP aproximado de 2,088 veces el del CO2","Un GWP aproximado de 1,430 veces el del CO2","Un GWP aproximado de 3,922 veces el del CO2"], respuesta_correcta:1, explicacion:"El R-410A tiene un GWP de aproximadamente 2,088, lo que significa que una libra de R-410A tiene el mismo efecto invernadero que 2,088 libras de CO2." , question: "What is the approximate GWP (Global Warming Potential) of the R-410A refrigerant used in A/C?", options: ["An approximate GWP of 675 times that of CO2", "An approximate GWP of 2,088 times that of CO2", "An approximate GWP of 1,430 times that of CO2", "An approximate GWP of 3,922 times that of CO2"], explanation: "R-410A has a GWP of approximately 2,088, meaning one pound of R-410A has the same greenhouse effect as 2,088 pounds of CO2." },
  { id:"epa608_62", categoria:"EPA608_CORE", pregunta:"¿Qué GWP aproximado tiene el refrigerante HFO R-1234yf comparado con el CO2 como referencia?", opciones:["Un GWP aproximado de 4 veces el del CO2 atmosférico","Un GWP aproximado de 150 veces el del CO2 atmosférico","Un GWP aproximado de 675 veces el del CO2 atmosférico","Un GWP aproximado de 1,430 veces el del CO2 atmosférico"], respuesta_correcta:0, explicacion:"El R-1234yf tiene un GWP de apenas 4, comparado con 1,430 del R-134a que reemplaza. Esta drástica reducción es la razón de la transición a HFO." , question: "What is the approximate GWP of the HFO refrigerant R-1234yf compared to CO2 as a reference?", options: ["An approximate GWP of 4 times that of atmospheric CO2", "An approximate GWP of 150 times that of atmospheric CO2", "An approximate GWP of 675 times that of atmospheric CO2", "An approximate GWP of 1,430 times that of atmospheric CO2"], explanation: "R-1234yf has a GWP of only 4, compared to 1,430 for the R-134a it replaces. This drastic reduction is the reason for the transition to HFOs." },
  { id:"epa608_63", categoria:"EPA608_CORE", pregunta:"¿Qué significa ODP (Ozone Depletion Potential) de 1.0 asignado a un refrigerante específico?", opciones:["Que destruye una molécula de ozono por cada molécula de refrigerante en la estratósfera","Que tiene el mayor potencial de agotamiento de ozono de todos los refrigerantes existentes","Que su producción fue la primera en ser prohibida por el Protocolo de Montreal en 1987","Que es el refrigerante de referencia contra el cual se miden todos los demás refrigerantes"], respuesta_correcta:3, explicacion:"Un ODP de 1.0 significa que es el valor de referencia (R-11 CFC). Otros refrigerantes se comparan contra este valor — R-22 HCFC tiene ODP de 0.055." , question: "What does an ODP (Ozone Depletion Potential) of 1.0 assigned to a specific refrigerant mean?", options: ["That it destroys one ozone molecule for every refrigerant molecule in the stratosphere", "That it has the highest ozone depletion potential of all existing refrigerants", "That its production was the first to be banned by the Montreal Protocol in 1987", "That it is the reference refrigerant against which all others are measured"], explanation: "An ODP of 1.0 means it is the reference value (R-11 CFC). Other refrigerants are compared against this value — R-22 HCFC has an ODP of 0.055." },
  { id:"epa608_64", categoria:"EPA608_CORE", pregunta:"¿Cuál es la composición química general de un refrigerante CFC (clorofluorocarbono)?", opciones:["Contiene hidrógeno, cloro, flúor y carbono en su estructura molecular completa","Contiene solo cloro, flúor y carbono sin hidrógeno en su estructura molecular","Contiene hidrógeno, flúor y carbono sin cloro en su estructura molecular base","Contiene solo flúor y carbono sin cloro ni hidrógeno en su molécula básica"], respuesta_correcta:1, explicacion:"Los CFC contienen solo cloro, flúor y carbono (sin hidrógeno). La ausencia de hidrógeno los hace muy estables, permitiéndoles llegar intactos a la estratósfera." , question: "What is the general chemical composition of a CFC (chlorofluorocarbon) refrigerant?", options: ["It contains hydrogen, chlorine, fluorine, and carbon in its molecular structure", "It contains only chlorine, fluorine, and carbon with no hydrogen in its molecular structure", "It contains hydrogen, fluorine, and carbon with no chlorine in its molecular structure", "It contains only fluorine and carbon with no chlorine or hydrogen in its molecule"], explanation: "CFCs contain only chlorine, fluorine, and carbon (no hydrogen). The absence of hydrogen makes them very stable, allowing them to reach the stratosphere intact." },
  { id:"epa608_65", categoria:"EPA608_CORE", pregunta:"¿Por qué los HCFC tienen un ODP menor que los CFC a pesar de contener cloro también?", opciones:["Porque los HCFC contienen menos átomos de cloro por molécula en su estructura","Porque los HCFC contienen hidrógeno que los hace descomponerse antes de llegar a la estratósfera","Porque los HCFC tienen una vida atmosférica más corta debido a su mayor peso molecular total","Porque los HCFC reaccionan con el oxígeno en la tropósfera neutralizando su cloro antes de subir"], respuesta_correcta:1, explicacion:"El hidrógeno en los HCFC los hace menos estables en la tropósfera, donde se descomponen parcialmente antes de alcanzar la estratósfera, reduciendo su ODP." , question: "Why do HCFCs have a lower ODP than CFCs despite also containing chlorine?", options: ["Because HCFCs contain fewer chlorine atoms per molecule in their structure", "Because HCFCs contain hydrogen, which causes them to break down before reaching the stratosphere", "Because HCFCs have a shorter atmospheric life due to their greater total molecular weight", "Because HCFCs react with oxygen in the troposphere, neutralizing their chlorine before rising"], explanation: "The hydrogen in HCFCs makes them less stable in the troposphere, where they partially break down before reaching the stratosphere, reducing their ODP." },
  { id:"epa608_66", categoria:"EPA608_CORE", pregunta:"¿Cuál es la principal diferencia entre una mezcla azeotrópica y una zeotrópica de refrigerantes?", opciones:["La azeotrópica se comporta como un solo componente; la zeotrópica tiene deslizamiento de temperatura","La azeotrópica cambia de composición al fugarse; la zeotrópica mantiene su composición estable","La azeotrópica tiene mayor presión de operación; la zeotrópica tiene menor presión de operación","La azeotrópica es siempre más eficiente; la zeotrópica es siempre menos eficiente en sistemas"], respuesta_correcta:0, explicacion:"Las mezclas azeotrópicas se comportan como un compuesto puro (sin glide). Las zeotrópicas tienen deslizamiento de temperatura (temperature glide) al cambiar de fase." , question: "What is the main difference between an azeotropic and a zeotropic refrigerant blend?", options: ["An azeotropic blend behaves like a single component; a zeotropic blend has temperature glide", "An azeotropic blend changes composition when it leaks; a zeotropic blend maintains stable composition", "An azeotropic blend has higher operating pressure; a zeotropic blend has lower operating pressure", "An azeotropic blend is always more efficient; a zeotropic blend is always less efficient in systems"], explanation: "Azeotropic blends behave like a pure compound (no glide). Zeotropic blends have temperature glide during phase change." },
  { id:"epa608_67", categoria:"EPA608_CORE", pregunta:"¿Qué problema puede ocurrir cuando una mezcla zeotrópica de refrigerante tiene una fuga significativa?", opciones:["La fuga causa un aumento en la presión de descarga sin afectar la composición del refrigerante","La fuga solo pierde aceite sin afectar la proporción de los componentes del refrigerante","La composición de la mezcla cambia porque los componentes se fugan a diferentes velocidades","La fuga causa cristalización del refrigerante en el punto de fuga bloqueando la salida"], respuesta_correcta:2, explicacion:"En mezclas zeotrópicas, los componentes más volátiles se fugan más rápido, cambiando la composición restante y afectando el rendimiento del sistema." , question: "What problem can occur when a zeotropic refrigerant blend has a significant leak?", options: ["The leak causes an increase in discharge pressure without affecting refrigerant composition", "The leak only loses oil without affecting the proportion of refrigerant components", "The composition of the blend changes because the components leak at different rates", "The leak causes crystallization of the refrigerant at the leak point, blocking the exit"], explanation: "In zeotropic blends, the more volatile components leak out faster, changing the remaining composition and affecting system performance." },
  { id:"epa608_68", categoria:"EPA608_CORE", pregunta:"¿Qué componente del sistema de refrigeración es responsable de rechazar el calor al ambiente exterior?", opciones:["El evaporador con su ventilador de circulación interior","El condensador con su ventilador de circulación exterior","El compresor con su bobina de arranque eléctrico motor","La válvula de expansión con su bulbo sensor térmico"], respuesta_correcta:1, explicacion:"El condensador rechaza el calor absorbido en el evaporador más el calor del trabajo de compresión, liberándolo al ambiente exterior." , question: "What component of the refrigeration system is responsible for rejecting heat to the outdoor environment?", options: ["The evaporator with its indoor circulation fan", "The condenser with its outdoor circulation fan", "The compressor with its electric start winding motor", "The expansion valve with its thermal sensing bulb"], explanation: "The condenser rejects the heat absorbed in the evaporator plus the heat of compression, releasing it to the outdoor environment." },
  { id:"epa608_69", categoria:"EPA608_CORE", pregunta:"¿Qué componente del sistema absorbe el calor del espacio que se desea enfriar o refrigerar?", opciones:["El condensador ubicado en la unidad exterior","El evaporador ubicado en la unidad interior","El compresor dentro de la unidad condensadora","La válvula de servicio de la línea de succión"], respuesta_correcta:1, explicacion:"El evaporador absorbe calor del espacio acondicionado al evaporarse el refrigerante líquido a baja presión, enfriando el aire que pasa sobre él." , question: "What component of the system absorbs heat from the space to be cooled or refrigerated?", options: ["The condenser located in the outdoor unit", "The evaporator located in the indoor unit", "The compressor inside the condensing unit", "The service valve on the suction line"], explanation: "The evaporator absorbs heat from the conditioned space as the liquid refrigerant evaporates at low pressure, cooling the air passing over it." },
  { id:"epa608_70", categoria:"EPA608_CORE", pregunta:"¿Cuál de los siguientes NO es uno de los cuatro componentes principales del ciclo de refrigeración?", opciones:["El compresor que bombea el refrigerante por todo el sistema de refrigeración completo","El filtro secador que remueve humedad y contaminantes del refrigerante en circulación","El condensador que rechaza el calor absorbido al exterior del espacio acondicionado","El dispositivo de medición que regula el flujo de refrigerante al evaporador del sistema"], respuesta_correcta:1, explicacion:"Los 4 componentes principales son: compresor, condensador, dispositivo de medición (expansión) y evaporador. El filtro secador es un componente auxiliar." , question: "Which of the following is NOT one of the four main components of the refrigeration cycle?", options: ["The compressor that pumps refrigerant throughout the entire refrigeration system", "The filter-drier that removes moisture and contaminants from the circulating refrigerant", "The condenser that rejects absorbed heat to the exterior of the conditioned space", "The metering device that regulates refrigerant flow to the system's evaporator"], explanation: "The 4 main components are: compressor, condenser, metering (expansion) device, and evaporator. The filter-drier is an auxiliary component." },
  { id:"epa608_71", categoria:"EPA608_CORE", pregunta:"¿Qué sucede con el punto de ebullición de un refrigerante cuando se aumenta la presión sobre él?", opciones:["El punto de ebullición disminuye proporcionalmente a medida que la presión sube","El punto de ebullición permanece constante sin importar los cambios de presión","El punto de ebullición primero sube y luego baja en una curva parabólica inversa","El punto de ebullición aumenta proporcionalmente a medida que la presión sube"], respuesta_correcta:3, explicacion:"Al aumentar la presión, el punto de ebullición sube. Por eso el refrigerante hierve a baja temperatura en el evaporador (baja presión) y se condensa a alta temperatura en el condensador (alta presión)." , question: "What happens to the boiling point of a refrigerant when the pressure on it is increased?", options: ["The boiling point decreases proportionally as pressure rises", "The boiling point remains constant regardless of pressure changes", "The boiling point first rises and then falls in an inverse parabolic curve", "The boiling point increases proportionally as pressure rises"], explanation: "As pressure increases, the boiling point rises. That is why refrigerant boils at a low temperature in the evaporator (low pressure) and condenses at a high temperature in the condenser (high pressure)." },
  { id:"epa608_72", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de calor se absorbe o libera cuando un refrigerante cambia de fase sin cambiar de temperatura?", opciones:["Calor sensible que se mide con un termómetro estándar de mercurio o digital","Calor específico que depende de la masa y tipo de material del refrigerante","Calor radiante que se transfiere a través del espacio sin medio de conducción","Calor latente que no produce cambio de temperatura durante el cambio de fase"], respuesta_correcta:3, explicacion:"El calor latente es la energía absorbida o liberada durante un cambio de fase (líquido a gas o viceversa) sin cambio de temperatura." , question: "What type of heat is absorbed or released when a refrigerant changes phase without changing temperature?", options: ["Sensible heat, measured with a standard mercury or digital thermometer", "Specific heat, which depends on the mass and material type of the refrigerant", "Radiant heat, which transfers through space without a conduction medium", "Latent heat, which produces no temperature change during the phase change"], explanation: "Latent heat is the energy absorbed or released during a phase change (liquid to gas or vice versa) without a change in temperature." },
  { id:"epa608_73", categoria:"EPA608_CORE", pregunta:"¿Cuál es el propósito principal de usar nitrógeno seco para romper el vacío durante una triple evacuación?", opciones:["Para añadir presión positiva que ayude a la bomba de vacío a funcionar más eficientemente","Para presurizar el sistema y poder detectar fugas entre los ciclos de evacuación aplicados","Para diluir y ayudar a liberar la humedad atrapada en el sistema que el vacío solo no extrae","Para absorber la humedad residual del sistema y convertirla en vapor que pueda evacuarse"], respuesta_correcta:2, explicacion:"El nitrógeno seco rompe el vacío y diluye la humedad residual atrapada, facilitando su extracción en el siguiente ciclo de evacuación." , question: "What is the main purpose of using dry nitrogen to break the vacuum during a triple evacuation?", options: ["To add positive pressure that helps the vacuum pump operate more efficiently", "To pressurize the system to detect leaks between evacuation cycles", "To dilute and help release trapped moisture in the system that vacuum alone cannot extract", "To absorb residual moisture from the system and convert it to vapor that can be evacuated"], explanation: "Dry nitrogen breaks the vacuum and dilutes trapped residual moisture, making it easier to extract in the next evacuation cycle." },
  { id:"epa608_74", categoria:"EPA608_CORE", pregunta:"¿Qué instrumento se utiliza para medir con precisión el nivel de vacío en micrones durante una evacuación?", opciones:["Un manómetro compuesto estándar del lado de baja presión del manifold del técnico","Un sensor de vacío electrónico o un medidor de vacío tipo micron gauge dedicado","Un micrómetro digital de alta precisión conectado a la línea de servicio del sistema","Un barómetro digital de presión atmosférica calibrado a nivel del mar estándar"], respuesta_correcta:1, explicacion:"Un micron gauge (medidor de micrones) electrónico es necesario para medir vacíos profundos con precisión. Los manómetros estándar no tienen la resolución necesaria." , question: "What instrument is used to precisely measure the vacuum level in microns during an evacuation?", options: ["A standard compound gauge on the low-pressure side of the technician's manifold", "An electronic vacuum sensor or a dedicated micron gauge", "A high-precision digital micrometer connected to the system's service line", "A digital barometric pressure gauge calibrated to standard sea level"], explanation: "An electronic micron gauge is necessary to measure deep vacuums with precision. Standard manifold gauges do not have the required resolution." },
  { id:"epa608_75", categoria:"EPA608_CORE", pregunta:"¿Por qué es importante que la bomba de vacío tenga su aceite limpio y al nivel correcto?", opciones:["Para evitar que la bomba se sobrecaliente y se dañen los rodamientos del motor eléctrico","Para reducir el ruido de operación y las vibraciones durante el proceso de evacuación largo","Para que la bomba pueda alcanzar un vacío profundo necesario para remover toda la humedad","Para evitar que el aceite de la bomba contamine el refrigerante nuevo que se va a cargar"], respuesta_correcta:2, explicacion:"El aceite limpio en la bomba de vacío sella las tolerancias internas, permitiendo alcanzar el vacío profundo necesario (500 micrones) para la deshidratación completa." , question: "Why is it important that the vacuum pump have clean oil at the correct level?", options: ["To prevent the pump from overheating and damaging the electric motor bearings", "To reduce operating noise and vibrations during the extended evacuation process", "So the pump can achieve the deep vacuum necessary to remove all moisture", "To prevent the pump oil from contaminating the new refrigerant to be charged"], explanation: "Clean oil in the vacuum pump seals the internal tolerances, allowing it to reach the deep vacuum necessary (500 microns) for complete dehydration." },
  { id:"epa608_76", categoria:"EPA608_CORE", pregunta:"¿A qué temperatura aproximada hierve el agua cuando el sistema está a un vacío de 500 micrones?", opciones:["El agua hierve a aproximadamente -40°F (-40°C) a 500 micrones de vacío profundo","El agua hierve a aproximadamente 32°F (0°C) a 500 micrones de vacío absoluto","El agua hierve a aproximadamente 0°F (-18°C) a 500 micrones de vacío absoluto","El agua hierve a aproximadamente -58°F (-50°C) a 500 micrones de vacío profundo"], respuesta_correcta:0, explicacion:"A 500 micrones de vacío, el punto de ebullición del agua baja a aproximadamente -40°F/-40°C, lo que permite evaporar y extraer toda la humedad del sistema." , question: "At approximately what temperature does water boil when the system is at a vacuum of 500 microns?", options: ["Water boils at approximately -40 degrees F (-40 degrees C) at 500 microns of deep vacuum", "Water boils at approximately 32 degrees F (0 degrees C) at 500 microns of absolute vacuum", "Water boils at approximately 0 degrees F (-18 degrees C) at 500 microns of absolute vacuum", "Water boils at approximately -58 degrees F (-50 degrees C) at 500 microns of deep vacuum"], explanation: "At 500 microns of vacuum, the boiling point of water drops to approximately -40 degrees F / -40 degrees C, which allows all moisture to be evaporated and extracted from the system." },
  { id:"epa608_77", categoria:"EPA608_CORE", pregunta:"¿Qué Sección del Clean Air Act autoriza al programa SNAP para evaluar sustitutos de sustancias ODS?", opciones:["La Sección 608 sobre prácticas de servicio de refrigerantes y certificación técnica","La Sección 609 sobre servicio de sistemas de A/C de vehículos motorizados en EE.UU.","La Sección 610 sobre reciclaje de refrigerantes en sistemas de aire acondicionado móvil","La Sección 612 sobre evaluación de sustitutos aceptables de sustancias ODS por EPA"], respuesta_correcta:3, explicacion:"La Sección 612 estableció el programa SNAP (Significant New Alternatives Policy) que evalúa y aprueba sustitutos aceptables de sustancias que agotan el ozono." , question: "What Section of the Clean Air Act authorizes the SNAP program to evaluate substitutes for ODS substances?", options: ["Section 608 on refrigerant service practices and technician certification", "Section 609 on motor vehicle A/C system service in the U.S.", "Section 610 on refrigerant recycling in mobile air conditioning systems", "Section 612 on evaluation of acceptable ODS substitutes by the EPA"], explanation: "Section 612 established the SNAP (Significant New Alternatives Policy) program that evaluates and approves acceptable substitutes for ozone-depleting substances." },
  { id:"epa608_78", categoria:"EPA608_CORE", pregunta:"¿Cuántos tipos de certificación EPA 608 existen para técnicos de refrigeración y aire acondicionado?", opciones:["Existen 4 tipos: Tipo I, Tipo II, Tipo III y Universal para diferentes sistemas","Existen 3 tipos: Tipo I, Tipo II y Tipo III para diferentes sistemas","Existen 2 tipos: Tipo Residencial y Tipo Comercial según el tipo de sistema","Existen 5 tipos: Básico, Intermedio, Avanzado, Experto y Maestro del oficio"], respuesta_correcta:0, explicacion:"Hay 4 certificaciones: Tipo I (sistemas pequeños), Tipo II (alta presión), Tipo III (baja presión) y Universal (todas las anteriores combinadas)." , question: "How many types of EPA 608 certification exist for refrigeration and air conditioning technicians?", options: ["There are 4 types: Type I, Type II, Type III, and Universal for different systems", "There are 3 types: Type I, Type II, and Type III for different systems", "There are 2 types: Residential and Commercial based on the system type", "There are 5 types: Basic, Intermediate, Advanced, Expert, and Master"], explanation: "There are 4 certifications: Type I (small appliances), Type II (high-pressure), Type III (low-pressure), and Universal (all of the above combined)." },
  { id:"epa608_79", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de certificación EPA 608 necesita un técnico que trabaja en todos los tipos de sistemas?", opciones:["Necesita certificación Universal que combina Tipo I, Tipo II y Tipo III en una sola","Necesita certificación Tipo III de baja presión que cubre todos los sistemas disponibles","Necesita certificación Tipo II de alta presión que es la más completa de todas ellas","Necesita certificación Tipo I de equipos pequeños que es válida para todo tipo equipo"], respuesta_correcta:0, explicacion:"La certificación Universal combina los tres tipos y permite al técnico trabajar en cualquier sistema de refrigeración, independientemente de su tamaño o presión." , question: "What type of EPA 608 certification does a technician need to work on all types of systems?", options: ["Universal certification, which combines Type I, Type II, and Type III into one", "Type III low-pressure certification, which covers all available systems", "Type II high-pressure certification, which is the most comprehensive of all", "Type I small appliance certification, which is valid for all equipment types"], explanation: "Universal certification combines all three types and allows the technician to work on any refrigeration system, regardless of its size or pressure." },
  { id:"epa608_80", categoria:"EPA608_CORE", pregunta:"¿Qué define a un sistema de 'equipos pequeños' que cae bajo la certificación Tipo I de la EPA?", opciones:["Sistemas residenciales con capacidad menor a 5 toneladas de refrigeración total","Sistemas con una carga de fábrica de 5 libras o menos de refrigerante en total","Sistemas portátiles que pueden moverse fácilmente de una ubicación a otra diferente","Sistemas de aire acondicionado de ventana con menos de 12,000 BTU de capacidad"], respuesta_correcta:1, explicacion:"Los sistemas Tipo I (equipos pequeños) son aquellos fabricados con 5 libras o menos de refrigerante, como refrigeradores domésticos, A/C de ventana, y PTAC." , question: "What defines a 'small appliance' system that falls under EPA Type I certification?", options: ["Residential systems with a capacity of less than 5 tons of refrigeration", "Systems with a factory charge of 5 pounds or less of refrigerant", "Portable systems that can be easily moved from one location to another", "Window air conditioners with less than 12,000 BTU of capacity"], explanation: "Type I systems (small appliances) are those manufactured with 5 pounds or less of refrigerant, such as household refrigerators, window A/C units, and PTACs." },
  { id:"epa608_81", categoria:"EPA608_CORE", pregunta:"¿Qué debe hacer un técnico antes de abrir un sistema de refrigeración para servicio o reparación?", opciones:["Recuperar el refrigerante a los niveles requeridos por la EPA antes de abrir el sistema","Verificar el voltaje del sistema y desconectar la alimentación eléctrica solamente","Purgar el sistema con nitrógeno para remover todo el refrigerante de las líneas internas","Agregar tinte UV al sistema para poder localizar la fuga después de abrirlo al ambiente"], respuesta_correcta:0, explicacion:"Antes de abrir un sistema para reparación, el técnico debe recuperar el refrigerante a los niveles de vacío requeridos por la EPA según el tipo de sistema." , question: "What must a technician do before opening a refrigeration system for service or repair?", options: ["Recover the refrigerant to the levels required by the EPA before opening the system", "Verify the system voltage and disconnect the electrical supply only", "Purge the system with nitrogen to remove all refrigerant from the internal lines", "Add UV dye to the system to locate the leak after opening it to the atmosphere"], explanation: "Before opening a system for repair, the technician must recover the refrigerant to the vacuum levels required by the EPA based on the system type." },
  { id:"epa608_82", categoria:"EPA608_CORE", pregunta:"¿Cuál es el color estándar del cilindro de recuperación de refrigerante aprobado por la AHRI?", opciones:["El cilindro de recuperación es de color azul con franja amarilla en la parte superior","El cilindro de recuperación es de color gris con tapa amarilla en la parte de arriba","El cilindro de recuperación es amarillo con tapa gris en la parte superior del tanque","El cilindro de recuperación es de color verde con franja blanca en la parte superior"], respuesta_correcta:2, explicacion:"Los cilindros de recuperación son amarillos con tapa gris, lo que los distingue de los cilindros de refrigerante virgen que tienen colores específicos por tipo." , question: "What is the standard color of the AHRI-approved refrigerant recovery cylinder?", options: ["The recovery cylinder is blue with a yellow stripe on top", "The recovery cylinder is gray with a yellow cap on top", "The recovery cylinder is yellow with a gray cap on top", "The recovery cylinder is green with a white stripe on top"], explanation: "Recovery cylinders are yellow with a gray cap, which distinguishes them from virgin refrigerant cylinders that have specific colors by type." },
  { id:"epa608_83", categoria:"EPA608_CORE", pregunta:"¿Hasta qué porcentaje máximo de su capacidad se debe llenar un cilindro de recuperación de refrigerante?", opciones:["Hasta el 60% de su capacidad total para dejar espacio para expansión del refrigerante","Hasta el 80% de su capacidad total para dejar espacio para expansión del refrigerante","Hasta el 70% de su capacidad total para dejar espacio para expansión del refrigerante","Hasta el 90% de su capacidad total para dejar espacio para expansión del refrigerante"], respuesta_correcta:1, explicacion:"Los cilindros de recuperación no deben llenarse más del 80% de su capacidad para permitir la expansión térmica del refrigerante líquido y evitar ruptura." , question: "To what maximum percentage of its capacity should a refrigerant recovery cylinder be filled?", options: ["Up to 60% of its total capacity to leave room for refrigerant expansion", "Up to 80% of its total capacity to leave room for refrigerant expansion", "Up to 70% of its total capacity to leave room for refrigerant expansion", "Up to 90% of its total capacity to leave room for refrigerant expansion"], explanation: "Recovery cylinders must not be filled beyond 80% of their capacity to allow for thermal expansion of the liquid refrigerant and prevent rupture." },
  { id:"epa608_84", categoria:"EPA608_CORE", pregunta:"¿Qué puede causar una ruptura catastrófica de un cilindro de refrigerante lleno en almacenamiento?", opciones:["Almacenarlo en un lugar con temperatura menor a 32°F causando contracción del metal","Almacenarlo acostado horizontalmente sobre una superficie de concreto húmeda fría","Almacenarlo en un lugar con temperaturas superiores a 125°F causando sobrepresión","Almacenarlo junto a cilindros de diferentes tipos de refrigerante en el mismo lugar"], respuesta_correcta:2, explicacion:"Las altas temperaturas causan expansión del refrigerante líquido dentro del cilindro. Si supera 125°F, la presión puede exceder el límite del cilindro y causar ruptura." , question: "What can cause a catastrophic rupture of a full refrigerant cylinder in storage?", options: ["Storing it in a location with temperatures below 32 degrees F causing metal contraction", "Storing it lying horizontally on a cold, wet concrete surface", "Storing it in a location with temperatures above 125 degrees F causing overpressure", "Storing it alongside cylinders of different refrigerant types in the same location"], explanation: "High temperatures cause the liquid refrigerant inside the cylinder to expand. If it exceeds 125 degrees F, the pressure can exceed the cylinder's limit and cause rupture." },
  { id:"epa608_85", categoria:"EPA608_CORE", pregunta:"¿Qué instrumento mide la cantidad exacta de refrigerante al cargar un sistema por peso?", opciones:["Un termómetro de presión-temperatura para calcular la carga por temperatura exacta","Un flujómetro digital instalado en la línea de carga para medir el volumen que pasa","Una balanza electrónica de refrigerante calibrada para pesar el cilindro con precisión","Un visor de líquido en la línea de carga para verificar si hay burbujas en el flujo"], respuesta_correcta:2, explicacion:"La balanza electrónica de refrigerante es el método más preciso para cargar por peso, midiendo exactamente cuántas libras/onzas salen del cilindro." , question: "What instrument measures the exact amount of refrigerant when charging a system by weight?", options: ["A pressure-temperature thermometer to calculate the charge by exact temperature", "A digital flow meter installed on the charging line to measure the volume passing through", "A calibrated electronic refrigerant scale to weigh the cylinder with precision", "A sight glass on the charging line to verify if there are bubbles in the flow"], explanation: "The electronic refrigerant scale is the most accurate method for charging by weight, measuring exactly how many pounds/ounces leave the cylinder." },
  { id:"epa608_86", categoria:"EPA608_CORE", pregunta:"¿Qué indica la presencia de burbujas constantes en el visor de líquido de la línea de líquido?", opciones:["Indica que el sistema puede tener baja carga de refrigerante o restricción en el flujo","Indica que el sistema tiene una sobrecarga excesiva de refrigerante en el circuito","Indica que el filtro secador está funcionando correctamente filtrando impurezas","Indica que la válvula de expansión está regulando correctamente el flujo al evaporador"], respuesta_correcta:0, explicacion:"Burbujas en el visor de líquido generalmente indican baja carga de refrigerante, restricción parcial, o subenfriamiento insuficiente en la línea de líquido." , question: "What does the presence of constant bubbles in the liquid line sight glass indicate?", options: ["It indicates the system may have a low refrigerant charge or flow restriction", "It indicates the system has an excessive refrigerant overcharge", "It indicates the filter-drier is functioning correctly and filtering impurities", "It indicates the expansion valve is correctly regulating flow to the evaporator"], explanation: "Bubbles in the sight glass generally indicate low refrigerant charge, partial restriction, or insufficient subcooling in the liquid line." },
  { id:"epa608_87", categoria:"EPA608_CORE", pregunta:"¿Qué tipo de aceite PAG se utiliza típicamente en los sistemas de A/C automotriz con R-134a?", opciones:["Aceite mineral de grado 150 para compresores de refrigeración industrial","Aceite polioléster (POE) de viscosidad media para sistemas estacionarios","Aceite polivinil éter (PVE) de alta viscosidad para compresores scroll","Aceite polialquilenglicol (PAG) específico para sistemas automotrices"], respuesta_correcta:3, explicacion:"Los sistemas automotrices con R-134a usan aceite PAG (polialquilenglicol). Los sistemas estacionarios con HFC generalmente usan POE." , question: "What type of PAG oil is typically used in automotive A/C systems with R-134a?", options: ["Grade 150 mineral oil for industrial refrigeration compressors", "Medium-viscosity polyol ester (POE) oil for stationary systems", "High-viscosity polyvinyl ether (PVE) oil for scroll compressors", "Polyalkylene glycol (PAG) oil specific to automotive systems"], explanation: "Automotive systems with R-134a use PAG (polyalkylene glycol) oil. Stationary systems with HFC generally use POE." },
  { id:"epa608_88", categoria:"EPA608_CORE", pregunta:"¿Cuál es la relación entre la presión y la temperatura de saturación de un refrigerante puro?", opciones:["No existe relación directa entre la presión y la temperatura de saturación del refrigerante","A cada presión le corresponde una sola temperatura de saturación específica y única","La temperatura de saturación varía aleatoriamente sin importar la presión del sistema","La presión y temperatura de saturación tienen una relación inversa proporcional constante"], respuesta_correcta:1, explicacion:"Para un refrigerante puro, cada presión tiene una temperatura de saturación correspondiente única. Esta relación P/T es fundamental para diagnosticar sistemas." , question: "What is the relationship between pressure and saturation temperature of a pure refrigerant?", options: ["There is no direct relationship between pressure and saturation temperature", "Each pressure corresponds to one specific and unique saturation temperature", "Saturation temperature varies randomly regardless of system pressure", "Pressure and saturation temperature have a constant inverse proportional relationship"], explanation: "For a pure refrigerant, each pressure has a unique corresponding saturation temperature. This P/T relationship is fundamental for diagnosing systems." },
  { id:"epa608_89", categoria:"EPA608_CORE", pregunta:"¿Qué sucede con la temperatura de saturación de un refrigerante si se reduce la presión significativamente?", opciones:["La temperatura de saturación del refrigerante aumenta proporcionalmente a la reducción","La temperatura de saturación del refrigerante permanece constante sin importar presión","La temperatura de saturación del refrigerante disminuye proporcionalmente a la reducción","La temperatura de saturación del refrigerante fluctúa de manera impredecible con presión"], respuesta_correcta:2, explicacion:"Al reducir la presión, la temperatura de saturación baja. Por eso el refrigerante en el evaporador (baja presión) tiene temperatura baja para absorber calor." , question: "What happens to the saturation temperature of a refrigerant if the pressure is significantly reduced?", options: ["The saturation temperature increases proportionally to the reduction", "The saturation temperature remains constant regardless of pressure", "The saturation temperature decreases proportionally to the reduction", "The saturation temperature fluctuates unpredictably with pressure"], explanation: "When pressure is reduced, the saturation temperature drops. That is why refrigerant in the evaporator (low pressure) has a low temperature to absorb heat." },
  { id:"epa608_90", categoria:"EPA608_CORE", pregunta:"¿Qué práctica se debe seguir al mezclar diferentes tipos de refrigerante en un mismo sistema?", opciones:["Se pueden mezclar refrigerantes del mismo grupo familiar como dos HFC diferentes","Se pueden mezclar si tienen presiones de operación similares y son compatibles","Se pueden mezclar si se agrega aceite POE nuevo al sistema antes de la mezcla final","NUNCA se deben mezclar diferentes refrigerantes en un mismo sistema de refrigeración"], respuesta_correcta:3, explicacion:"NUNCA se deben mezclar refrigerantes. Mezclarlos altera las presiones, temperaturas y el rendimiento del sistema, y puede dañar el compresor." , question: "What practice should be followed when mixing different types of refrigerant in the same system?", options: ["Refrigerants from the same chemical family, such as two different HFCs, can be mixed", "They can be mixed if they have similar operating pressures and are compatible", "They can be mixed if new POE oil is added to the system before the final blend", "Different refrigerants should NEVER be mixed in the same refrigeration system"], explanation: "Refrigerants should NEVER be mixed. Mixing them alters the pressures, temperatures, and system performance, and can damage the compressor." },
  { id:"epa608_91", categoria:"EPA608_CORE", pregunta:"¿Qué debe verificarse en un cilindro de recuperación antes de usarlo para almacenar refrigerante?", opciones:["Que esté dentro de su fecha de recertificación hidrostática y no tenga daños visibles","Solo que el cilindro esté limpio por fuera y que la etiqueta sea legible sin daños","Solo que la válvula abra y cierre correctamente sin ningún tipo de fuga de gas","Que sea del mismo color que el refrigerante que se va a recuperar del sistema actual"], respuesta_correcta:0, explicacion:"Los cilindros de recuperación deben estar dentro de su fecha de recertificación hidrostática (cada 5 años DOT) y no tener daños, abolladuras ni corrosión visible." , question: "What should be verified on a recovery cylinder before using it to store refrigerant?", options: ["That it is within its hydrostatic retest date and has no visible damage", "Only that the cylinder is clean on the outside and the label is legible", "Only that the valve opens and closes correctly without any gas leak", "That it is the same color as the refrigerant to be recovered from the current system"], explanation: "Recovery cylinders must be within their hydrostatic retest date (every 5 years per DOT) and have no damage, dents, or visible corrosion." },
  { id:"epa608_92", categoria:"EPA608_CORE", pregunta:"¿Qué es el 'temperature glide' o deslizamiento de temperatura en una mezcla de refrigerante?", opciones:["Es la diferencia entre la temperatura del compresor y la temperatura ambiente exterior","Es la diferencia de temperatura entre el aire de suministro y el aire de retorno del sistema","Es la diferencia de temperatura entre el lado de succión y el lado de descarga del compresor","Es la diferencia de temperatura entre el inicio y el fin del cambio de fase de la mezcla"], respuesta_correcta:3, explicacion:"El temperature glide es la diferencia de temperatura entre el punto de burbuja y el punto de rocío de una mezcla zeotrópica durante el cambio de fase." , question: "What is 'temperature glide' in a refrigerant blend?", options: ["It is the temperature difference between the compressor and the outdoor ambient temperature", "It is the temperature difference between the supply air and the return air of the system", "It is the temperature difference between the suction side and the discharge side of the compressor", "It is the temperature difference between the start and end of the phase change of the blend"], explanation: "Temperature glide is the temperature difference between the bubble point and the dew point of a zeotropic blend during phase change." },
  { id:"epa608_93", categoria:"EPA608_CORE", pregunta:"¿Cuál es la consecuencia de cargar refrigerante líquido directamente al lado de succión del compresor?", opciones:["Mejora la eficiencia del sistema al enfriar los devanados del motor del compresor","Aumenta temporalmente la capacidad de enfriamiento del evaporador del sistema","Reduce la presión de descarga mejorando la relación de compresión del compresor","Causa daño severo al compresor por golpe de líquido que daña válvulas y componentes"], respuesta_correcta:3, explicacion:"El líquido es incompresible. Si refrigerante líquido llega al compresor (liquid slugging/floodback), puede romper válvulas, bielas y otros componentes internos." , question: "What is the consequence of charging liquid refrigerant directly into the suction side of the compressor?", options: ["It improves system efficiency by cooling the compressor motor windings", "It temporarily increases the evaporator's cooling capacity", "It reduces discharge pressure, improving the compressor's compression ratio", "It causes severe compressor damage from liquid slugging that damages valves and components"], explanation: "Liquid is incompressible. If liquid refrigerant reaches the compressor (liquid slugging/floodback), it can break valves, connecting rods, and other internal components." },
  { id:"epa608_94", categoria:"EPA608_CORE", pregunta:"¿Por qué se recomienda cargar mezclas zeotrópicas de refrigerante en fase líquida desde el cilindro?", opciones:["Porque es más rápido cargar en fase líquida que en fase gaseosa desde el cilindro disponible","Porque la fase líquida contiene más aceite que beneficia la lubricación del compresor del sistema","Porque al cargar en gas los componentes salen a diferente velocidad cambiando la composición","Porque la fase gaseosa puede dañar el manómetro manifold por las altas presiones generadas"], respuesta_correcta:2, explicacion:"Las mezclas zeotrópicas se cargan como líquido para mantener la proporción correcta de componentes. Si se carga como gas, los componentes más volátiles salen primero." , question: "Why is it recommended to charge zeotropic refrigerant blends in the liquid phase from the cylinder?", options: ["Because it is faster to charge in liquid phase than in gas phase from the cylinder", "Because the liquid phase contains more oil that benefits compressor lubrication", "Because when charging as vapor, the components exit at different rates, changing the composition", "Because the gas phase can damage the manifold gauge due to the high pressures generated"], explanation: "Zeotropic blends are charged as liquid to maintain the correct proportion of components. If charged as vapor, the more volatile components exit first." },
  { id:"epa608_95", categoria:"EPA608_CORE", pregunta:"¿Qué dispositivo de seguridad protege un sistema de refrigeración contra presiones excesivamente altas?", opciones:["El termostato de control de temperatura del espacio acondicionado por el sistema","El presóstato de baja presión que detiene el compresor cuando la presión cae","La válvula de alivio de presión o fusible de alta presión del lado de descarga","El relé de sobrecarga térmica que protege el motor eléctrico del compresor"], respuesta_correcta:2, explicacion:"La válvula de alivio de presión y el fusible de alta presión protegen el sistema contra presiones peligrosamente altas descargando refrigerante de forma controlada." , question: "What safety device protects a refrigeration system against excessively high pressures?", options: ["The space temperature control thermostat", "The low-pressure switch that stops the compressor when pressure drops", "The pressure relief valve or high-pressure fusible plug on the discharge side", "The thermal overload relay that protects the compressor's electric motor"], explanation: "The pressure relief valve and high-pressure fusible plug protect the system against dangerously high pressures by discharging refrigerant in a controlled manner." },
  { id:"epa608_96", categoria:"EPA608_CORE", pregunta:"¿Qué regulación específica de la EPA requiere que los técnicos reparen fugas en equipos grandes?", opciones:["La regla de reporte de emisiones de la Sección 608 para grandes instalaciones industriales","La regla de eliminación de equipos obsoletos de la Sección 608 para sistemas antiguos","La regla de sustitución obligatoria de refrigerantes de la Sección 612 para sistemas CFC","La regla de reparación obligatoria de fugas de la Sección 608 para sistemas con 50+ lbs"], respuesta_correcta:3, explicacion:"La regla de reparación de fugas (leak repair rule) de la Sección 608 requiere que los propietarios de sistemas con 50+ lbs reparen fugas que excedan las tasas máximas." , question: "What specific EPA regulation requires technicians to repair leaks in large equipment?", options: ["The emissions reporting rule of Section 608 for large industrial facilities", "The obsolete equipment elimination rule of Section 608 for older systems", "The mandatory refrigerant substitution rule of Section 612 for CFC systems", "The mandatory leak repair rule of Section 608 for systems with 50+ lbs"], explanation: "The leak repair rule of Section 608 requires that owners of systems with 50+ lbs repair leaks that exceed the maximum allowable rates." },
  { id:"epa608_97", categoria:"EPA608_CORE", pregunta:"¿Cuál es el propósito del programa de certificación de técnicos bajo la Sección 608 de la EPA?", opciones:["Limitar la cantidad de técnicos que pueden trabajar con refrigerantes en el mercado laboral","Generar ingresos para la EPA mediante las tarifas de examen de certificación técnica cobradas","Crear un registro nacional de técnicos para cobrar impuestos sobre servicios de refrigeración","Asegurar que solo técnicos capacitados manejen refrigerantes para proteger el ozono y clima"], respuesta_correcta:3, explicacion:"El programa de certificación asegura que los técnicos conozcan las prácticas correctas de manejo de refrigerantes para minimizar emisiones que dañan el ozono y el clima." , question: "What is the purpose of the technician certification program under Section 608 of the EPA?", options: ["To limit the number of technicians who can work with refrigerants in the labor market", "To generate revenue for the EPA through certification exam fees charged", "To create a national registry of technicians for taxing refrigeration services", "To ensure that only trained technicians handle refrigerants to protect the ozone and climate"], explanation: "The certification program ensures that technicians know the correct refrigerant handling practices to minimize emissions that damage the ozone layer and the climate." },
  { id:"epa608_98", categoria:"EPA608_CORE", pregunta:"¿Qué información debe registrarse cada vez que se agrega refrigerante a un sistema con 50+ libras?", opciones:["Solo la fecha del servicio y el nombre del técnico que realizó el trabajo de carga","Solo la cantidad total de refrigerante en el sistema después de la recarga completa final","La fecha, tipo de refrigerante, cantidad agregada y la identidad del técnico certificado","La marca del refrigerante, el precio pagado y el proveedor que vendió el refrigerante"], respuesta_correcta:2, explicacion:"Los registros deben incluir fecha, tipo de refrigerante, cantidad agregada/recuperada, e identificación del técnico certificado que realizó el servicio." , question: "What information must be recorded each time refrigerant is added to a system with 50+ pounds?", options: ["Only the service date and the name of the technician who performed the work", "Only the total amount of refrigerant in the system after the complete final recharge", "The date, type of refrigerant, quantity added, and the identity of the certified technician", "The refrigerant brand, the price paid, and the supplier who sold the refrigerant"], explanation: "Records must include the date, type of refrigerant, quantity added/recovered, and identification of the certified technician who performed the service." },
  { id:"epa608_99", categoria:"EPA608_CORE", pregunta:"¿Qué acción legal puede tomar la EPA además de multas contra violadores de la Sección 608?", opciones:["Solo puede imponer multas monetarias sin ninguna otra acción legal adicional posible","Solo puede revocar la certificación sin imponer multas ni penas adicionales al técnico","Puede imponer multas pero no puede revocar certificaciones ni ordenar encarcelamiento","Puede imponer multas, ordenar encarcelamiento y revocar la certificación del técnico"], respuesta_correcta:3, explicacion:"La EPA puede imponer multas de hasta $44,539/día, revocar la certificación del técnico y, en casos graves, referir para procesamiento criminal con posible encarcelamiento." , question: "What legal action can the EPA take in addition to fines against violators of Section 608?", options: ["It can only impose monetary fines with no other legal action available", "It can only revoke certification without imposing fines or additional penalties", "It can impose fines but cannot revoke certifications or order imprisonment", "It can impose fines, order imprisonment, and revoke the technician's certification"], explanation: "The EPA can impose fines of up to $44,539/day, revoke the technician's certification, and in serious cases, refer for criminal prosecution with possible imprisonment." },
  { id:"epa608_100", categoria:"EPA608_CORE", pregunta:"¿Cuál es la función principal de la Enmienda de Kigali con respecto a la industria de refrigeración?", opciones:["Reducir gradualmente la producción y consumo de refrigerantes HFC por su alto potencial GWP","Eliminar completamente el uso de todos los refrigerantes sintéticos a nivel mundial para 2030","Prohibir inmediatamente todos los refrigerantes con ODP mayor a cero en países desarrollados","Crear un fondo global para financiar la transición a refrigerantes naturales en todos países"], respuesta_correcta:0, explicacion:"La Enmienda de Kigali (2016) al Protocolo de Montreal establece un calendario para reducir gradualmente los HFC un 80-85% para 2047 debido a su alto GWP." , question: "What is the main function of the Kigali Amendment with respect to the refrigeration industry?", options: ["To gradually reduce the production and consumption of HFC refrigerants due to their high GWP", "To completely eliminate the use of all synthetic refrigerants worldwide by 2030", "To immediately ban all refrigerants with an ODP greater than zero in developed countries", "To create a global fund to finance the transition to natural refrigerants in all countries"], explanation: "The Kigali Amendment (2016) to the Montreal Protocol establishes a schedule to gradually reduce HFCs by 80-85% by 2047 due to their high GWP." },
  // ── TIPO I (101-200) ──────────────────────────────────────────
  { id:"epa608_101", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la cantidad máxima de refrigerante que puede contener un sistema Tipo I según la EPA?", opciones:["5 libras (2.27 kg)","10 libras (4.54 kg)","3 libras (1.36 kg)","8 libras (3.63 kg)"], respuesta_correcta:0, explicacion:"Los sistemas Tipo I son aparatos pequeños sellados de fábrica que contienen 5 libras (2.27 kg) o menos de refrigerante." , question: "What is the maximum amount of refrigerant that a Type I system can contain according to the EPA?", options: ["5 pounds (2.27 kg)", "10 pounds (4.54 kg)", "3 pounds (1.36 kg)", "8 pounds (3.63 kg)"], explanation: "Type I systems are small factory-sealed appliances that contain 5 pounds (2.27 kg) or less of refrigerant." },
  { id:"epa608_102", categoria:"EPA608_TIPO1", pregunta:"¿Qué característica define a un sistema hermético sellado de fábrica?", opciones:["No tiene puertos de servicio instalados de fábrica","El compresor puede ser reemplazado en campo","Utiliza un compresor de tipo semi-hermético","Tiene válvulas de servicio accesibles al técnico"], respuesta_correcta:0, explicacion:"Los sistemas herméticos sellados de fábrica no tienen puertos de servicio; el técnico debe instalar válvulas de acceso para dar servicio." , question: "What characteristic defines a factory-sealed hermetic system?", options: ["It has no factory-installed service ports", "The compressor can be replaced in the field", "It uses a semi-hermetic compressor", "It has service valves accessible to the technician"], explanation: "Factory-sealed hermetic systems have no service ports; the technician must install access valves to perform service." },
  { id:"epa608_103", categoria:"EPA608_TIPO1", pregunta:"¿Cuál de los siguientes es un ejemplo de aparato Tipo I?", opciones:["Chiller centrífugo de 200 toneladas","Refrigerador doméstico con R-134a","Sistema split residencial de 3 toneladas","Unidad rooftop comercial de 15 toneladas"], respuesta_correcta:1, explicacion:"Los refrigeradores domésticos son sistemas herméticos sellados de fábrica con menos de 5 libras de refrigerante, clasificados como Tipo I." , question: "Which of the following is an example of a Type I appliance?", options: ["A 200-ton centrifugal chiller", "A household refrigerator with R-134a", "A 3-ton residential split system", "A 15-ton commercial rooftop unit"], explanation: "Household refrigerators are factory-sealed hermetic systems with less than 5 pounds of refrigerant, classified as Type I." },
  { id:"epa608_104", categoria:"EPA608_TIPO1", pregunta:"¿Qué método de recuperación se usa cuando el compresor del aparato Tipo I funciona correctamente?", opciones:["Recuperación activa con máquina externa","Venteo controlado a la atmósfera con filtro","Recuperación pasiva usando el propio compresor","Recuperación criogénica con nitrógeno líquido"], respuesta_correcta:2, explicacion:"Cuando el compresor funciona, se usa recuperación pasiva: el propio compresor del sistema bombea el refrigerante al tanque de recuperación." , question: "What recovery method is used when the compressor of a Type I appliance is operating correctly?", options: ["Active recovery with an external machine", "Controlled venting to the atmosphere through a filter", "Passive recovery using the appliance's own compressor", "Cryogenic recovery with liquid nitrogen"], explanation: "When the compressor is operational, passive recovery is used: the appliance's own compressor pumps the refrigerant into the recovery tank." },
  { id:"epa608_105", categoria:"EPA608_TIPO1", pregunta:"¿Cuándo se requiere una máquina de recuperación activa en un sistema Tipo I?", opciones:["Cuando el compresor del aparato no funciona","Cuando el refrigerante es inflamable tipo A3","Cuando el sistema tiene más de 5 libras total","Cuando el sistema fue fabricado antes de 1993"], respuesta_correcta:0, explicacion:"Se necesita recuperación activa (máquina externa) cuando el compresor del aparato no funciona y no puede bombear su propio refrigerante." , question: "When is an active recovery machine required for a Type I system?", options: ["When the appliance's compressor is not operating", "When the refrigerant is a Class A3 flammable type", "When the system contains more than 5 pounds total", "When the system was manufactured before 1993"], explanation: "Active recovery (external machine) is needed when the appliance's compressor is not working and cannot pump its own refrigerant." },
  { id:"epa608_106", categoria:"EPA608_TIPO1", pregunta:"¿Qué porcentaje de refrigerante debe recuperarse de un sistema Tipo I cuyo compresor funciona (pre-1993)?", opciones:["80% del refrigerante total del sistema","95% del refrigerante total del sistema","100% del refrigerante total del sistema","90% del refrigerante total del sistema"], respuesta_correcta:3, explicacion:"Cuando el compresor funciona en equipos fabricados antes del 15 de noviembre de 1993, se debe recuperar el 90% del refrigerante." , question: "What percentage of refrigerant must be recovered from a Type I system whose compressor operates (pre-1993)?", options: ["80% of the system's total refrigerant", "95% of the system's total refrigerant", "100% of the system's total refrigerant", "90% of the system's total refrigerant"], explanation: "When the compressor operates in equipment manufactured before November 15, 1993, 90% of the refrigerant must be recovered." },
  { id:"epa608_107", categoria:"EPA608_TIPO1", pregunta:"¿Qué porcentaje de recuperación se exige cuando el compresor del Tipo I no funciona (pre-1993)?", opciones:["90% del refrigerante en el sistema","80% del refrigerante en el sistema","85% del refrigerante en el sistema","70% del refrigerante en el sistema"], respuesta_correcta:1, explicacion:"Cuando el compresor no funciona en equipos pre-noviembre 1993, el requisito mínimo de recuperación es del 80%." , question: "What recovery percentage is required when the Type I compressor is not operating (pre-1993)?", options: ["90% of the refrigerant in the system", "80% of the refrigerant in the system", "85% of the refrigerant in the system", "70% of the refrigerant in the system"], explanation: "When the compressor is not operating in pre-November 1993 equipment, the minimum recovery requirement is 80%." },
  { id:"epa608_108", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de válvula se instala comúnmente para acceder a un sistema hermético sellado?", opciones:["Válvula de bola de tres vías estándar","Válvula de expansión termostática ajustable","Válvula de perforación tipo bullet o saddle","Válvula solenoide de control electrónico"], respuesta_correcta:2, explicacion:"Las válvulas de perforación (bullet piercing valve o saddle valve) se usan para crear un puerto de acceso en tubería de sistemas herméticos." , question: "What type of valve is commonly installed to gain access to a factory-sealed hermetic system?", options: ["A standard three-way ball valve", "An adjustable thermostatic expansion valve", "A bullet or saddle piercing valve", "An electronic solenoid control valve"], explanation: "Piercing valves (bullet piercing valve or saddle valve) are used to create an access port on the tubing of hermetic systems." },
  { id:"epa608_109", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el refrigerante más común en refrigeradores domésticos modernos?", opciones:["R-134a (HFC tetrafluoroetano)","R-410A (mezcla de HFC azeotrópica)","R-404A (mezcla HFC para baja temp)","R-22 (HCFC clorodifluorometano)"], respuesta_correcta:0, explicacion:"El R-134a es el refrigerante HFC estándar en refrigeradores domésticos modernos, reemplazando al R-12 que dañaba la capa de ozono." , question: "What is the most common refrigerant in modern household refrigerators?", options: ["R-134a (HFC tetrafluoroethane)", "R-410A (near-azeotropic HFC blend)", "R-404A (HFC blend for low temperature)", "R-22 (HCFC chlorodifluoromethane)"], explanation: "R-134a is the standard HFC refrigerant in modern household refrigerators, replacing R-12, which damaged the ozone layer." },
  { id:"epa608_110", categoria:"EPA608_TIPO1", pregunta:"¿Qué clasificación de seguridad tiene el refrigerante R-600a (isobutano)?", opciones:["A3 — altamente inflamable baja toxicidad","B1 — no inflamable y mayor toxicidad","A2L — ligeramente inflamable baja toxicidad","A1 — no inflamable y baja toxicidad"], respuesta_correcta:0, explicacion:"El R-600a (isobutano) tiene clasificación A3: altamente inflamable con baja toxicidad. Se requieren precauciones especiales contra chispas." , question: "What is the safety classification of the refrigerant R-600a (isobutane)?", options: ["A3 — highly flammable, low toxicity", "B1 — non-flammable, higher toxicity", "A2L — mildly flammable, low toxicity", "A1 — non-flammable, low toxicity"], explanation: "R-600a (isobutane) has a classification of A3: highly flammable with low toxicity. Special precautions against sparks are required." },
  { id:"epa608_111", categoria:"EPA608_TIPO1", pregunta:"¿Qué refrigerante hidrocarburo se usa en algunos refrigeradores europeos y domésticos?", opciones:["R-404A (mezcla HFC comercial estándar)","R-600a (isobutano para refrigeración)","R-290 (propano para aire acondicionado)","R-407C (mezcla HFC residencial común)"], respuesta_correcta:1, explicacion:"El R-600a (isobutano) se utiliza en refrigeradores domésticos, especialmente en Europa, por su bajo impacto ambiental (GWP=3)." , question: "What hydrocarbon refrigerant is used in some European and domestic refrigerators?", options: ["R-404A (standard commercial HFC blend)", "R-600a (isobutane for refrigeration)", "R-290 (propane for air conditioning)", "R-407C (common residential HFC blend)"], explanation: "R-600a (isobutane) is used in household refrigerators, especially in Europe, due to its low environmental impact (GWP = 3)." },
  { id:"epa608_112", categoria:"EPA608_TIPO1", pregunta:"¿Qué precaución especial se debe tomar al trabajar con R-290 (propano)?", opciones:["Usar gafas de protección contra radiación UV","Aplicar aceite mineral en todas las conexiones","Evitar chispas y fuentes de ignición cercanas","Mantener el sistema presurizado durante reparación"], respuesta_correcta:2, explicacion:"El R-290 (propano) es altamente inflamable (A3). Se deben evitar chispas, llamas abiertas y cualquier fuente de ignición en el área de trabajo." , question: "What special precaution must be taken when working with R-290 (propane)?", options: ["Wear UV protection goggles", "Apply mineral oil to all connections", "Avoid sparks and nearby ignition sources", "Keep the system pressurized during repair"], explanation: "R-290 (propane) is highly flammable (A3). Sparks, open flames, and any ignition sources must be avoided in the work area." },
  { id:"epa608_113", categoria:"EPA608_TIPO1", pregunta:"¿Qué dispositivo de medición se usa típicamente en sistemas Tipo I?", opciones:["Válvula de expansión termostática (TXV)","Válvula de expansión electrónica (EEV)","Orificio calibrado con flotador interno","Tubo capilar de diámetro pequeño y fijo"], respuesta_correcta:3, explicacion:"Los sistemas pequeños Tipo I generalmente usan tubos capilares como dispositivo de medición por su simplicidad y bajo costo." , question: "What metering device is typically used in Type I systems?", options: ["Thermostatic expansion valve (TXV)", "Electronic expansion valve (EEV)", "Calibrated orifice with internal float", "Small fixed-diameter capillary tube"], explanation: "Small Type I systems generally use capillary tubes as the metering device due to their simplicity and low cost." },
  { id:"epa608_114", categoria:"EPA608_TIPO1", pregunta:"¿Qué sucede si se llena un cilindro de recuperación a más del 80% de su capacidad?", opciones:["El refrigerante pierde sus propiedades químicas","Puede explotar por expansión térmica del líquido","Se reduce la eficiencia de recuperación del gas","El cilindro se congela y deja de aceptar gas"], respuesta_correcta:1, explicacion:"Llenar un cilindro más del 80% es peligroso porque el líquido se expande con el calor, pudiendo causar una explosión hidrostática." , question: "What can happen if a recovery cylinder is filled to more than 80% of its capacity?", options: ["The refrigerant loses its chemical properties", "It can explode due to thermal expansion of the liquid", "The gas recovery efficiency is reduced", "The cylinder freezes and stops accepting gas"], explanation: "Filling a cylinder beyond 80% is dangerous because the liquid expands with heat, potentially causing a hydrostatic explosion." },
  { id:"epa608_115", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe hacer un técnico ANTES de enviar un aparato Tipo I al desguace?", opciones:["Drenar el aceite del compresor al alcantarillado","Perforar el sistema para liberar presión rápidamente","Cortar las líneas de refrigerante para facilitar reciclaje","Recuperar el refrigerante según regulaciones de la EPA"], respuesta_correcta:3, explicacion:"La EPA exige que todo refrigerante sea recuperado antes de desechar cualquier aparato, incluyendo los de Tipo I." , question: "What must a technician do BEFORE sending a Type I appliance to scrap?", options: ["Drain the compressor oil into the sewer", "Puncture the system to release pressure quickly", "Cut the refrigerant lines to facilitate recycling", "Recover the refrigerant according to EPA regulations"], explanation: "The EPA requires that all refrigerant be recovered before disposing of any appliance, including Type I appliances." },
  { id:"epa608_116", categoria:"EPA608_TIPO1", pregunta:"¿Qué certificación necesita un técnico para comprar refrigerante en cantidades mayores a 2 libras?", opciones:["Certificación EPA Sección 608 de cualquier tipo","Licencia estatal de contratista HVAC general","Certificación OSHA de seguridad en el trabajo","Permiso municipal de manejo de materiales peligrosos"], respuesta_correcta:0, explicacion:"La EPA requiere certificación Sección 608 (Tipo I, II, III o Universal) para comprar refrigerante en contenedores de más de 2 libras." , question: "What certification does a technician need to purchase refrigerant in quantities greater than 2 pounds?", options: ["EPA Section 608 certification of any type", "A state HVAC general contractor license", "OSHA workplace safety certification", "A municipal hazardous materials handling permit"], explanation: "The EPA requires Section 608 certification (Type I, II, III, or Universal) to purchase refrigerant in containers of more than 2 pounds." },
  { id:"epa608_117", categoria:"EPA608_TIPO1", pregunta:"¿Se requiere llevar registros de recuperación para aparatos Tipo I?", opciones:["Sí, se deben guardar registros por 5 años mínimo","No, los registros no son requeridos para Tipo I","Sí, pero solo si el aparato usa refrigerante CFC","No, excepto si el sistema tiene más de 3 libras"], respuesta_correcta:1, explicacion:"Los aparatos con menos de 50 libras de refrigerante no requieren registros de servicio bajo las regulaciones EPA 608." , question: "Are recovery records required for Type I appliances?", options: ["Yes, records must be kept for a minimum of 5 years", "No, records are not required for Type I", "Yes, but only if the appliance uses CFC refrigerant", "No, except if the system contains more than 3 pounds"], explanation: "Appliances with less than 50 pounds of refrigerant do not require service records under EPA 608 regulations." },
  { id:"epa608_118", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de equipo de recuperación se conecta al sistema del aparato para funcionar?", opciones:["Equipo de recuperación autocontenido independiente","Equipo de recuperación de alta presión directa","Equipo de recuperación dependiente del sistema","Equipo de recuperación criogénica especializado"], respuesta_correcta:2, explicacion:"El equipo dependiente del sistema (system-dependent) usa el compresor del propio aparato para mover el refrigerante al tanque de recuperación." , question: "What type of recovery equipment connects to the appliance's system to operate?", options: ["Self-contained independent recovery equipment", "Direct high-pressure recovery equipment", "System-dependent recovery equipment", "Specialized cryogenic recovery equipment"], explanation: "System-dependent equipment uses the appliance's own compressor to move the refrigerant into the recovery tank." },
  { id:"epa608_119", categoria:"EPA608_TIPO1", pregunta:"¿Qué equipo de recuperación tiene su propio compresor incorporado?", opciones:["Equipo dependiente del sistema hermético sellado","Equipo autocontenido (self-contained) completo","Equipo de recuperación pasiva estándar del campo","Equipo de recuperación por gravedad sencilla"], respuesta_correcta:1, explicacion:"El equipo autocontenido (self-contained) tiene su propio compresor y puede recuperar refrigerante sin depender del sistema del aparato." , question: "What recovery equipment has its own built-in compressor?", options: ["System-dependent sealed hermetic equipment", "Self-contained recovery equipment", "Standard field passive recovery equipment", "Simple gravity recovery equipment"], explanation: "Self-contained recovery equipment has its own compressor and can recover refrigerant without depending on the appliance's system." },
  { id:"epa608_120", categoria:"EPA608_TIPO1", pregunta:"¿Qué refrigerante CFC fue ampliamente usado en refrigeradores domésticos antiguos?", opciones:["R-12 (diclorodifluorometano CFC común)","R-22 (clorodifluorometano HCFC común)","R-502 (mezcla azeotrópica para baja temp)","R-11 (triclorofluorometano para chillers)"], respuesta_correcta:0, explicacion:"El R-12 fue el refrigerante CFC estándar en refrigeradores domésticos hasta que fue prohibido por destruir la capa de ozono." , question: "What CFC refrigerant was widely used in older household refrigerators?", options: ["R-12 (dichlorodifluoromethane, a common CFC)", "R-22 (chlorodifluoromethane, a common HCFC)", "R-502 (azeotropic blend for low temperature)", "R-11 (trichlorofluoromethane for chillers)"], explanation: "R-12 was the standard CFC refrigerant in household refrigerators until it was banned for destroying the ozone layer." },
  { id:"epa608_121", categoria:"EPA608_TIPO1", pregunta:"¿Qué componente filtra la humedad y ácidos en un sistema Tipo I?", opciones:["El acumulador de succión del compresor hermético","El intercambiador de calor de subenfriamiento interno","El filtro secador (filter-drier) de la línea","El separador de aceite en la línea de descarga"], respuesta_correcta:2, explicacion:"El filtro secador (filter-drier) elimina humedad, ácidos y partículas del refrigerante, protegiendo el sistema de daños internos." , question: "What component filters moisture and acids in a Type I system?", options: ["The hermetic compressor suction accumulator", "The internal subcooling heat exchanger", "The filter-drier on the line", "The oil separator on the discharge line"], explanation: "The filter-drier removes moisture, acids, and particles from the refrigerant, protecting the system from internal damage." },
  { id:"epa608_122", categoria:"EPA608_TIPO1", pregunta:"¿Qué causa la formación de ácidos dentro de un sistema hermético?", opciones:["Exceso de aceite lubricante en el compresor","Sobrecarga de refrigerante en el sistema cerrado","Temperatura ambiente demasiado baja en operación","Presencia de humedad mezclada con refrigerante"], respuesta_correcta:3, explicacion:"La humedad dentro del sistema reacciona con el refrigerante y el aceite, formando ácidos que corroen componentes internos." , question: "What causes the formation of acids inside a hermetic system?", options: ["Excess lubricating oil in the compressor", "Refrigerant overcharge in the sealed system", "Excessively low ambient operating temperature", "The presence of moisture mixed with refrigerant"], explanation: "Moisture inside the system reacts with the refrigerant and oil, forming acids that corrode internal components." },
  { id:"epa608_123", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica un olor a quemado en el aceite de un compresor hermético?", opciones:["El compresor sufrió una quemadura interna (burnout)","El compresor necesita más aceite lubricante nuevo","El refrigerante del sistema es de tipo incorrecto","El filtro secador está saturado y necesita cambio"], respuesta_correcta:0, explicacion:"Un olor a quemado en el aceite indica quemadura del compresor (burnout), donde el motor eléctrico se quemó y contaminó el sistema con ácido." , question: "What does a burnt smell in the oil of a hermetic compressor indicate?", options: ["The compressor suffered an internal burnout", "The compressor needs more new lubricating oil", "The system's refrigerant is the wrong type", "The filter-drier is saturated and needs replacement"], explanation: "A burnt smell in the oil indicates a compressor burnout, where the electric motor burned and contaminated the system with acid." },
  { id:"epa608_124", categoria:"EPA608_TIPO1", pregunta:"¿Qué contaminante se genera típicamente después de una quemadura de compresor?", opciones:["Nitrógeno molecular atrapado en el aceite","Agua destilada de la condensación del motor","Ácido clorhídrico o fluorhídrico en el sistema","Carbón activado de los bobinados internos"], respuesta_correcta:2, explicacion:"La quemadura del compresor descompone el refrigerante y el aceite, generando ácidos como el clorhídrico (HCl) o fluorhídrico (HF)." , question: "What contaminant is typically generated after a compressor burnout?", options: ["Molecular nitrogen trapped in the oil", "Distilled water from motor condensation", "Hydrochloric acid or hydrofluoric acid in the system", "Activated carbon from the internal windings"], explanation: "A compressor burnout decomposes the refrigerant and oil, generating acids such as hydrochloric acid (HCl) or hydrofluoric acid (HF)." },
  { id:"epa608_125", categoria:"EPA608_TIPO1", pregunta:"¿Qué regulación del DOT aplica al transporte de cilindros de refrigerante recuperado?", opciones:["Los cilindros deben estar pintados de color amarillo","Los cilindros pueden transportarse sin etiquetas especiales","Los cilindros deben cumplir especificaciones DOT/UN","Solo se necesita factura del proveedor del refrigerante"], respuesta_correcta:2, explicacion:"Los cilindros de recuperación deben cumplir con las especificaciones DOT para transporte seguro de gases comprimidos." , question: "What DOT regulation applies to the transport of recovered refrigerant cylinders?", options: ["Cylinders must be painted yellow", "Cylinders can be transported without special labels", "Cylinders must meet DOT/UN specifications", "Only a supplier invoice for the refrigerant is needed"], explanation: "Recovery cylinders must comply with DOT specifications for the safe transport of compressed gases." },
  { id:"epa608_126", categoria:"EPA608_TIPO1", pregunta:"¿De qué color son típicamente los cilindros de recuperación de refrigerante?", opciones:["Azul con franja blanca en la parte superior","Gris con tapa amarilla como identificación estándar","Verde con franja roja para materiales peligrosos","Amarillo con tapa gris como estándar de la industria"], respuesta_correcta:3, explicacion:"Los cilindros de recuperación son amarillos con tapa gris, según el estándar ARI 740 para identificar refrigerante recuperado." , question: "What color are refrigerant recovery cylinders typically?", options: ["Blue with a white stripe on top", "Gray with a yellow cap as the standard identifier", "Green with a red stripe for hazardous materials", "Yellow with a gray cap as the industry standard"], explanation: "Recovery cylinders are yellow with a gray cap, per the ARI 740 standard for identifying recovered refrigerant." },
  { id:"epa608_127", categoria:"EPA608_TIPO1", pregunta:"¿Qué sucede si un técnico ventea refrigerante intencionalmente a la atmósfera?", opciones:["Puede enfrentar multas de hasta $44,539 por día","Recibe una advertencia verbal sin consecuencias legales","Solo se le requiere completar un curso de actualización","No hay penalidad si el sistema tiene menos de 5 libras"], respuesta_correcta:0, explicacion:"La EPA impone multas severas de hasta $44,539 o más por día por venteo intencional de refrigerante, sin importar la cantidad." , question: "What happens if a technician intentionally vents refrigerant to the atmosphere?", options: ["They can face fines of up to $44,539 per day", "They receive a verbal warning with no legal consequences", "They are only required to complete a refresher course", "There is no penalty if the system has less than 5 pounds"], explanation: "The EPA imposes severe fines of up to $44,539 or more per day for intentional venting of refrigerant, regardless of the quantity." },
  { id:"epa608_128", categoria:"EPA608_TIPO1", pregunta:"¿Cuál de estos aparatos NO es típicamente un sistema Tipo I?", opciones:["Enfriador de agua de oficina compacto y sellado","Máquina expendedora de refrescos fríos pequeña","Deshumidificador portátil doméstico estándar","Sistema central split residencial de 5 toneladas"], respuesta_correcta:3, explicacion:"Un sistema central split de 5 toneladas contiene mucho más de 5 libras de refrigerante, clasificándose como Tipo II, no Tipo I." , question: "Which of these appliances is NOT typically a Type I system?", options: ["A compact office water cooler, sealed", "A small cold beverage vending machine", "A standard portable household dehumidifier", "A 5-ton residential central split system"], explanation: "A 5-ton central split system contains well over 5 pounds of refrigerant, classifying it as Type II, not Type I." },
  { id:"epa608_129", categoria:"EPA608_TIPO1", pregunta:"¿Qué método se usa para detectar fugas en un sistema hermético pequeño?", opciones:["Presurizar con refrigerante R-22 y usar detector","Abrir el sistema y hacer inspección visual directa","Presurizar con nitrógeno seco y aplicar agua jabonosa","Añadir aceite fluorescente y esperar tres semanas"], respuesta_correcta:2, explicacion:"Se presuriza el sistema con nitrógeno seco y se aplica solución jabonosa en las conexiones para detectar burbujas en posibles fugas." , question: "What method is used to detect leaks in a small hermetic system?", options: ["Pressurize with R-22 refrigerant and use a detector", "Open the system and perform a direct visual inspection", "Pressurize with dry nitrogen and apply soapy water", "Add fluorescent oil and wait three weeks"], explanation: "The system is pressurized with dry nitrogen and soapy solution is applied to the connections to detect bubbles at possible leak points." },
  { id:"epa608_130", categoria:"EPA608_TIPO1", pregunta:"¿Por qué NUNCA se debe usar oxígeno para presurizar un sistema de refrigeración?", opciones:["El oxígeno congela las válvulas del sistema sellado","El oxígeno puede explotar al mezclarse con aceite","El oxígeno causa corrosión inmediata del cobre interno","El oxígeno descompone el filtro secador rápidamente"], respuesta_correcta:1, explicacion:"El oxígeno comprimido mezclado con aceite del sistema puede causar una explosión violenta. Solo se usa nitrógeno seco para pruebas." , question: "Why should oxygen NEVER be used to pressurize a refrigeration system?", options: ["Oxygen freezes the sealed system valves", "Oxygen can explode when mixed with oil", "Oxygen causes immediate corrosion of internal copper", "Oxygen breaks down the filter-drier rapidly"], explanation: "Compressed oxygen mixed with the system's oil can cause a violent explosion. Only dry nitrogen is used for pressure tests." },
  { id:"epa608_131", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de aceite lubricante usan los sistemas con R-134a?", opciones:["Aceite mineral (MO) de alta viscosidad estándar","Aceite alquilbenceno (AB) sintético puro comercial","Aceite polialquilenglicol (PAG) automotriz especial","Aceite polioléster (POE) sintético miscible con HFC"], respuesta_correcta:3, explicacion:"El R-134a requiere aceite POE (polioléster) porque es miscible con refrigerantes HFC, a diferencia del aceite mineral que no lo es." , question: "What type of lubricating oil do R-134a systems use?", options: ["High-viscosity standard mineral oil (MO)", "Pure commercial synthetic alkylbenzene (AB) oil", "Automotive-specific polyalkylene glycol (PAG) oil", "Polyol ester (POE) synthetic oil miscible with HFC"], explanation: "R-134a requires POE (polyol ester) oil because it is miscible with HFC refrigerants, unlike mineral oil, which is not." },
  { id:"epa608_132", categoria:"EPA608_TIPO1", pregunta:"¿Qué problema causa el 'oil logging' en un sistema Tipo I?", opciones:["El aceite se acumula en el evaporador reduciendo transferencia de calor","El aceite obstruye el tubo capilar reduciendo el flujo de refrigerante","El aceite aumenta la presión del lado de alta excesivamente en operación","El aceite se evapora completamente y daña el compresor seco del sistema"], respuesta_correcta:0, explicacion:"El oil logging ocurre cuando el aceite se acumula en el evaporador, reduciendo la transferencia de calor y la eficiencia del sistema." , question: "What problem does 'oil logging' cause in a Type I system?", options: ["Oil accumulates in the evaporator, reducing heat transfer", "Oil clogs the capillary tube, reducing refrigerant flow", "Oil excessively increases the high-side pressure during operation", "Oil evaporates completely and damages the dry compressor"], explanation: "Oil logging occurs when oil accumulates in the evaporator, reducing heat transfer and system efficiency." },
  { id:"epa608_133", categoria:"EPA608_TIPO1", pregunta:"¿Qué válvula deben tener los contenedores pequeños de refrigerante según la EPA?", opciones:["Válvula de alivio de presión de doble asiento industrial","Válvula de tres vías con manómetro incorporado preciso","Válvula autosellante (self-sealing) para evitar emisiones","Válvula de cierre manual con rosca NPT estándar"], respuesta_correcta:2, explicacion:"Desde 2018, la EPA requiere que los contenedores pequeños de refrigerante tengan válvulas autosellantes para minimizar emisiones." , question: "What valve must small refrigerant containers have according to the EPA?", options: ["An industrial double-seated pressure relief valve", "A three-way valve with a built-in precision gauge", "A self-sealing valve to prevent emissions", "A manual shutoff valve with standard NPT threads"], explanation: "Since 2018, the EPA requires small refrigerant containers to have self-sealing valves to minimize emissions." },
  { id:"epa608_134", categoria:"EPA608_TIPO1", pregunta:"¿Qué certificación EPA permite trabajar SOLO con aparatos pequeños Tipo I?", opciones:["Certificación Tipo II para equipos de alta presión","Certificación Tipo III para aparatos de baja presión","Certificación Universal que cubre todas las categorías","Certificación Tipo I para aparatos pequeños sellados"], respuesta_correcta:3, explicacion:"La certificación Tipo I autoriza al técnico a trabajar exclusivamente con aparatos pequeños con 5 libras o menos de refrigerante." , question: "What EPA certification allows working ONLY with Type I small appliances?", options: ["Type II certification for high-pressure equipment", "Type III certification for low-pressure equipment", "Universal certification covering all categories", "Type I certification for small sealed appliances"], explanation: "Type I certification authorizes the technician to work exclusively with small appliances containing 5 pounds or less of refrigerant." },
  { id:"epa608_135", categoria:"EPA608_TIPO1", pregunta:"¿Cuántos tipos de certificación EPA 608 existen para técnicos?", opciones:["Cuatro tipos: Tipo I, II, III y Universal completo","Dos tipos: residencial y comercial estándar únicamente","Tres tipos: pequeño, mediano y grande industrial","Cinco tipos: I, II, III, IV y Universal completo"], respuesta_correcta:0, explicacion:"Existen cuatro certificaciones: Tipo I (pequeños), Tipo II (alta presión), Tipo III (baja presión) y Universal (cubre los tres tipos)." , question: "How many types of EPA 608 certification exist for technicians?", options: ["Four types: Type I, II, III, and Universal", "Two types: residential and commercial standard only", "Three types: small, medium, and large industrial", "Five types: I, II, III, IV, and Universal"], explanation: "There are four certifications: Type I (small appliances), Type II (high-pressure), Type III (low-pressure), and Universal (covers all three types)." },
  { id:"epa608_136", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe verificar un técnico antes de usar un cilindro de recuperación?", opciones:["Que el cilindro haya sido pintado recientemente amarillo","Que el cilindro tenga etiqueta del fabricante original","Que la fecha de recertificación DOT esté vigente","Que el cilindro esté completamente vacío sin residuos"], respuesta_correcta:2, explicacion:"Los cilindros DOT deben recertificarse cada 5 años. Usar un cilindro con certificación vencida es una violación de seguridad." , question: "What should a technician verify before using a recovery cylinder?", options: ["That the cylinder has been recently painted yellow", "That the cylinder has the original manufacturer's label", "That the DOT retest date is current", "That the cylinder is completely empty with no residue"], explanation: "DOT cylinders must be retested every 5 years. Using a cylinder with an expired certification is a safety violation." },
  { id:"epa608_137", categoria:"EPA608_TIPO1", pregunta:"¿Qué componente en un PTAC lo clasificaría como Tipo I?", opciones:["Que tenga control de temperatura digital integrado","Que contenga 5 libras o menos de refrigerante total","Que esté instalado en la pared de un hotel comercial","Que use electricidad como fuente principal de energía"], respuesta_correcta:1, explicacion:"Un PTAC se clasifica como Tipo I solo si contiene 5 libras o menos de refrigerante, independientemente de su ubicación o tipo." , question: "What component in a PTAC would classify it as Type I?", options: ["Having an integrated digital temperature control", "Containing 5 pounds or less of total refrigerant", "Being installed in the wall of a commercial hotel", "Using electricity as its primary energy source"], explanation: "A PTAC is classified as Type I only if it contains 5 pounds or less of refrigerant, regardless of its location or type." },
  { id:"epa608_138", categoria:"EPA608_TIPO1", pregunta:"¿Qué le sucede a un tubo capilar si entra humedad al sistema?", opciones:["La humedad se congela y bloquea el tubo capilar","El tubo se corroe y se rompe causando fuga grande","La humedad lubrica el tubo mejorando la circulación","El tubo se expande y permite más flujo refrigerante"], respuesta_correcta:0, explicacion:"La humedad se congela en la restricción del tubo capilar, bloqueando el flujo de refrigerante y causando falla del sistema." , question: "What happens to a capillary tube if moisture enters the system?", options: ["The moisture freezes and blocks the capillary tube", "The tube corrodes and breaks, causing a large leak", "The moisture lubricates the tube, improving circulation", "The tube expands and allows more refrigerant flow"], explanation: "Moisture freezes at the restriction of the capillary tube, blocking refrigerant flow and causing system failure." },
  { id:"epa608_139", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica una lectura de vacío que sube rápidamente después de evacuar?", opciones:["Hay una fuga en el sistema o en las conexiones","La bomba de vacío funcionó mejor de lo esperado","El refrigerante nuevo ya está entrando al sistema","El sistema está completamente limpio y seco ahora"], respuesta_correcta:0, explicacion:"Si el vacío sube rápidamente al apagar la bomba, hay una fuga que permite la entrada de aire al sistema." , question: "What does a vacuum reading that rises rapidly after evacuation indicate?", options: ["There is a leak in the system or at the connections", "The vacuum pump worked better than expected", "New refrigerant is already entering the system", "The system is completely clean and dry now"], explanation: "If the vacuum rises rapidly when the pump is turned off, there is a leak allowing air to enter the system." },
  { id:"epa608_140", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la función principal del condensador en un refrigerador doméstico?", opciones:["Absorber el calor del interior del refrigerador frío","Rechazar el calor del refrigerante al ambiente externo","Regular el flujo de refrigerante al evaporador interno","Comprimir el vapor de refrigerante a alta presión"], respuesta_correcta:1, explicacion:"El condensador rechaza el calor absorbido del interior del refrigerador hacia el ambiente exterior, condensando el refrigerante." , question: "What is the primary function of the condenser in a household refrigerator?", options: ["To absorb heat from the cold interior of the refrigerator", "To reject heat from the refrigerant to the external environment", "To regulate the flow of refrigerant to the internal evaporator", "To compress the refrigerant vapor to high pressure"], explanation: "The condenser rejects heat absorbed from the interior of the refrigerator to the outside environment, condensing the refrigerant." },
  { id:"epa608_141", categoria:"EPA608_TIPO1", pregunta:"¿Dónde se instala generalmente la válvula de perforación en un sistema hermético?", opciones:["En el evaporador directamente sobre la placa fría","En el tubo de succión o en la línea de proceso","En el tubo capilar antes de entrada al evaporador","En la línea de líquido después del condensador"], respuesta_correcta:1, explicacion:"Las válvulas de perforación se instalan típicamente en el tubo de succión o la línea de proceso para acceder al sistema sellado." , question: "Where is the piercing valve generally installed on a hermetic system?", options: ["On the evaporator directly on the cold plate", "On the suction tube or the process line", "On the capillary tube before the evaporator inlet", "On the liquid line after the condenser"], explanation: "Piercing valves are typically installed on the suction tube or the process line to gain access to the sealed system." },
  { id:"epa608_142", categoria:"EPA608_TIPO1", pregunta:"¿Qué refrigerante antiguo tiene el mayor potencial de destrucción de ozono (ODP)?", opciones:["R-134a con ODP de 0.00 y clasificación HFC puro","R-12 con ODP de 1.0 y clasificación CFC puro alto","R-22 con ODP de 0.055 y clasificación HCFC medio","R-410A con ODP de 0.00 y clasificación HFC nuevo"], respuesta_correcta:1, explicacion:"El R-12 (CFC) tiene un ODP de 1.0, el más alto entre los refrigerantes comunes, razón por la cual fue eliminado gradualmente." , question: "Which legacy refrigerant has the highest Ozone Depletion Potential (ODP)?", options: ["R-134a with an ODP of 0.00 and a pure HFC classification", "R-12 with an ODP of 1.0 and a pure CFC classification", "R-22 with an ODP of 0.055 and a medium HCFC classification", "R-410A with an ODP of 0.00 and a new HFC classification"], explanation: "R-12 (CFC) has an ODP of 1.0, the highest among common refrigerants, which is why it was gradually phased out." },
  { id:"epa608_143", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe hacer un técnico si encuentra un refrigerador con fuga conocida de R-12?", opciones:["Recargar con R-12 y sellar la fuga con epóxico rápido","Ventear el R-12 restante porque es cantidad pequeña","Recuperar el R-12 restante antes de cualquier reparación","Mezclar R-12 con R-134a para completar la carga total"], respuesta_correcta:2, explicacion:"Siempre se debe recuperar el refrigerante antes de reparar, sin importar el tipo o cantidad. Ventear es ilegal." , question: "What must a technician do if they find a refrigerator with a known R-12 leak?", options: ["Recharge with R-12 and seal the leak with quick epoxy", "Vent the remaining R-12 because the quantity is small", "Recover the remaining R-12 before any repair", "Mix R-12 with R-134a to complete the total charge"], explanation: "Refrigerant must always be recovered before making repairs, regardless of the type or quantity. Venting is illegal." },
  { id:"epa608_144", categoria:"EPA608_TIPO1", pregunta:"¿Se pueden mezclar diferentes refrigerantes en un mismo cilindro de recuperación?", opciones:["Sí, siempre que sean del mismo grupo químico HFC","No, cada tipo de refrigerante debe ir en cilindro separado","Sí, si la cantidad total es menor a 5 libras en total","No, excepto si ambos refrigerantes son inflamables A3"], respuesta_correcta:1, explicacion:"Nunca se deben mezclar refrigerantes diferentes en un mismo cilindro. Cada tipo debe recuperarse en su propio cilindro separado." , question: "Can different refrigerants be mixed in the same recovery cylinder?", options: ["Yes, as long as they are from the same HFC chemical group", "No, each type of refrigerant must go in a separate cylinder", "Yes, if the total amount is less than 5 pounds", "No, except if both refrigerants are A3 flammable types"], explanation: "Different refrigerants must never be mixed in the same cylinder. Each type must be recovered into its own separate cylinder." },
  { id:"epa608_145", categoria:"EPA608_TIPO1", pregunta:"¿Qué sucede si se libera R-600a en un espacio cerrado sin ventilación?", opciones:["No pasa nada porque la cantidad es muy pequeña","Se crea riesgo de explosión por ser gas inflamable A3","Se forma un gas tóxico que irrita las vías respiratorias","Se genera nube visible que activa detectores de humo"], respuesta_correcta:1, explicacion:"El R-600a (isobutano) es altamente inflamable (A3). En espacios cerrados puede alcanzar concentración explosiva con cualquier chispa." , question: "What happens if R-600a is released in an enclosed space without ventilation?", options: ["Nothing happens because the quantity is very small", "An explosion risk is created because it is a flammable A3 gas", "A toxic gas forms that irritates the respiratory tract", "A visible cloud forms that activates smoke detectors"], explanation: "R-600a (isobutane) is highly flammable (A3). In enclosed spaces, it can reach explosive concentration with any spark." },
  { id:"epa608_146", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la presión de operación típica del lado bajo en un refrigerador con R-134a?", opciones:["Aproximadamente 2 a 5 psig en condiciones normales","Aproximadamente 50 a 70 psig en condiciones de operación","Aproximadamente 100 a 120 psig en condiciones estándar","Aproximadamente 150 a 180 psig en condiciones normales"], respuesta_correcta:0, explicacion:"Los refrigeradores domésticos con R-134a operan con presiones bajas en el lado de succión, típicamente entre 2 y 5 psig." , question: "What is the typical low-side operating pressure in a refrigerator with R-134a?", options: ["Approximately 2 to 5 psig under normal conditions", "Approximately 50 to 70 psig under operating conditions", "Approximately 100 to 120 psig under standard conditions", "Approximately 150 to 180 psig under normal conditions"], explanation: "Household refrigerators with R-134a operate with low suction-side pressures, typically between 2 and 5 psig." },
  { id:"epa608_147", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica aceite alrededor de una conexión en un sistema hermético?", opciones:["Probable fuga de refrigerante en esa conexión del sistema","Es condensación normal por diferencia de temperatura","El compresor está bombeando aceite en vez de refrigerante","El sistema tiene exceso de aceite y necesita drenado"], respuesta_correcta:0, explicacion:"Las manchas de aceite en conexiones indican fugas de refrigerante, ya que el aceite viaja con el refrigerante y se deposita donde hay escape." , question: "What does oil around a connection on a hermetic system indicate?", options: ["A probable refrigerant leak at that system connection", "It is normal condensation due to temperature difference", "The compressor is pumping oil instead of refrigerant", "The system has excess oil and needs to be drained"], explanation: "Oil stains at connections indicate refrigerant leaks, since oil travels with the refrigerant and deposits where there is an escape." },
  { id:"epa608_148", categoria:"EPA608_TIPO1", pregunta:"¿Qué hace un técnico con refrigerante recuperado que no puede ser identificado?", opciones:["Lo recarga en cualquier sistema que necesite refrigerante","Lo envía a un centro de reclamación para su análisis","Lo ventea al ambiente porque no se puede reciclar sin ID","Lo almacena indefinidamente hasta identificar su tipo"], respuesta_correcta:1, explicacion:"El refrigerante no identificado debe enviarse a un reclamador certificado que puede analizarlo, reciclarlo o destruirlo adecuadamente." , question: "What does a technician do with recovered refrigerant that cannot be identified?", options: ["Recharge it into any system that needs refrigerant", "Send it to a reclamation center for analysis", "Vent it to the atmosphere because it cannot be recycled without ID", "Store it indefinitely until its type can be identified"], explanation: "Unidentified refrigerant must be sent to a certified reclaimer who can analyze it, recycle it, or destroy it properly." },
  { id:"epa608_149", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la diferencia entre reciclaje y reclamación de refrigerante?", opciones:["Reciclaje es en campo con filtros; reclamación es en planta certificada a estándar ARI 700","Reciclaje se hace solo con CFC; reclamación solo con HFC y mezclas nuevas del mercado","Reciclaje destruye el refrigerante; reclamación lo reutiliza directamente sin procesar","No hay diferencia, ambos términos significan exactamente lo mismo para la EPA federal"], respuesta_correcta:0, explicacion:"El reciclaje es limpieza básica en campo. La reclamación se hace en instalaciones certificadas que procesan el refrigerante a estándar ARI 700." , question: "What is the difference between recycling and reclamation of refrigerant?", options: ["Recycling is done in the field with filters; reclamation is done at a certified facility to ARI 700 standards", "Recycling is done only with CFCs; reclamation only with HFCs and new blends on the market", "Recycling destroys the refrigerant; reclamation reuses it directly without processing", "There is no difference; both terms mean exactly the same thing according to federal EPA"], explanation: "Recycling is basic cleaning in the field. Reclamation is done at certified facilities that process the refrigerant to ARI 700 standards." },
  { id:"epa608_150", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de detector de fugas es más sensible para detectar fugas pequeñas?", opciones:["Detector de agua jabonosa aplicada con brocha","Detector de llama de haluro (antorcha halógena)","Detector electrónico de fugas de refrigerante","Detector ultravioleta con tinte fluorescente"], respuesta_correcta:2, explicacion:"Los detectores electrónicos son los más sensibles y pueden detectar fugas de menos de 0.5 oz por año en sistemas pequeños." , question: "What type of leak detector is most sensitive for detecting small leaks?", options: ["Soapy water detector applied with a brush", "Halide flame detector (halogen torch)", "Electronic refrigerant leak detector", "Ultraviolet detector with fluorescent dye"], explanation: "Electronic detectors are the most sensitive and can detect leaks of less than 0.5 oz per year in small systems." },
  { id:"epa608_151", categoria:"EPA608_TIPO1", pregunta:"¿Cuántas libras mínimo debe contener un recipiente para requerir certificación EPA para su compra?", opciones:["Más de 5 libras de refrigerante en el contenedor","Más de 2 libras de refrigerante en el contenedor","Más de 1 libra de refrigerante en el contenedor","Más de 10 libras de refrigerante en el contenedor"], respuesta_correcta:1, explicacion:"Se requiere certificación EPA 608 para comprar refrigerante en contenedores de más de 2 libras. Latas pequeñas están exentas." , question: "What is the minimum container size that requires EPA certification to purchase?", options: ["More than 5 pounds of refrigerant in the container", "More than 2 pounds of refrigerant in the container", "More than 1 pound of refrigerant in the container", "More than 10 pounds of refrigerant in the container"], explanation: "EPA 608 certification is required to purchase refrigerant in containers of more than 2 pounds. Small cans are exempt." },
  { id:"epa608_152", categoria:"EPA608_TIPO1", pregunta:"¿Qué aparato Tipo I puede contener refrigerante R-290 (propano)?", opciones:["Chiller comercial de gran capacidad industrial pesada","Sistemas VRF para edificios de oficinas grandes multi-piso","Torres de enfriamiento para procesos industriales pesados","Algunos refrigeradores domésticos de nueva generación"], respuesta_correcta:3, explicacion:"Algunos refrigeradores y congeladores domésticos modernos usan R-290 (propano) por su bajo GWP, en cantidades muy pequeñas." , question: "What Type I appliance can contain R-290 (propane) refrigerant?", options: ["A heavy-duty large-capacity commercial chiller", "Multi-floor office building VRF systems", "Cooling towers for heavy industrial processes", "Some new-generation household refrigerators"], explanation: "Some modern household refrigerators and freezers use R-290 (propane) due to its low GWP, in very small quantities." },
  { id:"epa608_153", categoria:"EPA608_TIPO1", pregunta:"¿Qué precaución se toma al soldar en un sistema que usó R-600a?", opciones:["Evacuar completamente y purgar con nitrógeno antes de soldar","Usar soldadura de plata de alta temperatura únicamente especial","Aplicar flux adicional para neutralizar el gas inflamable residual","Soldar rápidamente para minimizar la exposición del técnico"], respuesta_correcta:0, explicacion:"Antes de soldar en un sistema con refrigerante inflamable como R-600a, se debe evacuar todo el refrigerante y purgar con nitrógeno." , question: "What precaution is taken when brazing on a system that used R-600a?", options: ["Evacuate completely and purge with nitrogen before brazing", "Use only high-temperature silver brazing alloy", "Apply extra flux to neutralize residual flammable gas", "Braze quickly to minimize technician exposure"], explanation: "Before brazing on a system with a flammable refrigerant like R-600a, all refrigerant must be evacuated and the system purged with nitrogen." },
  { id:"epa608_154", categoria:"EPA608_TIPO1", pregunta:"¿Qué componente protege el compresor de líquido refrigerante que retorna?", opciones:["El filtro secador instalado en la línea de líquido","El tubo capilar que restringe el flujo del líquido","El acumulador de succión antes del compresor hermético","El condensador que enfría el gas de alta presión caliente"], respuesta_correcta:2, explicacion:"El acumulador de succión atrapa líquido refrigerante antes de que entre al compresor, evitando daño por golpe de líquido (slugging)." , question: "What component protects the compressor from returning liquid refrigerant?", options: ["The filter-drier installed on the liquid line", "The capillary tube that restricts liquid flow", "The suction accumulator before the hermetic compressor", "The condenser that cools the hot high-pressure gas"], explanation: "The suction accumulator traps liquid refrigerant before it enters the compressor, preventing damage from liquid slugging." },
  { id:"epa608_155", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el GWP (potencial de calentamiento global) del R-600a?", opciones:["GWP de 1430, similar al del R-134a estándar actual","GWP de 3, extremadamente bajo entre todos los refrigerantes","GWP de 675, moderado entre los HFC comunes del mercado","GWP de 2088, muy alto entre todos los refrigerantes usados"], respuesta_correcta:1, explicacion:"El R-600a tiene un GWP de solo 3, mucho menor que el R-134a (GWP 1430), lo que lo hace ambientalmente favorable." , question: "What is the GWP (Global Warming Potential) of R-600a?", options: ["A GWP of 1,430, similar to current standard R-134a", "A GWP of 3, extremely low among all refrigerants", "A GWP of 675, moderate among common HFCs on the market", "A GWP of 2,088, very high among all refrigerants in use"], explanation: "R-600a has a GWP of only 3, much lower than R-134a (GWP 1,430), making it environmentally favorable." },
  { id:"epa608_156", categoria:"EPA608_TIPO1", pregunta:"¿Quién puede legalmente desechar un electrodoméstico que contiene refrigerante?", opciones:["Cualquier persona siempre que lo lleve al vertedero municipal","El propietario del aparato sin ningún requisito adicional","Solo el fabricante original del aparato bajo garantía vigente","Solo técnico certificado EPA después de recuperar el refrigerante"], respuesta_correcta:3, explicacion:"Un técnico certificado EPA debe recuperar el refrigerante antes del desecho. Los desguazadores también deben tener certificación." , question: "Who can legally dispose of a household appliance that contains refrigerant?", options: ["Anyone as long as they take it to the municipal landfill", "The appliance owner without any additional requirements", "Only the original manufacturer of the appliance under active warranty", "Only an EPA-certified technician after recovering the refrigerant"], explanation: "An EPA-certified technician must recover the refrigerant before disposal. Scrap dealers must also have certification." },
  { id:"epa608_157", categoria:"EPA608_TIPO1", pregunta:"¿Qué obligación tienen los centros de reciclaje de metales respecto a refrigerantes?", opciones:["Pueden destruir los aparatos sin preocuparse del refrigerante","Deben verificar que el refrigerante fue recuperado antes de procesar","Solo necesitan reportar los aparatos que llegan con refrigerante","Pueden ventear el refrigerante si el aparato es muy viejo o dañado"], respuesta_correcta:1, explicacion:"Los centros de reciclaje deben asegurar que el refrigerante ha sido recuperado antes de procesar el aparato como chatarra." , question: "What obligation do metal recycling centers have regarding refrigerants?", options: ["They can destroy appliances without worrying about the refrigerant", "They must verify that the refrigerant was recovered before processing", "They only need to report appliances that arrive with refrigerant", "They can vent the refrigerant if the appliance is very old or damaged"], explanation: "Recycling centers must ensure that the refrigerant has been recovered before processing the appliance as scrap." },
  { id:"epa608_158", categoria:"EPA608_TIPO1", pregunta:"¿Qué gas se usa para hacer una prueba de presión en un sistema Tipo I?", opciones:["Aire comprimido del taller a alta presión disponible","Nitrógeno seco (OFN) libre de humedad contaminante","Dióxido de carbono (CO2) de grado industrial puro","Argón industrial de alta pureza especial para soldadura"], respuesta_correcta:1, explicacion:"Se usa nitrógeno seco (OFN - Oxygen Free Nitrogen) para pruebas de presión porque es inerte, seco y no contamina el sistema." , question: "What gas is used to perform a pressure test on a Type I system?", options: ["High-pressure shop compressed air", "Dry nitrogen (OFN) free of moisture contamination", "Industrial-grade pure carbon dioxide (CO2)", "High-purity industrial argon special for welding"], explanation: "Dry nitrogen (OFN - Oxygen-Free Nitrogen) is used for pressure tests because it is inert, dry, and does not contaminate the system." },
  { id:"epa608_159", categoria:"EPA608_TIPO1", pregunta:"¿Por qué es importante poner a tierra (grounding) el equipo al trabajar con R-290?", opciones:["Para mejorar la eficiencia del compresor del sistema","Para evitar chispas estáticas que podrían encender el gas","Para proteger los circuitos electrónicos del aparato","Para cumplir con el código eléctrico local únicamente"], respuesta_correcta:1, explicacion:"El R-290 es inflamable. La conexión a tierra previene la acumulación de electricidad estática que podría generar chispas e ignición." , question: "Why is it important to ground equipment when working with R-290?", options: ["To improve the system's compressor efficiency", "To prevent static sparks that could ignite the gas", "To protect the appliance's electronic circuits", "To comply with local electrical code only"], explanation: "R-290 is flammable. Grounding prevents the buildup of static electricity that could generate sparks and ignition." },
  { id:"epa608_160", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la temperatura de ebullición del R-134a a presión atmosférica?", opciones:["Aproximadamente -21.6°F (-29.8°C) a presión normal","Aproximadamente +26.1°F (-3.3°C) a presión normal","Aproximadamente -15.0°F (-26.1°C) a presión atmosférica","Aproximadamente +5.0°F (-15.0°C) a presión normal"], respuesta_correcta:2, explicacion:"El R-134a tiene un punto de ebullición de aproximadamente -15°F (-26.1°C) a presión atmosférica, adecuado para refrigeración doméstica." , question: "What is the boiling point of R-134a at atmospheric pressure?", options: ["Approximately -21.6 degrees F (-29.8 degrees C) at normal pressure", "Approximately +26.1 degrees F (-3.3 degrees C) at normal pressure", "Approximately -15.0 degrees F (-26.1 degrees C) at atmospheric pressure", "Approximately +5.0 degrees F (-15.0 degrees C) at normal pressure"], explanation: "R-134a has a boiling point of approximately -15 degrees F (-26.1 degrees C) at atmospheric pressure, suitable for household refrigeration." },
  { id:"epa608_161", categoria:"EPA608_TIPO1", pregunta:"¿Qué ocurre si se carga un sistema R-134a con R-12 por error?", opciones:["El sistema funciona mejor por la mayor eficiencia del R-12","El R-12 se convierte en R-134a dentro del sistema cerrado","No hay efecto porque ambos refrigerantes son casi idénticos","Los aceites son incompatibles causando falla del compresor"], respuesta_correcta:3, explicacion:"El R-12 usa aceite mineral y el R-134a usa POE. Mezclarlos causa incompatibilidad del aceite y falla prematura del compresor." , question: "What happens if an R-134a system is charged with R-12 by mistake?", options: ["The system runs better due to R-12's greater efficiency", "R-12 converts into R-134a inside the sealed system", "There is no effect because both refrigerants are nearly identical", "The oils are incompatible, causing compressor failure"], explanation: "R-12 uses mineral oil and R-134a uses POE. Mixing them causes oil incompatibility and premature compressor failure." },
  { id:"epa608_162", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el propósito de la línea de proceso (process tube) en un sistema hermético?", opciones:["Sirve como línea principal de líquido entre componentes","Funciona como bypass de emergencia si el capilar se obstruye","Es el puerto de servicio para carga, evacuación y recuperación","Conecta el motor eléctrico al compresor dentro del hermético"], respuesta_correcta:2, explicacion:"La línea de proceso (process tube) es el punto de acceso del técnico para cargar, evacuar y recuperar refrigerante del sistema hermético." , question: "What is the purpose of the process tube on a hermetic system?", options: ["It serves as the main liquid line between components", "It functions as an emergency bypass if the capillary clogs", "It is the service port for charging, evacuation, and recovery", "It connects the electric motor to the compressor inside the hermetic unit"], explanation: "The process tube is the technician's access point for charging, evacuating, and recovering refrigerant from the hermetic system." },
  { id:"epa608_163", categoria:"EPA608_TIPO1", pregunta:"¿Qué herramienta se necesita para instalar una válvula de perforación tipo bullet?", opciones:["Un soplete de acetileno para soldar la válvula al tubo","Una herramienta de perforación específica para válvula bullet","Una llave de torque calibrada para apretar a especificación","Un taladro eléctrico con broca para cobre de 1/4 pulgada"], respuesta_correcta:1, explicacion:"Las válvulas bullet requieren una herramienta de perforación específica que perfora la tubería y sella simultáneamente." , question: "What tool is needed to install a bullet-type piercing valve?", options: ["An acetylene torch to braze the valve to the tube", "A specific piercing tool for bullet valves", "A calibrated torque wrench to tighten to specification", "An electric drill with a 1/4-inch copper bit"], explanation: "Bullet valves require a specific piercing tool that punctures the tubing and seals simultaneously." },
  { id:"epa608_164", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica una presión de succión más alta de lo normal en un refrigerador?", opciones:["El compresor tiene válvulas de succión defectuosas o con fuga","El sistema tiene muy poco refrigerante en el circuito cerrado","El condensador está extremadamente sucio bloqueando el aire","El tubo capilar está parcialmente obstruido reduciendo el flujo"], respuesta_correcta:0, explicacion:"Una presión de succión alta puede indicar válvulas de succión con fuga en el compresor, que no comprimen adecuadamente." , question: "What does a higher-than-normal suction pressure in a refrigerator indicate?", options: ["The compressor has defective or leaking suction valves", "The system has too little refrigerant in the sealed circuit", "The condenser is extremely dirty and blocking airflow", "The capillary tube is partially clogged, reducing flow"], explanation: "High suction pressure can indicate leaking suction valves in the compressor, which are not compressing adequately." },
  { id:"epa608_165", categoria:"EPA608_TIPO1", pregunta:"¿Cuánto tiempo mínimo se debe mantener el vacío para verificar que no hay fugas?", opciones:["Solo 30 segundos es suficiente para verificación rápida","No es necesario esperar, se verifica con manómetro instantáneo","Se mantiene 24 horas completas antes de cargar el refrigerante","Mínimo 10 minutos observando que el vacío se mantenga estable"], respuesta_correcta:3, explicacion:"Se debe mantener el vacío por al menos 10 minutos. Si la presión sube, hay una fuga que debe repararse antes de cargar." , question: "What is the minimum time the vacuum should be held to verify there are no leaks?", options: ["Only 30 seconds is sufficient for a quick check", "No waiting is necessary; it is verified instantly with the gauge", "The vacuum is held for a full 24 hours before charging refrigerant", "A minimum of 10 minutes, observing that the vacuum remains stable"], explanation: "The vacuum should be held for at least 10 minutes. If the pressure rises, there is a leak that must be repaired before charging." },
  { id:"epa608_166", categoria:"EPA608_TIPO1", pregunta:"¿Qué refrigerante sustituyó al R-12 en la mayoría de los refrigeradores nuevos?", opciones:["R-22 como sustituto directo del R-12 en domésticos","R-134a como reemplazo HFC sin destrucción del ozono","R-410A como reemplazo de alta eficiencia del R-12 viejo","R-404A como reemplazo de baja temperatura del R-12 antiguo"], respuesta_correcta:1, explicacion:"El R-134a reemplazó al R-12 en refrigeradores domésticos porque no contiene cloro y tiene ODP de cero." , question: "What refrigerant replaced R-12 in most new refrigerators?", options: ["R-22 as a direct replacement for R-12 in household units", "R-134a as an HFC replacement with no ozone destruction", "R-410A as a high-efficiency replacement for old R-12", "R-404A as a low-temperature replacement for old R-12"], explanation: "R-134a replaced R-12 in household refrigerators because it contains no chlorine and has an ODP of zero." },
  { id:"epa608_167", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de recuperación usa una unidad de ventana cuando su compresor funciona?", opciones:["Recuperación activa con equipo autocontenido externo","Recuperación por vacío profundo con bomba de dos etapas","Recuperación dependiente del sistema (pasiva) con su compresor","Recuperación por desplazamiento con nitrógeno presurizado"], respuesta_correcta:2, explicacion:"Si el compresor funciona, se usa recuperación pasiva (system-dependent) donde el propio compresor mueve el refrigerante al cilindro." , question: "What type of recovery is used on a window unit when its compressor is working?", options: ["Active recovery with external self-contained equipment", "Deep vacuum recovery with a two-stage pump", "System-dependent (passive) recovery using its own compressor", "Displacement recovery with pressurized nitrogen"], explanation: "If the compressor works, system-dependent (passive) recovery is used, where the unit's own compressor moves the refrigerant to the cylinder." },
  { id:"epa608_168", categoria:"EPA608_TIPO1", pregunta:"¿Es legal que un técnico Tipo I repare un sistema central residencial de 3 toneladas?", opciones:["Sí, porque todos los sistemas residenciales son Tipo I","Sí, si el sistema tiene menos de 10 libras de refrigerante","No, pero puede hacerlo bajo supervisión de un técnico Universal","No, necesita certificación Tipo II o Universal para ese sistema"], respuesta_correcta:3, explicacion:"Un sistema central de 3 toneladas es alta presión con más de 5 lb, requiriendo certificación Tipo II o Universal." , question: "Is it legal for a Type I technician to repair a 3-ton residential central system?", options: ["Yes, because all residential systems are Type I", "Yes, if the system has less than 10 pounds of refrigerant", "No, but they can do it under the supervision of a Universal technician", "No, they need Type II or Universal certification for that system"], explanation: "A 3-ton central system is high-pressure with more than 5 lb, requiring Type II or Universal certification." },
  { id:"epa608_169", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe hacer un técnico si sospecha refrigerante incorrecto en un sistema?", opciones:["Agregar más del refrigerante correcto para diluir el incorrecto","Recuperar todo el refrigerante e identificarlo antes de recargar","Ventear una pequeña cantidad y oler para identificar el tipo","Operar el sistema 24 horas para que los refrigerantes se mezclen"], respuesta_correcta:1, explicacion:"Se debe recuperar todo el refrigerante y analizarlo. Nunca mezclar refrigerantes ni ventear para identificación." , question: "What should a technician do if they suspect incorrect refrigerant in a system?", options: ["Add more of the correct refrigerant to dilute the incorrect one", "Recover all the refrigerant and identify it before recharging", "Vent a small amount and smell it to identify the type", "Run the system for 24 hours so the refrigerants blend together"], explanation: "All the refrigerant must be recovered and analyzed. Never mix refrigerants or vent to identify them." },
  { id:"epa608_170", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el máximo nivel de llenado permitido para un cilindro de recuperación?", opciones:["60% de la capacidad total de agua del cilindro","80% de la capacidad total de agua del cilindro","70% de la capacidad total de agua del cilindro","90% de la capacidad total de agua del cilindro"], respuesta_correcta:1, explicacion:"Los cilindros de recuperación no deben llenarse más del 80% de su capacidad para dejar espacio de expansión térmica segura." , question: "What is the maximum fill level allowed for a recovery cylinder?", options: ["60% of the cylinder's total water capacity", "80% of the cylinder's total water capacity", "70% of the cylinder's total water capacity", "90% of the cylinder's total water capacity"], explanation: "Recovery cylinders must not be filled beyond 80% of their capacity to leave room for safe thermal expansion." },
  { id:"epa608_171", categoria:"EPA608_TIPO1", pregunta:"¿Qué instrumento se usa para verificar el peso de refrigerante en un cilindro?", opciones:["Un manómetro de alta precisión digital calibrado","Un termómetro infrarrojo apuntando al cilindro lleno","Una báscula electrónica certificada para refrigerantes","Un detector de nivel ultrasónico para líquidos presurizados"], respuesta_correcta:2, explicacion:"Se usa una báscula electrónica para pesar el cilindro y verificar que no exceda el 80% de capacidad por peso neto." , question: "What instrument is used to verify the weight of refrigerant in a cylinder?", options: ["A calibrated high-precision digital gauge", "An infrared thermometer pointed at the full cylinder", "A certified electronic scale for refrigerants", "An ultrasonic liquid level detector for pressurized containers"], explanation: "An electronic scale is used to weigh the cylinder and verify that it does not exceed 80% of capacity by net weight." },
  { id:"epa608_172", categoria:"EPA608_TIPO1", pregunta:"¿Qué ocurre cuando el evaporador de un refrigerador acumula exceso de escarcha?", opciones:["El refrigerador enfría más eficientemente por el hielo","El compresor funciona más rápido compensando automáticamente","El termostato apaga el sistema para proteger el motor","Se reduce la transferencia de calor y la eficiencia baja"], respuesta_correcta:3, explicacion:"El exceso de escarcha actúa como aislante, reduciendo la transferencia de calor y haciendo que el compresor trabaje más tiempo.", question: "What happens when a refrigerator's evaporator accumulates excessive frost?", options: ["The refrigerator cools more efficiently because of the ice", "The compressor runs faster to compensate automatically", "The thermostat shuts the system down to protect the motor", "Heat transfer is reduced and efficiency decreases"], explanation: "Excessive frost acts as an insulator, reducing heat transfer and causing the compressor to run longer." },
  { id:"epa608_173", categoria:"EPA608_TIPO1", pregunta:"¿Qué refrigerante es considerado 'drop-in' directo para reemplazar R-12 sin cambios?", opciones:["R-134a sin ninguna modificación necesaria al sistema","R-290 como reemplazo directo ecológico del R-12 viejo","R-401A (MP39) como sustituto HCFC temporal del R-12","Ninguno es verdadero drop-in; todos requieren cambios"], respuesta_correcta:3, explicacion:"No existe un verdadero 'drop-in' para R-12. Incluso R-134a requiere cambio de aceite a POE y otros ajustes al sistema." , question: "Which refrigerant is considered a true 'drop-in' replacement for R-12 with no changes required?", options: ["R-134a with no modifications needed to the system", "R-290 as a direct ecological replacement for older R-12", "R-401A (MP39) as a temporary HCFC substitute for R-12", "None is a true drop-in; all require changes"], explanation: "There is no true 'drop-in' replacement for R-12. Even R-134a requires an oil change to POE and other system adjustments." },
  { id:"epa608_174", categoria:"EPA608_TIPO1", pregunta:"¿Qué componente de un refrigerador doméstico libera calor al ambiente?", opciones:["El evaporador ubicado dentro del compartimiento frío","El tubo capilar que conecta condensador con evaporador","El compresor hermético ubicado en la base del aparato","El condensador ubicado en la parte trasera del aparato"], respuesta_correcta:3, explicacion:"El condensador, ubicado generalmente atrás del refrigerador, libera el calor absorbido del interior hacia el ambiente." , question: "Which component of a domestic refrigerator releases heat to the surrounding environment?", options: ["The evaporator located inside the cold compartment", "The capillary tube that connects the condenser to the evaporator", "The hermetic compressor located at the base of the appliance", "The condenser located on the back of the appliance"], explanation: "The condenser, typically located on the back of the refrigerator, releases the heat absorbed from the interior to the surrounding environment." },
  { id:"epa608_175", categoria:"EPA608_TIPO1", pregunta:"¿Qué pasa si un refrigerador opera con carga baja de refrigerante?", opciones:["El compresor se sobrecalienta y puede dañarse prematuramente","El refrigerador enfría más rápido por tener menos masa térmica","La presión del lado alto aumenta significativamente en operación","El evaporador produce más escarcha de lo normal en las paredes"], respuesta_correcta:0, explicacion:"Con carga baja, el compresor pierde el efecto de enfriamiento del refrigerante de succión, causando sobrecalentamiento y posible daño." , question: "What happens if a refrigerator operates with a low refrigerant charge?", options: ["The compressor overheats and may suffer premature damage", "The refrigerator cools faster due to less thermal mass", "The high-side pressure increases significantly during operation", "The evaporator produces more frost than normal on its walls"], explanation: "With a low charge, the compressor loses the cooling effect of suction refrigerant, causing overheating and possible damage." },
  { id:"epa608_176", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la función de la válvula Schrader en un sistema de refrigeración?", opciones:["Regular automáticamente la presión máxima del sistema","Prevenir el retorno de aceite al evaporador del sistema","Controlar el flujo de refrigerante al tubo capilar interno","Permitir conexión de mangueras para servicio y medición"], respuesta_correcta:3, explicacion:"La válvula Schrader permite conectar mangueras de servicio para medir presiones, cargar, evacuar o recuperar refrigerante." , question: "What is the function of a Schrader valve in a refrigeration system?", options: ["To automatically regulate the maximum system pressure", "To prevent oil from returning to the system evaporator", "To control the refrigerant flow to the internal capillary tube", "To allow connection of service hoses for measurement and servicing"], explanation: "The Schrader valve allows service hoses to be connected for measuring pressures, charging, evacuating, or recovering refrigerant." },
  { id:"epa608_177", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica un compresor que arranca y se detiene rápidamente (short cycling)?", opciones:["El termostato está ajustado a la temperatura correcta ideal","El sistema está funcionando en modo de descongelamiento normal","El ventilador del condensador está funcionando muy rápido","Posible sobrecarga eléctrica o protector térmico activándose"], respuesta_correcta:3, explicacion:"El short cycling indica problemas como sobrecarga eléctrica, protector térmico defectuoso, o presiones anormales del sistema." , question: "What does it indicate when a compressor starts and stops rapidly (short cycling)?", options: ["The thermostat is set to the correct ideal temperature", "The system is operating in normal defrost mode", "The condenser fan is running too fast", "Possible electrical overload or thermal protector activating"], explanation: "Short cycling indicates problems such as electrical overload, a defective thermal protector, or abnormal system pressures." },
  { id:"epa608_178", categoria:"EPA608_TIPO1", pregunta:"¿Qué se debe hacer con el aceite recuperado de un sistema con compresor quemado?", opciones:["Desecharlo adecuadamente porque está contaminado con ácidos","Reutilizarlo en otro sistema del mismo tipo de refrigerante","Filtrarlo y devolverlo al mismo sistema después de reparar","Mezclarlo con aceite nuevo para reducir costo de mantenimiento"], respuesta_correcta:0, explicacion:"El aceite de un compresor quemado está contaminado con ácidos y residuos de la quemadura. Debe desecharse adecuadamente." , question: "What should be done with oil recovered from a system with a burned compressor?", options: ["Dispose of it properly because it is contaminated with acids", "Reuse it in another system that uses the same refrigerant type", "Filter it and return it to the same system after the repair", "Mix it with new oil to reduce maintenance costs"], explanation: "Oil from a burned compressor is contaminated with acids and burnout residues. It must be disposed of properly." },
  { id:"epa608_179", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la temperatura típica del evaporador en un congelador doméstico?", opciones:["Entre 32°F y 40°F (0°C a 4.4°C) aproximadamente normal","Entre 20°F y 25°F (-6.7°C a -3.9°C) aproximadamente","Entre 0°F y 10°F (-17.8°C a -12.2°C) aproximadamente","Entre -20°F y -10°F (-28.9°C a -23.3°C) para congelación"], respuesta_correcta:3, explicacion:"Los congeladores domésticos operan con temperaturas de evaporador entre -20°F y -10°F para mantener alimentos congelados." , question: "What is the typical evaporator temperature in a domestic freezer?", options: ["Between 32 deg F and 40 deg F (0 deg C to 4.4 deg C) approximately", "Between 20 deg F and 25 deg F (-6.7 deg C to -3.9 deg C) approximately", "Between 0 deg F and 10 deg F (-17.8 deg C to -12.2 deg C) approximately", "Between -20 deg F and -10 deg F (-28.9 deg C to -23.3 deg C) for freezing"], explanation: "Domestic freezers operate with evaporator temperatures between -20 deg F and -10 deg F to keep food frozen." },
  { id:"epa608_180", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe verificar un técnico antes de perforar una tubería con válvula bullet?", opciones:["Que la tubería sea de aluminio y no de cobre estándar","Que el sistema esté apagado y el refrigerante recuperado","Que la presión del sistema sea mayor a 100 psig mínimo","Que la válvula bullet sea del tamaño correcto para tubería"], respuesta_correcta:3, explicacion:"La válvula bullet debe ser del tamaño correcto para la tubería. Una medida incorrecta causa fugas o daño a la línea." , question: "What should a technician verify before piercing a line with a bullet valve?", options: ["That the tubing is aluminum rather than standard copper", "That the system is off and the refrigerant has been recovered", "That the system pressure is above 100 psig minimum", "That the bullet valve is the correct size for the tubing"], explanation: "The bullet valve must be the correct size for the tubing. An incorrect size causes leaks or damage to the line." },
  { id:"epa608_181", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la principal razón por la que los HFC reemplazaron a los CFC?", opciones:["Los HFC son más baratos de producir industrialmente hoy","Los HFC tienen mejor eficiencia energética en todos sistemas","Los HFC son completamente no inflamables en cualquier caso","Los HFC no contienen cloro y no destruyen capa de ozono"], respuesta_correcta:3, explicacion:"Los HFC (como R-134a) no contienen cloro, por lo que tienen un ODP de cero y no destruyen la capa de ozono." , question: "What is the main reason HFCs replaced CFCs?", options: ["HFCs are cheaper to produce industrially today", "HFCs have better energy efficiency in all systems", "HFCs are completely non-flammable under any conditions", "HFCs do not contain chlorine and do not destroy the ozone layer"], explanation: "HFCs (such as R-134a) do not contain chlorine, so they have an ODP of zero and do not destroy the ozone layer." },
  { id:"epa608_182", categoria:"EPA608_TIPO1", pregunta:"¿Qué método de carga es más preciso para sistemas Tipo I con carga crítica?", opciones:["Carga por presión usando manómetros de alta precisión","Carga por temperatura del evaporador con termómetro","Carga por peso usando báscula electrónica según especificación","Carga por sobrecalentamiento y subenfriamiento con termoacoplador"], respuesta_correcta:2, explicacion:"Los sistemas pequeños con carga crítica se cargan mejor por peso, ya que cantidades pequeñas afectan significativamente el rendimiento." , question: "Which charging method is most accurate for Type I systems with a critical charge?", options: ["Charging by pressure using high-precision gauge manifolds", "Charging by evaporator temperature with a thermometer", "Charging by weight using an electronic scale per manufacturer specification", "Charging by superheat and subcooling with a thermocouple"], explanation: "Small systems with a critical charge are best charged by weight, since even small differences in quantity significantly affect performance." },
  { id:"epa608_183", categoria:"EPA608_TIPO1", pregunta:"¿Qué sucede si hay aire (no condensable) atrapado en un sistema de refrigeración?", opciones:["La presión del lado de alta aumenta y la eficiencia baja","La presión del lado de baja disminuye considerablemente","El compresor funciona más silencioso de lo habitual en operación","El refrigerante se vuelve más eficiente al mezclarse con aire"], respuesta_correcta:0, explicacion:"Los gases no condensables como el aire elevan la presión de condensación, reduciendo la eficiencia y aumentando el consumo eléctrico." , question: "What happens when non-condensable gases (such as air) are trapped in a refrigeration system?", options: ["The high-side pressure increases and efficiency decreases", "The low-side pressure decreases considerably", "The compressor runs more quietly than usual during operation", "The refrigerant becomes more efficient when mixed with air"], explanation: "Non-condensable gases such as air raise the condensing pressure, reducing efficiency and increasing electrical consumption." },
  { id:"epa608_184", categoria:"EPA608_TIPO1", pregunta:"¿Para qué sirve el proceso de evacuación en un sistema Tipo I?", opciones:["Para cargar refrigerante nuevo rápidamente al sistema preparado","Para enfriar el compresor después de una reparación larga","Para remover aire y humedad del sistema antes de cargar","Para verificar que el compresor funciona correctamente"], respuesta_correcta:2, explicacion:"La evacuación usa vacío para remover aire y humedad del sistema, previniendo congelamiento en el capilar y formación de ácidos." , question: "What is the purpose of the evacuation process on a Type I system?", options: ["To charge new refrigerant quickly into the prepared system", "To cool down the compressor after a lengthy repair", "To remove air and moisture from the system before charging", "To verify that the compressor is working correctly"], explanation: "Evacuation uses a vacuum to remove air and moisture from the system, preventing ice blockage in the capillary tube and acid formation." },
  { id:"epa608_185", categoria:"EPA608_TIPO1", pregunta:"¿A qué nivel de vacío se debe evacuar un sistema Tipo I?", opciones:["A 0 psig (presión atmosférica) durante 30 minutos mínimo","A 10,000 micrones que es suficiente para sistemas pequeños","A 500 micrones o menos para asegurar remoción de humedad","A 29.92 pulgadas Hg sin medidor de micrones necesario"], respuesta_correcta:2, explicacion:"Se recomienda evacuar a 500 micrones o menos para asegurar la eliminación completa de humedad del sistema." , question: "To what vacuum level should a Type I system be evacuated?", options: ["To 0 psig (atmospheric pressure) for a minimum of 30 minutes", "To 10,000 microns, which is sufficient for small systems", "To 500 microns or less to ensure moisture removal", "To 29.92 inches Hg without needing a micron gauge"], explanation: "It is recommended to evacuate to 500 microns or less to ensure complete moisture removal from the system." },
  { id:"epa608_186", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de máquina expendedora se clasifica como Tipo I?", opciones:["Solo las que dispensan alimentos calientes preparados al público","Solo las máquinas de hielo comerciales de alta capacidad","Todas las máquinas expendedoras sin importar su tamaño total","Las que dispensan bebidas frías con refrigerante de 5 lb o menos"], respuesta_correcta:3, explicacion:"Las máquinas expendedoras de bebidas frías con 5 libras o menos de refrigerante se clasifican como aparatos Tipo I." , question: "What type of vending machine is classified as Type I?", options: ["Only those that dispense hot prepared food to the public", "Only commercial high-capacity ice machines", "All vending machines regardless of their total size", "Those that dispense cold beverages with 5 lb or less of refrigerant"], explanation: "Cold beverage vending machines containing 5 pounds or less of refrigerant are classified as Type I appliances." },
  { id:"epa608_187", categoria:"EPA608_TIPO1", pregunta:"¿Qué debe hacer un técnico si descubre refrigerante desconocido en un Tipo I?", opciones:["Asumir que es R-134a porque es el más común actualmente","Recuperarlo en cilindro separado y etiquetarlo como desconocido","Mezclarlo con R-134a en el cilindro de recuperación estándar","Ventearlo porque la cantidad es menor a 5 libras en total"], respuesta_correcta:1, explicacion:"El refrigerante desconocido debe recuperarse en un cilindro separado y etiquetarse correctamente para análisis posterior." , question: "What should a technician do upon discovering unknown refrigerant in a Type I system?", options: ["Assume it is R-134a because it is the most common today", "Recover it into a separate cylinder and label it as unknown", "Mix it with R-134a in the standard recovery cylinder", "Vent it because the amount is less than 5 pounds total"], explanation: "Unknown refrigerant must be recovered into a separate cylinder and properly labeled for later analysis." },
  { id:"epa608_188", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el propósito de las aletas en el condensador de un refrigerador?", opciones:["Reducir el ruido del compresor durante operación normal","Proteger la tubería del condensador contra daños físicos","Aumentar la superficie de transferencia de calor al aire","Dirigir el flujo de refrigerante en la dirección correcta"], respuesta_correcta:2, explicacion:"Las aletas aumentan el área de superficie del condensador para mejorar la transferencia de calor al aire ambiente." , question: "What is the purpose of the fins on a refrigerator condenser?", options: ["To reduce compressor noise during normal operation", "To protect the condenser tubing against physical damage", "To increase the heat transfer surface area to the air", "To direct the refrigerant flow in the correct direction"], explanation: "The fins increase the condenser surface area to improve heat transfer to the surrounding ambient air." },
  { id:"epa608_189", categoria:"EPA608_TIPO1", pregunta:"¿Qué regulación aplica a la venta de R-134a en latas pequeñas para automóviles?", opciones:["Se requiere certificación EPA 608 para cualquier cantidad","Solo mecánicos automotrices certificados ASE pueden comprarlas","Las latas de 2 libras o menos se pueden vender sin certificación","Las latas solo se venden en distribuidores mayoristas autorizados"], respuesta_correcta:2, explicacion:"Los contenedores de 2 libras o menos de refrigerante pueden venderse al público sin requerir certificación EPA." , question: "What regulation applies to the sale of R-134a in small cans for automobiles?", options: ["EPA 608 certification is required for any quantity", "Only ASE-certified automotive mechanics can purchase them", "Cans of 2 pounds or less can be sold without certification", "Cans are only sold at authorized wholesale distributors"], explanation: "Containers of 2 pounds or less of refrigerant may be sold to the general public without requiring EPA certification." },
  { id:"epa608_190", categoria:"EPA608_TIPO1", pregunta:"¿Qué componente controla el ciclo encendido/apagado del compresor en un refrigerador?", opciones:["El relé de arranque del compresor hermético interno","El termostato (control de temperatura) del aparato refrigerador","El protector térmico de sobrecarga del motor eléctrico","El temporizador de descongelamiento automático programado"], respuesta_correcta:1, explicacion:"El termostato sensa la temperatura interior y enciende/apaga el compresor para mantener la temperatura deseada." , question: "Which component controls the on/off cycle of the compressor in a refrigerator?", options: ["The start relay of the internal hermetic compressor", "The thermostat (temperature control) of the refrigerator appliance", "The thermal overload protector of the electric motor", "The programmed automatic defrost timer"], explanation: "The thermostat senses the interior temperature and turns the compressor on and off to maintain the desired temperature." },
  { id:"epa608_191", categoria:"EPA608_TIPO1", pregunta:"¿Qué es una 'carga crítica' en un sistema Tipo I?", opciones:["La carga mínima para que el sistema arranque sin problemas","La carga máxima antes de que se active la válvula de alivio","La cantidad de refrigerante que permanece después de una fuga","La cantidad exacta de refrigerante especificada por el fabricante"], respuesta_correcta:3, explicacion:"La carga crítica es la cantidad exacta de refrigerante especificada por el fabricante. En sistemas pequeños, gramos de diferencia afectan el rendimiento." , question: "What is a 'critical charge' in a Type I system?", options: ["The minimum charge for the system to start without problems", "The maximum charge before the relief valve activates", "The amount of refrigerant remaining after a leak", "The exact amount of refrigerant specified by the manufacturer"], explanation: "A critical charge is the exact amount of refrigerant specified by the manufacturer. In small systems, even a few grams of difference affect performance." },
  { id:"epa608_192", categoria:"EPA608_TIPO1", pregunta:"¿Dónde se ubica típicamente el compresor en un refrigerador doméstico?", opciones:["En la parte superior trasera junto al condensador externo","En el centro del aparato debajo del evaporador interior","En un compartimiento lateral aislado del refrigerador","En la parte inferior trasera montado en una base"], respuesta_correcta:3, explicacion:"El compresor se ubica generalmente en la parte inferior trasera del refrigerador, montado sobre una base con amortiguadores." , question: "Where is the compressor typically located in a domestic refrigerator?", options: ["On the upper rear section next to the external condenser", "In the center of the appliance below the interior evaporator", "In an insulated side compartment of the refrigerator", "On the lower rear section mounted on a base"], explanation: "The compressor is generally located at the lower rear of the refrigerator, mounted on a base with vibration dampeners." },
  { id:"epa608_193", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la consecuencia de no cambiar el filtro secador después de un burnout?", opciones:["El nuevo compresor trabajará con mayor eficiencia inicial","El sistema operará con presiones ligeramente más bajas","Los ácidos residuales dañarán el nuevo compresor rápidamente","El refrigerante nuevo se contaminará solo levemente sin daño"], respuesta_correcta:2, explicacion:"Si no se reemplaza el filtro secador después de un burnout, los ácidos y contaminantes residuales destruirán el nuevo compresor." , question: "What is the consequence of not replacing the filter drier after a compressor burnout?", options: ["The new compressor will operate with greater initial efficiency", "The system will operate with slightly lower pressures", "Residual acids will damage the new compressor quickly", "The new refrigerant will be only slightly contaminated without damage"], explanation: "If the filter drier is not replaced after a burnout, residual acids and contaminants will destroy the new compressor." },
  { id:"epa608_194", categoria:"EPA608_TIPO1", pregunta:"¿Qué tipo de relé de arranque usan comúnmente los compresores herméticos domésticos?", opciones:["Relé de estado sólido PTC (coeficiente de temp positivo)","Relé de voltaje variable con transformador integrado","Relé electromagnético de alta potencia con contactor","Relé de frecuencia variable con inversor incorporado"], respuesta_correcta:0, explicacion:"Los compresores herméticos domésticos comúnmente usan relés PTC que desconectan el bobinado de arranque cuando se calientan." , question: "What type of start relay do domestic hermetic compressors commonly use?", options: ["PTC (positive temperature coefficient) solid-state relay", "Variable voltage relay with an integrated transformer", "High-power electromagnetic relay with a contactor", "Variable frequency relay with a built-in inverter"], explanation: "Domestic hermetic compressors commonly use PTC relays, which disconnect the start winding once they heat up." },
  { id:"epa608_195", categoria:"EPA608_TIPO1", pregunta:"¿Qué indica un compresor hermético que zumba pero no arranca?", opciones:["El termostato está ajustado demasiado bajo para la temperatura","El ventilador del condensador está girando en dirección contraria","El relé de arranque o capacitor de arranque están defectuosos","El sistema tiene exceso de refrigerante en el lado de baja presión"], respuesta_correcta:2, explicacion:"Un compresor que zumba sin arrancar típicamente indica falla del relé de arranque, capacitor o un compresor atascado mecánicamente." , question: "What does a hermetic compressor that hums but does not start indicate?", options: ["The thermostat is set too low for the current temperature", "The condenser fan is spinning in the wrong direction", "The start relay or start capacitor is defective", "The system has excess refrigerant on the low-pressure side"], explanation: "A compressor that hums without starting typically indicates a failed start relay, capacitor, or a mechanically seized compressor." },
  { id:"epa608_196", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es la principal razón para usar nitrógeno durante el brazing?", opciones:["El nitrógeno previene la oxidación interna de tubería de cobre","El nitrógeno enfría la soldadura más rápidamente para mejor unión","El nitrógeno presuriza el sistema para detectar fugas al soldar","El nitrógeno actúa como flux eliminando la necesidad de pasta"], respuesta_correcta:0, explicacion:"Pasar un flujo de nitrógeno durante el brazing previene la formación de óxidos de cobre dentro de la tubería que contaminarían el sistema." , question: "What is the main reason for flowing nitrogen during brazing?", options: ["Nitrogen prevents internal oxidation of copper tubing", "Nitrogen cools the solder more quickly for a better joint", "Nitrogen pressurizes the system to detect leaks while brazing", "Nitrogen acts as flux, eliminating the need for paste"], explanation: "Flowing nitrogen during brazing prevents the formation of copper oxides inside the tubing that would contaminate the system." },
  { id:"epa608_197", categoria:"EPA608_TIPO1", pregunta:"¿Qué ocurre si se sobrecarga de refrigerante un sistema Tipo I?", opciones:["El sistema enfría más rápido y es más eficiente temporalmente","El tubo capilar se expande permitiendo mayor flujo de gas","La presión de alta aumenta excesivamente y el compresor se esfuerza","El evaporador se seca completamente eliminando toda la escarcha"], respuesta_correcta:2, explicacion:"La sobrecarga eleva las presiones, especialmente del lado de alta, forzando al compresor a trabajar más y reduciendo la eficiencia." , question: "What happens if a Type I system is overcharged with refrigerant?", options: ["The system cools faster and is temporarily more efficient", "The capillary tube expands allowing greater gas flow", "The high-side pressure increases excessively and the compressor is strained", "The evaporator dries out completely, eliminating all frost"], explanation: "Overcharging raises pressures, especially on the high side, forcing the compressor to work harder and reducing efficiency." },
  { id:"epa608_198", categoria:"EPA608_TIPO1", pregunta:"¿Qué dispositivo protege el motor del compresor contra sobrecalentamiento?", opciones:["El termostato principal del aparato de refrigeración","El relé de arranque PTC del compresor hermético sellado","El capacitor de marcha conectado al bobinado principal","El protector térmico de sobrecarga (overload protector)"], respuesta_correcta:3, explicacion:"El protector térmico de sobrecarga desconecta el compresor cuando detecta corriente excesiva o temperatura peligrosamente alta." , question: "Which device protects the compressor motor against overheating?", options: ["The main thermostat of the refrigeration appliance", "The PTC start relay of the sealed hermetic compressor", "The run capacitor connected to the main winding", "The thermal overload protector"], explanation: "The thermal overload protector disconnects the compressor when it detects excessive current or dangerously high temperature." },
  { id:"epa608_199", categoria:"EPA608_TIPO1", pregunta:"¿Cuál es el rango típico de carga de refrigerante en un refrigerador doméstico?", opciones:["Entre 3 y 8 onzas (85 a 227 gramos) de refrigerante","Entre 10 y 20 onzas (283 a 567 gramos) de refrigerante","Entre 2 y 5 libras (907 a 2268 gramos) de refrigerante","Entre 30 y 50 onzas (850 a 1417 gramos) de refrigerante"], respuesta_correcta:0, explicacion:"Los refrigeradores domésticos típicamente contienen entre 3 y 8 onzas de refrigerante. La carga exacta varía según el modelo." , question: "What is the typical refrigerant charge range in a domestic refrigerator?", options: ["Between 3 and 8 ounces (85 to 227 grams) of refrigerant", "Between 10 and 20 ounces (283 to 567 grams) of refrigerant", "Between 2 and 5 pounds (907 to 2,268 grams) of refrigerant", "Between 30 and 50 ounces (850 to 1,417 grams) of refrigerant"], explanation: "Domestic refrigerators typically contain between 3 and 8 ounces of refrigerant. The exact charge varies by model." },
  { id:"epa608_200", categoria:"EPA608_TIPO1", pregunta:"¿Qué se debe verificar en las mangueras de recuperación ANTES de conectarlas?", opciones:["Que las mangueras sean del color correcto para cada presión","Que las mangueras midan exactamente 3 pies de longitud estándar","Que estén en buenas condiciones, sin grietas ni obstrucciones","Que las mangueras sean nuevas y nunca hayan sido usadas antes"], respuesta_correcta:2, explicacion:"Las mangueras deben inspeccionarse por grietas, daños u obstrucciones antes de cada uso para evitar fugas y contaminación." , question: "What should be verified on recovery hoses BEFORE connecting them?", options: ["That the hoses are the correct color for each pressure side", "That the hoses measure exactly 3 feet in standard length", "That they are in good condition, with no cracks or obstructions", "That the hoses are brand new and have never been used before"], explanation: "Hoses must be inspected for cracks, damage, or obstructions before each use to prevent leaks and contamination." },
  // ── TIPO II (201-300) ──────────────────────────────────────────
  { id:"epa608_201", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la definición correcta de un sistema de alta presión (Tipo II) según la EPA?", opciones:["Sistemas que usan refrigerantes con punto de ebullición entre -50°C y 10°C a presión atmosférica","Sistemas que usan refrigerantes con punto de ebullición por debajo de -50°C a presión atmosférica","Sistemas que operan exclusivamente con refrigerantes halogenados de baja toxicidad certificada","Sistemas que usan refrigerantes con punto de ebullición por encima de 10°C a presión atmosférica"], respuesta_correcta:0, explicacion:"Los sistemas Tipo II utilizan refrigerantes con punto de ebullición entre -50°C y 10°C a presión atmosférica, operando por encima de la presión atmosférica." , question: "What is the correct definition of a high-pressure (Type II) system according to the EPA?", options: ["Systems that use refrigerants with a boiling point between -50 deg C and 10 deg C at atmospheric pressure", "Systems that use refrigerants with a boiling point below -50 deg C at atmospheric pressure", "Systems that operate exclusively with halogenated refrigerants of certified low toxicity", "Systems that use refrigerants with a boiling point above 10 deg C at atmospheric pressure"], explanation: "Type II systems use refrigerants with a boiling point between -50 deg C and 10 deg C at atmospheric pressure, operating above atmospheric pressure." },
  { id:"epa608_202", categoria:"EPA608_TIPO2", pregunta:"¿Cuál de los siguientes refrigerantes es comúnmente asociado con sistemas Tipo II?", opciones:["R-123 utilizado en chillers centrífugos de baja presión","R-22 utilizado en sistemas de aire acondicionado split","R-744 utilizado en sistemas de refrigeración transcríticos","R-717 utilizado en sistemas industriales de amoníaco"], respuesta_correcta:1, explicacion:"El R-22 es un refrigerante de alta presión comúnmente usado en sistemas split de aire acondicionado y cae dentro de la clasificación Tipo II." , question: "Which of the following refrigerants is commonly associated with Type II systems?", options: ["R-123 used in low-pressure centrifugal chillers", "R-22 used in split air conditioning systems", "R-744 used in transcritical refrigeration systems", "R-717 used in industrial ammonia systems"], explanation: "R-22 is a high-pressure refrigerant commonly used in split air conditioning systems and falls within the Type II classification." },
  { id:"epa608_203", categoria:"EPA608_TIPO2", pregunta:"¿A qué nivel de vacío se debe recuperar refrigerante de un equipo Tipo II fabricado después de noviembre de 1993 con menos de 200 libras de carga?", opciones:["4 pulgadas de mercurio de vacío según la norma anterior vigente","0 psig según los requisitos actualizados de recuperación EPA","10 pulgadas de mercurio de vacío para equipos residenciales únicamente","15 pulgadas de mercurio de vacío para todos los equipos comerciales"], respuesta_correcta:1, explicacion:"Para equipos de recuperación fabricados después de noviembre de 1993 con menos de 200 lb, el nivel requerido es 0 psig." , question: "To what vacuum level must refrigerant be recovered from Type II equipment manufactured after November 1993 with less than 200 pounds of charge?", options: ["4 inches of mercury vacuum per the previous standard", "0 psig per the updated EPA recovery requirements", "10 inches of mercury vacuum for residential equipment only", "15 inches of mercury vacuum for all commercial equipment"], explanation: "For recovery equipment manufactured after November 1993 with less than 200 lb, the required level is 0 psig." },
  { id:"epa608_204", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el nivel de vacío requerido para recuperar refrigerante de un APARATO Tipo II con menos de 200 libras de carga?", opciones:["0 psig independientemente del tamaño del aparato conectado al sistema","15 pulgadas de mercurio de vacío para aparatos de cualquier capacidad","10 pulgadas de mercurio de vacío según las regulaciones de la EPA","4 pulgadas de mercurio de vacío para los aparatos más antiguos solamente"], respuesta_correcta:2, explicacion:"Para aparatos (appliances) Tipo II con menos de 200 lb de carga, el nivel de vacío requerido es 10 pulgadas de Hg." , question: "What is the required vacuum level to recover refrigerant from a Type II APPLIANCE with less than 200 pounds of charge?", options: ["0 psig regardless of the size of the appliance connected to the system", "15 inches of mercury vacuum for appliances of any capacity", "10 inches of mercury vacuum per EPA regulations", "4 inches of mercury vacuum for the oldest appliances only"], explanation: "For Type II appliances with less than 200 lb of charge, the required vacuum level is 10 inches of Hg." },
  { id:"epa608_205", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el nivel de vacío requerido para recuperar refrigerante de un APARATO Tipo II con 200 libras o más de carga?", opciones:["10 pulgadas de mercurio de vacío para aparatos de gran capacidad","0 psig para todos los aparatos de alta presión sin excepción alguna","4 pulgadas de mercurio para sistemas industriales de gran tamaño","15 pulgadas de mercurio de vacío según las regulaciones EPA vigentes"], respuesta_correcta:3, explicacion:"Para aparatos Tipo II con 200 lb o más de carga, la EPA requiere un nivel de vacío de 15 pulgadas de Hg." , question: "What is the required vacuum level to recover refrigerant from a Type II APPLIANCE with 200 pounds or more of charge?", options: ["10 inches of mercury vacuum for large-capacity appliances", "0 psig for all high-pressure appliances without exception", "4 inches of mercury for large industrial systems", "15 inches of mercury vacuum per current EPA regulations"], explanation: "For Type II appliances with 200 lb or more of charge, the EPA requires a vacuum level of 15 inches of Hg." },
  { id:"epa608_206", categoria:"EPA608_TIPO2", pregunta:"¿A cuánta presión más opera el R-410A en comparación con el R-22 aproximadamente?", opciones:["Opera a aproximadamente un 30% más de presión que el refrigerante R-22","Opera a aproximadamente un 60% más de presión que el refrigerante R-22","Opera a aproximadamente un 90% más de presión que el refrigerante R-22","Opera a aproximadamente un 45% más de presión que el refrigerante R-22"], respuesta_correcta:1, explicacion:"El R-410A opera a aproximadamente un 60% más de presión que el R-22, por lo que requiere componentes clasificados para mayor presión." , question: "How much higher is the operating pressure of R-410A compared to R-22 approximately?", options: ["It operates at approximately 30% higher pressure than R-22", "It operates at approximately 60% higher pressure than R-22", "It operates at approximately 90% higher pressure than R-22", "It operates at approximately 45% higher pressure than R-22"], explanation: "R-410A operates at approximately 60% higher pressure than R-22, which is why it requires components rated for higher pressure." },
  { id:"epa608_207", categoria:"EPA608_TIPO2", pregunta:"¿Por qué las mezclas zeotrópicas como el R-407C deben cargarse en fase LÍQUIDA al sistema?", opciones:["Porque el líquido se evapora más rápido y acelera el proceso de carga completa","Porque cargar en vapor causa fracccionamiento y cambia la composición de la mezcla","Porque el vapor genera presiones excesivas que pueden dañar el compresor del equipo","Porque la normativa EPA prohíbe cargar cualquier refrigerante en estado de vapor"], respuesta_correcta:1, explicacion:"Las mezclas zeotrópicas tienen diferentes puntos de ebullición por componente; cargar en vapor causa fraccionamiento, alterando la proporción de la mezcla." , question: "Why must zeotropic blends such as R-407C be charged in LIQUID phase into the system?", options: ["Because the liquid evaporates faster and speeds up the full charging process", "Because charging as vapor causes fractionation and changes the blend composition", "Because vapor generates excessive pressures that can damage the system compressor", "Because EPA regulations prohibit charging any refrigerant as vapor"], explanation: "Zeotropic blends have different boiling points for each component; charging as vapor causes fractionation, altering the mixture proportions." },
  { id:"epa608_208", categoria:"EPA608_TIPO2", pregunta:"¿Qué es el 'glide' (deslizamiento) de temperatura en una mezcla zeotrópica de refrigerante?", opciones:["La diferencia de temperatura entre el evaporador y el condensador durante operación normal","La diferencia entre la temperatura de inicio y fin de ebullición a presión constante","La variación de temperatura del refrigerante al pasar por la válvula de expansión","La caída de temperatura causada por la pérdida de carga en las tuberías del sistema"], respuesta_correcta:1, explicacion:"El glide es la diferencia entre la temperatura de burbuja (inicio de ebullición) y la temperatura de rocío (fin de ebullición) a presión constante." , question: "What is temperature 'glide' in a zeotropic refrigerant blend?", options: ["The temperature difference between the evaporator and condenser during normal operation", "The difference between the starting and ending boiling temperatures at constant pressure", "The temperature variation of the refrigerant as it passes through the expansion valve", "The temperature drop caused by pressure loss in the system piping"], explanation: "Glide is the difference between the bubble point temperature (start of boiling) and the dew point temperature (end of boiling) at constant pressure." },
  { id:"epa608_209", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la tasa anual de fuga que requiere reparación obligatoria en sistemas comerciales con más de 50 libras de refrigerante?", opciones:["15% de tasa anual de fuga para todos los sistemas comerciales registrados","20% de tasa anual de fuga para sistemas comerciales de mediana capacidad","25% de tasa anual de fuga para sistemas de refrigeración comerciales","30% de tasa anual de fuga para sistemas comerciales de refrigeración"], respuesta_correcta:3, explicacion:"Para sistemas comerciales de refrigeración con más de 50 lb de carga, la tasa de fuga anual que obliga a reparación es del 30%." , question: "What is the annual leak rate that requires mandatory repair in commercial systems containing more than 50 pounds of refrigerant?", options: ["15% annual leak rate for all registered commercial systems", "20% annual leak rate for medium-capacity commercial systems", "25% annual leak rate for commercial refrigeration systems", "30% annual leak rate for commercial refrigeration systems"], explanation: "For commercial refrigeration systems with more than 50 lb of charge, the annual leak rate that triggers mandatory repair is 30%." },
  { id:"epa608_210", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la tasa anual de fuga que requiere reparación obligatoria en procesos INDUSTRIALES con más de 50 libras?", opciones:["15% de tasa anual de fuga para procesos industriales de refrigeración","30% de tasa anual de fuga para procesos industriales de refrigeración","20% de tasa anual de fuga para procesos industriales de refrigeración","25% de tasa anual de fuga para procesos industriales de refrigeración"], respuesta_correcta:0, explicacion:"Para procesos industriales con más de 50 lb de refrigerante, la tasa de fuga anual que obliga a reparación es del 15%, más estricta que la comercial." , question: "What is the annual leak rate that requires mandatory repair in INDUSTRIAL processes containing more than 50 pounds?", options: ["15% annual leak rate for industrial refrigeration processes", "30% annual leak rate for industrial refrigeration processes", "20% annual leak rate for industrial refrigeration processes", "25% annual leak rate for industrial refrigeration processes"], explanation: "For industrial processes with more than 50 lb of refrigerant, the annual leak rate that triggers mandatory repair is 15%, stricter than the commercial threshold." },
  { id:"epa608_211", categoria:"EPA608_TIPO2", pregunta:"¿Cuántos días tiene el propietario para reparar una fuga que excede la tasa permitida por la EPA?", opciones:["60 días calendario a partir de la fecha de detección de la fuga confirmada","45 días calendario a partir de la fecha de detección de la fuga confirmada","30 días calendario a partir de la fecha de detección de la fuga confirmada","15 días calendario a partir de la fecha de detección de la fuga confirmada"], respuesta_correcta:2, explicacion:"La EPA requiere que las fugas se reparen dentro de 30 días desde su descubrimiento, con extensión a 120 días si se necesitan partes especiales." , question: "How many days does the owner have to repair a leak that exceeds the EPA-allowed rate?", options: ["60 calendar days from the date the confirmed leak was detected", "45 calendar days from the date the confirmed leak was detected", "30 calendar days from the date the confirmed leak was detected", "15 calendar days from the date the confirmed leak was detected"], explanation: "The EPA requires that leaks be repaired within 30 days of discovery, with an extension to 120 days if special parts are needed." },
  { id:"epa608_212", categoria:"EPA608_TIPO2", pregunta:"¿Cuántos días adicionales se permiten si las partes necesarias para reparar la fuga deben ser ordenadas?", opciones:["Se extiende el plazo a un máximo total de 90 días desde la detección de fuga","Se extiende el plazo a un máximo total de 120 días desde la detección de fuga","Se extiende el plazo a un máximo total de 60 días desde la detección de fuga","Se extiende el plazo a un máximo total de 180 días desde la detección de fuga"], respuesta_correcta:1, explicacion:"Si las partes deben ser ordenadas, el plazo de reparación se extiende hasta un máximo de 120 días desde la detección de la fuga." , question: "How many additional days are allowed if the parts needed to repair the leak must be ordered?", options: ["The deadline is extended to a maximum total of 90 days from leak detection", "The deadline is extended to a maximum total of 120 days from leak detection", "The deadline is extended to a maximum total of 60 days from leak detection", "The deadline is extended to a maximum total of 180 days from leak detection"], explanation: "If parts must be ordered, the repair deadline is extended to a maximum of 120 days from the date the leak was detected." },
  { id:"epa608_213", categoria:"EPA608_TIPO2", pregunta:"¿Dentro de cuántos días después de la reparación se debe realizar una prueba de verificación de fugas?", opciones:["60 días después de completar la reparación del sistema de refrigeración","45 días después de completar la reparación del sistema de refrigeración","15 días después de completar la reparación del sistema de refrigeración","30 días después de completar la reparación del sistema de refrigeración"], respuesta_correcta:3, explicacion:"La EPA requiere una prueba de verificación de fugas dentro de los 30 días posteriores a completar la reparación." , question: "Within how many days after the repair must a leak verification test be performed?", options: ["60 days after completing the refrigeration system repair", "45 days after completing the refrigeration system repair", "15 days after completing the refrigeration system repair", "30 days after completing the refrigeration system repair"], explanation: "The EPA requires a leak verification test within 30 days after completing the repair." },
  { id:"epa608_214", categoria:"EPA608_TIPO2", pregunta:"¿Para qué tamaño de sistema se requiere mantener registros de servicio de refrigerante según la EPA?", opciones:["Para todos los sistemas de refrigeración sin importar la cantidad de carga","Para sistemas que contienen más de 50 libras de refrigerante exclusivamente","Para sistemas que contienen más de 25 libras de refrigerante exclusivamente","Para sistemas que contienen más de 100 libras de refrigerante solamente"], respuesta_correcta:1, explicacion:"La EPA requiere mantener registros de servicio para sistemas que contienen más de 50 libras de refrigerante." , question: "For what size system must refrigerant service records be maintained according to the EPA?", options: ["For all refrigeration systems regardless of the charge amount", "For systems containing more than 50 pounds of refrigerant exclusively", "For systems containing more than 25 pounds of refrigerant exclusively", "For systems containing more than 100 pounds of refrigerant only"], explanation: "The EPA requires service records to be maintained for systems containing more than 50 pounds of refrigerant." },
  { id:"epa608_215", categoria:"EPA608_TIPO2", pregunta:"¿Qué tipo de aceite lubricante se utiliza con el refrigerante R-22 en sistemas de compresión?", opciones:["Aceite poliolester (POE) sintético de alta viscosidad para compresores herméticos","Aceite mineral convencional compatible con refrigerantes clorados tipo HCFC","Aceite polialquilenglicol (PAG) utilizado en sistemas de refrigeración móvil","Aceite alquilbenceno (AB) diseñado exclusivamente para compresores semi-herméticos"], respuesta_correcta:1, explicacion:"El R-22 es compatible con aceite mineral convencional debido a su naturaleza como HCFC; los HFCs como R-410A requieren aceite POE." , question: "What type of lubricating oil is used with R-22 refrigerant in compression systems?", options: ["Polyolester (POE) synthetic oil with high viscosity for hermetic compressors", "Conventional mineral oil compatible with HCFC-type chlorinated refrigerants", "Polyalkylene glycol (PAG) oil used in mobile refrigeration systems", "Alkylbenzene (AB) oil designed exclusively for semi-hermetic compressors"], explanation: "R-22 is compatible with conventional mineral oil due to its nature as an HCFC; HFCs like R-410A require POE oil." },
  { id:"epa608_216", categoria:"EPA608_TIPO2", pregunta:"¿Qué tipo de aceite lubricante requiere el refrigerante R-410A en sistemas de compresión?", opciones:["Aceite mineral convencional de viscosidad media para compresores herméticos estándar","Aceite alquilbenceno sintético diseñado para refrigerantes de alta presión operativa","Aceite poliolester (POE) sintético compatible con refrigerantes tipo HFC modernos","Aceite polialquilenglicol (PAG) utilizado en compresores de velocidad variable"], respuesta_correcta:2, explicacion:"El R-410A es un HFC que requiere aceite POE (poliolester) porque el aceite mineral no es miscible con refrigerantes HFC." , question: "What type of lubricating oil does R-410A refrigerant require in compression systems?", options: ["Conventional mineral oil of medium viscosity for standard hermetic compressors", "Synthetic alkylbenzene oil designed for high-operating-pressure refrigerants", "Polyolester (POE) synthetic oil compatible with modern HFC-type refrigerants", "Polyalkylene glycol (PAG) oil used in variable-speed compressors"], explanation: "R-410A is an HFC that requires POE (polyolester) oil because mineral oil is not miscible with HFC refrigerants." },
  { id:"epa608_217", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el nivel de vacío recomendado durante la evacuación de un sistema de refrigeración Tipo II?", opciones:["1000 micrones de vacío para garantizar la eliminación de humedad del sistema","500 micrones de vacío para garantizar la deshidratación completa del sistema","250 micrones de vacío para garantizar la máxima pureza interna del sistema","750 micrones de vacío para cumplir con los estándares mínimos de evacuación"], respuesta_correcta:1, explicacion:"Se recomienda evacuar hasta 500 micrones para asegurar la eliminación adecuada de humedad y gases no condensables del sistema." , question: "What is the recommended vacuum level during evacuation of a Type II refrigeration system?", options: ["1,000 microns of vacuum to ensure moisture removal from the system", "500 microns of vacuum to ensure complete system dehydration", "250 microns of vacuum to ensure maximum internal purity of the system", "750 microns of vacuum to meet the minimum evacuation standards"], explanation: "It is recommended to evacuate to 500 microns to ensure adequate removal of moisture and non-condensable gases from the system." },
  { id:"epa608_218", categoria:"EPA608_TIPO2", pregunta:"¿Qué gas se debe utilizar para presurizar un sistema y realizar una prueba de fugas?", opciones:["Oxígeno seco comprimido a alta presión para detectar fugas rápidamente","Nitrógeno seco con regulador de presión para presurizar el sistema de forma segura","Dióxido de carbono comprimido para detectar fugas en conexiones del sistema","Aire comprimido filtrado y deshidratado para presurizar el sistema completo"], respuesta_correcta:1, explicacion:"Se debe usar nitrógeno seco para pruebas de presión. NUNCA oxígeno, ya que puede causar explosiones al mezclarse con aceite refrigerante." , question: "What gas should be used to pressurize a system for a leak test?", options: ["Dry compressed oxygen at high pressure to detect leaks quickly", "Dry nitrogen with a pressure regulator to pressurize the system safely", "Compressed carbon dioxide to detect leaks at system connections", "Filtered and dehydrated compressed air to pressurize the entire system"], explanation: "Dry nitrogen must be used for pressure testing. NEVER use oxygen, as it can cause an explosion when mixed with refrigerant oil." },
  { id:"epa608_219", categoria:"EPA608_TIPO2", pregunta:"¿Por qué NUNCA se debe usar oxígeno para presurizar un sistema de refrigeración?", opciones:["Porque el oxígeno reacciona con el cobre de las tuberías causando corrosión acelerada","Porque el oxígeno puede causar una explosión violenta al mezclarse con aceite del sistema","Porque el oxígeno contamina el refrigerante y reduce la eficiencia de transferencia térmica","Porque el oxígeno genera ácidos que destruyen los sellos mecánicos del compresor"], respuesta_correcta:1, explicacion:"El oxígeno bajo presión al contacto con aceite refrigerante puede causar una explosión violenta; siempre usar nitrógeno seco." , question: "Why should oxygen NEVER be used to pressurize a refrigeration system?", options: ["Because oxygen reacts with the copper tubing causing accelerated corrosion", "Because oxygen can cause a violent explosion when mixed with the system oil", "Because oxygen contaminates the refrigerant and reduces heat transfer efficiency", "Because oxygen generates acids that destroy the compressor mechanical seals"], explanation: "Oxygen under pressure in contact with refrigerant oil can cause a violent explosion; always use dry nitrogen." },
  { id:"epa608_220", categoria:"EPA608_TIPO2", pregunta:"¿Cuándo se debe reemplazar el filtro secador en un sistema de refrigeración Tipo II?", opciones:["Únicamente durante el mantenimiento preventivo anual programado del sistema completo","Solamente cuando el visor de líquido muestra burbujas continuas durante la operación","Después de una quemadura del compresor o cuando hay contaminación por humedad detectada","Cada vez que se realiza una recarga parcial de refrigerante en el sistema de enfriamiento"], respuesta_correcta:2, explicacion:"El filtro secador debe reemplazarse después de un burnout del compresor o cuando se detecta contaminación por humedad para proteger el sistema." , question: "When should the filter drier be replaced in a Type II refrigeration system?", options: ["Only during the scheduled annual preventive maintenance of the entire system", "Only when the sight glass shows continuous bubbles during operation", "After a compressor burnout or when moisture contamination is detected", "Every time a partial refrigerant recharge is performed on the cooling system"], explanation: "The filter drier must be replaced after a compressor burnout or when moisture contamination is detected to protect the system." },
  { id:"epa608_221", categoria:"EPA608_TIPO2", pregunta:"¿Qué indica la presencia de burbujas constantes en el visor de líquido durante operación normal?", opciones:["Indica que el sistema tiene una carga excesiva de refrigerante y necesita recuperación","Indica que el filtro secador está saturado y necesita ser reemplazado inmediatamente","Indica que el sistema tiene carga baja de refrigerante o restricción en la línea líquida","Indica que la válvula de expansión está sobredimensionada para la capacidad del sistema"], respuesta_correcta:2, explicacion:"Burbujas constantes en el visor de líquido generalmente indican carga baja de refrigerante o una restricción en la línea de líquido." , question: "What does the presence of constant bubbles in the sight glass during normal operation indicate?", options: ["The system has an excessive refrigerant charge and needs recovery", "The filter drier is saturated and needs to be replaced immediately", "The system has a low refrigerant charge or a restriction in the liquid line", "The expansion valve is oversized for the system capacity"], explanation: "Constant bubbles in the sight glass generally indicate a low refrigerant charge or a restriction in the liquid line." },
  { id:"epa608_222", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el propósito principal de un acumulador en la línea de succión del sistema?", opciones:["Aumentar la presión del refrigerante antes de entrar al compresor de forma gradual","Evitar que refrigerante líquido llegue al compresor y cause daño por golpe hidráulico","Separar el aceite del refrigerante gaseoso antes de que entre al cilindro del compresor","Reducir el ruido de pulsación del refrigerante en la línea de succión del sistema"], respuesta_correcta:1, explicacion:"El acumulador de succión atrapa refrigerante líquido que no se evaporó, evitando que llegue al compresor y cause daño por golpe de líquido." , question: "What is the main purpose of an accumulator on the suction line of a system?", options: ["To increase the refrigerant pressure before it gradually enters the compressor", "To prevent liquid refrigerant from reaching the compressor and causing liquid slugging damage", "To separate oil from the gaseous refrigerant before it enters the compressor cylinder", "To reduce refrigerant pulsation noise in the system suction line"], explanation: "The suction accumulator traps liquid refrigerant that has not evaporated, preventing it from reaching the compressor and causing liquid slugging damage." },
  { id:"epa608_223", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el propósito de una válvula solenoide en la línea de líquido de un sistema de refrigeración?", opciones:["Regular la presión del condensador durante períodos de baja temperatura ambiente exterior","Controlar el flujo de refrigerante líquido cerrando durante el ciclo de apagado del compresor","Proteger el compresor contra sobrepresión en el lado de alta del circuito frigorífico","Mantener el subenfriamiento constante durante variaciones de carga térmica del espacio"], respuesta_correcta:1, explicacion:"La válvula solenoide en la línea de líquido cierra el flujo de refrigerante cuando el compresor se apaga, previniendo migración de refrigerante al evaporador." , question: "What is the purpose of a solenoid valve in the liquid line of a refrigeration system?", options: ["To regulate condenser pressure during periods of low outdoor ambient temperature", "To control liquid refrigerant flow by closing during the compressor off cycle", "To protect the compressor against high pressure on the high side of the refrigeration circuit", "To maintain constant subcooling during thermal load variations in the space"], explanation: "The liquid line solenoid valve shuts off refrigerant flow when the compressor turns off, preventing refrigerant migration to the evaporator." },
  { id:"epa608_224", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la función principal de un calentador de cárter (crankcase heater) en un compresor?", opciones:["Precalentar el aceite para reducir la viscosidad y facilitar el arranque del compresor","Evitar que el refrigerante migre y se acumule en el aceite del cárter durante el apagado","Mantener la temperatura del motor eléctrico dentro de los parámetros de operación seguros","Acelerar la evaporación del refrigerante líquido residual en la carcasa del compresor"], respuesta_correcta:1, explicacion:"El calentador de cárter mantiene el aceite caliente durante el apagado, evitando que el refrigerante migre y se disuelva en el aceite del compresor." , question: "What is the main function of a crankcase heater on a compressor?", options: ["To preheat the oil to reduce viscosity and facilitate compressor startup", "To prevent refrigerant from migrating into and accumulating in the crankcase oil during shutdown", "To maintain the electric motor temperature within safe operating parameters", "To accelerate evaporation of residual liquid refrigerant in the compressor housing"], explanation: "The crankcase heater keeps the oil warm during shutdown, preventing refrigerant from migrating and dissolving in the compressor oil." },
  { id:"epa608_225", categoria:"EPA608_TIPO2", pregunta:"¿Qué es el sobrecalentamiento (superheat) en un sistema de refrigeración Tipo II?", opciones:["La temperatura del refrigerante líquido por encima de su punto de condensación a esa presión","La diferencia entre la temperatura del aire y la temperatura del refrigerante en el evaporador","La temperatura del refrigerante gaseoso por encima de su punto de ebullición a esa presión","La cantidad de calor total absorbido por el refrigerante durante el proceso de evaporación"], respuesta_correcta:2, explicacion:"El sobrecalentamiento es la temperatura del vapor de refrigerante por encima de su temperatura de saturación (ebullición) a la presión de succión." , question: "What is superheat in a Type II refrigeration system?", options: ["The temperature of the liquid refrigerant above its condensation point at that pressure", "The difference between the air temperature and the refrigerant temperature in the evaporator", "The temperature of the gaseous refrigerant above its boiling point at that pressure", "The total amount of heat absorbed by the refrigerant during the evaporation process"], explanation: "Superheat is the temperature of the refrigerant vapor above its saturation (boiling) temperature at the suction pressure." },
  { id:"epa608_226", categoria:"EPA608_TIPO2", pregunta:"¿Qué es el subenfriamiento (subcooling) en un sistema de refrigeración Tipo II?", opciones:["La caída de temperatura del refrigerante al pasar a través del dispositivo de expansión","La diferencia entre la temperatura del aire exterior y la temperatura de descarga del gas","La temperatura del refrigerante líquido por debajo de su punto de condensación a esa presión","La cantidad de calor rechazado por el refrigerante durante el proceso de condensación total"], respuesta_correcta:2, explicacion:"El subenfriamiento es la temperatura del líquido por debajo de su temperatura de saturación (condensación) a la presión del condensador." , question: "What is subcooling in a Type II refrigeration system?", options: ["The temperature drop of the refrigerant as it passes through the expansion device", "The difference between the outdoor air temperature and the discharge gas temperature", "The temperature of the liquid refrigerant below its condensation point at that pressure", "The total amount of heat rejected by the refrigerant during the complete condensation process"], explanation: "Subcooling is the temperature of the liquid below its saturation (condensation) temperature at the condenser pressure." },
  { id:"epa608_227", categoria:"EPA608_TIPO2", pregunta:"¿Cómo se carga un sistema con R-410A cuando se necesita agregar refrigerante al circuito?", opciones:["Se carga en fase de vapor por la línea de succión con el compresor funcionando normalmente","Se carga en fase líquida debido a que es una mezcla zeotrópica cercana al azeótropo","Se carga en fase de vapor por el lado de alta presión con el compresor apagado completamente","Se puede cargar indistintamente en vapor o líquido sin afectar la composición del refrigerante"], respuesta_correcta:1, explicacion:"El R-410A debe cargarse como líquido porque es una mezcla casi azeotrópica; cargar como vapor podría alterar ligeramente su composición." , question: "How is R-410A charged into a system when refrigerant needs to be added?", options: ["It is charged as vapor through the suction line with the compressor running normally", "It is charged as liquid because it is a near-azeotropic blend", "It is charged as vapor through the high-pressure side with the compressor completely off", "It can be charged as either vapor or liquid without affecting the refrigerant composition"], explanation: "R-410A must be charged as a liquid because it is a near-azeotropic blend; charging as vapor could slightly alter its composition." },
  { id:"epa608_228", categoria:"EPA608_TIPO2", pregunta:"¿Qué clasificación de seguridad tiene el refrigerante R-454B según ASHRAE?", opciones:["Clasificación A1 — baja toxicidad y sin propagación de llama en condiciones normales","Clasificación B1 — alta toxicidad y sin propagación de llama en condiciones normales","Clasificación A2L — baja toxicidad y ligeramente inflamable con baja velocidad de llama","Clasificación B2L — alta toxicidad y ligeramente inflamable con baja velocidad de llama"], respuesta_correcta:2, explicacion:"El R-454B tiene clasificación A2L (baja toxicidad, ligeramente inflamable), diseñado como reemplazo del R-410A con menor GWP." , question: "What ASHRAE safety classification does refrigerant R-454B have?", options: ["Classification A1 -- low toxicity and no flame propagation under normal conditions", "Classification B1 -- higher toxicity and no flame propagation under normal conditions", "Classification A2L -- low toxicity and mildly flammable with low flame speed", "Classification B2L -- higher toxicity and mildly flammable with low flame speed"], explanation: "R-454B has an A2L classification (low toxicity, mildly flammable), designed as a replacement for R-410A with lower GWP." },
  { id:"epa608_229", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el potencial de calentamiento global (GWP) aproximado del refrigerante R-454B?", opciones:["GWP de 675 según los estándares internacionales de evaluación de impacto ambiental","GWP de 466 según los estándares internacionales de evaluación de impacto ambiental","GWP de 2088 según los estándares internacionales de evaluación de impacto ambiental","GWP de 1030 según los estándares internacionales de evaluación de impacto ambiental"], respuesta_correcta:1, explicacion:"El R-454B tiene un GWP de 466, significativamente menor que el R-410A (GWP=2088), por lo que es considerado un reemplazo más ecológico." , question: "What is the approximate Global Warming Potential (GWP) of refrigerant R-454B?", options: ["GWP of 675 per international environmental impact assessment standards", "GWP of 466 per international environmental impact assessment standards", "GWP of 2,088 per international environmental impact assessment standards", "GWP of 1,030 per international environmental impact assessment standards"], explanation: "R-454B has a GWP of 466, significantly lower than R-410A (GWP of 2,088), making it a more environmentally friendly replacement." },
  { id:"epa608_230", categoria:"EPA608_TIPO2", pregunta:"¿Qué diferencia principal existe entre una mezcla azeotrópica y una zeotrópica de refrigerante?", opciones:["La azeotrópica tiene mayor presión de operación que la zeotrópica en el mismo sistema","La azeotrópica se comporta como sustancia pura al evaporarse sin deslizamiento de temperatura","La zeotrópica tiene menor potencial de calentamiento global que la mezcla azeotrópica similar","La zeotrópica requiere aceite mineral mientras que la azeotrópica necesita aceite POE siempre"], respuesta_correcta:1, explicacion:"Una mezcla azeotrópica se evapora y condensa a temperatura constante como sustancia pura, sin deslizamiento (glide) de temperatura." , question: "What is the main difference between an azeotropic blend and a zeotropic blend of refrigerant?", options: ["The azeotropic blend has higher operating pressure than the zeotropic in the same system", "The azeotropic blend behaves like a pure substance when evaporating, with no temperature glide", "The zeotropic blend has a lower global warming potential than a similar azeotropic blend", "The zeotropic blend requires mineral oil while the azeotropic always requires POE oil"], explanation: "An azeotropic blend evaporates and condenses at a constant temperature like a pure substance, with no temperature glide." },
  { id:"epa608_231", categoria:"EPA608_TIPO2", pregunta:"¿Qué refrigerante se considera el reemplazo directo más probable del R-410A en nuevos sistemas?", opciones:["R-32 por su mayor eficiencia energética y menor impacto ambiental comprobado actualmente","R-407C por su compatibilidad directa con componentes diseñados para sistemas de R-22","R-454B por su menor GWP y clasificación A2L compatible con equipos de R-410A existentes","R-134a por su amplia disponibilidad comercial y bajo costo de producción industrial actual"], respuesta_correcta:2, explicacion:"El R-454B es el reemplazo más probable del R-410A por su GWP bajo (466) y su clasificación A2L, compatible con muchos sistemas existentes." , question: "Which refrigerant is considered the most likely direct replacement for R-410A in new systems?", options: ["R-32 for its greater energy efficiency and proven lower environmental impact", "R-407C for its direct compatibility with components designed for R-22 systems", "R-454B for its lower GWP and A2L classification compatible with existing R-410A equipment", "R-134a for its wide commercial availability and low industrial production cost"], explanation: "R-454B is the most likely replacement for R-410A due to its low GWP (466) and A2L classification, compatible with many existing systems." },
  { id:"epa608_232", categoria:"EPA608_TIPO2", pregunta:"¿Por qué NO se pueden usar componentes de R-22 directamente en un sistema de R-410A?", opciones:["Porque el R-410A tiene diferente compatibilidad química con las tuberías de aluminio usadas","Porque el R-410A opera a presiones significativamente más altas que requieren componentes reforzados","Porque el R-410A requiere un tipo diferente de termostato para controlar la temperatura ambiente","Porque el R-410A tiene un caudal másico menor que requiere tuberías de mayor diámetro interno"], respuesta_correcta:1, explicacion:"El R-410A opera a presiones ~60% más altas que el R-22, requiriendo componentes (válvulas, tuberías, compresores) clasificados para mayor presión." , question: "Why can R-22 components NOT be used directly in an R-410A system?", options: ["Because R-410A has different chemical compatibility with the aluminum tubing used", "Because R-410A operates at significantly higher pressures requiring reinforced components", "Because R-410A requires a different type of thermostat to control ambient temperature", "Because R-410A has a lower mass flow rate requiring larger diameter internal tubing"], explanation: "R-410A operates at pressures approximately 60% higher than R-22, requiring components (valves, tubing, compressors) rated for higher pressure." },
  { id:"epa608_233", categoria:"EPA608_TIPO2", pregunta:"En una evacuación triple (triple evacuation), ¿qué se introduce entre cada ciclo de vacío?", opciones:["Se introduce refrigerante del tipo correcto para purgar la humedad residual del sistema","Se introduce nitrógeno seco para romper el vacío y ayudar a eliminar humedad residual","Se introduce aire comprimido filtrado para secar las superficies internas de las tuberías","Se introduce una mezcla de nitrógeno y CO2 para neutralizar ácidos dentro del circuito"], respuesta_correcta:1, explicacion:"En la evacuación triple, se rompe el vacío con nitrógeno seco entre cada ciclo para ayudar a arrastrar la humedad residual del sistema." , question: "In a triple evacuation, what is introduced between each vacuum cycle?", options: ["The correct type of refrigerant is introduced to purge residual moisture from the system", "Dry nitrogen is introduced to break the vacuum and help remove residual moisture", "Filtered compressed air is introduced to dry the internal surfaces of the tubing", "A mixture of nitrogen and CO2 is introduced to neutralize acids inside the circuit"], explanation: "In a triple evacuation, the vacuum is broken with dry nitrogen between each cycle to help carry out residual moisture from the system." },
  { id:"epa608_234", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la función principal de una válvula de expansión termostática (TXV) en el sistema?", opciones:["Controlar la presión de descarga del compresor durante variaciones de carga térmica del espacio","Regular el flujo de refrigerante al evaporador manteniendo un sobrecalentamiento constante ideal","Proteger el compresor contra retorno de líquido cuando la carga térmica baja súbitamente","Mantener la presión del condensador estable durante cambios de temperatura ambiente exterior"], respuesta_correcta:1, explicacion:"La TXV regula el flujo de refrigerante al evaporador para mantener un sobrecalentamiento constante, adaptándose a las variaciones de carga." , question: "What is the main function of a thermostatic expansion valve (TXV) in a system?", options: ["To control the compressor discharge pressure during thermal load variations in the space", "To regulate refrigerant flow to the evaporator while maintaining a constant ideal superheat", "To protect the compressor against liquid return when the thermal load drops suddenly", "To keep the condenser pressure stable during changes in outdoor ambient temperature"], explanation: "The TXV regulates refrigerant flow to the evaporator to maintain constant superheat, adapting to load variations." },
  { id:"epa608_235", categoria:"EPA608_TIPO2", pregunta:"¿Qué tipo de dispositivo de expansión es un orificio fijo (fixed orifice/piston)?", opciones:["Un dispositivo que ajusta automáticamente el flujo según la presión diferencial del sistema","Un dispositivo de expansión que no se ajusta y tiene un solo punto óptimo de operación diseñado","Un dispositivo electrónico que modula el flujo basándose en señales del termostato principal","Un dispositivo que varía su apertura según la temperatura del refrigerante en la línea líquida"], respuesta_correcta:1, explicacion:"El orificio fijo tiene una apertura que no cambia; funciona óptimamente en una sola condición de diseño, a diferencia de la TXV que se ajusta." , question: "What type of expansion device is a fixed orifice (piston)?", options: ["A device that automatically adjusts flow based on the system differential pressure", "An expansion device that does not adjust and has only one designed optimal operating point", "An electronic device that modulates flow based on signals from the main thermostat", "A device that varies its opening based on the temperature of the refrigerant in the liquid line"], explanation: "A fixed orifice has an opening that does not change; it works optimally at only one design condition, unlike a TXV which adjusts." },
  { id:"epa608_236", categoria:"EPA608_TIPO2", pregunta:"Al cargar un sistema con orificio fijo, ¿qué método de carga se prefiere normalmente?", opciones:["Carga por subenfriamiento midiendo la temperatura de la línea de líquido del condensador","Carga por sobrecalentamiento midiendo la temperatura de la línea de succión del evaporador","Carga por presión de descarga hasta alcanzar la presión nominal del fabricante del equipo","Carga por temperatura del aire de retorno comparada con la temperatura del aire de suministro"], respuesta_correcta:1, explicacion:"Para sistemas con orificio fijo, se carga midiendo el sobrecalentamiento en la línea de succión, ya que no hay TXV que lo regule automáticamente." , question: "When charging a system with a fixed orifice, which charging method is normally preferred?", options: ["Charging by subcooling, measuring the temperature of the condenser liquid line", "Charging by superheat, measuring the temperature of the evaporator suction line", "Charging by discharge pressure until reaching the manufacturer's rated pressure", "Charging by return air temperature compared to supply air temperature"], explanation: "For systems with a fixed orifice, charging is done by measuring superheat on the suction line, since there is no TXV to regulate it automatically." },
  { id:"epa608_237", categoria:"EPA608_TIPO2", pregunta:"Al cargar un sistema con válvula TXV, ¿qué método de carga se prefiere normalmente?", opciones:["Carga por sobrecalentamiento en la línea de succión del evaporador del sistema conectado","Carga por peso exacto según la especificación de la placa de datos del equipo instalado","Carga por subenfriamiento en la línea de líquido a la salida del condensador del sistema","Carga por presión de succión hasta alcanzar el valor nominal del fabricante del compresor"], respuesta_correcta:2, explicacion:"Para sistemas con TXV, se carga midiendo el subenfriamiento porque la TXV controla automáticamente el sobrecalentamiento." , question: "When charging a system with a TXV, which charging method is normally preferred?", options: ["Charging by superheat on the evaporator suction line of the connected system", "Charging by exact weight per the equipment nameplate data specification", "Charging by subcooling on the liquid line at the condenser outlet of the system", "Charging by suction pressure until reaching the manufacturer's rated compressor value"], explanation: "For systems with a TXV, charging is done by measuring subcooling because the TXV automatically controls the superheat." },
  { id:"epa608_238", categoria:"EPA608_TIPO2", pregunta:"¿Qué ocurre si un sistema de R-410A tiene sobrecalentamiento excesivamente alto en la succión?", opciones:["Indica exceso de refrigerante en el sistema causando condensación incompleta en el condensador","Indica falta de refrigerante, restricción en el flujo, o evaporador con exceso de carga térmica","Indica que el compresor tiene válvulas dañadas y no está comprimiendo adecuadamente el gas","Indica que el ventilador del condensador está funcionando a velocidad reducida por fallo motor"], respuesta_correcta:1, explicacion:"Un sobrecalentamiento alto generalmente indica falta de refrigerante, restricción en el dispositivo de expansión, o exceso de carga térmica en el evaporador." , question: "What happens if an R-410A system has excessively high superheat on the suction line?", options: ["It indicates excess refrigerant in the system causing incomplete condensation in the condenser", "It indicates low refrigerant, a flow restriction, or excessive thermal load on the evaporator", "It indicates the compressor has damaged valves and is not compressing the gas adequately", "It indicates the condenser fan is running at reduced speed due to motor failure"], explanation: "High superheat generally indicates low refrigerant charge, a restriction in the expansion device, or excessive thermal load on the evaporator." },
  { id:"epa608_239", categoria:"EPA608_TIPO2", pregunta:"¿Qué ocurre si un sistema tiene subenfriamiento excesivamente alto a la salida del condensador?", opciones:["Indica falta de refrigerante en el sistema causando evaporación prematura en línea líquida","Indica sobrecarga de refrigerante o restricción en el flujo entre el condensador y evaporador","Indica que el evaporador tiene poca carga térmica y el refrigerante no se evapora completamente","Indica que la válvula de expansión está abierta en exceso permitiendo demasiado flujo de líquido"], respuesta_correcta:1, explicacion:"Un subenfriamiento excesivamente alto generalmente indica sobrecarga de refrigerante o una restricción en la línea de líquido." , question: "What happens if a system has excessively high subcooling at the condenser outlet?", options: ["It indicates low refrigerant in the system causing premature evaporation in the liquid line", "It indicates a refrigerant overcharge or a flow restriction between the condenser and evaporator", "It indicates the evaporator has a low thermal load and the refrigerant is not fully evaporating", "It indicates the expansion valve is open too far, allowing excessive liquid flow"], explanation: "Excessively high subcooling generally indicates a refrigerant overcharge or a restriction in the liquid line." },
  { id:"epa608_240", categoria:"EPA608_TIPO2", pregunta:"¿Qué indica una presión de succión más baja de lo normal en un sistema Tipo II operando?", opciones:["Puede indicar sobrecarga de refrigerante con exceso de líquido inundando el evaporador completo","Puede indicar falta de refrigerante, restricción en el flujo, o flujo de aire reducido en evaporador","Puede indicar que el condensador está sucio y la transferencia de calor es deficiente actualmente","Puede indicar que la válvula de servicio del lado de alta está parcialmente cerrada por error"], respuesta_correcta:1, explicacion:"Presión de succión baja puede indicar carga baja, restricción en el dispositivo de expansión, o flujo de aire insuficiente sobre el evaporador." , question: "What does a lower-than-normal suction pressure indicate in an operating Type II system?", options: ["May indicate a refrigerant overcharge with excess liquid flooding the entire evaporator", "May indicate low refrigerant, a flow restriction, or reduced airflow over the evaporator", "May indicate a dirty condenser with deficient heat transfer currently", "May indicate the high-side service valve is partially closed by mistake"], explanation: "Low suction pressure can indicate a low charge, a restriction in the expansion device, or insufficient airflow over the evaporator." },
  { id:"epa608_241", categoria:"EPA608_TIPO2", pregunta:"¿Qué indica una presión de descarga más alta de lo normal en un sistema Tipo II operando?", opciones:["Puede indicar falta de refrigerante causando que el compresor trabaje más para mantener presión","Puede indicar que el evaporador está bloqueado y no absorbe suficiente calor del espacio","Puede indicar sobrecarga, condensador sucio, o exceso de aire no condensable en el sistema","Puede indicar que la válvula de expansión está completamente abierta permitiendo exceso flujo"], respuesta_correcta:2, explicacion:"Presión de descarga alta puede indicar sobrecarga, condensador sucio, ventilador del condensador defectuoso, o gases no condensables." , question: "What does a higher-than-normal discharge pressure indicate in an operating Type II system?", options: ["May indicate low refrigerant causing the compressor to work harder to maintain pressure", "May indicate the evaporator is blocked and not absorbing enough heat from the space", "May indicate an overcharge, dirty condenser, or excess non-condensable air in the system", "May indicate the expansion valve is fully open allowing excessive flow"], explanation: "High discharge pressure can indicate an overcharge, a dirty condenser, a defective condenser fan, or non-condensable gases." },
  { id:"epa608_242", categoria:"EPA608_TIPO2", pregunta:"¿Qué es la evacuación de un sistema y por qué es necesaria antes de cargar refrigerante nuevo?", opciones:["Es el proceso de limpiar las tuberías con nitrógeno para eliminar residuos de soldadura","Es el proceso de aplicar vacío profundo para eliminar humedad y gases no condensables del sistema","Es el proceso de presurizar con refrigerante para verificar que no existan fugas en conexiones","Es el proceso de circular aceite nuevo por el sistema para lubricar todas las partes móviles"], respuesta_correcta:1, explicacion:"La evacuación aplica vacío profundo para eliminar humedad y gases no condensables, que pueden causar ácidos, corrosión y presiones anormales." , question: "What is system evacuation and why is it necessary before charging with new refrigerant?", options: ["It is the process of cleaning the tubing with nitrogen to remove brazing residues", "It is the process of applying deep vacuum to remove moisture and non-condensable gases from the system", "It is the process of pressurizing with refrigerant to verify there are no leaks at connections", "It is the process of circulating new oil through the system to lubricate all moving parts"], explanation: "Evacuation applies a deep vacuum to remove moisture and non-condensable gases, which can cause acids, corrosion, and abnormal pressures." },
  { id:"epa608_243", categoria:"EPA608_TIPO2", pregunta:"¿Qué sucede si queda humedad dentro del sistema de refrigeración después de una evacuación incompleta?", opciones:["La humedad se evapora naturalmente con el calor de operación sin causar daños al sistema","La humedad puede formar ácidos que corroen componentes internos y causan fallas en el compresor","La humedad mejora la lubricación del aceite al reducir la fricción entre partes metálicas móviles","La humedad se congela en el filtro secador y se captura de forma permanente sin afectar nada"], respuesta_correcta:1, explicacion:"La humedad reacciona con el refrigerante y aceite formando ácidos corrosivos que deterioran aislamientos, válvulas y rodamientos del compresor." , question: "What happens if moisture remains inside the refrigeration system after an incomplete evacuation?", options: ["The moisture naturally evaporates with the heat of operation without causing any system damage", "The moisture can form acids that corrode internal components and cause compressor failure", "The moisture improves oil lubrication by reducing friction between moving metal parts", "The moisture freezes in the filter drier and is permanently captured without affecting anything"], explanation: "Moisture reacts with the refrigerant and oil, forming corrosive acids that deteriorate insulation, valves, and compressor bearings." },
  { id:"epa608_244", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el propósito del control de presión de cabeza (head pressure control) en un sistema?", opciones:["Proteger el compresor contra sobrepresión excesiva durante los días más calurosos del verano","Mantener la presión del condensador suficientemente alta para alimentar el dispositivo de expansión","Reducir el consumo eléctrico del compresor durante períodos de baja demanda de enfriamiento","Evitar que la presión de succión caiga demasiado bajo durante períodos de baja carga térmica"], respuesta_correcta:1, explicacion:"El control de presión de cabeza mantiene presión mínima en el condensador para asegurar flujo adecuado de refrigerante al dispositivo de expansión, especialmente en clima frío." , question: "What is the purpose of head pressure control in a system?", options: ["To protect the compressor against excessive high pressure during the hottest summer days", "To maintain condenser pressure high enough to feed the expansion device properly", "To reduce compressor electrical consumption during low cooling demand periods", "To prevent suction pressure from dropping too low during low thermal load periods"], explanation: "Head pressure control maintains minimum condenser pressure to ensure adequate refrigerant flow to the expansion device, especially in cold weather." },
  { id:"epa608_245", categoria:"EPA608_TIPO2", pregunta:"¿Por qué es importante mantener limpio el serpentín del condensador en un sistema de aire acondicionado?", opciones:["Un condensador sucio reduce la capacidad de enfriamiento pero no afecta la vida útil del compresor","Un condensador sucio aumenta la presión de descarga, reduce eficiencia y puede dañar el compresor","Un condensador sucio solo afecta el nivel de ruido del ventilador sin impactar el rendimiento","Un condensador sucio disminuye la presión de descarga haciendo que el sistema opere ineficiente"], respuesta_correcta:1, explicacion:"Un condensador sucio reduce la transferencia de calor, aumentando la presión y temperatura de descarga, reduciendo eficiencia y acortando la vida del compresor." , question: "Why is it important to keep the condenser coil clean in an air conditioning system?", options: ["A dirty condenser reduces cooling capacity but does not affect compressor lifespan", "A dirty condenser increases discharge pressure, reduces efficiency, and can damage the compressor", "A dirty condenser only affects the fan noise level without impacting system performance", "A dirty condenser decreases discharge pressure causing the system to operate inefficiently"], explanation: "A dirty condenser reduces heat transfer, increasing discharge pressure and temperature, reducing efficiency, and shortening compressor life." },
  { id:"epa608_246", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la diferencia entre un sistema split y un sistema paquete (package unit)?", opciones:["El sistema split tiene mayor eficiencia que el paquete debido a la separación de componentes clave","El split tiene componentes separados interior/exterior; el paquete tiene todo en una sola unidad","El sistema paquete solo se usa en aplicaciones residenciales mientras el split es solo comercial","El split usa refrigerante R-410A exclusivamente y el paquete usa R-22 en todas las aplicaciones"], respuesta_correcta:1, explicacion:"Un sistema split separa el evaporador (interior) del condensador (exterior); un package unit contiene todos los componentes en una sola unidad exterior." , question: "What is the difference between a split system and a package unit?", options: ["The split system has greater efficiency than the package unit due to the separation of key components", "The split has separate indoor/outdoor components; the package unit has everything in a single unit", "The package unit is only used in residential applications while the split is only commercial", "The split uses R-410A exclusively and the package unit uses R-22 in all applications"], explanation: "A split system separates the evaporator (indoor) from the condenser (outdoor); a package unit contains all components in a single outdoor unit." },
  { id:"epa608_247", categoria:"EPA608_TIPO2", pregunta:"¿Qué es un sistema VRF/VRV y cuál es su característica principal de operación?", opciones:["Es un sistema de refrigeración con compresores recíprocos que operan a velocidad fija constante","Es un sistema que varía el flujo de refrigerante con compresor de velocidad variable tipo inverter","Es un sistema de expansión directa que usa múltiples compresores scroll operando en secuencia","Es un sistema centralizado con chiller que distribuye agua helada a unidades manejadoras de aire"], respuesta_correcta:1, explicacion:"VRF (Variable Refrigerant Flow) usa compresores inverter de velocidad variable para modular el flujo de refrigerante según la demanda de cada zona." , question: "What is a VRF/VRV system and what is its main operating characteristic?", options: ["It is a refrigeration system with reciprocating compressors that operate at constant fixed speed", "It is a system that varies refrigerant flow using a variable-speed inverter-driven compressor", "It is a direct expansion system that uses multiple scroll compressors operating in sequence", "It is a centralized system with a chiller that distributes chilled water to air handling units"], explanation: "VRF (Variable Refrigerant Flow) uses inverter-driven variable-speed compressors to modulate refrigerant flow according to the demand of each zone." },
  { id:"epa608_248", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el nivel de vacío requerido para equipos de recuperación fabricados ANTES de noviembre de 1993 para Tipo II con menos de 200 lb?", opciones:["0 psig según los estándares originales de recuperación establecidos por la normativa EPA inicial","10 pulgadas de mercurio de vacío para los equipos de recuperación de primera generación","4 pulgadas de mercurio de vacío según las regulaciones de la EPA para equipos más antiguos","15 pulgadas de mercurio de vacío para todos los equipos de recuperación sin distinción"], respuesta_correcta:2, explicacion:"Los equipos de recuperación fabricados antes de noviembre de 1993 debían alcanzar 4 pulgadas de Hg de vacío para sistemas Tipo II con <200 lb." , question: "What is the required vacuum level for recovery equipment manufactured BEFORE November 1993 for Type II with less than 200 lb?", options: ["0 psig per the original recovery standards established by the initial EPA regulation", "10 inches of mercury vacuum for first-generation recovery equipment", "4 inches of mercury vacuum per EPA regulations for older equipment", "15 inches of mercury vacuum for all recovery equipment without distinction"], explanation: "Recovery equipment manufactured before November 1993 was required to reach 4 inches of Hg vacuum for Type II systems with less than 200 lb." },
  { id:"epa608_249", categoria:"EPA608_TIPO2", pregunta:"¿Qué refrigerante de la serie 400 es una mezcla zeotrópica comúnmente usada como alternativa al R-22?", opciones:["R-404A que se usa principalmente en refrigeración comercial de media y baja temperatura","R-410A que se usa principalmente en sistemas de aire acondicionado residencial nuevos","R-407C que fue diseñado específicamente como reemplazo directo del R-22 en retrofits","R-422D que se usa exclusivamente en sistemas de refrigeración industrial de gran escala"], respuesta_correcta:2, explicacion:"El R-407C es una mezcla zeotrópica diseñada como reemplazo retrofit del R-22, con presiones similares aunque requiere cambio a aceite POE." , question: "Which 400-series refrigerant is a zeotropic blend commonly used as an alternative to R-22?", options: ["R-404A, used primarily in medium- and low-temperature commercial refrigeration", "R-410A, used primarily in new residential air conditioning systems", "R-407C, designed specifically as a direct retrofit replacement for R-22", "R-422D, used exclusively in large-scale industrial refrigeration systems"], explanation: "R-407C is a zeotropic blend designed as a retrofit replacement for R-22, with similar pressures, although it requires a change to POE oil." },
  { id:"epa608_250", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el deslizamiento (glide) de temperatura aproximado del R-407C durante la evaporación?", opciones:["Aproximadamente 1°F de deslizamiento porque es una mezcla casi azeotrópica en composición","Aproximadamente 3°F de deslizamiento típico durante el proceso de cambio de fase completo","Aproximadamente 9°F de deslizamiento lo que complica las mediciones de sobrecalentamiento","Aproximadamente 15°F de deslizamiento haciéndolo incompatible con sistemas convencionales"], respuesta_correcta:2, explicacion:"El R-407C tiene un glide de aproximadamente 9°F, lo que requiere usar temperatura de rocío para medir sobrecalentamiento y burbuja para subenfriamiento." , question: "What is the approximate temperature glide of R-407C during evaporation?", options: ["Approximately 1 deg F of glide because it is a near-azeotropic blend in composition", "Approximately 3 deg F of typical glide during the complete phase-change process", "Approximately 9 deg F of glide, which complicates superheat measurements", "Approximately 15 deg F of glide, making it incompatible with conventional systems"], explanation: "R-407C has a glide of approximately 9 deg F, which requires using the dew point temperature for measuring superheat and the bubble point for subcooling." },
  { id:"epa608_251", categoria:"EPA608_TIPO2", pregunta:"Cuando se mide sobrecalentamiento con R-407C, ¿qué temperatura de saturación se debe usar?", opciones:["La temperatura de burbuja (bubble point) correspondiente a la presión de succión medida","La temperatura de rocío (dew point) correspondiente a la presión de succión del sistema","La temperatura promedio entre burbuja y rocío a la presión de succión del evaporador","La temperatura de saturación estándar como si fuera un refrigerante puro sin corrección"], respuesta_correcta:1, explicacion:"Para medir sobrecalentamiento con mezclas zeotrópicas, se usa la temperatura de rocío (dew point) a la presión de succión." , question: "When measuring superheat with R-407C, which saturation temperature should be used?", options: ["The bubble point temperature corresponding to the measured suction pressure", "The dew point temperature corresponding to the system suction pressure", "The average temperature between the bubble and dew points at the evaporator suction pressure", "The standard saturation temperature as if it were a pure refrigerant without correction"], explanation: "When measuring superheat with zeotropic blends, the dew point temperature at the suction pressure is used." },
  { id:"epa608_252", categoria:"EPA608_TIPO2", pregunta:"Cuando se mide subenfriamiento con R-407C, ¿qué temperatura de saturación se debe usar?", opciones:["La temperatura de rocío (dew point) correspondiente a la presión del lado de alta del sistema","La temperatura promedio entre rocío y burbuja a la presión del condensador del sistema medido","La temperatura de saturación estándar como si fuera un refrigerante puro a esa misma presión","La temperatura de burbuja (bubble point) correspondiente a la presión del condensador medida"], respuesta_correcta:3, explicacion:"Para medir subenfriamiento con mezclas zeotrópicas, se usa la temperatura de burbuja (bubble point) a la presión de descarga." , question: "When measuring subcooling with R-407C, which saturation temperature should be used?", options: ["The dew point temperature corresponding to the high-side pressure of the system", "The average temperature between the dew and bubble points at the measured condenser pressure", "The standard saturation temperature as if it were a pure refrigerant at that same pressure", "The bubble point temperature corresponding to the measured condenser pressure"], explanation: "When measuring subcooling with zeotropic blends, the bubble point temperature at the discharge pressure is used." },
  { id:"epa608_253", categoria:"EPA608_TIPO2", pregunta:"¿Qué es el fraccionamiento de un refrigerante zeotrópico y cuándo puede ocurrir?", opciones:["Es la separación de componentes por fugas o carga incorrecta en vapor que altera la composición","Es la descomposición química del refrigerante por exposición a temperaturas excesivamente altas","Es la formación de cristales de hielo dentro del refrigerante por contaminación con humedad","Es la reacción del refrigerante con el aceite lubricante formando compuestos ácidos corrosivos"], respuesta_correcta:0, explicacion:"El fraccionamiento ocurre cuando los componentes de la mezcla se separan por fugas o carga en vapor, cambiando las propiedades del refrigerante." , question: "What is fractionation of a zeotropic refrigerant and when can it occur?", options: ["It is the separation of components due to leaks or incorrect vapor charging that alters the composition", "It is the chemical decomposition of the refrigerant due to exposure to excessively high temperatures", "It is the formation of ice crystals inside the refrigerant due to moisture contamination", "It is the reaction of the refrigerant with the lubricating oil forming corrosive acid compounds"], explanation: "Fractionation occurs when the components of the blend separate due to leaks or vapor charging, changing the refrigerant properties." },
  { id:"epa608_254", categoria:"EPA608_TIPO2", pregunta:"¿Por qué el R-404A se usa comúnmente en refrigeración comercial de media y baja temperatura?", opciones:["Porque tiene el GWP más bajo de todos los refrigerantes HFC disponibles comercialmente ahora","Porque tiene excelentes propiedades de transferencia de calor a temperaturas de evaporación bajas","Porque es el único refrigerante compatible con aceite mineral en compresores semi-herméticos","Porque opera a presiones más bajas que el R-22 reduciendo el riesgo de fugas en el sistema"], respuesta_correcta:1, explicacion:"El R-404A tiene excelentes propiedades termodinámicas a temperaturas de evaporación bajas, haciéndolo ideal para refrigeración comercial." , question: "Why is R-404A commonly used in medium- and low-temperature commercial refrigeration?", options: ["Because it has the lowest GWP of all commercially available HFC refrigerants today", "Because it has excellent heat transfer properties at low evaporation temperatures", "Because it is the only refrigerant compatible with mineral oil in semi-hermetic compressors", "Because it operates at lower pressures than R-22, reducing the risk of system leaks"], explanation: "R-404A has excellent thermodynamic properties at low evaporation temperatures, making it ideal for commercial refrigeration." },
  { id:"epa608_255", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la diferencia principal entre R-507A y R-404A en aplicaciones de refrigeración?", opciones:["El R-507A opera a presiones significativamente más bajas que el R-404A en todos los casos","El R-507A es una mezcla azeotrópica mientras que el R-404A es zeotrópica con glide mínimo","El R-507A requiere aceite mineral mientras que el R-404A requiere aceite POE exclusivamente","El R-507A tiene un GWP mucho más bajo que el R-404A haciéndolo más ecológico actualmente"], respuesta_correcta:1, explicacion:"El R-507A es azeotrópico (sin glide) mientras el R-404A es zeotrópico con glide mínimo; ambos tienen presiones y rendimiento similares." , question: "What is the main difference between R-507A and R-404A in refrigeration applications?", options: ["R-507A operates at significantly lower pressures than R-404A in all cases", "R-507A is an azeotropic blend while R-404A is zeotropic with minimal glide", "R-507A requires mineral oil while R-404A requires POE oil exclusively", "R-507A has a much lower GWP than R-404A, making it more environmentally friendly today"], explanation: "R-507A is azeotropic (no glide) while R-404A is zeotropic with minimal glide; both have similar pressures and performance." },
  { id:"epa608_256", categoria:"EPA608_TIPO2", pregunta:"¿Qué debe hacerse con el refrigerante recuperado que está contaminado y no puede ser reutilizado?", opciones:["Debe ser devuelto al proveedor original del refrigerante para su procesamiento adecuado","Debe ser enviado a un reclamador certificado por la EPA para su purificación o destrucción","Debe ser mezclado con refrigerante nuevo para diluir los contaminantes a niveles aceptables","Debe ser almacenado indefinidamente en cilindros sellados hasta que exista tecnología nueva"], respuesta_correcta:1, explicacion:"El refrigerante contaminado que no puede ser reutilizado debe enviarse a un reclamador certificado por la EPA (como AHRI) para purificación o destrucción." , question: "What should be done with recovered refrigerant that is contaminated and cannot be reused?", options: ["It should be returned to the original refrigerant supplier for proper processing", "It should be sent to an EPA-certified reclaimer for purification or destruction", "It should be mixed with new refrigerant to dilute the contaminants to acceptable levels", "It should be stored indefinitely in sealed cylinders until new technology becomes available"], explanation: "Contaminated refrigerant that cannot be reused must be sent to an EPA-certified reclaimer (such as AHRI) for purification or destruction." },
  { id:"epa608_257", categoria:"EPA608_TIPO2", pregunta:"¿De qué color es el cilindro de recuperación utilizado para almacenar refrigerante recuperado?", opciones:["El cilindro de recuperación es de color azul con franja amarilla según estándar industrial","El cilindro de recuperación es de color amarillo con tapa gris según el estándar ARI/DOT","El cilindro de recuperación es de color verde con franja blanca según normativa EPA vigente","El cilindro de recuperación es de color gris con tapa amarilla según el estándar ARI/DOT"], respuesta_correcta:3, explicacion:"Los cilindros de recuperación son gris con tapa amarilla según el estándar ARI/DOT, para diferenciarlos de los cilindros de refrigerante nuevo." , question: "What color is the recovery cylinder used to store recovered refrigerant?", options: ["The recovery cylinder is blue with a yellow stripe per the industry standard", "The recovery cylinder is yellow with a gray cap per the ARI/DOT standard", "The recovery cylinder is green with a white stripe per current EPA regulations", "The recovery cylinder is gray with a yellow cap per the ARI/DOT standard"], explanation: "Recovery cylinders are gray with a yellow cap per the ARI/DOT standard, to differentiate them from new refrigerant cylinders." },
  { id:"epa608_258", categoria:"EPA608_TIPO2", pregunta:"¿A qué porcentaje máximo de su capacidad se debe llenar un cilindro de recuperación con refrigerante líquido?", opciones:["Se debe llenar a un máximo del 90% de su capacidad para dejar espacio de expansión térmica","Se debe llenar a un máximo del 80% de su capacidad para dejar espacio de expansión térmica","Se debe llenar a un máximo del 70% de su capacidad para dejar espacio de expansión térmica","Se debe llenar a un máximo del 60% de su capacidad para dejar espacio de expansión térmica"], respuesta_correcta:1, explicacion:"Los cilindros de recuperación no deben llenarse más del 80% de su capacidad para permitir la expansión térmica del líquido y prevenir rupturas." , question: "To what maximum percentage of its capacity should a recovery cylinder be filled with liquid refrigerant?", options: ["It should be filled to a maximum of 90% of its capacity to allow for thermal expansion", "It should be filled to a maximum of 80% of its capacity to allow for thermal expansion", "It should be filled to a maximum of 70% of its capacity to allow for thermal expansion", "It should be filled to a maximum of 60% of its capacity to allow for thermal expansion"], explanation: "Recovery cylinders must not be filled beyond 80% of their capacity to allow for thermal expansion of the liquid and prevent rupture." },
  { id:"epa608_259", categoria:"EPA608_TIPO2", pregunta:"¿Qué se debe verificar antes de conectar la máquina de recuperación a un sistema de refrigeración?", opciones:["Verificar que el sistema está completamente cargado y funcionando a plena capacidad de diseño","Verificar que los cilindros de recuperación están vacíos, evacuados y dentro de fecha de prueba","Verificar que el compresor del sistema ha estado apagado por al menos 24 horas antes de iniciar","Verificar que la temperatura ambiente es superior a 70°F para una recuperación eficiente total"], respuesta_correcta:1, explicacion:"Antes de recuperar, se debe verificar que los cilindros están evacuados, no sobrepasen el 80% de capacidad y estén dentro de su fecha de prueba hidrostática." , question: "What should be verified before connecting the recovery machine to a refrigeration system?", options: ["Verify that the system is fully charged and operating at full design capacity", "Verify that the recovery cylinders are empty, evacuated, and within their hydrostatic test date", "Verify that the system compressor has been off for at least 24 hours before starting", "Verify that the ambient temperature is above 70 deg F for efficient total recovery"], explanation: "Before recovering, verify that the cylinders are evacuated, do not exceed 80% capacity, and are within their hydrostatic test date." },
  { id:"epa608_260", categoria:"EPA608_TIPO2", pregunta:"¿Qué precaución se debe tomar al recuperar refrigerante de un sistema que tuvo quemadura de compresor?", opciones:["No se necesita precaución especial ya que el refrigerante no se contamina en una quemadura","Se debe usar un filtro ácido en la línea de recuperación para proteger la máquina recuperadora","Se debe ventilar el refrigerante contaminado a la atmósfera por ser irrecuperable por ley EPA","Se debe mezclar con refrigerante nuevo directamente en el cilindro para neutralizar los ácidos"], respuesta_correcta:1, explicacion:"Tras un burnout, el refrigerante contiene ácidos y contaminantes; se debe usar un filtro en la línea de recuperación para proteger el equipo recuperador." , question: "What precaution should be taken when recovering refrigerant from a system that had a compressor burnout?", options: ["No special precaution is needed since the refrigerant is not contaminated in a burnout", "An acid filter should be used on the recovery line to protect the recovery machine", "The contaminated refrigerant should be vented to the atmosphere since it is unrecoverable by EPA law", "It should be mixed with new refrigerant directly in the cylinder to neutralize the acids"], explanation: "After a burnout, the refrigerant contains acids and contaminants; a filter must be used on the recovery line to protect the recovery equipment." },
  { id:"epa608_261", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la presión máxima de prueba típica para un sistema residencial de R-410A al buscar fugas?", opciones:["La presión de prueba es determinada por el fabricante, típicamente entre 500-600 psig para R-410A","La presión de prueba es siempre 150 psig independientemente del tipo de refrigerante del sistema","La presión de prueba es la presión de operación normal más un 10% como margen de seguridad","La presión de prueba nunca debe exceder la presión de succión máxima especificada del sistema"], respuesta_correcta:0, explicacion:"La presión de prueba la determina el fabricante y para R-410A típicamente es entre 500-600 psig; siempre consultar la placa de datos del equipo." , question: "What is the typical maximum test pressure for a residential R-410A system when searching for leaks?", options: ["The test pressure is determined by the manufacturer, typically between 500-600 psig for R-410A", "The test pressure is always 150 psig regardless of the system refrigerant type", "The test pressure is the normal operating pressure plus 10% as a safety margin", "The test pressure must never exceed the maximum specified suction pressure of the system"], explanation: "The test pressure is determined by the manufacturer and for R-410A typically ranges between 500-600 psig; always check the equipment nameplate data." },
  { id:"epa608_262", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el método más sensible para detectar fugas pequeñas en sistemas de refrigeración Tipo II?", opciones:["Detector de fugas ultrasónico que detecta el sonido de alta frecuencia del refrigerante escapando","Solución de burbujas aplicada en todas las conexiones y juntas del sistema bajo presión normal","Detector electrónico de fugas calibrado para el tipo específico de refrigerante del sistema usado","Tinte fluorescente UV inyectado en el sistema y verificado con lámpara ultravioleta especial"], respuesta_correcta:2, explicacion:"Los detectores electrónicos de fugas son los más sensibles, capaces de detectar fugas de hasta 0.1 oz/año cuando están correctamente calibrados." , question: "What is the most sensitive method for detecting small leaks in Type II refrigeration systems?", options: ["An ultrasonic leak detector that detects the high-frequency sound of escaping refrigerant", "A bubble solution applied to all connections and joints of the system under normal pressure", "An electronic leak detector calibrated for the specific refrigerant type used in the system", "UV fluorescent dye injected into the system and verified with a special ultraviolet lamp"], explanation: "Electronic leak detectors are the most sensitive, capable of detecting leaks as small as 0.1 oz/year when properly calibrated." },
  { id:"epa608_263", categoria:"EPA608_TIPO2", pregunta:"¿Qué componente del sistema se daña más rápidamente cuando hay gases no condensables presentes?", opciones:["El evaporador sufre daño por congelación excesiva de la superficie del serpentín de enfriamiento","El dispositivo de expansión se obstruye con los gases atrapados reduciendo el flujo de refrigerante","El compresor se sobrecalienta porque los gases no condensables aumentan la presión de descarga","El filtro secador se satura prematuramente perdiendo su capacidad de absorción de la humedad"], respuesta_correcta:2, explicacion:"Los gases no condensables (como aire) aumentan la presión y temperatura de descarga, causando sobrecalentamiento del compresor y reduciendo su vida útil." , question: "Which system component is damaged most quickly when non-condensable gases are present?", options: ["The evaporator suffers damage from excessive frost buildup on the cooling coil surface", "The expansion device becomes clogged by the trapped gases, reducing refrigerant flow", "The compressor overheats because non-condensable gases increase the discharge pressure", "The filter drier saturates prematurely, losing its moisture absorption capacity"], explanation: "Non-condensable gases (such as air) increase the discharge pressure and temperature, causing compressor overheating and reducing its lifespan." },
  { id:"epa608_264", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el indicador más claro de presencia de aire (gas no condensable) en un sistema de refrigeración?", opciones:["Presión de succión más baja de lo normal con temperatura de evaporación también baja anormalmente","Presión de descarga más alta de lo normal para la temperatura de condensación medida actualmente","Temperatura de la línea de líquido fluctuando constantemente sin patrón lógico de operación","Sobrecalentamiento excesivamente bajo en la línea de succión indicando inundación del evaporador"], respuesta_correcta:1, explicacion:"Aire en el sistema causa presión de descarga más alta que la correspondiente a la temperatura de condensación, ya que el aire no se condensa." , question: "What is the clearest indicator of air (non-condensable gas) presence in a refrigeration system?", options: ["Lower-than-normal suction pressure with abnormally low evaporation temperature as well", "Higher-than-normal discharge pressure for the currently measured condensing temperature", "Liquid line temperature fluctuating constantly with no logical operating pattern", "Excessively low superheat on the suction line indicating evaporator flooding"], explanation: "Air in the system causes discharge pressure to be higher than what corresponds to the condensing temperature, since air does not condense." },
  { id:"epa608_265", categoria:"EPA608_TIPO2", pregunta:"¿Para qué sirve el aceite POE (poliolester) que se usa con refrigerantes HFC como R-410A?", opciones:["Sirve exclusivamente para lubricar los cojinetes del motor eléctrico dentro del compresor hermético","Sirve como lubricante miscible con HFCs que además absorbe humedad y requiere manejo cuidadoso","Sirve para reducir la temperatura del refrigerante en el condensador mejorando transferencia calor","Sirve como sellador de las juntas internas del compresor previniendo fugas de refrigerante gas"], respuesta_correcta:1, explicacion:"El aceite POE es miscible con refrigerantes HFC pero es muy higroscópico (absorbe humedad rápidamente), por lo que debe manejarse con cuidado y mínima exposición al aire." , question: "What is the purpose of POE (polyolester) oil used with HFC refrigerants such as R-410A?", options: ["It serves exclusively to lubricate the electric motor bearings inside the hermetic compressor", "It serves as a lubricant miscible with HFCs that also absorbs moisture and requires careful handling", "It serves to reduce the refrigerant temperature in the condenser, improving heat transfer", "It serves as a sealant for the compressor internal joints, preventing refrigerant gas leaks"], explanation: "POE oil is miscible with HFC refrigerants but is highly hygroscopic (absorbs moisture rapidly), so it must be handled carefully with minimal air exposure." },
  { id:"epa608_266", categoria:"EPA608_TIPO2", pregunta:"¿Qué precaución especial requiere el aceite POE respecto a la exposición ambiental durante servicio?", opciones:["El aceite POE se degrada con la luz solar directa y debe almacenarse en recipientes oscuros","El aceite POE es extremadamente inflamable y debe mantenerse alejado de cualquier fuente de calor","El aceite POE es muy higroscópico y absorbe humedad del aire rápidamente al estar expuesto al ambiente","El aceite POE reacciona con el cobre de las tuberías si se expone a temperaturas superiores a 100°F"], respuesta_correcta:2, explicacion:"El aceite POE absorbe humedad del aire muy rápidamente; los recipientes deben mantenerse sellados y la exposición al aire minimizada durante el servicio." , question: "What special precaution does POE oil require regarding environmental exposure during service?", options: ["POE oil degrades in direct sunlight and must be stored in dark containers", "POE oil is extremely flammable and must be kept away from any heat source", "POE oil is very hygroscopic and absorbs moisture from the air rapidly when exposed to the atmosphere", "POE oil reacts with copper tubing if exposed to temperatures above 100 deg F"], explanation: "POE oil absorbs moisture from the air very rapidly; containers must be kept sealed and air exposure minimized during service." },
  { id:"epa608_267", categoria:"EPA608_TIPO2", pregunta:"¿Qué indica un compresor que tiene alta corriente de amperaje y baja presión de succión simultáneamente?", opciones:["Indica sobrecarga de refrigerante causando que el compresor trabaje con líquido en los cilindros","Indica una posible restricción en el lado de succión como un filtro secador tapado parcialmente","Indica que el ventilador del condensador está fallando y no rechaza suficiente calor al ambiente","Indica un problema eléctrico en el capacitor de arranque del motor del compresor monofásico"], respuesta_correcta:1, explicacion:"Alta corriente con baja succión sugiere que el compresor trabaja más para compensar una restricción en el lado de succión del sistema." , question: "What does a compressor with high amperage draw and low suction pressure simultaneously indicate?", options: ["It indicates a refrigerant overcharge causing the compressor to work with liquid in the cylinders", "It indicates a possible restriction on the suction side, such as a partially clogged filter drier", "It indicates the condenser fan is failing and not rejecting enough heat to the ambient", "It indicates an electrical problem in the start capacitor of the single-phase compressor motor"], explanation: "High amperage with low suction suggests the compressor is working harder to compensate for a restriction on the suction side of the system." },
  { id:"epa608_268", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la temperatura normal de la línea de descarga en un sistema de aire acondicionado Tipo II?", opciones:["Entre 50°F y 80°F dependiendo de la temperatura ambiente exterior y la carga térmica del espacio","Entre 100°F y 150°F dependiendo de las condiciones operativas del sistema de aire acondicionado","Entre 150°F y 225°F dependiendo de las condiciones de operación y tipo de refrigerante usado","Entre 250°F y 350°F dependiendo del tipo de compresor y la relación de compresión del sistema"], respuesta_correcta:2, explicacion:"La temperatura de la línea de descarga normalmente está entre 150°F y 225°F; temperaturas más altas indican problemas como retorno de vapor caliente." , question: "What is the normal discharge line temperature in a Type II air conditioning system?", options: ["Between 50 deg F and 80 deg F depending on the outdoor ambient temperature and thermal load", "Between 100 deg F and 150 deg F depending on the air conditioning system operating conditions", "Between 150 deg F and 225 deg F depending on operating conditions and the type of refrigerant used", "Between 250 deg F and 350 deg F depending on the compressor type and compression ratio"], explanation: "The discharge line temperature normally ranges between 150 deg F and 225 deg F; higher temperatures indicate problems such as hot gas return." },
  { id:"epa608_269", categoria:"EPA608_TIPO2", pregunta:"¿Qué significa 'retrofit' cuando se habla de convertir un sistema de R-22 a un refrigerante alternativo?", opciones:["Significa reemplazar completamente el sistema por uno nuevo diseñado para el refrigerante alternativo","Significa modificar un sistema existente para usar un refrigerante diferente al original de fábrica","Significa agregar refrigerante alternativo al R-22 existente para mejorar su rendimiento general","Significa cambiar únicamente el compresor manteniendo todos los demás componentes sin modificar"], respuesta_correcta:1, explicacion:"Un retrofit implica modificar un sistema existente (cambiar aceite, sellos, filtros) para usar un refrigerante alternativo sin reemplazar todo el equipo." , question: "What does 'retrofit' mean when referring to converting an R-22 system to an alternative refrigerant?", options: ["It means completely replacing the system with a new one designed for the alternative refrigerant", "It means modifying an existing system to use a refrigerant different from the factory original", "It means adding alternative refrigerant to the existing R-22 to improve its overall performance", "It means changing only the compressor while keeping all other components unmodified"], explanation: "A retrofit involves modifying an existing system (changing oil, seals, filters) to use an alternative refrigerant without replacing all the equipment." },
  { id:"epa608_270", categoria:"EPA608_TIPO2", pregunta:"Al hacer retrofit de R-22 a R-407C, ¿qué componente debe cambiarse obligatoriamente?", opciones:["El compresor completo porque el R-407C opera a presiones incompatibles con compresores de R-22","El aceite mineral debe cambiarse a aceite POE compatible con el refrigerante HFC tipo R-407C","Las tuberías de cobre deben reemplazarse por tuberías de mayor diámetro para el nuevo flujo","El condensador debe reemplazarse por uno de mayor capacidad para las presiones más altas usadas"], respuesta_correcta:1, explicacion:"Al convertir de R-22 a R-407C, es obligatorio cambiar el aceite mineral por aceite POE, ya que los HFC no son miscibles con aceite mineral." , question: "When retrofitting from R-22 to R-407C, which component must be changed as a requirement?", options: ["The entire compressor, because R-407C operates at pressures incompatible with R-22 compressors", "The mineral oil must be changed to POE oil compatible with the HFC-type R-407C refrigerant", "The copper tubing must be replaced with larger-diameter tubing for the new flow requirements", "The condenser must be replaced with a higher-capacity one for the higher pressures used"], explanation: "When converting from R-22 to R-407C, the mineral oil must be replaced with POE oil, as HFCs are not miscible with mineral oil." },
  { id:"epa608_271", categoria:"EPA608_TIPO2", pregunta:"¿Por qué NUNCA se deben mezclar refrigerantes diferentes dentro de un mismo sistema de refrigeración?", opciones:["Porque la mezcla cambia las presiones de operación y hace imposible el diagnóstico correcto del sistema","Porque es ilegal según la EPA y el refrigerante mezclado no puede ser reclamado ni reciclado fácilmente","Porque la mezcla puede crear refrigerantes desconocidos con propiedades termodinámicas impredecibles","Todas las opciones anteriores son razones válidas por las que no se deben mezclar refrigerantes"], respuesta_correcta:3, explicacion:"Mezclar refrigerantes es ilegal, crea mezclas impredecibles, dificulta el servicio, y el refrigerante resultante no puede ser reclamado." , question: "Why should different refrigerants NEVER be mixed inside the same refrigeration system?", options: ["Because the mixture changes operating pressures and makes correct system diagnosis impossible", "Because it is illegal under the EPA and the mixed refrigerant cannot be easily reclaimed or recycled", "Because the mixture can create unknown refrigerants with unpredictable thermodynamic properties", "All of the above are valid reasons why refrigerants should not be mixed"], explanation: "Mixing refrigerants is illegal, creates unpredictable blends, makes servicing difficult, and the resulting refrigerant cannot be reclaimed." },
  { id:"epa608_272", categoria:"EPA608_TIPO2", pregunta:"¿Qué tipo de válvula de servicio permite aislar el compresor del resto del sistema para dar servicio?", opciones:["Válvulas de acceso Schrader instaladas en las líneas de succión y descarga del compresor","Válvulas de servicio tipo vástago (stem valves) en succión y descarga del compresor hermético","Válvulas check (no retorno) instaladas en la descarga para prevenir flujo inverso de refrigerante","Válvulas de alivio de presión instaladas en el cárter del compresor para protección contra sobrepresión"], respuesta_correcta:1, explicacion:"Las válvulas de servicio de vástago (back-seated, front-seated) permiten aislar el compresor del sistema para servicio, carga y recuperación." , question: "What type of service valve allows the compressor to be isolated from the rest of the system for service?", options: ["Schrader access valves installed on the suction and discharge lines of the compressor", "Stem-type service valves on the suction and discharge of the hermetic compressor", "Check (non-return) valves installed on the discharge to prevent reverse refrigerant flow", "Pressure relief valves installed on the compressor crankcase for overpressure protection"], explanation: "Stem-type service valves (back-seated, front-seated) allow the compressor to be isolated from the system for service, charging, and recovery." },
  { id:"epa608_273", categoria:"EPA608_TIPO2", pregunta:"¿Cuándo una válvula de servicio está en posición 'back-seated' (completamente abierta), qué ocurre?", opciones:["El puerto del manómetro está abierto y el flujo al sistema está bloqueado completamente cerrado","El puerto del manómetro está cerrado y el refrigerante fluye normalmente a través del sistema","Tanto el puerto del manómetro como el flujo al sistema están abiertos simultáneamente al operar","Tanto el puerto del manómetro como el flujo al sistema están bloqueados completamente cerrados"], respuesta_correcta:1, explicacion:"En posición back-seated, la válvula está completamente abierta al sistema y el puerto del manómetro está sellado; es la posición normal de operación." , question: "When a service valve is in the 'back-seated' (fully open) position, what happens?", options: ["The gauge port is open and the flow to the system is completely blocked", "The gauge port is closed and the refrigerant flows normally through the system", "Both the gauge port and the system flow are open simultaneously during operation", "Both the gauge port and the system flow are completely blocked"], explanation: "In the back-seated position, the valve is fully open to the system and the gauge port is sealed; this is the normal operating position." },
  { id:"epa608_274", categoria:"EPA608_TIPO2", pregunta:"¿Qué es la 'posición media' (mid-seated/cracked) de una válvula de servicio de vástago?", opciones:["Es la posición donde el flujo está completamente bloqueado para aislar el compresor del sistema","Es la posición donde tanto el sistema como el puerto de manómetro están abiertos simultáneamente","Es la posición donde solo el puerto del manómetro está abierto y el sistema está completamente cerrado","Es la posición de emergencia que abre la válvula de alivio para descargar presión excesiva"], respuesta_correcta:1, explicacion:"En posición media (cracked), el refrigerante fluye al sistema Y al puerto del manómetro, permitiendo leer presiones durante la operación." , question: "What is the 'mid-seated' (cracked) position of a stem-type service valve?", options: ["It is the position where flow is completely blocked to isolate the compressor from the system", "It is the position where both the system and the gauge port are open simultaneously", "It is the position where only the gauge port is open and the system is completely closed", "It is the emergency position that opens the relief valve to release excessive pressure"], explanation: "In the mid-seated (cracked) position, refrigerant flows to the system AND to the gauge port, allowing pressure readings during operation." },
  { id:"epa608_275", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el rango típico de sobrecalentamiento aceptable en la línea de succión de un sistema con TXV?", opciones:["Entre 1°F y 5°F de sobrecalentamiento para máxima eficiencia del sistema de refrigeración","Entre 8°F y 12°F de sobrecalentamiento para operación segura y eficiente del compresor equipo","Entre 20°F y 30°F de sobrecalentamiento para proteger el compresor contra retorno de líquido","Entre 35°F y 50°F de sobrecalentamiento para garantizar que no llegue líquido al compresor"], respuesta_correcta:1, explicacion:"El sobrecalentamiento típico con TXV es 8-12°F; muy bajo arriesga retorno de líquido, muy alto indica alimentación insuficiente al evaporador." , question: "What is the typical acceptable superheat range on the suction line of a system with a TXV?", options: ["Between 1 deg F and 5 deg F of superheat for maximum refrigeration system efficiency", "Between 8 deg F and 12 deg F of superheat for safe and efficient compressor operation", "Between 20 deg F and 30 deg F of superheat to protect the compressor against liquid return", "Between 35 deg F and 50 deg F of superheat to guarantee no liquid reaches the compressor"], explanation: "Typical superheat with a TXV is 8-12 deg F; too low risks liquid return, too high indicates insufficient evaporator feeding." },
  { id:"epa608_276", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el rango típico de subenfriamiento aceptable a la salida del condensador en un sistema Tipo II?", opciones:["Entre 1°F y 5°F de subenfriamiento para mantener presiones de operación estables y correctas","Entre 10°F y 18°F de subenfriamiento para asegurar líquido sólido al dispositivo de expansión","Entre 25°F y 35°F de subenfriamiento indicando que el sistema está funcionando correctamente","Entre 40°F y 50°F de subenfriamiento como valor óptimo de diseño en la mayoría de los equipos"], respuesta_correcta:1, explicacion:"El subenfriamiento típico es 10-18°F; asegura que llegue líquido sólido (sin flash gas) al dispositivo de expansión para máxima eficiencia." , question: "What is the typical acceptable subcooling range at the condenser outlet in a Type II system?", options: ["Between 1 deg F and 5 deg F of subcooling to maintain stable and correct operating pressures", "Between 10 deg F and 18 deg F of subcooling to ensure solid liquid to the expansion device", "Between 25 deg F and 35 deg F of subcooling indicating the system is operating correctly", "Between 40 deg F and 50 deg F of subcooling as the optimal design value in most equipment"], explanation: "Typical subcooling is 10-18 deg F; this ensures solid liquid (no flash gas) reaches the expansion device for maximum efficiency." },
  { id:"epa608_277", categoria:"EPA608_TIPO2", pregunta:"¿Qué es el 'flash gas' y dónde ocurre típicamente en un sistema de refrigeración Tipo II?", opciones:["Es el gas que se forma en el compresor cuando la relación de compresión es excesivamente alta","Es la evaporación parcial del refrigerante líquido en la línea de líquido antes de llegar a la TXV","Es el vapor que se acumula en la parte superior del receptor de líquido durante operación normal","Es el gas caliente que se inyecta al evaporador para iniciar el ciclo de descongelamiento rápido"], respuesta_correcta:1, explicacion:"El flash gas ocurre cuando el refrigerante líquido pierde presión o gana calor en la línea de líquido, evaporándose parcialmente antes de la TXV, reduciendo capacidad." , question: "What is 'flash gas' and where does it typically occur in a Type II refrigeration system?", options: ["It is the gas that forms in the compressor when the compression ratio is excessively high", "It is the partial evaporation of liquid refrigerant in the liquid line before it reaches the TXV", "It is the vapor that accumulates at the top of the liquid receiver during normal operation", "It is the hot gas injected into the evaporator to initiate the rapid defrost cycle"], explanation: "Flash gas occurs when liquid refrigerant loses pressure or gains heat in the liquid line, partially evaporating before the TXV and reducing capacity." },
  { id:"epa608_278", categoria:"EPA608_TIPO2", pregunta:"¿Qué componente se utiliza para asegurar que solo líquido llegue al dispositivo de expansión en sistemas grandes?", opciones:["Un acumulador de succión instalado antes del compresor para separar líquido del vapor entrante","Un receptor de líquido instalado después del condensador para almacenar refrigerante líquido extra","Un intercambiador de calor de succión-líquido para subenfriamiento adicional de la línea líquida","Un separador de aceite instalado en la línea de descarga para recuperar aceite del refrigerante"], respuesta_correcta:1, explicacion:"El receptor de líquido almacena refrigerante líquido y asegura un suministro constante de líquido sólido al dispositivo de expansión." , question: "What component is used to ensure only liquid reaches the expansion device in large systems?", options: ["A suction accumulator installed before the compressor to separate liquid from incoming vapor", "A liquid receiver installed after the condenser to store extra liquid refrigerant", "A suction-to-liquid heat exchanger for additional subcooling of the liquid line", "An oil separator installed on the discharge line to recover oil from the refrigerant"], explanation: "The liquid receiver stores liquid refrigerant and ensures a constant supply of solid liquid to the expansion device." },
  { id:"epa608_279", categoria:"EPA608_TIPO2", pregunta:"¿Qué debe hacerse si un sistema de refrigeración grande necesita ser abierto para reparación?", opciones:["Se puede abrir directamente si la presión interna está por debajo de 5 psig de presión positiva","Se debe recuperar el refrigerante a los niveles requeridos por la EPA antes de abrir el sistema","Se puede ventilar una pequeña cantidad de refrigerante para reducir la presión a nivel seguro","Se debe agregar nitrógeno antes de abrir para mantener presión positiva y evitar entrada de aire"], respuesta_correcta:1, explicacion:"Antes de abrir cualquier sistema, se debe recuperar el refrigerante a los niveles de vacío requeridos por la EPA; ventear está prohibido." , question: "What must be done if a large refrigeration system needs to be opened for repair?", options: ["It can be opened directly if the internal pressure is below 5 psig positive pressure", "The refrigerant must be recovered to the EPA-required levels before opening the system", "A small amount of refrigerant may be vented to reduce the pressure to a safe level", "Nitrogen should be added before opening to maintain positive pressure and prevent air entry"], explanation: "Before opening any system, the refrigerant must be recovered to the vacuum levels required by the EPA; venting is prohibited." },
  { id:"epa608_280", categoria:"EPA608_TIPO2", pregunta:"¿En qué situaciones es legal ventear una cantidad mínima de refrigerante a la atmósfera?", opciones:["Cuando se purga una manguera corta de manómetro que contiene una cantidad de minimis de refrigerante","Cuando se necesita reducir rápidamente la presión del sistema para una reparación de emergencia","Cuando el refrigerante está contaminado y no es económicamente viable recuperarlo correctamente","Cuando se trabaja en un sistema con menos de 5 libras de carga total de refrigerante instalado"], respuesta_correcta:0, explicacion:"Solo se permite ventear cantidades de minimis, como lo contenido en mangueras de manómetros; cualquier otra liberación intencional es ilegal." , question: "In what situations is it legal to vent a minimal amount of refrigerant to the atmosphere?", options: ["When purging a short gauge hose that contains a de minimis amount of refrigerant", "When a rapid pressure reduction is needed for an emergency repair on the system", "When the refrigerant is contaminated and it is not economically viable to recover it properly", "When working on a system with less than 5 pounds of total installed refrigerant charge"], explanation: "Only de minimis amounts are allowed to be vented, such as the refrigerant contained in gauge hoses; any other intentional release is illegal." },
  { id:"epa608_281", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la multa máxima por día que la EPA puede imponer por liberar refrigerante intencionalmente?", opciones:["Hasta $10,000 por día por cada violación de las regulaciones sobre manejo de refrigerantes","Hasta $27,500 por día por cada violación de las regulaciones sobre manejo de refrigerantes","Hasta $44,539 por día por cada violación de las regulaciones de la Sección 608 del Clean Air Act","Hasta $75,000 por día por cada violación de las regulaciones sobre manejo de refrigerantes"], respuesta_correcta:2, explicacion:"La EPA puede imponer multas de hasta $44,539 por día por violación de la Sección 608, incluyendo la liberación intencional de refrigerante." , question: "What is the maximum daily fine the EPA can impose for intentionally releasing refrigerant?", options: ["Up to $10,000 per day per violation of the refrigerant handling regulations", "Up to $27,500 per day per violation of the refrigerant handling regulations", "Up to $44,539 per day per violation of the Clean Air Act Section 608 regulations", "Up to $75,000 per day per violation of the refrigerant handling regulations"], explanation: "The EPA can impose fines of up to $44,539 per day per violation of Section 608, including the intentional release of refrigerant." },
  { id:"epa608_282", categoria:"EPA608_TIPO2", pregunta:"¿Qué debe hacer un técnico si sospecha que otro técnico está venteando refrigerante ilegalmente?", opciones:["Debe confrontar directamente al técnico y detener la actividad ilegal de forma inmediata","Debe reportar la violación a la línea de denuncias de la EPA para investigación formal","Debe documentar la actividad pero no está obligado a reportarla a ninguna autoridad competente","Debe informar al propietario del equipo y dejar que él decida si reporta o no la violación"], respuesta_correcta:1, explicacion:"Los técnicos deben reportar violaciones a la EPA; existe una línea de denuncias y las denuncias pueden ser anónimas con posibles recompensas." , question: "What should a technician do if they suspect another technician is illegally venting refrigerant?", options: ["Directly confront the technician and immediately stop the illegal activity", "Report the violation to the EPA tip line for formal investigation", "Document the activity but is not required to report it to any authority", "Inform the equipment owner and let them decide whether to report the violation or not"], explanation: "Technicians must report violations to the EPA; there is a tip line available and reports can be anonymous with possible rewards." },
  { id:"epa608_283", categoria:"EPA608_TIPO2", pregunta:"¿Qué información debe incluirse en los registros de servicio de un sistema con más de 50 libras de refrigerante?", opciones:["Solo la fecha del servicio y el nombre del técnico que realizó el trabajo de mantenimiento","Fecha, tipo y cantidad de refrigerante agregado/removido, y resultado de prueba de verificación","Solo la cantidad de refrigerante agregado y el costo total del servicio realizado al equipo","Fecha del servicio y firma del propietario confirmando que autoriza el trabajo a realizar"], respuesta_correcta:1, explicacion:"Los registros deben incluir fecha, tipo de refrigerante, cantidad agregada o removida, resultados de pruebas de fugas, y acciones correctivas." , question: "What information must be included in the service records for a system with more than 50 pounds of refrigerant?", options: ["Only the service date and the name of the technician who performed the maintenance work", "Date, type and amount of refrigerant added/removed, and the result of the verification test", "Only the amount of refrigerant added and the total cost of the service performed on the equipment", "Service date and owner signature confirming authorization for the work to be performed"], explanation: "Records must include the date, refrigerant type, quantity added or removed, leak test results, and corrective actions taken." },
  { id:"epa608_284", categoria:"EPA608_TIPO2", pregunta:"¿Qué es un 'compresor scroll' y cuál es su ventaja principal en sistemas de aire acondicionado?", opciones:["Es un compresor con pistones que se mueven en espiral ofreciendo mayor capacidad de desplazamiento","Es un compresor con dos espirales que comprimen gas suavemente con menos piezas móviles y vibración","Es un compresor con paletas deslizantes que ajustan automáticamente la capacidad según demanda","Es un compresor centrífugo miniaturizado diseñado para aplicaciones residenciales de alta eficiencia"], respuesta_correcta:1, explicacion:"El compresor scroll usa dos espirales (fija y orbital) para comprimir gas de forma continua y suave, con menos vibración, ruido y partes móviles." , question: "What is a 'scroll compressor' and what is its main advantage in air conditioning systems?", options: ["It is a compressor with pistons that move in a spiral, offering greater displacement capacity", "It is a compressor with two scrolls that compresses gas smoothly with fewer moving parts and vibration", "It is a compressor with sliding vanes that automatically adjusts capacity according to demand", "It is a miniaturized centrifugal compressor designed for high-efficiency residential applications"], explanation: "A scroll compressor uses two scrolls (fixed and orbiting) to compress gas continuously and smoothly, with less vibration, noise, and fewer moving parts." },
  { id:"epa608_285", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la función de una válvula de reversión (4-way valve) en una bomba de calor?", opciones:["Proteger el compresor contra sobrepresión invirtiendo el flujo cuando la presión es excesiva","Invertir la dirección del flujo de refrigerante para cambiar entre modo enfriamiento y calefacción","Regular el flujo de refrigerante entre el evaporador interior y el evaporador exterior del sistema","Desviar gas caliente al evaporador exterior para iniciar el ciclo de descongelamiento del serpentín"], respuesta_correcta:1, explicacion:"La válvula de 4 vías invierte el flujo de refrigerante, intercambiando las funciones del serpentín interior y exterior entre modo frío y calor." , question: "What is the function of a reversing valve (4-way valve) in a heat pump?", options: ["To protect the compressor against overpressure by reversing the flow when pressure is excessive", "To reverse the direction of refrigerant flow to switch between cooling and heating modes", "To regulate refrigerant flow between the indoor and outdoor evaporators of the system", "To divert hot gas to the outdoor evaporator to initiate the coil defrost cycle"], explanation: "The 4-way valve reverses the refrigerant flow, switching the functions of the indoor and outdoor coils between cooling and heating modes." },
  { id:"epa608_286", categoria:"EPA608_TIPO2", pregunta:"¿Cuándo se activa el ciclo de descongelamiento en una bomba de calor operando en modo calefacción?", opciones:["Se activa cuando la temperatura exterior baja de 32°F independientemente del estado del serpentín","Se activa cuando se detecta acumulación de escarcha en el serpentín exterior que reduce su eficiencia","Se activa cada 30 minutos de operación continua como medida preventiva programada de fábrica","Se activa cuando la presión de descarga excede los límites máximos seguros de operación del sistema"], respuesta_correcta:1, explicacion:"El descongelamiento se activa cuando sensores detectan acumulación de escarcha (por diferencial de presión o temperatura/tiempo) en el serpentín exterior." , question: "When does the defrost cycle activate in a heat pump operating in heating mode?", options: ["It activates when the outdoor temperature drops below 32 deg F regardless of the coil condition", "It activates when frost accumulation is detected on the outdoor coil that reduces its efficiency", "It activates every 30 minutes of continuous operation as a factory-programmed preventive measure", "It activates when the discharge pressure exceeds the maximum safe operating limits of the system"], explanation: "Defrost activates when sensors detect frost accumulation (via pressure differential or temperature/time) on the outdoor coil." },
  { id:"epa608_287", categoria:"EPA608_TIPO2", pregunta:"¿Qué clasificación de seguridad ASHRAE tiene el refrigerante R-32?", opciones:["Clasificación A1 indicando baja toxicidad y nula inflamabilidad en condiciones normales de uso","Clasificación A2L indicando baja toxicidad y ligera inflamabilidad con baja velocidad de llama","Clasificación B1 indicando mayor toxicidad y nula inflamabilidad en condiciones normales de uso","Clasificación A3 indicando baja toxicidad pero alta inflamabilidad requiriendo precauciones extremas"], respuesta_correcta:1, explicacion:"El R-32 tiene clasificación A2L (baja toxicidad, ligeramente inflamable); se usa cada vez más como componente principal o único en sistemas nuevos." , question: "What ASHRAE safety classification does refrigerant R-32 have?", options: ["Classification A1 indicating low toxicity and no flammability under normal conditions of use", "Classification A2L indicating low toxicity and mild flammability with low flame speed", "Classification B1 indicating higher toxicity and no flammability under normal conditions of use", "Classification A3 indicating low toxicity but high flammability requiring extreme precautions"], explanation: "R-32 has an A2L classification (low toxicity, mildly flammable); it is increasingly used as a primary or sole component in new systems." },
  { id:"epa608_288", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el GWP del R-32 comparado con el R-410A?", opciones:["R-32 tiene un GWP de 675, aproximadamente un tercio del GWP del R-410A que es de 2088","R-32 tiene un GWP de 1430, aproximadamente dos tercios del GWP del R-410A que es de 2088","R-32 tiene un GWP de 150, aproximadamente una catorceava parte del GWP del R-410A actual","R-32 tiene un GWP de 1000, aproximadamente la mitad del GWP del R-410A que es de 2088"], respuesta_correcta:0, explicacion:"El R-32 tiene un GWP de 675, aproximadamente un tercio del R-410A (GWP=2088), ofreciendo mejor rendimiento ambiental con buena eficiencia." , question: "What is the GWP of R-32 compared to R-410A?", options: ["R-32 has a GWP of 675, approximately one-third of R-410A's GWP of 2,088", "R-32 has a GWP of 1,430, approximately two-thirds of R-410A's GWP of 2,088", "R-32 has a GWP of 150, approximately one-fourteenth of R-410A's current GWP", "R-32 has a GWP of 1,000, approximately half of R-410A's GWP of 2,088"], explanation: "R-32 has a GWP of 675, approximately one-third of R-410A (GWP of 2,088), offering better environmental performance with good efficiency." },
  { id:"epa608_289", categoria:"EPA608_TIPO2", pregunta:"¿Qué precaución adicional se requiere al trabajar con refrigerantes clasificados como A2L?", opciones:["No se requieren precauciones adicionales ya que A2L indica muy baja inflamabilidad en la práctica","Se deben usar detectores de fugas certificados para refrigerantes inflamables y evitar llamas abiertas","Se debe usar equipo de respiración autónomo obligatoriamente durante todo el proceso de servicio","Se debe trabajar exclusivamente en exteriores ya que el gas es más pesado que el aire y se acumula"], respuesta_correcta:1, explicacion:"Los refrigerantes A2L son ligeramente inflamables; se requieren detectores apropiados, ventilación adecuada y evitar fuentes de ignición cercanas." , question: "What additional precaution is required when working with A2L-classified refrigerants?", options: ["No additional precautions are required since A2L indicates very low flammability in practice", "Leak detectors certified for flammable refrigerants must be used and open flames must be avoided", "Self-contained breathing apparatus must be worn throughout the entire service process", "Work must be performed exclusively outdoors since the gas is heavier than air and can accumulate"], explanation: "A2L refrigerants are mildly flammable; appropriate leak detectors, adequate ventilation, and avoidance of ignition sources are required." },
  { id:"epa608_290", categoria:"EPA608_TIPO2", pregunta:"¿Qué es la 'relación de compresión' y cómo afecta al rendimiento del compresor del sistema?", opciones:["Es la relación entre la presión de descarga y la presión de succión del compresor en operación","Es la relación entre el volumen del cilindro y el volumen de gas comprimido en cada ciclo","Es la relación entre la corriente de arranque y la corriente de operación del motor eléctrico","Es la relación entre la capacidad nominal y la capacidad real del compresor a plena carga"], respuesta_correcta:0, explicacion:"La relación de compresión es presión de descarga absoluta dividida entre presión de succión absoluta; ratios altos reducen eficiencia y aumentan temperatura de descarga." , question: "What is the 'compression ratio' and how does it affect compressor performance?", options: ["It is the ratio between the discharge pressure and the suction pressure of the compressor during operation", "It is the ratio between the cylinder volume and the volume of compressed gas in each cycle", "It is the ratio between the starting current and the operating current of the electric motor", "It is the ratio between the rated capacity and the actual capacity of the compressor at full load"], explanation: "The compression ratio is the absolute discharge pressure divided by the absolute suction pressure; high ratios reduce efficiency and increase discharge temperature." },
  { id:"epa608_291", categoria:"EPA608_TIPO2", pregunta:"¿Qué ocurre cuando la relación de compresión de un compresor es excesivamente alta?", opciones:["El compresor opera más eficientemente porque mueve más refrigerante por ciclo de compresión","La temperatura de descarga baja porque el gas se comprime más rápidamente y pierde calor","La eficiencia volumétrica disminuye y la temperatura de descarga aumenta peligrosamente alta","La presión de succión aumenta compensando automáticamente la relación de compresión excesiva"], respuesta_correcta:2, explicacion:"Una relación de compresión alta reduce la eficiencia volumétrica y eleva la temperatura de descarga, lo que puede dañar válvulas y aceite." , question: "What happens when a compressor's compression ratio is excessively high?", options: ["The compressor operates more efficiently because it moves more refrigerant per compression cycle", "The discharge temperature drops because the gas is compressed more quickly and loses heat", "The volumetric efficiency decreases and the discharge temperature increases dangerously", "The suction pressure increases, automatically compensating for the excessive compression ratio"], explanation: "A high compression ratio reduces volumetric efficiency and raises discharge temperature, which can damage valves and oil." },
  { id:"epa608_292", categoria:"EPA608_TIPO2", pregunta:"¿Qué componente se utiliza para separar el aceite del refrigerante en la descarga de sistemas grandes?", opciones:["Un filtro secador de línea de succión instalado antes de la entrada del compresor del sistema","Un separador de aceite instalado en la línea de descarga que retorna el aceite al cárter","Un receptor de líquido que permite que el aceite se sedimente en el fondo por gravedad natural","Un acumulador de succión que separa el aceite del gas de retorno antes de entrar al compresor"], respuesta_correcta:1, explicacion:"El separador de aceite en la línea de descarga captura aceite arrastrado por el gas caliente y lo retorna al cárter del compresor." , question: "What component is used to separate oil from the refrigerant at the discharge of large systems?", options: ["A suction-line filter drier installed before the system compressor inlet", "An oil separator installed on the discharge line that returns oil to the crankcase", "A liquid receiver that allows oil to settle at the bottom by natural gravity", "A suction accumulator that separates oil from the return gas before entering the compressor"], explanation: "The oil separator on the discharge line captures oil carried by the hot gas and returns it to the compressor crankcase." },
  { id:"epa608_293", categoria:"EPA608_TIPO2", pregunta:"¿Por qué es importante que la línea de succión esté correctamente aislada térmicamente?", opciones:["Para prevenir la condensación exterior que puede causar daños por agua y problemas de corrosión","Para evitar que la línea gane calor del ambiente reduciendo el sobrecalentamiento y la eficiencia","Para proteger a los técnicos de quemaduras por frío al tocar la línea de succión durante servicio","Para reducir el nivel de ruido que genera el flujo de refrigerante gaseoso dentro de la tubería"], respuesta_correcta:1, explicacion:"Aislar la línea de succión previene ganancia de calor del ambiente, mantiene el sobrecalentamiento bajo control y previene condensación exterior." , question: "Why is it important for the suction line to be properly insulated?", options: ["To prevent exterior condensation that can cause water damage and corrosion problems", "To prevent the line from gaining heat from the ambient, reducing superheat and efficiency", "To protect technicians from cold burns when touching the suction line during service", "To reduce the noise level generated by gaseous refrigerant flow inside the tubing"], explanation: "Insulating the suction line prevents heat gain from the ambient, keeps superheat under control, and prevents exterior condensation." },
  { id:"epa608_294", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la consecuencia de una restricción parcial en el filtro secador de la línea de líquido?", opciones:["La presión de descarga aumenta significativamente causando sobrecalentamiento del compresor","Se produce una caída de temperatura notable al tocar el filtro antes y después de la restricción","El sobrecalentamiento en la succión disminuye indicando exceso de refrigerante en el evaporador","La presión de succión aumenta causando que el compresor opere con alta corriente de amperaje"], respuesta_correcta:1, explicacion:"Una restricción en el filtro secador causa caída de presión y temperatura notables; al tocarlo se siente más frío después de la restricción que antes." , question: "What is the consequence of a partial restriction in the liquid line filter drier?", options: ["The discharge pressure increases significantly, causing compressor overheating", "A noticeable temperature drop is felt when touching the filter before and after the restriction", "The suction superheat decreases, indicating excess refrigerant in the evaporator", "The suction pressure increases, causing the compressor to operate with high amperage draw"], explanation: "A restriction in the filter drier causes a noticeable pressure and temperature drop; it feels colder after the restriction than before it when touched." },
  { id:"epa608_295", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es la función del bulbo sensor de una válvula TXV y dónde debe instalarse correctamente?", opciones:["Debe instalarse en la línea de líquido antes de la válvula para medir la temperatura del líquido","Debe instalarse en la línea de succión después del evaporador para medir el sobrecalentamiento","Debe instalarse en la línea de descarga para medir la temperatura del gas caliente comprimido","Debe instalarse en el evaporador directamente para medir la temperatura del aire de retorno"], respuesta_correcta:1, explicacion:"El bulbo sensor se instala en la línea de succión a la salida del evaporador, midiendo la temperatura del gas para controlar el sobrecalentamiento." , question: "What is the function of the sensing bulb on a TXV and where should it be installed correctly?", options: ["It should be installed on the liquid line before the valve to measure liquid temperature", "It should be installed on the suction line after the evaporator to measure superheat", "It should be installed on the discharge line to measure the compressed hot gas temperature", "It should be installed directly on the evaporator to measure the return air temperature"], explanation: "The sensing bulb is installed on the suction line at the evaporator outlet, measuring gas temperature to control superheat." },
  { id:"epa608_296", categoria:"EPA608_TIPO2", pregunta:"¿Qué ocurre si el bulbo sensor de la TXV pierde su carga (pierde el fluido interno)?", opciones:["La TXV se abre completamente permitiendo exceso de refrigerante líquido al evaporador siempre","La TXV se cierra completamente cortando el flujo de refrigerante al evaporador del sistema","La TXV se mantiene en posición media proporcionando flujo parcial constante al evaporador","La TXV oscila entre abierta y cerrada causando fluctuaciones de presión en todo el sistema"], respuesta_correcta:1, explicacion:"Si el bulbo pierde su carga, la presión del resorte cierra la válvula completamente, cortando el flujo de refrigerante al evaporador." , question: "What happens if the TXV sensing bulb loses its charge (loses its internal fluid)?", options: ["The TXV opens fully, allowing excess liquid refrigerant to the evaporator at all times", "The TXV closes completely, cutting off refrigerant flow to the system evaporator", "The TXV stays in a mid-position, providing constant partial flow to the evaporator", "The TXV oscillates between open and closed, causing pressure fluctuations throughout the system"], explanation: "If the bulb loses its charge, the spring pressure closes the valve completely, cutting off refrigerant flow to the evaporator." },
  { id:"epa608_297", categoria:"EPA608_TIPO2", pregunta:"¿Cuál es el propósito de un intercambiador de calor succión-líquido en un sistema de refrigeración?", opciones:["Calentar la línea de líquido para prevenir formación de escarcha en la tubería del condensador","Subenfriiar la línea de líquido usando el gas frío de succión mejorando eficiencia y protección","Aumentar la presión de la línea de succión para mejorar la eficiencia volumétrica del compresor","Ecualizar las presiones entre el lado alto y bajo del sistema durante el ciclo de apagado del equipo"], respuesta_correcta:1, explicacion:"El intercambiador succión-líquido subenfría el líquido (previene flash gas) y sobrecalienta el gas de succión (protege el compresor), mejorando eficiencia." , question: "What is the purpose of a suction-to-liquid heat exchanger in a refrigeration system?", options: ["To heat the liquid line to prevent frost formation on the condenser tubing", "To subcool the liquid line using the cold suction gas, improving efficiency and compressor protection", "To increase the suction line pressure to improve the volumetric efficiency of the compressor", "To equalize pressures between the high and low sides of the system during the equipment off cycle"], explanation: "The suction-to-liquid heat exchanger subcools the liquid (prevents flash gas) and superheats the suction gas (protects the compressor), improving efficiency." },
  { id:"epa608_298", categoria:"EPA608_TIPO2", pregunta:"¿En qué posición de las manecillas del reloj se recomienda instalar el bulbo de la TXV en la tubería?", opciones:["En la posición de las 6 en punto (parte inferior) de la tubería de succión horizontal del sistema","En la posición de las 12 en punto (parte superior) de la tubería de succión horizontal del sistema","En la posición de las 10 o las 2 (parte lateral superior) de la tubería de succión horizontal","En cualquier posición ya que la ubicación del bulbo no afecta la lectura de temperatura medida"], respuesta_correcta:2, explicacion:"El bulbo debe instalarse a las 10 o 2 en punto para evitar lecturas falsas por aceite acumulado abajo (6) o vapor caliente arriba (12)." , question: "At what clock position is it recommended to install the TXV sensing bulb on the tubing?", options: ["At the 6 o'clock position (bottom) of the horizontal suction tubing", "At the 12 o'clock position (top) of the horizontal suction tubing", "At the 10 o'clock or 2 o'clock position (upper side) of the horizontal suction tubing", "At any position since the bulb location does not affect the temperature reading"], explanation: "The bulb should be installed at the 10 or 2 o'clock position to avoid false readings from oil pooled at the bottom (6) or hot vapor at the top (12)." },
  { id:"epa608_299", categoria:"EPA608_TIPO2", pregunta:"¿Qué indica una lectura de 0°F de sobrecalentamiento en la línea de succión durante operación?", opciones:["Indica que el sistema está operando con máxima eficiencia y el evaporador está perfectamente cargado","Indica que hay refrigerante líquido llegando al compresor lo cual puede causar daño por golpe hidráulico","Indica que la carga de refrigerante es ligeramente baja y necesita ser complementada con más gas","Indica que la temperatura ambiente es demasiado baja para que el sistema opere de forma eficiente"], respuesta_correcta:1, explicacion:"Un sobrecalentamiento de 0°F significa que el refrigerante no se ha evaporado completamente, y líquido puede llegar al compresor causando daño severo." , question: "What does a 0 deg F superheat reading on the suction line during operation indicate?", options: ["The system is operating at maximum efficiency and the evaporator is perfectly charged", "Liquid refrigerant is reaching the compressor, which can cause liquid slugging damage", "The refrigerant charge is slightly low and needs to be topped off with more refrigerant", "The ambient temperature is too low for the system to operate efficiently"], explanation: "A superheat of 0 deg F means the refrigerant has not fully evaporated, and liquid can reach the compressor causing severe damage." },
  { id:"epa608_300", categoria:"EPA608_TIPO2", pregunta:"¿Cuánto tiempo se debe mantener el vacío en 'standing vacuum test' para verificar la integridad del sistema?", opciones:["Un mínimo de 5 minutos verificando que el vacuómetro no muestre aumento de presión significativo","Un mínimo de 15 minutos verificando que el vacuómetro no muestre aumento de presión del sistema","Un mínimo de 30 minutos verificando que el vacuómetro se mantenga estable sin aumento de presión","Un mínimo de 60 minutos verificando que el vacuómetro permanezca estable sin cambios de presión"], respuesta_correcta:2, explicacion:"El standing vacuum test requiere mantener el vacío por mínimo 30 minutos; si la presión sube, indica fuga o humedad residual en el sistema." , question: "How long should the vacuum be held during a standing vacuum test to verify system integrity?", options: ["A minimum of 5 minutes, verifying the vacuum gauge shows no significant pressure rise", "A minimum of 15 minutes, verifying the vacuum gauge shows no system pressure rise", "A minimum of 30 minutes, verifying the vacuum gauge remains stable with no pressure rise", "A minimum of 60 minutes, verifying the vacuum gauge remains stable with no changes in pressure"], explanation: "A standing vacuum test requires holding the vacuum for a minimum of 30 minutes; if pressure rises, it indicates a leak or residual moisture in the system." },

  // ── TIPO III (301-400) ──────────────────────────────────────────
  { id:"epa608_301", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la característica principal que define a un sistema de baja presión (Tipo III) según la EPA 608?", opciones:["Opera con refrigerantes cuyo punto de ebullición es superior a 10°C a presión atmosférica","Opera con refrigerantes cuyo punto de ebullición es inferior a 10°C a presión atmosférica","Opera con refrigerantes cuyo punto de ebullición es superior a 10°C a presión de vacío","Opera con refrigerantes cuyo punto de ebullición es inferior a 10°C a presión de vacío"], respuesta_correcta:0, explicacion:"Los sistemas Tipo III usan refrigerantes con punto de ebullición superior a 10°C a presión atmosférica, lo que significa que operan por debajo de la presión atmosférica (en vacío)." , question: "What is the main characteristic that defines a low-pressure (Type III) system according to EPA 608?", options: ["It operates with refrigerants whose boiling point is above 50 deg F (10 deg C) at atmospheric pressure", "It operates with refrigerants whose boiling point is below 50 deg F (10 deg C) at atmospheric pressure", "It operates with refrigerants whose boiling point is above 50 deg F (10 deg C) at vacuum pressure", "It operates with refrigerants whose boiling point is below 50 deg F (10 deg C) at vacuum pressure"], explanation: "Type III systems use refrigerants with a boiling point above 50 deg F (10 deg C) at atmospheric pressure, meaning they operate below atmospheric pressure (under vacuum)." },
  { id:"epa608_302", categoria:"EPA608_TIPO3", pregunta:"¿Qué sucede cuando un sistema de baja presión tiene una fuga en el lado de baja?", opciones:["El refrigerante se escapa rápidamente hacia la atmósfera exterior","El aire atmosférico entra al sistema a través de la fuga","El aceite lubricante sale expulsado por la diferencia de presión","El agua del condensador se infiltra al circuito de refrigerante"], respuesta_correcta:1, explicacion:"Como los sistemas de baja presión operan en vacío (por debajo de la presión atmosférica), si hay una fuga el aire ENTRA al sistema en lugar de que el refrigerante salga." , question: "What happens when a low-pressure system has a leak on the low side?", options: ["The refrigerant escapes rapidly to the outside atmosphere", "Atmospheric air enters the system through the leak", "The lubricating oil is expelled by the pressure differential", "The condenser water infiltrates the refrigerant circuit"], explanation: "Since low-pressure systems operate under vacuum (below atmospheric pressure), if there is a leak, air ENTERS the system rather than refrigerant escaping." },
  { id:"epa608_303", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el refrigerante CFC que fue históricamente el más utilizado en chillers centrífugos de baja presión?", opciones:["R-22 con potencial de agotamiento de ozono moderado","R-11 con potencial de agotamiento de ozono de 1.0","R-134a con potencial de agotamiento de ozono nulo","R-410A con potencial de agotamiento de ozono nulo"], respuesta_correcta:1, explicacion:"El R-11 es un CFC con ODP de 1.0, fue el refrigerante estándar en chillers centrífugos de baja presión antes de su eliminación por el Protocolo de Montreal." , question: "Which CFC refrigerant was historically the most widely used in low-pressure centrifugal chillers?", options: ["R-22 with moderate ozone depletion potential", "R-11 with an ozone depletion potential of 1.0", "R-134a with zero ozone depletion potential", "R-410A with zero ozone depletion potential"], explanation: "R-11 is a CFC with an ODP of 1.0 and was the standard refrigerant in low-pressure centrifugal chillers before its phase-out under the Montreal Protocol." },
  { id:"epa608_304", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el punto de ebullición del R-11 a presión atmosférica?", opciones:["40.6°F (4.8°C) lo que lo hace gas a temperatura ambiente","74.9°F (23.8°C) lo que lo hace líquido a temperatura ambiente","120.3°F (49.1°C) lo que requiere presión para evaporarse","212.0°F (100°C) similar al punto de ebullición del agua pura"], respuesta_correcta:1, explicacion:"El R-11 tiene un punto de ebullición de 74.9°F (23.8°C), lo que significa que es líquido a temperatura ambiente normal y opera en vacío cuando se usa como refrigerante." , question: "What is the boiling point of R-11 at atmospheric pressure?", options: ["40.6 deg F (4.8 deg C), making it a gas at room temperature", "74.9 deg F (23.8 deg C), making it a liquid at room temperature", "120.3 deg F (49.1 deg C), requiring pressure to evaporate", "212.0 deg F (100 deg C), similar to the boiling point of pure water"], explanation: "R-11 has a boiling point of 74.9 deg F (23.8 deg C), meaning it is a liquid at normal room temperature and operates under vacuum when used as a refrigerant." },
  { id:"epa608_305", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el punto de ebullición del R-123 a presión atmosférica?", opciones:["74.9°F (23.8°C) idéntico al del refrigerante R-11 original","82.2°F (27.9°C) ligeramente superior al del R-11 que reemplaza","55.3°F (12.9°C) significativamente inferior al del R-11","99.5°F (37.5°C) cercano a la temperatura corporal del humano"], respuesta_correcta:1, explicacion:"El R-123 tiene un punto de ebullición de 82.2°F (27.9°C), ligeramente más alto que el R-11 (74.9°F). Ambos son líquidos a temperatura ambiente." , question: "What is the boiling point of R-123 at atmospheric pressure?", options: ["74.9 deg F (23.8 deg C), identical to the original R-11 refrigerant", "82.2 deg F (27.9 deg C), slightly higher than the R-11 it replaces", "55.3 deg F (12.9 deg C), significantly lower than R-11", "99.5 deg F (37.5 deg C), close to human body temperature"], explanation: "R-123 has a boiling point of 82.2 deg F (27.9 deg C), slightly higher than R-11 (74.9 deg F). Both are liquids at room temperature." },
  { id:"epa608_306", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de refrigerante es el R-123 y a cuál reemplaza en sistemas de baja presión?", opciones:["Es un HFC que reemplaza al R-22 en sistemas de media presión comerciales","Es un HCFC que reemplaza al R-11 en chillers centrífugos de baja presión","Es un HFO que reemplaza al R-134a en sistemas de alta presión vehiculares","Es un CFC que reemplaza al R-113 en sistemas de limpieza industrial"], respuesta_correcta:1, explicacion:"El R-123 es un HCFC (hidroclorofluorocarbono) desarrollado como reemplazo directo del R-11 CFC en chillers centrífugos de baja presión." , question: "What type of refrigerant is R-123 and which refrigerant does it replace in low-pressure systems?", options: ["It is an HFC that replaces R-22 in medium-pressure commercial systems", "It is an HCFC that replaces R-11 in low-pressure centrifugal chillers", "It is an HFO that replaces R-134a in high-pressure automotive systems", "It is a CFC that replaces R-113 in industrial cleaning systems"], explanation: "R-123 is an HCFC (hydrochlorofluorocarbon) developed as a direct replacement for the CFC R-11 in low-pressure centrifugal chillers." },
  { id:"epa608_307", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la clasificación de seguridad del R-123 según ASHRAE?", opciones:["A1 — baja toxicidad y no inflamable, el más seguro disponible","A2L — baja toxicidad pero ligeramente inflamable en concentraciones altas","B1 — mayor toxicidad pero no inflamable, requiere monitores de ambiente","B2 — mayor toxicidad y ligeramente inflamable, requiere ventilación forzada"], respuesta_correcta:2, explicacion:"El R-123 tiene clasificación B1: mayor toxicidad (B) pero no inflamable (1). Por su toxicidad requiere monitores de ambiente en la sala de máquinas." , question: "What is the ASHRAE safety classification of R-123?", options: ["A1 -- low toxicity and non-flammable, the safest available", "A2L -- low toxicity but mildly flammable at high concentrations", "B1 -- higher toxicity but non-flammable, requires room air monitors", "B2 -- higher toxicity and mildly flammable, requires forced ventilation"], explanation: "R-123 has a B1 classification: higher toxicity (B) but non-flammable (1). Due to its toxicity, it requires room air monitors in the machinery room." },
  { id:"epa608_308", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de equipo se encuentra comúnmente en las aplicaciones de sistemas Tipo III?", opciones:["Unidades de ventana residenciales de 1 a 3 toneladas de capacidad","Sistemas mini split inverter de alta eficiencia para oficinas","Chillers centrífugos de 100 a más de 2,000 toneladas de capacidad","Unidades empacadas rooftop de 5 a 25 toneladas para comercios"], respuesta_correcta:2, explicacion:"Los sistemas Tipo III (baja presión) se utilizan principalmente en chillers centrífugos grandes, con capacidades de 100 a más de 2,000 toneladas, para edificios comerciales, hospitales y campus." , question: "What type of equipment is commonly found in Type III system applications?", options: ["Residential window units of 1 to 3 tons of capacity", "High-efficiency inverter mini-split systems for offices", "Centrifugal chillers of 100 to more than 2,000 tons of capacity", "Packaged rooftop units of 5 to 25 tons for commercial buildings"], explanation: "Type III (low-pressure) systems are primarily used in large centrifugal chillers with capacities of 100 to more than 2,000 tons, for commercial buildings, hospitals, and campuses." },
  { id:"epa608_309", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la función principal de una unidad de purga en un chiller de baja presión?", opciones:["Filtrar partículas sólidas del refrigerante líquido en el evaporador","Remover continuamente aire y gases no condensables del sistema","Mantener el nivel de aceite lubricante en el compresor centrífugo","Regular la presión del condensador durante cambios de carga térmica"], respuesta_correcta:1, explicacion:"La unidad de purga remueve continuamente aire y otros gases no condensables que entran al sistema a través de fugas, ya que el sistema opera en vacío." , question: "What is the main function of a purge unit on a low-pressure chiller?", options: ["To filter solid particles from the liquid refrigerant in the evaporator", "To continuously remove air and non-condensable gases from the system", "To maintain the lubricating oil level in the centrifugal compressor", "To regulate condenser pressure during thermal load changes"], explanation: "The purge unit continuously removes air and other non-condensable gases that enter the system through leaks, since the system operates under vacuum." },
  { id:"epa608_310", categoria:"EPA608_TIPO3", pregunta:"¿Qué indica una operación frecuente de la unidad de purga en un chiller de baja presión?", opciones:["Que el sistema está funcionando con máxima eficiencia energética posible","Que el sistema probablemente tiene una fuga significativa de aire","Que el refrigerante está siendo recuperado correctamente del sistema","Que las válvulas de servicio están completamente cerradas y selladas"], respuesta_correcta:1, explicacion:"Si la unidad de purga opera con mucha frecuencia, indica que hay una fuga considerable por donde el aire está entrando al sistema de baja presión." , question: "What does frequent operation of the purge unit on a low-pressure chiller indicate?", options: ["The system is operating at maximum possible energy efficiency", "The system likely has a significant air leak", "The refrigerant is being recovered correctly from the system", "The service valves are completely closed and sealed"], explanation: "If the purge unit operates very frequently, it indicates a considerable leak through which air is entering the low-pressure system." },
  { id:"epa608_311", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el requisito de recuperación de refrigerante para equipos de baja presión según la EPA?", opciones:["0 psig de presión manométrica en el lado de baja del sistema","25 pulgadas de Hg de vacío medido desde presión atmosférica","25 mm de Hg absoluto, que es casi un vacío perfecto completo","10 pulgadas de Hg de vacío medido en el lado de alta presión"], respuesta_correcta:2, explicacion:"Para sistemas de baja presión, la EPA requiere recuperar hasta 25 mm Hg absoluto, que es casi un vacío perfecto. Esto hace que la recuperación sea muy lenta." , question: "What is the refrigerant recovery requirement for low-pressure equipment according to the EPA?", options: ["0 psig gauge pressure on the low side of the system", "25 inches of Hg vacuum measured from atmospheric pressure", "25 mm Hg absolute, which is nearly a complete perfect vacuum", "10 inches of Hg vacuum measured on the high-pressure side"], explanation: "For low-pressure systems, the EPA requires recovery down to 25 mm Hg absolute, which is nearly a perfect vacuum. This makes recovery very slow." },
  { id:"epa608_312", categoria:"EPA608_TIPO3", pregunta:"¿Por qué la recuperación de refrigerante en sistemas Tipo III es particularmente lenta?", opciones:["Porque los compresores centrífugos son muy grandes y difíciles de drenar","Porque las presiones de operación son muy bajas, cerca del vacío absoluto","Porque el refrigerante es extremadamente viscoso a baja temperatura","Porque se requiere calentar todo el sistema antes de iniciar el proceso"], respuesta_correcta:1, explicacion:"La recuperación en sistemas de baja presión es muy lenta porque las presiones de operación están cerca del vacío, lo que dificulta mover el refrigerante hacia la máquina de recuperación." , question: "Why is refrigerant recovery in Type III systems particularly slow?", options: ["Because the centrifugal compressors are very large and difficult to drain", "Because the operating pressures are very low, near absolute vacuum", "Because the refrigerant is extremely viscous at low temperatures", "Because the entire system must be heated before starting the process"], explanation: "Recovery in low-pressure systems is very slow because the operating pressures are near vacuum, making it difficult to move the refrigerant toward the recovery machine." },
  { id:"epa608_313", categoria:"EPA608_TIPO3", pregunta:"¿Cuánta pérdida de refrigerante tiene una unidad de purga de alta eficiencia por cada libra de aire purgado?", opciones:["Menos de 5.0 libras de refrigerante por cada libra de aire extraído","Menos de 2.0 libras de refrigerante por cada libra de aire extraído","Menos de 1.0 libras de refrigerante por cada libra de aire extraído","Menos de 0.5 libras de refrigerante por cada libra de aire extraído"], respuesta_correcta:3, explicacion:"Una unidad de purga de alta eficiencia pierde menos de 0.5 libras de refrigerante por cada libra de aire purgado, minimizando las emisiones de refrigerante." , question: "How much refrigerant loss does a high-efficiency purge unit have per pound of air purged?", options: ["Less than 5.0 pounds of refrigerant per pound of air extracted", "Less than 2.0 pounds of refrigerant per pound of air extracted", "Less than 1.0 pound of refrigerant per pound of air extracted", "Less than 0.5 pounds of refrigerant per pound of air extracted"], explanation: "A high-efficiency purge unit loses less than 0.5 pounds of refrigerant per pound of air purged, minimizing refrigerant emissions." },
  { id:"epa608_314", categoria:"EPA608_TIPO3", pregunta:"¿Qué efecto tienen los gases no condensables (como el aire) dentro de un sistema de baja presión?", opciones:["Reducen la presión del condensador y mejoran la eficiencia del ciclo","Aumentan la presión de cabeza y reducen la eficiencia del sistema","Disminuyen la temperatura del evaporador mejorando la capacidad total","Lubrican las partes móviles del compresor centrífugo internamente"], respuesta_correcta:1, explicacion:"Los gases no condensables elevan la presión de cabeza (condensador), reducen la eficiencia y aumentan el consumo de energía del chiller." , question: "What effect do non-condensable gases (such as air) have inside a low-pressure system?", options: ["They reduce condenser pressure and improve the cycle efficiency", "They increase head pressure and reduce system efficiency", "They decrease evaporator temperature, improving total capacity", "They lubricate the internal moving parts of the centrifugal compressor"], explanation: "Non-condensable gases raise head pressure (condenser), reduce efficiency, and increase the chiller's energy consumption." },
  { id:"epa608_315", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de condensador se utiliza comúnmente en chillers centrífugos de baja presión?", opciones:["Condensador enfriado por aire con ventiladores axiales de alta velocidad","Condensador evaporativo con serpentín expuesto a corriente de agua y aire","Condensador enfriado por agua tipo carcasa y tubos (shell and tube)","Condensador de placas soldadas con flujo de agua en contracorriente"], respuesta_correcta:2, explicacion:"Los chillers centrífugos de baja presión utilizan condensadores enfriados por agua tipo carcasa y tubos (shell and tube) debido a su gran capacidad y eficiencia." , question: "What type of condenser is commonly used in low-pressure centrifugal chillers?", options: ["An air-cooled condenser with high-speed axial fans", "An evaporative condenser with a coil exposed to a stream of water and air", "A water-cooled shell-and-tube condenser", "A brazed-plate condenser with counterflow water"], explanation: "Low-pressure centrifugal chillers use water-cooled shell-and-tube condensers due to their large capacity and efficiency." },
  { id:"epa608_316", categoria:"EPA608_TIPO3", pregunta:"¿Qué es una prueba de corrientes de Eddy (eddy current test) en un chiller centrífugo?", opciones:["Una prueba eléctrica del motor del compresor para detectar cortocircuitos","Una prueba de integridad de los tubos del condensador y evaporador","Una prueba de flujo de refrigerante a través de las válvulas de expansión","Una prueba de vibración del rotor del compresor centrífugo a plena carga"], respuesta_correcta:1, explicacion:"La prueba de corrientes de Eddy se usa para verificar la integridad de los tubos en los intercambiadores de calor (condensador/evaporador) tipo carcasa y tubos sin necesidad de desarmarlos." , question: "What is an eddy current test on a centrifugal chiller?", options: ["An electrical test of the compressor motor to detect short circuits", "An integrity test of the condenser and evaporator tubes", "A refrigerant flow test through the expansion valves", "A vibration test of the centrifugal compressor rotor at full load"], explanation: "The eddy current test is used to verify the integrity of the tubes in shell-and-tube heat exchangers (condenser/evaporator) without disassembly." },
  { id:"epa608_317", categoria:"EPA608_TIPO3", pregunta:"¿Qué es una prueba hidrostática de tubos en un chiller de baja presión?", opciones:["Una prueba que mide el flujo de agua a través del evaporador del chiller","Una prueba de presión con agua para verificar la integridad de los tubos","Una prueba que detecta la presencia de humedad dentro del refrigerante","Una prueba que mide la conductividad térmica del agua de condensación"], respuesta_correcta:1, explicacion:"La prueba hidrostática llena los tubos con agua a alta presión para verificar que no tengan fugas ni debilidades estructurales en su pared." , question: "What is a hydrostatic tube test on a low-pressure chiller?", options: ["A test that measures water flow through the chiller evaporator", "A pressure test with water to verify tube integrity", "A test that detects the presence of moisture inside the refrigerant", "A test that measures the thermal conductivity of the condensing water"], explanation: "A hydrostatic test fills the tubes with water at high pressure to verify they have no leaks or structural weaknesses in their walls." },
  { id:"epa608_318", categoria:"EPA608_TIPO3", pregunta:"¿Qué dispositivo de seguridad se encuentra en el condensador o evaporador de un chiller de baja presión?", opciones:["Válvula de alivio de presión con resorte calibrado a 15 psig","Disco de ruptura que se rompe a una presión predeterminada alta","Interruptor de alta presión que detiene el compresor automáticamente","Fusible térmico que se funde a una temperatura excesiva del sistema"], respuesta_correcta:1, explicacion:"Los chillers de baja presión tienen un disco de ruptura en el condensador o evaporador como dispositivo de seguridad que se rompe si la presión interna sube peligrosamente." , question: "What safety device is found on the condenser or evaporator of a low-pressure chiller?", options: ["A spring-loaded pressure relief valve calibrated at 15 psig", "A rupture disc that bursts at a predetermined high pressure", "A high-pressure switch that stops the compressor automatically", "A thermal fuse that melts at excessive system temperature"], explanation: "Low-pressure chillers have a rupture disc on the condenser or evaporator as a safety device that bursts if internal pressure rises dangerously." },
  { id:"epa608_319", categoria:"EPA608_TIPO3", pregunta:"¿Qué método se usa para detectar fugas en un sistema de baja presión que está apagado?", opciones:["Prueba con detector electrónico de fugas mientras el sistema opera","Prueba de presión/vacío estacionaria (standing pressure/vacuum test)","Prueba con solución jabonosa aplicada en todas las conexiones","Prueba con lámpara ultravioleta y tinte fluorescente en el aceite"], respuesta_correcta:1, explicacion:"La prueba de presión/vacío estacionaria consiste en presurizar ligeramente el sistema con nitrógeno seco y monitorear si la presión cae, o hacer vacío y verificar que se mantenga." , question: "What method is used to detect leaks in a low-pressure system that is turned off?", options: ["Testing with an electronic leak detector while the system is running", "A standing pressure/vacuum test", "Testing with a soap bubble solution applied to all connections", "Testing with an ultraviolet lamp and fluorescent dye in the oil"], explanation: "A standing pressure/vacuum test involves slightly pressurizing the system with dry nitrogen and monitoring for pressure drop, or pulling a vacuum and verifying it holds." },
  { id:"epa608_320", categoria:"EPA608_TIPO3", pregunta:"¿Cómo se carga refrigerante líquido en un sistema de baja presión Tipo III?", opciones:["Se carga como vapor por el lado de succión del compresor centrífugo","Se carga como líquido directamente en el evaporador de carcasa y tubos","Se carga como vapor por el lado de descarga del compresor centrífugo","Se carga como líquido en el condensador a través de la línea de líquido"], respuesta_correcta:1, explicacion:"En sistemas de baja presión, el refrigerante se puede cargar como líquido directamente en el evaporador, ya que opera en vacío y el líquido se evapora rápidamente." , question: "How is liquid refrigerant charged into a low-pressure Type III system?", options: ["It is charged as vapor through the suction side of the centrifugal compressor", "It is charged as liquid directly into the shell-and-tube evaporator", "It is charged as vapor through the discharge side of the centrifugal compressor", "It is charged as liquid into the condenser through the liquid line"], explanation: "In low-pressure systems, refrigerant can be charged as liquid directly into the evaporator, since it operates under vacuum and the liquid evaporates quickly." },
  { id:"epa608_321", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el refrigerante HFC utilizado como alternativa en algunos chillers centrífugos de baja presión?", opciones:["R-134a que opera a presiones positivas en sistemas centrífugos","R-245fa que opera a baja presión en chillers centrífugos grandes","R-410A que ofrece alta capacidad en sistemas de expansión directa","R-407C que es una mezcla zeotrópica para sistemas existentes"], respuesta_correcta:1, explicacion:"El R-245fa es un HFC de baja presión utilizado en chillers centrífugos como alternativa a los refrigerantes CFC y HCFC eliminados." , question: "What HFC refrigerant is used as an alternative in some low-pressure centrifugal chillers?", options: ["R-134a, which operates at positive pressures in centrifugal systems", "R-245fa, which operates at low pressure in large centrifugal chillers", "R-410A, which offers high capacity in direct expansion systems", "R-407C, which is a zeotropic blend for existing systems"], explanation: "R-245fa is a low-pressure HFC used in centrifugal chillers as an alternative to the phased-out CFC and HCFC refrigerants." },
  { id:"epa608_322", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el refrigerante HFO desarrollado para reemplazar al R-245fa en sistemas de baja presión?", opciones:["R-1234yf diseñado para sistemas automotrices de aire acondicionado","R-1234ze usado en sistemas comerciales de media presión estándar","R-1233zd desarrollado específicamente para chillers de baja presión","R-1336mzz diseñado exclusivamente para bombas de calor residenciales"], respuesta_correcta:2, explicacion:"El R-1233zd es un HFO (hidrofluoroolefina) de baja presión con muy bajo potencial de calentamiento global, diseñado como reemplazo del R-245fa en chillers centrífugos." , question: "What HFO refrigerant was developed to replace R-245fa in low-pressure systems?", options: ["R-1234yf, designed for automotive air conditioning systems", "R-1234ze, used in standard medium-pressure commercial systems", "R-1233zd, developed specifically for low-pressure chillers", "R-1336mzz, designed exclusively for residential heat pumps"], explanation: "R-1233zd is a low-pressure HFO (hydrofluoroolefin) with very low global warming potential, designed as a replacement for R-245fa in centrifugal chillers." },
  { id:"epa608_323", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el refrigerante CFC de baja presión que se usaba como solvente y en refrigeración?", opciones:["R-12 utilizado ampliamente en refrigeración doméstica y automotriz","R-113 utilizado como solvente industrial y en algunos sistemas HVAC","R-22 utilizado en sistemas de aire acondicionado residenciales","R-502 utilizado en sistemas de refrigeración comercial de baja temp"], respuesta_correcta:1, explicacion:"El R-113 es un CFC de baja presión que se usó como solvente industrial y en algunas aplicaciones de refrigeración. Fue eliminado bajo el Protocolo de Montreal." , question: "Which low-pressure CFC refrigerant was used as both a solvent and in refrigeration?", options: ["R-12, widely used in domestic and automotive refrigeration", "R-113, used as an industrial solvent and in some HVAC systems", "R-22, used in residential air conditioning systems", "R-502, used in commercial low-temperature refrigeration systems"], explanation: "R-113 is a low-pressure CFC that was used as an industrial solvent and in some refrigeration applications. It was phased out under the Montreal Protocol." },
  { id:"epa608_324", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de compresor se utiliza predominantemente en los chillers de baja presión?", opciones:["Compresor reciprocante de múltiples cilindros y válvulas de lámina","Compresor de tornillo rotativo con inyección de aceite para sellado","Compresor centrífugo con impulsor de alta velocidad y álabes guía","Compresor scroll hermético con espirales fijas y orbitantes internas"], respuesta_correcta:2, explicacion:"Los chillers de baja presión usan compresores centrífugos que mueven grandes volúmenes de vapor a baja presión mediante un impulsor de alta velocidad." , question: "What type of compressor is predominantly used in low-pressure chillers?", options: ["A multi-cylinder reciprocating compressor with reed valves", "A rotary screw compressor with oil injection for sealing", "A centrifugal compressor with a high-speed impeller and guide vanes", "A hermetic scroll compressor with fixed and orbiting internal scrolls"], explanation: "Low-pressure chillers use centrifugal compressors that move large volumes of vapor at low pressure using a high-speed impeller." },
  { id:"epa608_325", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la función de los álabes guía (guide vanes) en un compresor centrífugo?", opciones:["Dirigir el aceite lubricante hacia los rodamientos del eje principal","Controlar la capacidad del compresor regulando el flujo de refrigerante","Prevenir el flujo inverso de refrigerante durante el apagado del equipo","Reducir la vibración del impulsor a velocidades de rotación elevadas"], respuesta_correcta:1, explicacion:"Los álabes guía (guide vanes) controlan la capacidad del compresor centrífugo al regular la cantidad de vapor de refrigerante que entra al impulsor." , question: "What is the function of guide vanes in a centrifugal compressor?", options: ["To direct lubricating oil toward the main shaft bearings", "To control compressor capacity by regulating refrigerant flow", "To prevent reverse refrigerant flow during equipment shutdown", "To reduce impeller vibration at high rotational speeds"], explanation: "Guide vanes control the capacity of the centrifugal compressor by regulating the amount of refrigerant vapor entering the impeller." },
  { id:"epa608_326", categoria:"EPA608_TIPO3", pregunta:"¿Qué tecnología alternativa a los álabes guía se usa para controlar la capacidad en chillers centrífugos modernos?", opciones:["Válvulas de expansión electrónica con control proporcional integral","Variadores de frecuencia (VFD) que ajustan la velocidad del compresor","Válvulas solenoides de descarga parcial en el cabezal del compresor","Bypass de gas caliente desde la descarga hacia la línea de succión"], respuesta_correcta:1, explicacion:"Los variadores de frecuencia (VFD) permiten ajustar la velocidad del compresor centrífugo para modular la capacidad de manera más eficiente que los álabes guía solos." , question: "What alternative technology to guide vanes is used to control capacity in modern centrifugal chillers?", options: ["Electronic expansion valves with proportional-integral control", "Variable frequency drives (VFDs) that adjust the compressor speed", "Partial-load solenoid valves on the compressor head", "Hot gas bypass from the discharge to the suction line"], explanation: "Variable frequency drives (VFDs) allow adjustment of the centrifugal compressor speed to modulate capacity more efficiently than guide vanes alone." },
  { id:"epa608_327", categoria:"EPA608_TIPO3", pregunta:"¿En qué unidades se mide comúnmente la eficiencia de un chiller centrífugo?", opciones:["BTU por hora dividido entre el área en pies cuadrados del edificio","Coeficiente de rendimiento (COP) sin unidades para comparar sistemas","Kilovatios por tonelada (kW/ton) de refrigeración producida por el equipo","Toneladas de refrigeración por galón de agua circulada por el sistema"], respuesta_correcta:2, explicacion:"La eficiencia de los chillers se mide en kW/ton (kilovatios consumidos por tonelada de refrigeración producida). Un valor más bajo indica mayor eficiencia." , question: "In what units is the efficiency of a centrifugal chiller commonly measured?", options: ["BTU per hour divided by the building area in square feet", "Coefficient of performance (COP), a dimensionless ratio for comparing systems", "Kilowatts per ton (kW/ton) of refrigeration produced by the equipment", "Tons of refrigeration per gallon of water circulated through the system"], explanation: "Chiller efficiency is measured in kW/ton (kilowatts consumed per ton of refrigeration produced). A lower value indicates higher efficiency." },
  { id:"epa608_328", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es un valor de eficiencia típico de un chiller centrífugo moderno de alta eficiencia?", opciones:["0.50 a 0.60 kW/ton que indica un rendimiento excepcional en el mercado","2.00 a 3.00 kW/ton que es estándar para la mayoría de los fabricantes","5.00 a 6.00 kW/ton comparable a un sistema de expansión directa comercial","0.90 a 1.20 kW/ton que está por debajo del promedio de la industria"], respuesta_correcta:0, explicacion:"Los chillers centrífugos modernos de alta eficiencia pueden alcanzar 0.50-0.60 kW/ton a condiciones nominales, siendo los más eficientes del mercado." , question: "What is a typical efficiency value for a modern high-efficiency centrifugal chiller?", options: ["0.50 to 0.60 kW/ton, indicating exceptional performance in the market", "2.00 to 3.00 kW/ton, which is the standard for most manufacturers", "5.00 to 6.00 kW/ton, comparable to a commercial direct-expansion system", "0.90 to 1.20 kW/ton, which is below the industry average"], explanation: "Modern high-efficiency centrifugal chillers can achieve 0.50-0.60 kW/ton at rated conditions, making them the most efficient on the market." },
  { id:"epa608_329", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la función del calentador de aceite (oil heater) en un chiller de baja presión cuando está apagado?", opciones:["Mantener el aceite caliente para lubricación inmediata durante el arranque","Evitar que el refrigerante migre y se mezcle con el aceite del cárter","Precalentar el aceite para reducir la viscosidad antes de la operación","Eliminar la humedad del aceite lubricante mediante evaporación térmica"], respuesta_correcta:1, explicacion:"El calentador de aceite evita la migración del refrigerante hacia el aceite cuando el chiller está apagado. Sin él, el refrigerante se disuelve en el aceite frío." , question: "What is the function of the oil heater on a low-pressure chiller when it is shut down?", options: ["To keep the oil warm for immediate lubrication during startup", "To prevent refrigerant from migrating into and mixing with the crankcase oil", "To preheat the oil to reduce viscosity before operation", "To remove moisture from the lubricating oil through thermal evaporation"], explanation: "The oil heater prevents refrigerant from migrating into the oil when the chiller is shut down. Without it, refrigerant dissolves in the cold oil." },
  { id:"epa608_330", categoria:"EPA608_TIPO3", pregunta:"¿Qué es la migración de refrigerante en un chiller de baja presión que está fuera de servicio?", opciones:["El movimiento del refrigerante del condensador al evaporador por gravedad lenta","La absorción del refrigerante líquido por el aceite lubricante frío del cárter","La fuga gradual de refrigerante a través de sellos desgastados del compresor","La transferencia de refrigerante entre chillers conectados en paralelo cercanos"], respuesta_correcta:1, explicacion:"Cuando un chiller está apagado, el refrigerante puede migrar hacia el aceite frío del compresor, diluyéndolo. El calentador de aceite previene esto manteniendo el aceite caliente." , question: "What is refrigerant migration in a low-pressure chiller that is out of service?", options: ["The movement of refrigerant from the condenser to the evaporator by slow gravity", "The absorption of liquid refrigerant by the cold lubricating oil in the crankcase", "The gradual leak of refrigerant through worn compressor seals", "The transfer of refrigerant between chillers connected in close parallel"], explanation: "When a chiller is shut down, refrigerant can migrate into the cold compressor oil, diluting it. The oil heater prevents this by keeping the oil warm." },
  { id:"epa608_331", categoria:"EPA608_TIPO3", pregunta:"¿Dónde se acumulan típicamente los gases no condensables en un chiller de baja presión?", opciones:["En la parte inferior del evaporador donde la temperatura es más baja","En el punto más alto del condensador donde la presión es mayor del sistema","En la línea de succión del compresor antes de los álabes guía de entrada","En el separador de aceite ubicado entre el compresor y el condensador"], respuesta_correcta:1, explicacion:"Los gases no condensables se acumulan en el punto más alto del condensador porque son más ligeros que el vapor de refrigerante condensado." , question: "Where do non-condensable gases typically accumulate in a low-pressure chiller?", options: ["At the bottom of the evaporator where the temperature is lowest", "At the highest point of the condenser where the system pressure is greatest", "In the compressor suction line before the inlet guide vanes", "In the oil separator located between the compressor and the condenser"], explanation: "Non-condensable gases accumulate at the highest point of the condenser because they are lighter than the condensed refrigerant vapor." },
  { id:"epa608_332", categoria:"EPA608_TIPO3", pregunta:"¿Qué es un economizador flash en un chiller centrífugo de baja presión?", opciones:["Un dispositivo que enfría el motor eléctrico del compresor centrífugo","Un tanque intermedio que mejora la eficiencia del ciclo de refrigeración","Un controlador electrónico que optimiza la secuencia de arranque del equipo","Un intercambiador que subenfría el agua helada antes de distribuirla al edificio"], respuesta_correcta:1, explicacion:"El economizador flash es un tanque a presión intermedia donde parte del refrigerante se evapora (flash), enfriando el resto y mejorando la eficiencia general del ciclo." , question: "What is a flash economizer in a low-pressure centrifugal chiller?", options: ["A device that cools the centrifugal compressor electric motor", "An intermediate tank that improves the efficiency of the refrigeration cycle", "An electronic controller that optimizes the equipment startup sequence", "A heat exchanger that subcools the chilled water before distribution to the building"], explanation: "The flash economizer is a tank at an intermediate pressure where part of the refrigerant evaporates (flashes), cooling the rest and improving overall cycle efficiency." },
  { id:"epa608_333", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de válvula de expansión se usa comúnmente en chillers de baja presión?", opciones:["Válvula de expansión termostática con bulbo sensor en la salida del evaporador","Válvula de flotador que mantiene el nivel de refrigerante líquido constante","Tubo capilar de longitud calculada para la caída de presión necesaria","Válvula de expansión electrónica con motor paso a paso de alta precisión"], respuesta_correcta:1, explicacion:"Los chillers de baja presión comúnmente usan válvulas de flotador para mantener el nivel apropiado de refrigerante líquido en el evaporador o condensador." , question: "What type of expansion valve is commonly used in low-pressure chillers?", options: ["A thermostatic expansion valve with a sensing bulb at the evaporator outlet", "A float valve that maintains a constant liquid refrigerant level", "A capillary tube of calculated length for the required pressure drop", "An electronic expansion valve with a high-precision stepper motor"], explanation: "Low-pressure chillers commonly use float valves to maintain the appropriate liquid refrigerant level in the evaporator or condenser." },
  { id:"epa608_334", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la tasa máxima de fuga anual permitida para equipos de refrigeración comercial con más de 50 libras de refrigerante?", opciones:["5% del total de la carga de refrigerante del equipo por año calendario","10% del total de la carga de refrigerante del equipo por año calendario","15% del total de la carga de refrigerante del equipo por año calendario","20% del total de la carga de refrigerante del equipo por año calendario"], respuesta_correcta:2, explicacion:"La EPA establece una tasa máxima de fuga del 15% anual para equipos de refrigeración comercial. Si se excede, las reparaciones deben hacerse en un plazo determinado." , question: "What is the maximum allowable annual leak rate for commercial refrigeration equipment containing more than 50 pounds of refrigerant?", options: ["5% of the total equipment refrigerant charge per calendar year", "10% of the total equipment refrigerant charge per calendar year", "15% of the total equipment refrigerant charge per calendar year", "20% of the total equipment refrigerant charge per calendar year"], explanation: "The EPA sets a maximum annual leak rate of 15% for commercial refrigeration equipment. If exceeded, repairs must be made within a set timeframe." },
  { id:"epa608_335", categoria:"EPA608_TIPO3", pregunta:"¿Qué sucede si un chiller de baja presión excede la tasa de fuga permitida por la EPA?", opciones:["Se debe reemplazar todo el refrigerante por uno de menor impacto ambiental","Se debe reparar la fuga dentro de los 30 días siguientes a su descubrimiento","Se debe apagar el equipo permanentemente y desmantelarlo de inmediato","Se debe reportar a la EPA pero puede seguir operando sin restricción alguna"], respuesta_correcta:1, explicacion:"Si se excede la tasa de fuga permitida, el propietario debe reparar la fuga dentro de 30 días o desarrollar un plan de retiro del equipo dentro del plazo establecido." , question: "What happens if a low-pressure chiller exceeds the EPA-allowed leak rate?", options: ["All the refrigerant must be replaced with one that has a lower environmental impact", "The leak must be repaired within 30 days of its discovery", "The equipment must be permanently shut down and dismantled immediately", "It must be reported to the EPA but may continue operating without restriction"], explanation: "If the allowed leak rate is exceeded, the owner must repair the leak within 30 days or develop an equipment retirement plan within the established timeframe." },
  { id:"epa608_336", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la importancia del tratamiento de agua en los circuitos de un chiller enfriado por agua?", opciones:["Mantener el color del agua cristalino para inspecciones visuales periódicas","Prevenir incrustaciones, corrosión y crecimiento biológico en los tubos","Aumentar la presión del agua para mejorar el flujo a través del sistema","Reducir la temperatura del agua para incrementar la capacidad del chiller"], respuesta_correcta:1, explicacion:"El tratamiento de agua previene incrustaciones minerales, corrosión de los tubos y crecimiento de algas/bacterias, manteniendo la eficiencia de transferencia de calor." , question: "What is the importance of water treatment in the circuits of a water-cooled chiller?", options: ["To keep the water crystal clear for periodic visual inspections", "To prevent scale buildup, corrosion, and biological growth in the tubes", "To increase water pressure to improve flow through the system", "To reduce water temperature to increase the chiller capacity"], explanation: "Water treatment prevents mineral scale, tube corrosion, and algae/bacteria growth, maintaining heat transfer efficiency." },
  { id:"epa608_337", categoria:"EPA608_TIPO3", pregunta:"¿Cómo se enfría el motor del compresor en un chiller centrífugo hermético?", opciones:["Con un ventilador externo dedicado montado directamente sobre la carcasa","Con el refrigerante del propio sistema que pasa por el motor continuamente","Con un circuito de agua independiente conectado a la torre de enfriamiento","Con un sistema de aceite lubricante que circula a través del devanado"], respuesta_correcta:1, explicacion:"En compresores centrífugos herméticos, el motor se enfría directamente con el vapor de refrigerante del sistema que pasa sobre los devanados del motor." , question: "How is the compressor motor cooled in a hermetic centrifugal chiller?", options: ["With a dedicated external fan mounted directly on the housing", "With the system's own refrigerant that continuously passes over the motor", "With an independent water circuit connected to the cooling tower", "With a lubricating oil system that circulates through the windings"], explanation: "In hermetic centrifugal compressors, the motor is cooled directly by the system's refrigerant vapor passing over the motor windings." },
  { id:"epa608_338", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el propósito de las hojas de registro (log sheets) de operación de un chiller?", opciones:["Cumplir únicamente con el requisito de documentación de la OSHA federal","Rastrear tendencias de rendimiento y detectar problemas tempranamente","Proporcionar información de marketing sobre la eficiencia del edificio","Calcular los impuestos anuales por uso de refrigerantes regulados federalmente"], respuesta_correcta:1, explicacion:"Las hojas de registro permiten rastrear tendencias de temperatura, presión y eficiencia del chiller para detectar problemas como fugas o degradación antes de que sean graves." , question: "What is the purpose of chiller operation log sheets?", options: ["Solely to comply with the federal OSHA documentation requirement", "To track performance trends and detect problems early", "To provide marketing information about the building's efficiency", "To calculate annual taxes for the use of federally regulated refrigerants"], explanation: "Log sheets allow tracking of temperature, pressure, and efficiency trends of the chiller to detect problems like leaks or degradation before they become severe." },
  { id:"epa608_339", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de instalaciones típicamente utilizan chillers centrífugos de baja presión?", opciones:["Residencias unifamiliares y apartamentos de hasta tres dormitorios","Tiendas minoristas pequeñas y restaurantes de comida rápida locales","Grandes edificios comerciales, hospitales y campus universitarios","Vehículos de transporte refrigerado y contenedores marítimos de carga"], respuesta_correcta:2, explicacion:"Los chillers centrífugos de baja presión se usan en grandes edificios comerciales, hospitales y campus por su alta capacidad (100-2,000+ toneladas)." , question: "What type of facilities typically use low-pressure centrifugal chillers?", options: ["Single-family homes and apartments with up to three bedrooms", "Small retail stores and local fast-food restaurants", "Large commercial buildings, hospitals, and university campuses", "Refrigerated transport vehicles and maritime cargo containers"], explanation: "Low-pressure centrifugal chillers are used in large commercial buildings, hospitals, and campuses due to their high capacity (100-2,000+ tons)." },
  { id:"epa608_340", categoria:"EPA608_TIPO3", pregunta:"¿Por qué se requieren monitores de ambiente en la sala de máquinas cuando se usa R-123?", opciones:["Porque el R-123 es altamente inflamable y puede causar una explosión grave","Porque el R-123 tiene clasificación B1 indicando mayor toxicidad potencial","Porque el R-123 desplaza todo el oxígeno en espacios cerrados rápidamente","Porque el R-123 es invisible y no tiene olor detectable por el ser humano"], respuesta_correcta:1, explicacion:"El R-123 tiene clasificación B1 (mayor toxicidad), por lo que se requieren monitores de ambiente para alertar al personal si la concentración excede límites seguros." , question: "Why are room ambient monitors required in the mechanical room when using R-123?", options: ["Because R-123 is highly flammable and can cause a serious explosion", "Because R-123 has a B1 safety classification indicating higher potential toxicity", "Because R-123 displaces all oxygen in enclosed spaces rapidly", "Because R-123 is invisible and has no odor detectable by humans"], explanation: "R-123 has a B1 safety classification (higher toxicity), so room ambient monitors are required to alert personnel if the concentration exceeds safe limits." },
  { id:"epa608_341", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el procedimiento correcto para descomisionar un chiller de baja presión?", opciones:["Abrir las válvulas de servicio y dejar que el refrigerante se evapore naturalmente","Recuperar todo el refrigerante hasta alcanzar 25 mm Hg absoluto antes de desmantelar","Drenar el refrigerante líquido al drenaje y ventilar el vapor residual a la atmósfera","Transferir el refrigerante al chiller más cercano sin necesidad de recuperación formal"], respuesta_correcta:1, explicacion:"Al descomisionar un chiller de baja presión, se debe recuperar todo el refrigerante hasta alcanzar 25 mm Hg absoluto antes de cualquier procedimiento de desmantelamiento." , question: "What is the correct procedure for decommissioning a low-pressure chiller?", options: ["Open the service valves and allow the refrigerant to evaporate naturally", "Recover all refrigerant down to 25 mm Hg absolute before dismantling", "Drain the liquid refrigerant to the drain and vent the residual vapor to the atmosphere", "Transfer the refrigerant to the nearest chiller without the need for formal recovery"], explanation: "When decommissioning a low-pressure chiller, all refrigerant must be recovered down to 25 mm Hg absolute before any dismantling procedures." },
  { id:"epa608_342", categoria:"EPA608_TIPO3", pregunta:"¿Qué gas se utiliza para presurizar un sistema de baja presión durante una prueba de fugas?", opciones:["Oxígeno comprimido a presión regulada para detectar fugas con llama abierta","Nitrógeno seco a presión regulada para no introducir humedad al sistema","Aire comprimido del taller filtrado para ahorrar costos en la operación","Dióxido de carbono comprimido por su fácil disponibilidad en el mercado"], respuesta_correcta:1, explicacion:"Se usa nitrógeno seco para presurizar el sistema durante pruebas de fugas porque es inerte, no contiene humedad y no daña los componentes internos del sistema." , question: "What gas is used to pressurize a low-pressure system during a leak test?", options: ["Compressed oxygen at regulated pressure to detect leaks with an open flame", "Dry nitrogen at regulated pressure to avoid introducing moisture into the system", "Filtered shop compressed air to save costs during the operation", "Compressed carbon dioxide due to its easy availability on the market"], explanation: "Dry nitrogen is used to pressurize the system during leak tests because it is inert, contains no moisture, and does not damage internal system components." },
  { id:"epa608_343", categoria:"EPA608_TIPO3", pregunta:"¿A qué presión máxima se debe presurizar un sistema de baja presión para una prueba de fugas?", opciones:["No más de 10 psig para evitar dañar componentes diseñados para vacío","No más de 50 psig que es el límite estándar de prueba industrial general","No más de 150 psig para asegurar que se detecten fugas muy pequeñas","No más de 300 psig siguiendo el estándar de ASME para recipientes a presión"], respuesta_correcta:0, explicacion:"Los sistemas de baja presión están diseñados para operar en vacío, por lo que la presión de prueba no debe exceder 10 psig para evitar dañar los componentes." , question: "What is the maximum pressure to which a low-pressure system should be pressurized for a leak test?", options: ["No more than 10 psig to avoid damaging components designed for vacuum", "No more than 50 psig, which is the standard general industrial test limit", "No more than 150 psig to ensure very small leaks are detected", "No more than 300 psig following the ASME standard for pressure vessels"], explanation: "Low-pressure systems are designed to operate under vacuum, so the test pressure must not exceed 10 psig to avoid damaging components." },
  { id:"epa608_344", categoria:"EPA608_TIPO3", pregunta:"¿Qué componente separa el aceite lubricante del refrigerante en un chiller centrífugo?", opciones:["El filtro deshidratador instalado en la línea de líquido del sistema","El separador de aceite ubicado en la línea de descarga del compresor","El evaporador donde el aceite se sedimenta por diferencia de densidad","El economizador flash que separa fases por presión intermedia controlada"], respuesta_correcta:1, explicacion:"El separador de aceite en la línea de descarga del compresor centrífugo separa el aceite arrastrado por el vapor de refrigerante y lo devuelve al cárter." , question: "What component separates the lubricating oil from the refrigerant in a centrifugal chiller?", options: ["The filter-drier installed in the liquid line of the system", "The oil separator located in the compressor discharge line", "The evaporator where the oil settles out due to density differences", "The flash economizer that separates phases by controlled intermediate pressure"], explanation: "The oil separator in the centrifugal compressor discharge line separates the oil carried by the refrigerant vapor and returns it to the crankcase." },
  { id:"epa608_345", categoria:"EPA608_TIPO3", pregunta:"¿Qué efecto tiene la presencia de humedad dentro de un sistema de baja presión?", opciones:["Mejora la lubricación del compresor al mezclarse con el aceite mineral","Puede causar corrosión, formación de ácidos y congelamiento en válvulas","Aumenta la eficiencia del evaporador al mejorar la transferencia de calor","No tiene efecto significativo porque el sistema opera a temperatura ambiente"], respuesta_correcta:1, explicacion:"La humedad dentro del sistema causa corrosión de metales, formación de ácidos al reaccionar con el refrigerante y puede congelarse en válvulas de expansión." , question: "What effect does moisture have inside a low-pressure system?", options: ["It improves compressor lubrication by mixing with the mineral oil", "It can cause corrosion, acid formation, and freezing in valves", "It increases evaporator efficiency by improving heat transfer", "It has no significant effect because the system operates at ambient temperature"], explanation: "Moisture inside the system causes metal corrosion, acid formation when it reacts with the refrigerant, and can freeze in expansion valves." },
  { id:"epa608_346", categoria:"EPA608_TIPO3", pregunta:"¿Por qué los sistemas de baja presión son más susceptibles a la entrada de humedad que los de alta presión?", opciones:["Porque usan tubería de cobre que es más permeable al vapor de agua ambiental","Porque operan en vacío, lo que succiona aire húmedo a través de cualquier fuga","Porque el refrigerante de baja presión atrae químicamente las moléculas de agua","Porque sus conexiones de servicio son más grandes y tienen más puntos de sellado"], respuesta_correcta:1, explicacion:"Al operar por debajo de la presión atmosférica, cualquier fuga permite la entrada de aire húmedo al sistema, a diferencia de los sistemas de alta presión donde el refrigerante sale." , question: "Why are low-pressure systems more susceptible to moisture infiltration than high-pressure systems?", options: ["Because they use copper tubing that is more permeable to ambient water vapor", "Because they operate under vacuum, which draws humid air in through any leak", "Because low-pressure refrigerant chemically attracts water molecules", "Because their service connections are larger and have more sealing points"], explanation: "By operating below atmospheric pressure, any leak allows humid air to enter the system, unlike high-pressure systems where refrigerant leaks out." },
  { id:"epa608_347", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la función del reservorio de aceite en un chiller centrífugo de baja presión?", opciones:["Almacenar aceite de repuesto para cambios programados de mantenimiento anual","Mantener un suministro adecuado de aceite lubricante para el compresor centrífugo","Enfriar el aceite antes de que regrese a los rodamientos del eje del impulsor","Filtrar las partículas metálicas que se generan por desgaste del compresor"], respuesta_correcta:1, explicacion:"El reservorio de aceite almacena aceite lubricante suficiente para mantener un suministro constante al compresor centrífugo durante todas las condiciones de operación." , question: "What is the function of the oil reservoir in a low-pressure centrifugal chiller?", options: ["To store spare oil for scheduled annual maintenance changes", "To maintain an adequate supply of lubricating oil for the centrifugal compressor", "To cool the oil before it returns to the impeller shaft bearings", "To filter metallic particles generated by compressor wear"], explanation: "The oil reservoir stores enough lubricating oil to maintain a constant supply to the centrifugal compressor during all operating conditions." },
  { id:"epa608_348", categoria:"EPA608_TIPO3", pregunta:"¿Qué indica un aumento gradual en la presión del condensador de un chiller de baja presión sin cambio en la carga térmica?", opciones:["Que el compresor centrífugo está operando por encima de su velocidad nominal","Que hay acumulación de gases no condensables dentro del condensador del equipo","Que el nivel de refrigerante en el evaporador es demasiado alto actualmente","Que la válvula de flotador está completamente abierta permitiendo exceso de flujo"], respuesta_correcta:1, explicacion:"Un aumento gradual en la presión del condensador sin cambio en la carga generalmente indica acumulación de aire u otros gases no condensables en el sistema." , question: "What does a gradual increase in condenser pressure of a low-pressure chiller indicate when there is no change in thermal load?", options: ["That the centrifugal compressor is operating above its rated speed", "That there is a buildup of non-condensable gases inside the condenser", "That the refrigerant level in the evaporator is currently too high", "That the float valve is fully open allowing excess flow"], explanation: "A gradual increase in condenser pressure without a change in load generally indicates accumulation of air or other non-condensable gases in the system." },
  { id:"epa608_349", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el ODP (potencial de agotamiento de ozono) del R-123 comparado con el R-11?", opciones:["R-123 tiene ODP de 1.0, igual que el R-11 al que reemplaza directamente","R-123 tiene ODP de 0.5, exactamente la mitad que el del R-11 original","R-123 tiene ODP de 0.02, significativamente menor que el 1.0 del R-11","R-123 tiene ODP de 0.0, ya que es un refrigerante HFC sin cloro en su molécula"], respuesta_correcta:2, explicacion:"El R-123 tiene un ODP de aproximadamente 0.02, mucho menor que el 1.0 del R-11, pero aún contiene cloro como HCFC por lo que eventualmente será eliminado." , question: "What is the ODP (Ozone Depletion Potential) of R-123 compared to R-11?", options: ["R-123 has an ODP of 1.0, the same as the R-11 it directly replaces", "R-123 has an ODP of 0.5, exactly half that of the original R-11", "R-123 has an ODP of 0.02, significantly lower than the 1.0 of R-11", "R-123 has an ODP of 0.0, since it is an HFC refrigerant with no chlorine in its molecule"], explanation: "R-123 has an ODP of approximately 0.02, much lower than the 1.0 of R-11, but it still contains chlorine as an HCFC and will eventually be phased out." },
  { id:"epa608_350", categoria:"EPA608_TIPO3", pregunta:"¿Qué precaución especial se debe tomar al trabajar con R-123 en una sala de máquinas cerrada?", opciones:["Usar casco de protección contra impactos por presiones extremadamente altas","Verificar que los monitores de ambiente estén funcionando antes de entrar","Usar guantes de soldadura por las temperaturas criogénicas del refrigerante","Conectar el equipo a tierra eléctrica para evitar chispas por la inflamabilidad"], respuesta_correcta:1, explicacion:"Debido a la mayor toxicidad del R-123 (clasificación B1), se debe verificar que los monitores de ambiente funcionen correctamente antes de entrar a la sala de máquinas." , question: "What special precaution should be taken when working with R-123 in an enclosed mechanical room?", options: ["Wear an impact-protection hard hat due to extremely high pressures", "Verify that the room ambient monitors are functioning before entering", "Wear welding gloves due to the cryogenic temperatures of the refrigerant", "Ground the equipment electrically to prevent sparks due to flammability"], explanation: "Due to the higher toxicity of R-123 (B1 classification), ambient monitors must be verified as functioning correctly before entering the mechanical room." },
  { id:"epa608_351", categoria:"EPA608_TIPO3", pregunta:"¿Qué sucede si se rompe un disco de ruptura en un chiller de baja presión?", opciones:["El sistema automáticamente se represuriza con nitrógeno del tanque de reserva","El refrigerante puede escapar a la atmósfera y el sistema pierde su carga completa","El compresor centrífugo se apaga y reinicia después de un tiempo de espera","La unidad de purga se activa a máxima velocidad para compensar la presión"], respuesta_correcta:1, explicacion:"Si el disco de ruptura se rompe, libera la presión interna y el refrigerante puede escapar a la atmósfera. El disco debe ser reemplazado y el sistema recargado." , question: "What happens if a rupture disc breaks on a low-pressure chiller?", options: ["The system automatically repressurizes with nitrogen from the reserve tank", "The refrigerant can escape to the atmosphere and the system loses its entire charge", "The centrifugal compressor shuts down and restarts after a waiting period", "The purge unit activates at maximum speed to compensate for the pressure"], explanation: "If the rupture disc breaks, it releases internal pressure and refrigerant can escape to the atmosphere. The disc must be replaced and the system recharged." },
  { id:"epa608_352", categoria:"EPA608_TIPO3", pregunta:"¿Cuándo se activa el disco de ruptura en un chiller de baja presión?", opciones:["Cuando la temperatura del agua helada cae por debajo del punto de congelación","Cuando la presión interna excede un valor predeterminado de diseño seguro","Cuando el nivel de aceite en el cárter del compresor es insuficiente para operar","Cuando la corriente eléctrica del motor excede el valor nominal de placa"], respuesta_correcta:1, explicacion:"El disco de ruptura se activa cuando la presión interna del recipiente excede un valor predeterminado, como en caso de incendio o falla que caliente el refrigerante." , question: "When does the rupture disc activate on a low-pressure chiller?", options: ["When the chilled water temperature drops below the freezing point", "When the internal pressure exceeds a predetermined safe design value", "When the oil level in the compressor crankcase is insufficient for operation", "When the motor electrical current exceeds the nameplate rated value"], explanation: "The rupture disc activates when the internal pressure of the vessel exceeds a predetermined value, such as in the case of a fire or a failure that heats the refrigerant." },
  { id:"epa608_353", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es un escenario que podría causar que la presión suba peligrosamente en un chiller de baja presión?", opciones:["Una caída repentina en la temperatura del agua de la torre de enfriamiento","Un incendio en la sala de máquinas que caliente el refrigerante del sistema","Una fuga de aire que ingrese al sistema durante operación a baja carga","Un exceso de aceite lubricante en el cárter del compresor centrífugo"], respuesta_correcta:1, explicacion:"Un incendio puede calentar el refrigerante dentro del chiller, causando una presión peligrosamente alta que active el disco de ruptura como medida de seguridad." , question: "What scenario could cause pressure to rise dangerously in a low-pressure chiller?", options: ["A sudden drop in cooling tower water temperature", "A fire in the mechanical room that heats the refrigerant in the system", "An air leak entering the system during low-load operation", "Excess lubricating oil in the centrifugal compressor crankcase"], explanation: "A fire can heat the refrigerant inside the chiller, causing dangerously high pressure that activates the rupture disc as a safety measure." },
  { id:"epa608_354", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de evaporador se utiliza en chillers centrífugos de baja presión?", opciones:["Evaporador de expansión directa con serpentín de cobre aleteado montado en aire","Evaporador tipo carcasa y tubos (shell and tube) inundado con agua en los tubos","Evaporador de placas con flujo de refrigerante y agua en capas alternas delgadas","Evaporador de tubo en tubo con refrigerante en el tubo interno y agua en externo"], respuesta_correcta:1, explicacion:"Los chillers centrífugos de baja presión usan evaporadores tipo carcasa y tubos (shell and tube) donde el agua circula por los tubos y el refrigerante inunda la carcasa." , question: "What type of evaporator is used in low-pressure centrifugal chillers?", options: ["A direct expansion evaporator with a finned copper coil mounted in air", "A flooded shell-and-tube evaporator with water in the tubes", "A plate evaporator with refrigerant and water flowing in alternating thin layers", "A tube-in-tube evaporator with refrigerant in the inner tube and water in the outer"], explanation: "Low-pressure centrifugal chillers use shell-and-tube evaporators where water circulates through the tubes and the refrigerant floods the shell." },
  { id:"epa608_355", categoria:"EPA608_TIPO3", pregunta:"¿Qué efecto tiene una incrustación en los tubos del condensador de un chiller enfriado por agua?", opciones:["Reduce la presión del condensador y aumenta la eficiencia del ciclo completo","Aumenta la presión del condensador y reduce la eficiencia de transferencia térmica","No tiene efecto medible si el flujo de agua se mantiene constante y estable","Reduce la temperatura de descarga del compresor mejorando su vida útil total"], respuesta_correcta:1, explicacion:"Las incrustaciones actúan como aislante térmico en los tubos, reduciendo la transferencia de calor, lo que eleva la presión del condensador y reduce la eficiencia." , question: "What effect does scale buildup in the condenser tubes of a water-cooled chiller have?", options: ["It reduces condenser pressure and increases the efficiency of the entire cycle", "It increases condenser pressure and reduces heat transfer efficiency", "It has no measurable effect if the water flow is kept constant and stable", "It reduces compressor discharge temperature, improving its total service life"], explanation: "Scale acts as thermal insulation on the tubes, reducing heat transfer, which raises condenser pressure and reduces efficiency." },
  { id:"epa608_356", categoria:"EPA608_TIPO3", pregunta:"¿Con qué frecuencia se deben inspeccionar los tubos de un chiller centrífugo mediante prueba de corrientes de Eddy?", opciones:["Cada mes durante la temporada de enfriamiento para detectar degradación temprana","Anualmente o según las recomendaciones del fabricante del equipo específico","Cada cinco años como parte del programa de mantenimiento mayor del equipo","Solo cuando se detecta una fuga de refrigerante confirmada en el circuito de agua"], respuesta_correcta:1, explicacion:"Las pruebas de corrientes de Eddy se realizan típicamente de forma anual o según las recomendaciones del fabricante para detectar adelgazamiento o corrosión de los tubos." , question: "How often should the tubes of a centrifugal chiller be inspected using an eddy current test?", options: ["Every month during the cooling season to detect early degradation", "Annually or per the specific equipment manufacturer's recommendations", "Every five years as part of the equipment's major maintenance program", "Only when a confirmed refrigerant leak is detected in the water circuit"], explanation: "Eddy current tests are typically performed annually or per the manufacturer's recommendations to detect tube thinning or corrosion." },
  { id:"epa608_357", categoria:"EPA608_TIPO3", pregunta:"¿Qué refrigerante de baja presión tiene el punto de ebullición más bajo entre los siguientes?", opciones:["R-11 con punto de ebullición de 74.9°F a presión atmosférica estándar","R-113 con punto de ebullición de 117.6°F a presión atmosférica estándar","R-123 con punto de ebullición de 82.2°F a presión atmosférica estándar","R-245fa con punto de ebullición de 59.0°F a presión atmosférica estándar"], respuesta_correcta:3, explicacion:"El R-245fa tiene el punto de ebullición más bajo (~59°F/15°C) entre los listados, seguido por R-11 (74.9°F), R-123 (82.2°F) y R-113 (117.6°F)." , question: "Which low-pressure refrigerant has the lowest boiling point among the following?", options: ["R-11 with a boiling point of 74.9 degrees F at standard atmospheric pressure", "R-113 with a boiling point of 117.6 degrees F at standard atmospheric pressure", "R-123 with a boiling point of 82.2 degrees F at standard atmospheric pressure", "R-245fa with a boiling point of 59.0 degrees F at standard atmospheric pressure"], explanation: "R-245fa has the lowest boiling point (approximately 59 degrees F / 15 degrees C) among those listed, followed by R-11 (74.9 degrees F), R-123 (82.2 degrees F), and R-113 (117.6 degrees F)." },
  { id:"epa608_358", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la consecuencia de tener demasiado aceite en el evaporador de un chiller de baja presión?", opciones:["El compresor centrífugo opera más silenciosamente por mejor lubricación interna","La transferencia de calor se reduce porque el aceite cubre los tubos del evaporador","La capacidad del sistema aumenta porque el aceite mejora el contacto térmico","El nivel de refrigerante sube mejorando la eficiencia de la evaporación total"], respuesta_correcta:1, explicacion:"El exceso de aceite en el evaporador cubre los tubos, actuando como aislante térmico que reduce la transferencia de calor y disminuye la eficiencia del chiller." , question: "What is the consequence of having too much oil in the evaporator of a low-pressure chiller?", options: ["The centrifugal compressor operates more quietly due to better internal lubrication", "Heat transfer is reduced because the oil coats the evaporator tubes", "System capacity increases because the oil improves thermal contact", "The refrigerant level rises, improving the efficiency of total evaporation"], explanation: "Excess oil in the evaporator coats the tubes, acting as thermal insulation that reduces heat transfer and decreases chiller efficiency." },
  { id:"epa608_359", categoria:"EPA608_TIPO3", pregunta:"¿Cómo afecta una carga insuficiente de refrigerante a un chiller de baja presión?", opciones:["Aumenta la eficiencia porque hay menos refrigerante que comprimir en cada ciclo","Reduce la capacidad de enfriamiento y puede causar baja presión excesiva de succión","No tiene efecto notable porque el sistema se autorregula con los álabes guía","Mejora la lubricación del compresor al reducir la dilución del aceite con refrigerante"], respuesta_correcta:1, explicacion:"Una carga insuficiente reduce la capacidad de enfriamiento del chiller y puede causar presiones de succión excesivamente bajas, afectando la operación del compresor." , question: "How does an insufficient refrigerant charge affect a low-pressure chiller?", options: ["It increases efficiency because there is less refrigerant to compress each cycle", "It reduces cooling capacity and can cause excessively low suction pressure", "It has no noticeable effect because the system self-regulates with the guide vanes", "It improves compressor lubrication by reducing refrigerant dilution of the oil"], explanation: "An insufficient charge reduces the chiller's cooling capacity and can cause excessively low suction pressures, affecting compressor operation." },
  { id:"epa608_360", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el propósito del enfriador de aceite en un chiller centrífugo?", opciones:["Calentar el aceite durante el arranque para reducir su viscosidad inicial","Mantener el aceite a temperatura óptima para lubricación adecuada del equipo","Filtrar impurezas del aceite antes de que lleguen a los rodamientos internos","Separar el refrigerante disuelto en el aceite durante la operación normal continua"], respuesta_correcta:1, explicacion:"El enfriador de aceite mantiene la temperatura del aceite lubricante en un rango óptimo para asegurar la viscosidad correcta y proteger los rodamientos del compresor." , question: "What is the purpose of the oil cooler in a centrifugal chiller?", options: ["To heat the oil during startup to reduce its initial viscosity", "To maintain the oil at an optimal temperature for proper equipment lubrication", "To filter impurities from the oil before they reach the internal bearings", "To separate dissolved refrigerant from the oil during normal continuous operation"], explanation: "The oil cooler maintains the lubricating oil temperature within an optimal range to ensure the correct viscosity and protect the compressor bearings." },
  { id:"epa608_361", categoria:"EPA608_TIPO3", pregunta:"¿Qué condición puede causar 'surge' (oleaje) en un compresor centrífugo?", opciones:["Operación a carga máxima con la torre de enfriamiento funcionando correctamente","Operación a carga baja con alta diferencia de presión entre condensador y evaporador","Operación a velocidad nominal con los álabes guía completamente abiertos en posición","Operación con exceso de refrigerante en el evaporador y nivel de aceite adecuado"], respuesta_correcta:1, explicacion:"El surge ocurre cuando el compresor opera a baja carga con alta diferencia de presión, causando flujo reverso intermitente y vibraciones peligrosas en el equipo." , question: "What condition can cause surge in a centrifugal compressor?", options: ["Operation at maximum load with the cooling tower functioning properly", "Operation at low load with a high pressure differential between the condenser and evaporator", "Operation at rated speed with the inlet guide vanes fully open", "Operation with excess refrigerant in the evaporator and adequate oil level"], explanation: "Surge occurs when the compressor operates at low load with a high pressure differential, causing intermittent reverse flow and dangerous vibrations in the equipment." },
  { id:"epa608_362", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la consecuencia del fenómeno de 'surge' en un compresor centrífugo?", opciones:["Mayor eficiencia energética temporal por compresión intermitente del vapor","Vibraciones severas que pueden dañar los rodamientos y el impulsor del compresor","Menor ruido de operación por la reducción en el flujo de vapor de refrigerante","Aumento gradual de la capacidad de enfriamiento del sistema hasta estabilizarse"], respuesta_correcta:1, explicacion:"El surge causa vibraciones severas, ruidos fuertes y puede dañar permanentemente los rodamientos, sellos y el impulsor del compresor centrífugo." , question: "What is the consequence of surge in a centrifugal compressor?", options: ["Temporarily higher energy efficiency due to intermittent vapor compression", "Severe vibrations that can damage the compressor bearings and impeller", "Less operating noise due to reduced refrigerant vapor flow", "Gradual increase in the system's cooling capacity until it stabilizes"], explanation: "Surge causes severe vibrations, loud noises, and can permanently damage the bearings, seals, and impeller of the centrifugal compressor." },
  { id:"epa608_363", categoria:"EPA608_TIPO3", pregunta:"¿Qué refrigerante de Tipo III tiene el GWP (potencial de calentamiento global) más bajo?", opciones:["R-11 con GWP de 4,750 utilizado en chillers centrífugos durante décadas","R-123 con GWP de 77 como reemplazo temporal del R-11 en baja presión","R-245fa con GWP de 1,030 como alternativa HFC de baja presión moderna","R-1233zd con GWP de 1 como refrigerante HFO de última generación actual"], respuesta_correcta:3, explicacion:"El R-1233zd(E) es un HFO con GWP de aproximadamente 1, lo que lo hace la opción con menor impacto climático entre los refrigerantes de baja presión disponibles." , question: "Which Type III refrigerant has the lowest GWP (Global Warming Potential)?", options: ["R-11 with a GWP of 4,750, used in centrifugal chillers for decades", "R-123 with a GWP of 77, as a temporary replacement for R-11 in low-pressure applications", "R-245fa with a GWP of 1,030, as a modern low-pressure HFC alternative", "R-1233zd with a GWP of 1, as a current next-generation HFO refrigerant"], explanation: "R-1233zd(E) is an HFO with a GWP of approximately 1, making it the option with the lowest climate impact among available low-pressure refrigerants." },
  { id:"epa608_364", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el rango de capacidad típico de un chiller centrífugo de baja presión?", opciones:["5 a 50 toneladas para aplicaciones comerciales ligeras y oficinas pequeñas","50 a 100 toneladas para edificios medianos y tiendas departamentales standard","100 a más de 2,000 toneladas para grandes edificios y plantas industriales","2,000 a 10,000 toneladas exclusivamente para plantas de energía nuclear"], respuesta_correcta:2, explicacion:"Los chillers centrífugos de baja presión tienen capacidades de 100 a más de 2,000 toneladas, siendo ideales para grandes edificios comerciales e institucionales." , question: "What is the typical capacity range of a low-pressure centrifugal chiller?", options: ["5 to 50 tons for light commercial applications and small offices", "50 to 100 tons for medium-sized buildings and standard department stores", "100 to over 2,000 tons for large buildings and industrial plants", "2,000 to 10,000 tons exclusively for nuclear power plants"], explanation: "Low-pressure centrifugal chillers have capacities ranging from 100 to over 2,000 tons, making them ideal for large commercial and institutional buildings." },
  { id:"epa608_365", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la presión de operación típica en el evaporador de un chiller que usa R-11?", opciones:["Aproximadamente 50 psig, similar a un sistema de R-22 residencial estándar","Aproximadamente 25 psig, en el rango positivo pero bajo para refrigeración","Aproximadamente 5 a 8 pulgadas de Hg de vacío, por debajo de la atmosférica","Aproximadamente 0.5 psig, apenas por encima de la presión atmosférica normal"], respuesta_correcta:2, explicacion:"El evaporador de un chiller con R-11 opera en vacío, típicamente entre 5 a 8 pulgadas de Hg de vacío, ya que el R-11 hierve a 74.9°F a presión atmosférica." , question: "What is the typical operating pressure in the evaporator of a chiller using R-11?", options: ["Approximately 50 psig, similar to a standard residential R-22 system", "Approximately 25 psig, in the positive but low range for refrigeration", "Approximately 5 to 8 inches of Hg vacuum, below atmospheric pressure", "Approximately 0.5 psig, just above normal atmospheric pressure"], explanation: "The evaporator of an R-11 chiller operates under vacuum, typically between 5 to 8 inches of Hg vacuum, since R-11 boils at 74.9 degrees F at atmospheric pressure." },
  { id:"epa608_366", categoria:"EPA608_TIPO3", pregunta:"¿Por qué es importante mantener registros detallados de la cantidad de refrigerante añadido y removido de un chiller?", opciones:["Para cumplir con los requisitos de la EPA sobre seguimiento de fugas anuales","Para calcular correctamente los impuestos federales sobre el uso de refrigerantes","Para determinar la fecha exacta del próximo mantenimiento preventivo programado","Para comparar el rendimiento entre distintas marcas de refrigerante del mercado"], respuesta_correcta:0, explicacion:"La EPA requiere que se mantengan registros de refrigerante para calcular la tasa de fuga anual y verificar el cumplimiento con los límites máximos permitidos." , question: "Why is it important to maintain detailed records of the amount of refrigerant added to and removed from a chiller?", options: ["To comply with EPA requirements for tracking annual leak rates", "To correctly calculate federal taxes on refrigerant usage", "To determine the exact date of the next scheduled preventive maintenance", "To compare performance between different refrigerant brands on the market"], explanation: "The EPA requires that refrigerant records be maintained to calculate the annual leak rate and verify compliance with maximum allowable limits." },
  { id:"epa608_367", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el método más efectivo para detectar una fuga muy pequeña en un chiller de baja presión en operación?", opciones:["Aplicar solución jabonosa en todas las juntas mientras el sistema opera en vacío","Monitorear la frecuencia de operación de la unidad de purga durante un período","Usar un detector ultrasónico de fugas desde el exterior de la sala de máquinas","Verificar visualmente las manchas de aceite en el piso debajo del equipo completo"], respuesta_correcta:1, explicacion:"En sistemas de baja presión, monitorear la frecuencia de purga es el método más efectivo: si la purga opera más frecuentemente, indica que más aire está entrando por fugas." , question: "What is the most effective method for detecting a very small leak in an operating low-pressure chiller?", options: ["Applying a soap solution to all joints while the system operates under vacuum", "Monitoring the purge unit's operating frequency over a period of time", "Using an ultrasonic leak detector from outside the mechanical room", "Visually checking for oil stains on the floor beneath the entire unit"], explanation: "In low-pressure systems, monitoring the purge frequency is the most effective method: if the purge operates more frequently, it indicates more air is entering through leaks." },
  { id:"epa608_368", categoria:"EPA608_TIPO3", pregunta:"¿Qué componente en un chiller centrífugo regula el flujo de refrigerante entre el condensador y el evaporador?", opciones:["La válvula de servicio ubicada en la línea de descarga del compresor central","El orificio fijo calibrado instalado permanentemente en la línea de líquido","La válvula de flotador que controla el nivel de líquido en el recipiente receptor","Los álabes guía de entrada del compresor que regulan el caudal de vapor"], respuesta_correcta:2, explicacion:"La válvula de flotador regula el flujo de refrigerante líquido del condensador al evaporador, manteniendo el nivel apropiado en el recipiente correspondiente." , question: "What component in a centrifugal chiller regulates the flow of refrigerant between the condenser and the evaporator?", options: ["The service valve located in the main compressor discharge line", "The fixed-calibrated orifice permanently installed in the liquid line", "The float valve that controls the liquid level in the receiver vessel", "The compressor inlet guide vanes that regulate vapor flow rate"], explanation: "The float valve regulates the flow of liquid refrigerant from the condenser to the evaporator, maintaining the appropriate level in the corresponding vessel." },
  { id:"epa608_369", categoria:"EPA608_TIPO3", pregunta:"¿Qué se debe hacer antes de abrir un chiller de baja presión para mantenimiento interno?", opciones:["Solo despresurizar el sistema hasta presión atmosférica y abrir inmediatamente","Recuperar el refrigerante hasta 25 mm Hg absoluto y verificar la presión de seguridad","Drenar únicamente el aceite del compresor y proceder con la apertura del recipiente","Enfriar el sistema a temperatura ambiente y desconectar la alimentación eléctrica únicamente"], respuesta_correcta:1, explicacion:"Antes de abrir un chiller para mantenimiento, se debe recuperar el refrigerante hasta alcanzar 25 mm Hg absoluto según los requisitos de la EPA para sistemas de baja presión." , question: "What must be done before opening a low-pressure chiller for internal maintenance?", options: ["Only depressurize the system to atmospheric pressure and open immediately", "Recover the refrigerant down to 25 mm Hg absolute and verify safe pressure", "Drain only the compressor oil and proceed with opening the vessel", "Cool the system to ambient temperature and disconnect the electrical supply only"], explanation: "Before opening a chiller for maintenance, the refrigerant must be recovered down to 25 mm Hg absolute per EPA requirements for low-pressure systems." },
  { id:"epa608_370", categoria:"EPA608_TIPO3", pregunta:"¿Qué ocurre cuando un tubo del evaporador se perfora en un chiller enfriado por agua de baja presión?", opciones:["El refrigerante se fuga hacia el circuito de agua contaminando el agua helada","El agua entra al sistema de refrigerante porque el evaporador está en vacío","El aceite lubricante se filtra al circuito de agua causando contaminación visible","La presión del evaporador sube inmediatamente hasta igualar la presión del agua"], respuesta_correcta:1, explicacion:"Como el evaporador opera en vacío, si un tubo se perfora, el agua del circuito de agua helada entra al sistema de refrigerante por la diferencia de presión." , question: "What happens when an evaporator tube is punctured in a water-cooled low-pressure chiller?", options: ["Refrigerant leaks into the water circuit, contaminating the chilled water", "Water enters the refrigerant system because the evaporator is under vacuum", "Lubricating oil seeps into the water circuit causing visible contamination", "Evaporator pressure rises immediately to equalize with the water pressure"], explanation: "Since the evaporator operates under vacuum, if a tube is punctured, water from the chilled water circuit enters the refrigerant system due to the pressure difference." },
  { id:"epa608_371", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la consecuencia de que agua entre al circuito de refrigerante de un chiller de baja presión?", opciones:["Mejora la transferencia de calor en el evaporador al añadir masa térmica","Contamina el refrigerante y puede formar ácidos corrosivos dentro del sistema","Aumenta la capacidad de enfriamiento al mezclar agua con el refrigerante líquido","Lubrica mejor los rodamientos del compresor al mezclarse con el aceite mineral"], respuesta_correcta:1, explicacion:"El agua contamina el refrigerante y reacciona con él para formar ácidos (como ácido clorhídrico o fluorhídrico) que corroen los componentes internos del sistema." , question: "What is the consequence of water entering the refrigerant circuit of a low-pressure chiller?", options: ["It improves heat transfer in the evaporator by adding thermal mass", "It contaminates the refrigerant and can form corrosive acids inside the system", "It increases cooling capacity by mixing water with the liquid refrigerant", "It better lubricates the compressor bearings by mixing with the mineral oil"], explanation: "Water contaminates the refrigerant and reacts with it to form acids (such as hydrochloric or hydrofluoric acid) that corrode the internal components of the system." },
  { id:"epa608_372", categoria:"EPA608_TIPO3", pregunta:"¿Por qué un chiller de baja presión requiere una unidad de purga mientras que uno de alta presión no?", opciones:["Porque los chillers de alta presión usan refrigerantes que absorben el aire naturalmente","Porque los chillers de baja presión operan en vacío y aspiran aire por las fugas","Porque los chillers de alta presión tienen sellos herméticos que impiden toda fuga","Porque los chillers de baja presión tienen más conexiones y puntos de fuga potenciales"], respuesta_correcta:1, explicacion:"Los chillers de baja presión operan por debajo de la presión atmosférica, por lo que cualquier fuga permite la entrada de aire. Los de alta presión pierden refrigerante en vez de aspirar aire." , question: "Why does a low-pressure chiller require a purge unit while a high-pressure chiller does not?", options: ["Because high-pressure chillers use refrigerants that naturally absorb air", "Because low-pressure chillers operate under vacuum and draw air in through leaks", "Because high-pressure chillers have hermetic seals that prevent all leakage", "Because low-pressure chillers have more connections and potential leak points"], explanation: "Low-pressure chillers operate below atmospheric pressure, so any leak allows air to enter. High-pressure chillers lose refrigerant instead of drawing in air." },
  { id:"epa608_373", categoria:"EPA608_TIPO3", pregunta:"¿Dónde se conecta típicamente la unidad de purga en un chiller de baja presión?", opciones:["En la parte inferior del evaporador donde se acumula el aceite lubricante usado","En la línea de succión del compresor antes de los álabes guía de entrada","En la parte superior del condensador donde se acumulan los no condensables","En la línea de líquido entre el condensador y el dispositivo de expansión"], respuesta_correcta:2, explicacion:"La unidad de purga se conecta en la parte superior del condensador porque los gases no condensables (aire) son más ligeros y se acumulan en el punto más alto." , question: "Where is the purge unit typically connected on a low-pressure chiller?", options: ["At the bottom of the evaporator where used lubricating oil accumulates", "On the compressor suction line before the inlet guide vanes", "At the top of the condenser where non-condensable gases accumulate", "On the liquid line between the condenser and the expansion device"], explanation: "The purge unit is connected at the top of the condenser because non-condensable gases (air) are lighter and accumulate at the highest point." },
  { id:"epa608_374", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el efecto de los no condensables en el consumo energético de un chiller centrífugo?", opciones:["Reducen el consumo energético al disminuir la carga térmica del condensador","Aumentan significativamente el consumo de energía del compresor centrífugo","No tienen efecto medible en el consumo de energía del equipo en operación","Reducen la corriente del motor al disminuir la presión de descarga del compresor"], respuesta_correcta:1, explicacion:"Los no condensables elevan la presión del condensador, forzando al compresor a trabajar más duro, lo que incrementa significativamente el consumo de energía." , question: "What effect do non-condensable gases have on the energy consumption of a centrifugal chiller?", options: ["They reduce energy consumption by decreasing the condenser thermal load", "They significantly increase the energy consumption of the centrifugal compressor", "They have no measurable effect on the equipment's energy consumption during operation", "They reduce motor current by lowering the compressor discharge pressure"], explanation: "Non-condensable gases raise condenser pressure, forcing the compressor to work harder, which significantly increases energy consumption." },
  { id:"epa608_375", categoria:"EPA608_TIPO3", pregunta:"¿Qué indica un nivel de aceite bajo en el visor del compresor centrífugo de un chiller?", opciones:["Que el aceite se ha acumulado en el evaporador y necesita ser devuelto al cárter","Que el compresor está operando a máxima eficiencia con mínima fricción interna","Que la temperatura del aceite es demasiado alta y el aceite se ha expandido excesivamente","Que el sistema necesita aceite adicional porque se ha consumido durante la operación"], respuesta_correcta:0, explicacion:"Un nivel bajo de aceite generalmente indica que el aceite ha migrado al evaporador u otras partes del sistema y necesita ser devuelto al cárter del compresor." , question: "What does a low oil level in the sight glass of a centrifugal chiller compressor indicate?", options: ["That the oil has accumulated in the evaporator and needs to be returned to the crankcase", "That the compressor is operating at maximum efficiency with minimal internal friction", "That the oil temperature is too high and the oil has expanded excessively", "That the system needs additional oil because it has been consumed during operation"], explanation: "A low oil level generally indicates that the oil has migrated to the evaporator or other parts of the system and needs to be returned to the compressor crankcase." },
  { id:"epa608_376", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el propósito de la válvula de alivio en un recipiente de recuperación usado con refrigerantes de baja presión?", opciones:["Regular la velocidad de recuperación para proteger la bomba del equipo de recuperación","Prevenir que la presión exceda el límite seguro del tanque durante almacenamiento","Permitir el flujo de refrigerante en una sola dirección durante la carga del sistema","Mantener un vacío constante dentro del tanque para facilitar la recuperación inicial"], respuesta_correcta:1, explicacion:"La válvula de alivio protege el tanque de recuperación evitando que la presión interna exceda el límite de diseño seguro, especialmente si la temperatura ambiente sube." , question: "What is the purpose of the relief valve on a recovery cylinder used with low-pressure refrigerants?", options: ["To regulate the recovery speed to protect the recovery equipment pump", "To prevent pressure from exceeding the safe tank limit during storage", "To allow refrigerant flow in only one direction during system charging", "To maintain a constant vacuum inside the tank to facilitate initial recovery"], explanation: "The relief valve protects the recovery tank by preventing internal pressure from exceeding the safe design limit, especially if the ambient temperature rises." },
  { id:"epa608_377", categoria:"EPA608_TIPO3", pregunta:"¿Cuánto refrigerante puede contener un tanque de recuperación como máximo según el código DOT?", opciones:["100% de su capacidad volumétrica para maximizar la eficiencia de recuperación","90% de su capacidad volumétrica para dejar espacio para expansión térmica limitada","80% de su capacidad volumétrica para permitir la expansión térmica del refrigerante","60% de su capacidad volumétrica para cumplir con las regulaciones de transporte"], respuesta_correcta:2, explicacion:"Los tanques de recuperación no deben llenarse más del 80% de su capacidad para permitir la expansión térmica del refrigerante líquido si la temperatura sube." , question: "What is the maximum amount of refrigerant a recovery cylinder can hold according to DOT code?", options: ["100% of its volumetric capacity to maximize recovery efficiency", "90% of its volumetric capacity to leave room for limited thermal expansion", "80% of its volumetric capacity to allow for thermal expansion of the refrigerant", "60% of its volumetric capacity to comply with transportation regulations"], explanation: "Recovery cylinders must not be filled beyond 80% of their capacity to allow for thermal expansion of the liquid refrigerant if the temperature rises." },
  { id:"epa608_378", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de prueba se realiza para verificar la integridad de los tubos del condensador sin removerlos?", opciones:["Prueba de presión hidrostática que requiere drenar completamente el refrigerante del lado","Prueba de corrientes de Eddy que detecta adelgazamiento y corrosión electromagnéticamente","Prueba de ultrasonido que mide el espesor de cada tubo individualmente con precisión","Prueba de tinte penetrante que requiere acceso visual directo a la superficie externa"], respuesta_correcta:1, explicacion:"La prueba de corrientes de Eddy puede realizarse con los tubos instalados, insertando una sonda electromagnética que detecta cambios en el grosor de la pared." , question: "What type of test is performed to verify the integrity of condenser tubes without removing them?", options: ["A hydrostatic pressure test that requires completely draining the refrigerant side", "An eddy current test that detects thinning and corrosion electromagnetically", "An ultrasound test that measures each tube's thickness individually with precision", "A dye penetrant test that requires direct visual access to the outer surface"], explanation: "The eddy current test can be performed with the tubes installed by inserting an electromagnetic probe that detects changes in wall thickness." },
  { id:"epa608_379", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la diferencia principal entre una válvula de flotador de alta presión y una de baja presión en un chiller?", opciones:["La de alta presión regula el nivel en el condensador, la de baja en el evaporador","La de alta presión es más grande físicamente que la de baja presión en todos los casos","La de alta presión usa un motor eléctrico, la de baja presión es completamente mecánica","La de alta presión opera con refrigerante gaseoso, la de baja con refrigerante líquido"], respuesta_correcta:0, explicacion:"La válvula de flotador de alta presión mantiene el nivel en el condensador (lado de alta), mientras la de baja presión mantiene el nivel en el evaporador (lado de baja)." , question: "What is the main difference between a high-side float valve and a low-side float valve in a chiller?", options: ["The high-side float valve regulates the level in the condenser; the low-side float valve regulates the level in the evaporator", "The high-side float valve is physically larger than the low-side float valve in all cases", "The high-side float valve uses an electric motor; the low-side float valve is fully mechanical", "The high-side float valve operates with gaseous refrigerant; the low-side with liquid refrigerant"], explanation: "The high-side float valve maintains the level in the condenser (high side), while the low-side float valve maintains the level in the evaporator (low side)." },
  { id:"epa608_380", categoria:"EPA608_TIPO3", pregunta:"¿Qué debe verificarse antes de arrancar un chiller centrífugo que ha estado fuera de servicio por un período prolongado?", opciones:["Solo la presión de aceite y el nivel de refrigerante visible en el visor lateral","Que el calentador de aceite haya estado operando y el aceite esté a temperatura adecuada","Que todas las válvulas de servicio estén completamente cerradas para máxima seguridad","Que el tanque de recuperación esté conectado para capturar cualquier posible exceso"], respuesta_correcta:1, explicacion:"Antes de arrancar un chiller que estuvo apagado, se debe verificar que el calentador de aceite haya operado suficiente tiempo para evitar que el refrigerante migrado cause espuma." , question: "What should be verified before starting a centrifugal chiller that has been out of service for an extended period?", options: ["Only the oil pressure and the refrigerant level visible in the side sight glass", "That the oil heater has been running and the oil is at the proper temperature", "That all service valves are fully closed for maximum safety", "That the recovery tank is connected to capture any possible excess"], explanation: "Before starting a chiller that has been shut down, it must be verified that the oil heater has been operating long enough to prevent refrigerant migration from causing foaming." },
  { id:"epa608_381", categoria:"EPA608_TIPO3", pregunta:"¿Qué es la formación de espuma en el aceite de un chiller de baja presión?", opciones:["El aceite se mezcla con agua formando una emulsión espumosa que no lubrica correctamente","El refrigerante disuelto en el aceite hierve rápidamente al arrancar el compresor del equipo","El aire atrapado en el aceite crea burbujas permanentes que reducen la viscosidad del aceite","Los aditivos del aceite reaccionan químicamente con el refrigerante produciendo una espuma estable"], respuesta_correcta:1, explicacion:"Cuando el compresor arranca, la caída de presión hace que el refrigerante disuelto en el aceite hierva repentinamente, creando espuma que reduce la capacidad de lubricación." , question: "What is oil foaming in a low-pressure chiller?", options: ["The oil mixes with water forming a foamy emulsion that does not lubricate properly", "The refrigerant dissolved in the oil boils rapidly when the compressor starts", "Trapped air in the oil creates permanent bubbles that reduce oil viscosity", "Oil additives chemically react with the refrigerant producing a stable foam"], explanation: "When the compressor starts, the pressure drop causes the refrigerant dissolved in the oil to boil suddenly, creating foam that reduces lubrication capacity." },
  { id:"epa608_382", categoria:"EPA608_TIPO3", pregunta:"¿Por qué es especialmente importante evitar la formación de espuma en el aceite de un chiller centrífugo?", opciones:["Porque la espuma puede tapar los filtros de aceite, cortando el suministro a los rodamientos","Porque la espuma reduce la capacidad de lubricación y puede dañar los rodamientos del compresor","Porque la espuma aumenta la presión del cárter causando la activación de la protección de alta","Porque la espuma cambia la viscosidad del aceite a un nivel inaceptable permanentemente"], respuesta_correcta:1, explicacion:"La espuma reduce drásticamente la capacidad de lubricación del aceite, lo que puede causar daño catastrófico a los rodamientos del compresor centrífugo de alta velocidad." , question: "Why is it especially important to prevent oil foaming in a centrifugal chiller?", options: ["Because the foam can clog the oil filters, cutting supply to the bearings", "Because the foam reduces lubrication capacity and can damage the compressor bearings", "Because the foam raises crankcase pressure causing the high-pressure protection to trip", "Because the foam permanently changes oil viscosity to an unacceptable level"], explanation: "Foam drastically reduces the oil's lubrication capacity, which can cause catastrophic damage to the high-speed centrifugal compressor bearings." },
  { id:"epa608_383", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el impacto de las incrustaciones biológicas (biofouling) en los tubos del condensador?", opciones:["Mejoran el flujo de agua al crear una superficie más lisa dentro de los tubos","Reducen la transferencia de calor y aumentan la presión del condensador del chiller","No tienen efecto si el sistema de tratamiento de agua está funcionando normalmente","Protegen los tubos de cobre contra la corrosión electrolítica del agua de torre"], respuesta_correcta:1, explicacion:"Las incrustaciones biológicas actúan como aislante térmico, reduciendo la transferencia de calor, lo que eleva la presión del condensador y reduce la eficiencia." , question: "What is the impact of biological fouling (biofouling) on condenser tubes?", options: ["It improves water flow by creating a smoother surface inside the tubes", "It reduces heat transfer and increases the chiller's condenser pressure", "It has no effect if the water treatment system is operating normally", "It protects the copper tubes against electrolytic corrosion from tower water"], explanation: "Biological fouling acts as thermal insulation, reducing heat transfer, which raises condenser pressure and reduces efficiency." },
  { id:"epa608_384", categoria:"EPA608_TIPO3", pregunta:"¿Qué tipo de agua de torre de enfriamiento puede causar mayor daño a los tubos del condensador?", opciones:["Agua blanda con bajo contenido mineral que no forma incrustaciones protectoras","Agua con alto contenido de cloruros que puede causar corrosión por picadura severa","Agua destilada pura que es altamente agresiva contra los metales no ferrosos","Agua con alto pH que tiende a depositar sales de calcio protectoras en los tubos"], respuesta_correcta:1, explicacion:"El agua con alto contenido de cloruros causa corrosión por picadura (pitting) en los tubos de cobre del condensador, lo que puede llevar a perforaciones y fugas." , question: "What type of cooling tower water can cause the most damage to condenser tubes?", options: ["Soft water with low mineral content that does not form protective scale", "Water with high chloride content that can cause severe pitting corrosion", "Pure distilled water that is highly aggressive against non-ferrous metals", "Water with high pH that tends to deposit protective calcium salts on the tubes"], explanation: "Water with high chloride content causes pitting corrosion in the copper condenser tubes, which can lead to perforations and leaks." },
  { id:"epa608_385", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la temperatura típica de agua helada que produce un chiller centrífugo de baja presión?", opciones:["32°F (0°C) justo en el punto de congelación del agua pura sin aditivos","44°F (6.7°C) que es el estándar para la mayoría de sistemas de aire acondicionado","55°F (12.8°C) que es suficiente para deshumidificar pero no para enfriar el aire","65°F (18.3°C) que se usa solo para procesos industriales de baja demanda"], respuesta_correcta:1, explicacion:"La temperatura típica de agua helada es 44°F (6.7°C), que es el estándar de diseño para la mayoría de sistemas de aire acondicionado con chillers en edificios comerciales." , question: "What is the typical chilled water temperature produced by a low-pressure centrifugal chiller?", options: ["32 degrees F (0 degrees C), right at the freezing point of pure water without additives", "44 degrees F (6.7 degrees C), which is the standard for most air conditioning systems", "55 degrees F (12.8 degrees C), which is sufficient for dehumidification but not for cooling air", "65 degrees F (18.3 degrees C), which is used only for low-demand industrial processes"], explanation: "The typical chilled water temperature is 44 degrees F (6.7 degrees C), which is the design standard for most air conditioning systems with chillers in commercial buildings." },
  { id:"epa608_386", categoria:"EPA608_TIPO3", pregunta:"¿Qué se debe hacer si se detecta una concentración peligrosa de R-123 en la sala de máquinas?", opciones:["Cerrar la puerta de la sala para contener el refrigerante y evitar su dispersión","Evacuar inmediatamente la sala y activar los sistemas de ventilación de emergencia","Encender el chiller para que el compresor aspire el refrigerante fugado de vuelta","Rociar agua sobre el área para absorber el vapor de refrigerante que está en el aire"], respuesta_correcta:1, explicacion:"Si se detecta una concentración peligrosa de R-123 (clasificación B1, mayor toxicidad), se debe evacuar inmediatamente y activar la ventilación de emergencia." , question: "What should be done if a dangerous concentration of R-123 is detected in the mechanical room?", options: ["Close the room door to contain the refrigerant and prevent its dispersal", "Evacuate the room immediately and activate the emergency ventilation systems", "Turn on the chiller so the compressor draws the leaked refrigerant back in", "Spray water over the area to absorb the refrigerant vapor in the air"], explanation: "If a dangerous concentration of R-123 (B1 classification, higher toxicity) is detected, the room must be evacuated immediately and emergency ventilation activated." },
  { id:"epa608_387", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el propósito de las válvulas de servicio en un chiller centrífugo de baja presión?", opciones:["Regular la capacidad del compresor durante cambios de carga térmica del edificio","Aislar secciones del sistema para mantenimiento sin perder toda la carga de refrigerante","Controlar la velocidad del flujo de agua a través del condensador enfriado por agua","Prevenir el flujo inverso de refrigerante cuando el compresor se detiene por protección"], respuesta_correcta:1, explicacion:"Las válvulas de servicio permiten aislar secciones del chiller (compresor, condensador, evaporador) para realizar mantenimiento sin necesidad de recuperar todo el refrigerante." , question: "What is the purpose of the service valves on a low-pressure centrifugal chiller?", options: ["To regulate compressor capacity during building thermal load changes", "To isolate sections of the system for maintenance without losing the entire refrigerant charge", "To control the water flow rate through the water-cooled condenser", "To prevent reverse refrigerant flow when the compressor stops on a safety"], explanation: "Service valves allow sections of the chiller (compressor, condenser, evaporator) to be isolated for maintenance without needing to recover all the refrigerant." },
  { id:"epa608_388", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es la presión de condensación típica de un chiller que usa R-123 a condiciones normales?", opciones:["Aproximadamente 150 psig, similar a la de un sistema de R-410A residencial","Aproximadamente 60 psig, similar a la de un sistema de R-22 comercial estándar","Aproximadamente 3 a 8 psig, apenas por encima de la presión atmosférica ambiental","Aproximadamente 30 a 40 psig, en un rango medio de presión para refrigeración"], respuesta_correcta:2, explicacion:"El R-123 tiene presiones de condensación muy bajas, típicamente de 3 a 8 psig, debido a su alto punto de ebullición y características de baja presión." , question: "What is the typical condensing pressure of a chiller using R-123 under normal conditions?", options: ["Approximately 150 psig, similar to a residential R-410A system", "Approximately 60 psig, similar to a standard commercial R-22 system", "Approximately 3 to 8 psig, just above ambient atmospheric pressure", "Approximately 30 to 40 psig, in a mid-range pressure for refrigeration"], explanation: "R-123 has very low condensing pressures, typically 3 to 8 psig, due to its high boiling point and low-pressure characteristics." },
  { id:"epa608_389", categoria:"EPA608_TIPO3", pregunta:"¿Qué precaución se debe tomar al manejar refrigerantes de baja presión que son líquidos a temperatura ambiente?", opciones:["Mantenerlos siempre a temperatura inferior a 32°F para prevenir la evaporación excesiva","Usar equipo de protección personal incluyendo guantes y gafas de seguridad apropiadas","Calentarlos antes de transferirlos para reducir la viscosidad y facilitar el manejo","Almacenarlos siempre en tanques presurizados con nitrógeno para evitar la contaminación"], respuesta_correcta:1, explicacion:"Al manejar refrigerantes como R-11 y R-123, se debe usar equipo de protección personal porque el contacto con la piel puede causar irritación y la inhalación puede ser tóxica." , question: "What precaution should be taken when handling low-pressure refrigerants that are liquid at room temperature?", options: ["Always keep them at temperatures below 32 degrees F to prevent excessive evaporation", "Use personal protective equipment including appropriate safety gloves and goggles", "Heat them before transferring to reduce viscosity and facilitate handling", "Always store them in tanks pressurized with nitrogen to prevent contamination"], explanation: "When handling refrigerants such as R-11 and R-123, personal protective equipment must be used because skin contact can cause irritation and inhalation can be toxic." },
  { id:"epa608_390", categoria:"EPA608_TIPO3", pregunta:"¿Cómo se mide típicamente la tasa de fuga en un chiller de baja presión?", opciones:["Contando el número de burbujas por minuto en la prueba de jabón de las conexiones","Comparando la cantidad de refrigerante añadido con el peso total de la carga original","Midiendo la caída de presión en la línea de líquido durante un período de 24 horas","Calculando la diferencia de temperatura entre la entrada y salida del condensador"], respuesta_correcta:1, explicacion:"La tasa de fuga se calcula dividiendo la cantidad de refrigerante añadido durante el año entre la carga total del sistema, expresándola como porcentaje anual." , question: "How is the leak rate typically measured in a low-pressure chiller?", options: ["By counting the number of bubbles per minute in the soap test of the connections", "By comparing the amount of refrigerant added to the total weight of the original charge", "By measuring the pressure drop in the liquid line over a 24-hour period", "By calculating the temperature difference between the condenser inlet and outlet"], explanation: "The leak rate is calculated by dividing the amount of refrigerant added during the year by the total system charge, expressed as an annual percentage." },
  { id:"epa608_391", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el requisito de certificación EPA para trabajar con sistemas de baja presión?", opciones:["Certificación EPA 608 Tipo I que cubre equipos pequeños y electrodomésticos","Certificación EPA 608 Tipo II que cubre equipos de alta presión y media presión","Certificación EPA 608 Tipo III que cubre específicamente equipos de baja presión","Certificación EPA 608 Universal que es la única que permite trabajo en cualquier tipo"], respuesta_correcta:2, explicacion:"Se requiere certificación EPA 608 Tipo III para trabajar con equipos de baja presión. La certificación Universal también permite trabajar con todos los tipos de equipos." , question: "What EPA certification is required to work on low-pressure systems?", options: ["EPA 608 Type I certification covering small appliances", "EPA 608 Type II certification covering high-pressure and medium-pressure equipment", "EPA 608 Type III certification specifically covering low-pressure equipment", "EPA 608 Universal certification, which is the only one that allows work on any type"], explanation: "EPA 608 Type III certification is required to work on low-pressure equipment. Universal certification also allows work on all equipment types." },
  { id:"epa608_392", categoria:"EPA608_TIPO3", pregunta:"¿Qué sucede con la presión en el evaporador de un chiller de baja presión si el agua helada está demasiado fría?", opciones:["La presión del evaporador baja aún más, pudiendo caer en vacío muy profundo dañino","La presión del evaporador sube porque el refrigerante se condensa más eficientemente","La presión del evaporador se mantiene igual porque es regulada por la válvula de flotador","La presión del evaporador oscila rápidamente entre valores positivos y negativos inestables"], respuesta_correcta:0, explicacion:"Si el agua helada está muy fría, la temperatura del evaporador baja más de lo normal, reduciendo la presión en el evaporador a un vacío más profundo que puede ser problemático." , question: "What happens to the evaporator pressure in a low-pressure chiller if the chilled water is too cold?", options: ["The evaporator pressure drops even further, potentially falling to a harmfully deep vacuum", "The evaporator pressure rises because the refrigerant condenses more efficiently", "The evaporator pressure stays the same because it is regulated by the float valve", "The evaporator pressure fluctuates rapidly between unstable positive and negative values"], explanation: "If the chilled water is too cold, the evaporator temperature drops lower than normal, reducing the evaporator pressure to a deeper vacuum that can be problematic." },
  { id:"epa608_393", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el riesgo principal de operar un chiller de baja presión con el evaporador a temperatura muy baja?", opciones:["El refrigerante puede congelarse dentro de los tubos del evaporador bloqueando el flujo","El agua en los tubos del evaporador puede congelarse causando daño a los tubos internos","El aceite lubricante se solidifica impidiendo la operación del compresor centrífugo","El impulsor del compresor centrífugo se contrae térmicamente y pierde balance rotatorio"], respuesta_correcta:1, explicacion:"Si la temperatura del evaporador baja demasiado, el agua dentro de los tubos puede congelarse, expandirse y romper los tubos del intercambiador de calor." , question: "What is the main risk of operating a low-pressure chiller with the evaporator at a very low temperature?", options: ["The refrigerant can freeze inside the evaporator tubes, blocking flow", "The water in the evaporator tubes can freeze, causing damage to the internal tubes", "The lubricating oil solidifies, preventing operation of the centrifugal compressor", "The centrifugal compressor impeller contracts thermally and loses rotational balance"], explanation: "If the evaporator temperature drops too low, the water inside the tubes can freeze, expand, and rupture the heat exchanger tubes." },
  { id:"epa608_394", categoria:"EPA608_TIPO3", pregunta:"¿Qué protección evita que el agua se congele en el evaporador de un chiller de baja presión?", opciones:["Un sensor de flujo de agua que detiene el chiller si el flujo es insuficiente","Un control de baja temperatura de agua que apaga el chiller antes del punto de congelación","Un calentador eléctrico de respaldo sumergido en el evaporador del sistema completo","Una válvula de tres vías que mezcla agua caliente de retorno con agua helada de salida"], respuesta_correcta:1, explicacion:"El control de baja temperatura del agua de salida detiene el compresor si la temperatura se acerca peligrosamente al punto de congelación para proteger los tubos." , question: "What protection prevents water from freezing in the evaporator of a low-pressure chiller?", options: ["A water flow sensor that stops the chiller if the flow is insufficient", "A low water temperature control that shuts down the chiller before the freezing point", "A backup electric heater submerged in the evaporator of the complete system", "A three-way valve that mixes hot return water with chilled supply water"], explanation: "The low leaving water temperature control stops the compressor if the temperature approaches the freezing point dangerously, protecting the tubes." },
  { id:"epa608_395", categoria:"EPA608_TIPO3", pregunta:"¿Por qué se debe mantener el flujo de agua constante a través del evaporador de un chiller?", opciones:["Para evitar la formación de hielo en los tubos que podría dañarlos permanentemente","Para mantener la presión del agua constante en todo el circuito de distribución","Para proteger la bomba de agua helada contra la cavitación por bajo flujo continuo","Para evitar que el refrigerante se sobrecaliente en la salida del evaporador completo"], respuesta_correcta:0, explicacion:"Mantener un flujo constante de agua previene que el agua se estanque y congele en los tubos del evaporador, lo que causaría su ruptura por expansión del hielo." , question: "Why must constant water flow be maintained through the evaporator of a chiller?", options: ["To prevent ice formation on the tubes that could permanently damage them", "To keep the water pressure constant throughout the entire distribution circuit", "To protect the chilled water pump against cavitation from continuous low flow", "To prevent the refrigerant from superheating at the evaporator outlet"], explanation: "Maintaining constant water flow prevents water from stagnating and freezing in the evaporator tubes, which would cause tube rupture due to ice expansion." },
  { id:"epa608_396", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el procedimiento correcto para transferir refrigerante de baja presión entre tanques?", opciones:["Usar presión de nitrógeno para empujar el líquido del tanque lleno al tanque vacío","Calentar el tanque lleno y enfriar el vacío para crear diferencia de presión de vapor","Bombear con una máquina de recuperación certificada que evita emisiones al ambiente","Simplemente volcar el tanque lleno sobre el vacío aprovechando que es líquido a temperatura"], respuesta_correcta:2, explicacion:"Se debe usar una máquina de recuperación certificada para transferir refrigerante entre tanques, evitando emisiones a la atmósfera según los requisitos de la EPA." , question: "What is the correct procedure for transferring low-pressure refrigerant between tanks?", options: ["Use nitrogen pressure to push the liquid from the full tank to the empty tank", "Heat the full tank and cool the empty one to create a vapor pressure difference", "Pump with a certified recovery machine that prevents emissions to the atmosphere", "Simply pour from the full tank into the empty one since it is liquid at room temperature"], explanation: "A certified recovery machine must be used to transfer refrigerant between tanks, preventing atmospheric emissions as required by the EPA." },
  { id:"epa608_397", categoria:"EPA608_TIPO3", pregunta:"¿Qué indica que la unidad de purga de un chiller de baja presión está funcionando correctamente?", opciones:["Que la presión del condensador es significativamente más alta de lo normal esperado","Que la unidad opera raramente porque mantiene el sistema libre de no condensables","Que la unidad opera continuamente sin parar durante todo el ciclo de enfriamiento","Que la presión del evaporador fluctúa constantemente entre valores positivos y vacío"], respuesta_correcta:1, explicacion:"Una unidad de purga funcionando correctamente en un sistema bien sellado operará con poca frecuencia, indicando que hay pocas fugas y pocos no condensables entrando al sistema." , question: "What indicates that the purge unit of a low-pressure chiller is functioning properly?", options: ["That the condenser pressure is significantly higher than normally expected", "That the unit operates infrequently because it keeps the system free of non-condensable gases", "That the unit operates continuously without stopping throughout the entire cooling cycle", "That the evaporator pressure constantly fluctuates between positive values and vacuum"], explanation: "A properly functioning purge unit in a well-sealed system will operate infrequently, indicating few leaks and few non-condensable gases entering the system." },
  { id:"epa608_398", categoria:"EPA608_TIPO3", pregunta:"¿Cuántas libras de refrigerante debe contener un sistema para que apliquen los requisitos de la EPA sobre fugas?", opciones:["Más de 5 libras de refrigerante de cualquier tipo dentro del sistema completo","Más de 15 libras de refrigerante de cualquier tipo dentro del sistema completo","Más de 50 libras de refrigerante de cualquier tipo dentro del sistema completo","Más de 100 libras de refrigerante de cualquier tipo dentro del sistema completo"], respuesta_correcta:2, explicacion:"Los requisitos de la EPA sobre tasas de fuga y reparación obligatoria aplican a sistemas que contienen más de 50 libras de refrigerante." , question: "How many pounds of refrigerant must a system contain for EPA leak requirements to apply?", options: ["More than 5 pounds of any type of refrigerant within the complete system", "More than 15 pounds of any type of refrigerant within the complete system", "More than 50 pounds of any type of refrigerant within the complete system", "More than 100 pounds of any type of refrigerant within the complete system"], explanation: "EPA leak rate and mandatory repair requirements apply to systems containing more than 50 pounds of refrigerant." },
  { id:"epa608_399", categoria:"EPA608_TIPO3", pregunta:"¿Cuál es el plazo para reparar una fuga que excede la tasa permitida en un sistema de confort con más de 50 libras?", opciones:["7 días calendario desde que se descubre o debió haberse descubierto la fuga","14 días calendario desde que se descubre o debió haberse descubierto la fuga","30 días calendario desde que se descubre o debió haberse descubierto la fuga","90 días calendario desde que se descubre o debió haberse descubierto la fuga"], respuesta_correcta:2, explicacion:"Para sistemas de confort (AC), la EPA requiere que las fugas que excedan la tasa permitida sean reparadas dentro de 30 días de su descubrimiento." , question: "What is the deadline for repairing a leak that exceeds the allowable rate in a comfort cooling system with more than 50 pounds?", options: ["7 calendar days from when the leak is discovered or should have been discovered", "14 calendar days from when the leak is discovered or should have been discovered", "30 calendar days from when the leak is discovered or should have been discovered", "90 calendar days from when the leak is discovered or should have been discovered"], explanation: "For comfort cooling (AC) systems, the EPA requires that leaks exceeding the allowable rate be repaired within 30 days of discovery." },
  { id:"epa608_400", categoria:"EPA608_TIPO3", pregunta:"¿Qué método se recomienda para identificar la ubicación exacta de una fuga en un chiller de baja presión?", opciones:["Presurizar ligeramente con nitrógeno seco y usar detector electrónico o jabón para localizar","Operar el sistema a máxima capacidad y buscar manchas de aceite visibles externamente","Inyectar tinte UV al aceite y revisar con lámpara ultravioleta todas las conexiones externas","Escuchar el silbido de la fuga con estetoscopio industrial en cada junta del sistema"], respuesta_correcta:0, explicacion:"Se presuriza ligeramente con nitrógeno seco (máximo 10 psig) y se usa un detector electrónico de fugas o solución jabonosa para localizar la fuga exacta." , question: "What method is recommended to identify the exact location of a leak in a low-pressure chiller?", options: ["Slightly pressurize with dry nitrogen and use an electronic detector or soap solution to locate it", "Operate the system at maximum capacity and look for visible oil stains externally", "Inject UV dye into the oil and check all external connections with an ultraviolet lamp", "Listen for the hissing sound of the leak with an industrial stethoscope at each system joint"], explanation: "The system is slightly pressurized with dry nitrogen (maximum 10 psig) and an electronic leak detector or soap solution is used to pinpoint the exact leak location." },

  // ── UNIVERSAL (401-500) ──────────────────────────────────────────
  { id:"epa608_401", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la multa máxima por día que la EPA puede imponer por cada violación a las regulaciones de refrigerantes?", opciones:["Hasta $27,500 por violación por día","Hasta $37,500 por violación por día","Hasta $44,539 por violación por día","Hasta $50,000 por violación por día"], respuesta_correcta:2, explicacion:"La EPA puede imponer multas civiles de hasta $44,539 por violación por día bajo la Sección 113 del Clean Air Act." , question: "What is the maximum fine per day that the EPA can impose for each violation of refrigerant regulations?", options: ["Up to $27,500 per violation per day", "Up to $37,500 per violation per day", "Up to $44,539 per violation per day", "Up to $50,000 per violation per day"], explanation: "The EPA can impose civil fines of up to $44,539 per violation per day under Section 113 of the Clean Air Act." },
  { id:"epa608_402", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué certificación EPA 608 se requiere para comprar refrigerante en cilindros de más de 2 libras?", opciones:["Certificación Tipo I como mínimo","Certificación Tipo II como mínimo","Certificación Tipo III como mínimo","Cualquier nivel de certificación 608"], respuesta_correcta:3, explicacion:"Desde 2018, se requiere poseer cualquier nivel de certificación EPA 608 (Tipo I, II, III o Universal) para comprar refrigerante en cilindros mayores a 2 libras." , question: "What EPA 608 certification is required to purchase refrigerant in cylinders larger than 2 pounds?", options: ["Type I certification at a minimum", "Type II certification at a minimum", "Type III certification at a minimum", "Any level of Section 608 certification"], explanation: "Since 2018, any level of EPA 608 certification (Type I, II, III, or Universal) is required to purchase refrigerant in cylinders larger than 2 pounds." },
  { id:"epa608_403", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el potencial de calentamiento global (GWP) del refrigerante R-404A?", opciones:["GWP de 2088 veces el CO₂","GWP de 3922 veces el CO₂","GWP de 1430 veces el CO₂","GWP de 1774 veces el CO₂"], respuesta_correcta:1, explicacion:"El R-404A tiene un GWP de 3922, uno de los más altos entre los refrigerantes HFC comerciales, por eso es prioridad en la reducción gradual." , question: "What is the Global Warming Potential (GWP) of the refrigerant R-404A?", options: ["GWP of 2,088 times that of CO2", "GWP of 3,922 times that of CO2", "GWP of 1,430 times that of CO2", "GWP of 1,774 times that of CO2"], explanation: "R-404A has a GWP of 3,922, one of the highest among commercial HFC refrigerants, which is why it is a priority in the phasedown." },
  { id:"epa608_404", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cada cuántos años se debe realizar la prueba hidrostática a los cilindros de recuperación según el DOT?", opciones:["Cada 3 años desde su fabricación","Cada 5 años desde su fabricación","Cada 7 años desde su fabricación","Cada 10 años desde su fabricación"], respuesta_correcta:1, explicacion:"El DOT requiere que los cilindros de recuperación sean sometidos a prueba hidrostática cada 5 años para verificar su integridad estructural." , question: "How often must recovery cylinders undergo hydrostatic testing according to the DOT?", options: ["Every 3 years from the date of manufacture", "Every 5 years from the date of manufacture", "Every 7 years from the date of manufacture", "Every 10 years from the date of manufacture"], explanation: "The DOT requires that recovery cylinders undergo hydrostatic testing every 5 years to verify their structural integrity." },
  { id:"epa608_405", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué porcentaje máximo de su capacidad puede llenarse un cilindro de recuperación de refrigerante?", opciones:["70% de su capacidad total en peso","75% de su capacidad total en peso","80% de su capacidad total en peso","85% de su capacidad total en peso"], respuesta_correcta:2, explicacion:"La regla del 80% del DOT prohíbe llenar cilindros de recuperación más allá del 80% de su capacidad en peso para permitir la expansión térmica segura." , question: "What is the maximum percentage of capacity to which a refrigerant recovery cylinder can be filled?", options: ["70% of its total capacity by weight", "75% of its total capacity by weight", "80% of its total capacity by weight", "85% of its total capacity by weight"], explanation: "The DOT 80% rule prohibits filling recovery cylinders beyond 80% of their capacity by weight to allow for safe thermal expansion." },
  { id:"epa608_406", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué ley federal de EE.UU. establece la reducción gradual de los refrigerantes HFC?", opciones:["El Protocolo de Montreal de 1987","La Sección 608 del Clean Air Act","La AIM Act de 2020 (American Innovation)","La Enmienda de Kigali al Protocolo"], respuesta_correcta:2, explicacion:"La AIM Act (American Innovation and Manufacturing Act) de 2020 otorga a la EPA autoridad para reducir gradualmente la producción y consumo de HFCs en EE.UU." , question: "What U.S. federal law establishes the phasedown of HFC refrigerants?", options: ["The Montreal Protocol of 1987", "Section 608 of the Clean Air Act", "The AIM Act of 2020 (American Innovation and Manufacturing)", "The Kigali Amendment to the Protocol"], explanation: "The AIM Act (American Innovation and Manufacturing Act) of 2020 grants the EPA authority to gradually phase down the production and consumption of HFCs in the U.S." },
  { id:"epa608_407", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la recompensa máxima que puede recibir un denunciante por reportar violaciones de regulaciones de refrigerantes?", opciones:["Hasta $5,000 por información válida","Hasta $10,000 por información válida","Hasta $15,000 por información válida","Hasta $25,000 por información válida"], respuesta_correcta:1, explicacion:"La EPA ofrece recompensas de hasta $10,000 a personas que proporcionen información que conduzca a sanciones por violaciones de la Sección 608." , question: "What is the maximum reward a whistleblower can receive for reporting violations of refrigerant regulations?", options: ["Up to $5,000 for valid information", "Up to $10,000 for valid information", "Up to $15,000 for valid information", "Up to $25,000 for valid information"], explanation: "The EPA offers rewards of up to $10,000 to individuals who provide information leading to penalties for violations of Section 608." },
  { id:"epa608_408", categoria:"EPA608_UNIVERSAL", pregunta:"¿En qué año se prohibió completamente la producción e importación de R-22 nuevo en Estados Unidos?", opciones:["Se prohibió a partir del año 2015","Se prohibió a partir del año 2020","Se prohibió a partir del año 2025","Se prohibió a partir del año 2030"], respuesta_correcta:1, explicacion:"La producción e importación de R-22 nuevo se prohibió el 1 de enero de 2020. Solo se permite R-22 reciclado o recuperado para servicio de equipos existentes." , question: "In what year was the production and importation of new R-22 completely banned in the United States?", options: ["It was banned starting in 2015", "It was banned starting in 2020", "It was banned starting in 2025", "It was banned starting in 2030"], explanation: "The production and importation of new R-22 was banned on January 1, 2020. Only recycled or reclaimed R-22 is permitted for servicing existing equipment." },
  { id:"epa608_409", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el estándar de pureza que debe cumplir el refrigerante reclamado antes de ser revendido?", opciones:["Estándar EPA 700 de pureza mínima","Estándar ARI 700 de pureza mínima","Estándar ASHRAE 34 de clasificación","Estándar DOT 39 de especificación"], respuesta_correcta:1, explicacion:"El estándar ARI 700 (ahora AHRI 700) establece los niveles de pureza que debe cumplir el refrigerante reclamado, equivalente a producto virgen nuevo." , question: "What purity standard must reclaimed refrigerant meet before it can be resold?", options: ["EPA 700 minimum purity standard", "ARI 700 minimum purity standard", "ASHRAE 34 classification standard", "DOT 39 specification standard"], explanation: "The ARI 700 standard (now AHRI 700) establishes the purity levels that reclaimed refrigerant must meet, equivalent to virgin new product." },
  { id:"epa608_410", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la diferencia principal entre recuperación y reciclaje de refrigerante?", opciones:["Recuperación limpia el refrigerante; reciclaje solo lo almacena en cilindros","Recuperación lo retira del sistema; reciclaje lo limpia para reutilizar","Recuperación requiere laboratorio; reciclaje se hace en campo sin equipo","Recuperación es para CFC solamente; reciclaje es para HFC solamente"], respuesta_correcta:1, explicacion:"Recuperación es retirar el refrigerante del sistema y almacenarlo. Reciclaje es limpiar el refrigerante (filtrar, separar aceite/humedad) para reutilizarlo." , question: "What is the main difference between refrigerant recovery and recycling?", options: ["Recovery cleans the refrigerant; recycling only stores it in cylinders", "Recovery removes it from the system; recycling cleans it for reuse", "Recovery requires a laboratory; recycling is done in the field without equipment", "Recovery is for CFCs only; recycling is for HFCs only"], explanation: "Recovery is the removal of refrigerant from a system and storing it. Recycling is cleaning the refrigerant (filtering, separating oil/moisture) for reuse." },
  { id:"epa608_411", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de aceite lubricante es compatible con los refrigerantes HFC como R-410A?", opciones:["Aceite mineral es el indicado para HFCs","Aceite PAG es el indicado para los HFCs","Aceite POE (polioléster) es el indicado","Aceite alquilbenceno para refrigerantes HFC"], respuesta_correcta:2, explicacion:"Los refrigerantes HFC como R-410A requieren aceite POE (polioléster) porque los aceites minerales no son miscibles con los HFC." , question: "What type of lubricating oil is compatible with HFC refrigerants such as R-410A?", options: ["Mineral oil is the appropriate choice for HFCs", "PAG oil is the appropriate choice for HFCs", "POE (polyol ester) oil is the appropriate choice", "Alkylbenzene oil for HFC refrigerants"], explanation: "HFC refrigerants such as R-410A require POE (polyol ester) oil because mineral oils are not miscible with HFCs." },
  { id:"epa608_412", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué debe hacerse con refrigerante recuperado que está contaminado con mezcla de diferentes tipos?", opciones:["Filtrarlo y reciclarlo en campo para uso inmediato","Mezclarlo con refrigerante virgen para diluir la contaminación","Enviarlo a un reclamador certificado por la EPA para procesamiento","Ventilarlo al ambiente si la cantidad es menor a cinco libras"], respuesta_correcta:2, explicacion:"El refrigerante contaminado con mezcla de tipos no puede reciclarse en campo; debe enviarse a un reclamador certificado por la EPA para su procesamiento." , question: "What should be done with recovered refrigerant that is contaminated with a mixture of different types?", options: ["Filter it and recycle it in the field for immediate use", "Mix it with virgin refrigerant to dilute the contamination", "Send it to an EPA-certified reclaimer for processing", "Vent it to the atmosphere if the amount is less than five pounds"], explanation: "Refrigerant contaminated with mixed types cannot be recycled in the field; it must be sent to an EPA-certified reclaimer for processing." },
  { id:"epa608_413", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el GWP (potencial de calentamiento global) del refrigerante R-410A?", opciones:["GWP de 675 veces el del CO₂","GWP de 1430 veces el del CO₂","GWP de 2088 veces el del CO₂","GWP de 3922 veces el del CO₂"], respuesta_correcta:2, explicacion:"El R-410A tiene un GWP de 2088, significativamente más alto que sus reemplazos propuestos como R-32 (675) o R-454B (466)." , question: "What is the GWP (Global Warming Potential) of the refrigerant R-410A?", options: ["GWP of 675 times that of CO2", "GWP of 1,430 times that of CO2", "GWP of 2,088 times that of CO2", "GWP of 3,922 times that of CO2"], explanation: "R-410A has a GWP of 2,088, significantly higher than its proposed replacements such as R-32 (675) or R-454B (466)." },
  { id:"epa608_414", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué refrigerante tiene un ODP (potencial de destrucción del ozono) de cero y un GWP menor a 1?", opciones:["R-134a con ODP cero y GWP menor a uno","R-32 con ODP de cero y GWP menor a uno","R-1234yf con ODP cero y GWP menor a uno","R-454B con ODP cero y GWP menor a uno"], respuesta_correcta:2, explicacion:"El R-1234yf es un HFO con ODP de 0 y GWP menor a 1, diseñado como reemplazo del R-134a en sistemas automotrices." , question: "What refrigerant has an ODP (Ozone Depletion Potential) of zero and a GWP of less than 1?", options: ["R-134a with zero ODP and GWP less than one", "R-32 with zero ODP and GWP less than one", "R-1234yf with zero ODP and GWP less than one", "R-454B with zero ODP and GWP less than one"], explanation: "R-1234yf is an HFO with an ODP of 0 and a GWP of less than 1, designed as a replacement for R-134a in automotive systems." },
  { id:"epa608_415", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuándo se completó la eliminación total de la producción de refrigerantes CFC en Estados Unidos?", opciones:["La producción de CFCs cesó en el año 1992","La producción de CFCs cesó en el año 1996","La producción de CFCs cesó en el año 2000","La producción de CFCs cesó en el año 2010"], respuesta_correcta:1, explicacion:"La producción de CFCs (como R-12, R-11, R-502) se eliminó completamente en 1996 bajo el Protocolo de Montreal debido a su alto ODP." , question: "When was the total phase-out of CFC refrigerant production completed in the United States?", options: ["CFC production ceased in 1992", "CFC production ceased in 1996", "CFC production ceased in 2000", "CFC production ceased in 2010"], explanation: "CFC production (such as R-12, R-11, R-502) was completely eliminated in 1996 under the Montreal Protocol due to their high ODP." },
  { id:"epa608_416", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué equipo de protección se debe usar si hay una liberación grande de refrigerante en un espacio cerrado?", opciones:["Máscara con filtro de carbón activado estándar","Aparato de respiración autónomo SCBA completo","Guantes de nitrilo y gafas de protección","Respirador de media cara con cartucho químico"], respuesta_correcta:1, explicacion:"En liberaciones grandes de refrigerante se debe usar SCBA (Self-Contained Breathing Apparatus) porque los refrigerantes desplazan el oxígeno y los filtros no protegen contra asfixia." , question: "What protective equipment should be used if there is a large release of refrigerant in an enclosed space?", options: ["A standard activated carbon filter mask", "A self-contained breathing apparatus (SCBA)", "Nitrile gloves and safety goggles", "A half-face respirator with a chemical cartridge"], explanation: "In large refrigerant releases, an SCBA (Self-Contained Breathing Apparatus) must be used because refrigerants displace oxygen and filters do not protect against asphyxiation." },
  { id:"epa608_417", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué los refrigerantes representan un peligro de asfixia en espacios cerrados?", opciones:["Porque son tóxicos y atacan directamente los pulmones","Porque desplazan el oxígeno al ser más pesados que el aire","Porque reaccionan con el CO₂ formando gases muy tóxicos","Porque elevan la temperatura del espacio extremadamente"], respuesta_correcta:1, explicacion:"La mayoría de los refrigerantes son más pesados que el aire y se acumulan en zonas bajas, desplazando el oxígeno y creando riesgo de asfixia." , question: "Why do refrigerants pose an asphyxiation hazard in enclosed spaces?", options: ["Because they are toxic and directly attack the lungs", "Because they displace oxygen since they are heavier than air", "Because they react with CO2 forming highly toxic gases", "Because they raise the space temperature extremely"], explanation: "Most refrigerants are heavier than air and accumulate in low areas, displacing oxygen and creating a risk of asphyxiation." },
  { id:"epa608_418", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la principal ventaja del R-32 sobre el R-410A como refrigerante?", opciones:["El R-32 opera a presiones mucho más bajas que el 410A","El R-32 tiene un GWP de 675 versus 2088 del R-410A","El R-32 no es inflamable a diferencia del R-410A actual","El R-32 es compatible con aceite mineral a diferencia del 410A"], respuesta_correcta:1, explicacion:"El R-32 tiene un GWP de 675, aproximadamente un tercio del GWP del R-410A (2088), lo que lo hace más favorable ambientalmente bajo la AIM Act." , question: "What is the main advantage of R-32 over R-410A as a refrigerant?", options: ["R-32 operates at much lower pressures than R-410A", "R-32 has a GWP of 675 versus 2,088 for R-410A", "R-32 is not flammable unlike the current R-410A", "R-32 is compatible with mineral oil unlike R-410A"], explanation: "R-32 has a GWP of 675, approximately one-third of the GWP of R-410A (2,088), making it more environmentally favorable under the AIM Act." },
  { id:"epa608_419", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué se debe verificar PRIMERO antes de usar un cilindro de recuperación para almacenar refrigerante?", opciones:["Que el cilindro tenga la etiqueta del tipo de refrigerante anterior","Que la fecha de prueba hidrostática DOT esté vigente y sea válida","Que el cilindro esté completamente vacío sin rastros de residuos","Que el cilindro sea del color correcto según el tipo de refrigerante"], respuesta_correcta:1, explicacion:"Antes de usar un cilindro de recuperación se debe verificar que la prueba hidrostática DOT esté vigente (cada 5 años) para garantizar seguridad." , question: "What must be verified FIRST before using a recovery cylinder to store refrigerant?", options: ["That the cylinder has the label for the previous type of refrigerant", "That the DOT hydrostatic test date is current and valid", "That the cylinder is completely empty with no trace of residue", "That the cylinder is the correct color for the refrigerant type"], explanation: "Before using a recovery cylinder, the DOT hydrostatic test date must be verified as current (every 5 years) to ensure safety." },
  { id:"epa608_420", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de aceite lubricante se usa en sistemas automotrices con R-134a?", opciones:["Aceite mineral convencional de refrigeración","Aceite POE (polioléster) sintético industrial","Aceite PAG (polialquilenglicol) automotriz","Aceite PVE (polivinil éter) de nueva generación"], respuesta_correcta:2, explicacion:"Los sistemas automotrices con R-134a utilizan aceite PAG (polialquilenglicol), que es específico para aplicaciones de aire acondicionado vehicular." , question: "What type of lubricating oil is used in automotive systems with R-134a?", options: ["Conventional mineral refrigeration oil", "Synthetic industrial POE (polyol ester) oil", "Automotive PAG (polyalkylene glycol) oil", "New-generation PVE (polyvinyl ether) oil"], explanation: "Automotive systems with R-134a use PAG (polyalkylene glycol) oil, which is specific to vehicle air conditioning applications." },
  { id:"epa608_421", categoria:"EPA608_UNIVERSAL", pregunta:"¿La certificación EPA 608 tiene fecha de vencimiento o debe renovarse periódicamente?", opciones:["Se renueva cada 3 años con examen actualizado","Se renueva cada 5 años con curso de actualización","Es permanente y no tiene fecha de vencimiento","Expira a los 10 años y requiere recertificación"], respuesta_correcta:2, explicacion:"La certificación EPA 608 es permanente y no expira. Una vez aprobado el examen, la certificación es válida de por vida sin necesidad de renovación." , question: "Does EPA 608 certification have an expiration date or must it be renewed periodically?", options: ["It is renewed every 3 years with an updated exam", "It is renewed every 5 years with a refresher course", "It is permanent and does not have an expiration date", "It expires after 10 years and requires recertification"], explanation: "EPA 608 certification is permanent and does not expire. Once the exam is passed, the certification is valid for life without the need for renewal." },
  { id:"epa608_422", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué organización debe aprobar los programas de examen para la certificación EPA 608?", opciones:["La OSHA debe aprobar cada centro de examen","La EPA debe aprobar las organizaciones de prueba","El DOT debe certificar los centros de evaluación","La ASHRAE debe validar cada programa de examen"], respuesta_correcta:1, explicacion:"La EPA aprueba las organizaciones de prueba (testing organizations) que administran los exámenes de certificación de la Sección 608." , question: "What organization must approve the examination programs for EPA 608 certification?", options: ["OSHA must approve each examination center", "The EPA must approve the testing organizations", "The DOT must certify the evaluation centers", "ASHRAE must validate each examination program"], explanation: "The EPA approves the testing organizations that administer the Section 608 certification exams." },
  { id:"epa608_423", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué gas se debe usar para presurizar un sistema de refrigeración durante una prueba de fugas?", opciones:["Oxígeno seco comprimido a alta presión","Nitrógeno seco libre de humedad y oxígeno","Aire comprimido filtrado con desecante incluido","Dióxido de carbono grado industrial de alta pureza"], respuesta_correcta:1, explicacion:"Se debe usar nitrógeno seco para pruebas de presión. Nunca oxígeno (riesgo de explosión), ni aire comprimido (contiene humedad), ni CO₂ (forma ácido)." , question: "What gas should be used to pressurize a refrigeration system during a leak test?", options: ["Dry compressed oxygen at high pressure", "Dry nitrogen free of moisture and oxygen", "Filtered compressed air with desiccant included", "High-purity industrial-grade carbon dioxide"], explanation: "Dry nitrogen must be used for pressure tests. Never use oxygen (explosion risk), compressed air (contains moisture), or CO2 (forms acid)." },
  { id:"epa608_424", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la definición correcta de 'reclamación' de refrigerante según la EPA?", opciones:["Retirar el refrigerante del sistema y almacenarlo en un cilindro aprobado","Limpiar el refrigerante en campo usando filtros y separación de aceite","Reprocesar refrigerante a nivel de pureza de producto virgen (ARI 700)","Reutilizar el refrigerante en el mismo equipo sin ningún procesamiento"], respuesta_correcta:2, explicacion:"Reclamación es reprocesar refrigerante usado para que cumpla la pureza de producto nuevo según ARI 700. Solo puede hacerse en instalaciones certificadas por la EPA." , question: "What is the correct EPA definition of refrigerant 'reclamation'?", options: ["Removing the refrigerant from the system and storing it in an approved cylinder", "Cleaning the refrigerant in the field using filters and oil separation", "Reprocessing refrigerant to virgin product purity level (ARI 700)", "Reusing the refrigerant in the same equipment without any processing"], explanation: "Reclamation is reprocessing used refrigerant to meet new product purity per ARI 700. It can only be done at EPA-certified facilities." },
  { id:"epa608_425", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el GWP del refrigerante R-454B comparado con el R-410A?", opciones:["R-454B tiene GWP de 466 vs 2088 del R-410A","R-454B tiene GWP de 675 vs 2088 del R-410A","R-454B tiene GWP de 750 vs 2088 del R-410A","R-454B tiene GWP de 148 vs 2088 del R-410A"], respuesta_correcta:0, explicacion:"El R-454B tiene un GWP de 466, aproximadamente un 78% menor que el R-410A (2088), siendo uno de los principales reemplazos propuestos bajo la AIM Act." , question: "What is the GWP of the refrigerant R-454B compared to R-410A?", options: ["R-454B has a GWP of 466 vs. 2,088 for R-410A", "R-454B has a GWP of 675 vs. 2,088 for R-410A", "R-454B has a GWP of 750 vs. 2,088 for R-410A", "R-454B has a GWP of 148 vs. 2,088 for R-410A"], explanation: "R-454B has a GWP of 466, approximately 78% lower than R-410A (2,088), making it one of the leading proposed replacements under the AIM Act." },
  { id:"epa608_426", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué método de detección de fugas puede localizar fugas muy pequeñas que otros métodos no detectan?", opciones:["Detector electrónico de fugas portátil estándar","Solución de burbujas de jabón aplicada en las juntas","Tinte fluorescente ultravioleta inyectado al sistema","Detector de presión diferencial con manómetro digital"], respuesta_correcta:2, explicacion:"El tinte fluorescente UV puede detectar fugas muy pequeñas que otros métodos no logran encontrar, ya que se acumula visiblemente en el punto de fuga bajo luz UV." , question: "What leak detection method can locate very small leaks that other methods cannot detect?", options: ["Standard portable electronic leak detector", "Standard high-frequency ultrasonic detector", "Fluorescent UV dye injected into the system", "Differential pressure detector with a digital gauge"], explanation: "Fluorescent UV dye can detect very small leaks that other methods cannot find, as it visibly accumulates at the leak point under UV light." },
  { id:"epa608_427", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué indica la presencia de ácido en el aceite de un sistema de refrigeración?", opciones:["Que el sistema tiene exceso de refrigerante cargado","Que hubo descomposición del refrigerante por humedad y calor","Que el aceite lubricante es del tipo incorrecto para el sistema","Que las tuberías tienen residuos de soldadura con fundente"], respuesta_correcta:1, explicacion:"La presencia de ácido indica que el refrigerante se descompuso, generalmente por humedad en el sistema combinada con altas temperaturas, formando ácidos corrosivos." , question: "What does the presence of acid in a refrigeration system's oil indicate?", options: ["That the system has been overcharged with refrigerant", "That the refrigerant has decomposed due to moisture and heat", "That the lubricating oil is the wrong type for the system", "That the piping has soldering flux residue"], explanation: "The presence of acid indicates that the refrigerant has decomposed, generally due to moisture in the system combined with high temperatures, forming corrosive acids." },
  { id:"epa608_428", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué es importante evacuar un sistema de refrigeración antes de cargarlo con refrigerante?", opciones:["Para eliminar la presión residual del refrigerante anterior en el circuito","Para remover humedad y gases no condensables que causan problemas","Para verificar que el compresor funcione correctamente sin carga alguna","Para calibrar los manómetros del manifold con referencia al vacío total"], respuesta_correcta:1, explicacion:"La evacuación remueve humedad y gases no condensables del sistema. La humedad causa formación de ácidos y los no condensables elevan las presiones de operación." , question: "Why is it important to evacuate a refrigeration system before charging it with refrigerant?", options: ["To eliminate residual pressure from the previous refrigerant in the circuit", "To remove moisture and non-condensable gases that cause problems", "To verify that the compressor functions correctly without any charge", "To calibrate the manifold gauges with a total vacuum reference"], explanation: "Evacuation removes moisture and non-condensable gases from the system. Moisture causes acid formation and non-condensable gases raise operating pressures." },
  { id:"epa608_429", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué es un 'service aperture' (apertura de servicio) en un sistema de refrigeración?", opciones:["La válvula de alivio de presión del lado de alta del sistema","El puerto de acceso para conectar equipos de servicio al sistema","La mirilla de inspección de nivel de refrigerante del recibidor","El orificio del dispositivo de expansión del evaporador del sistema"], respuesta_correcta:1, explicacion:"Un service aperture es cualquier punto del sistema diseñado para conectar equipos de servicio como mangueras, manifolds o equipos de recuperación." , question: "What is a 'service aperture' in a refrigeration system?", options: ["The high-side pressure relief valve of the system", "The access port for connecting service equipment to the system", "The refrigerant level inspection sight glass on the receiver", "The orifice of the system evaporator's expansion device"], explanation: "A service aperture is any point on the system designed for connecting service equipment such as hoses, manifolds, or recovery equipment." },
  { id:"epa608_430", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la diferencia entre equipo de recuperación 'system-dependent' y 'self-contained'?", opciones:["System-dependent usa su propio compresor; self-contained depende del sistema","System-dependent depende del compresor del sistema; self-contained tiene el suyo","System-dependent es para sistemas pequeños; self-contained solo para grandes","System-dependent funciona con vacío; self-contained funciona con presión positiva"], respuesta_correcta:1, explicacion:"El equipo system-dependent depende del compresor del sistema o de la presión interna para mover el refrigerante. El self-contained tiene su propio compresor." , question: "What is the difference between 'system-dependent' and 'self-contained' recovery equipment?", options: ["System-dependent uses its own compressor; self-contained relies on the system", "System-dependent relies on the system's compressor; self-contained has its own", "System-dependent is for small systems; self-contained is only for large ones", "System-dependent works with vacuum; self-contained works with positive pressure"], explanation: "System-dependent equipment relies on the system's compressor or internal pressure to move the refrigerant. Self-contained equipment has its own compressor." },
  { id:"epa608_431", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué color tienen los cilindros de recuperación aprobados por el DOT según la norma actual?", opciones:["Amarillo completo con franja negra en la parte superior","Verde con etiqueta blanca indicando el tipo de refrigerante","Gris en el cuerpo con la parte superior de color amarillo","Azul con franja roja y etiqueta DOT de identificación visible"], respuesta_correcta:2, explicacion:"Los cilindros de recuperación DOT aprobados son de color gris en el cuerpo con la parte superior amarilla, lo que los identifica como cilindros de recuperación." , question: "What color are DOT-approved recovery cylinders according to the current standard?", options: ["Completely yellow with a black stripe on the top", "Green with a white label indicating the type of refrigerant", "Gray body with a yellow top", "Blue with a red stripe and a visible DOT identification label"], explanation: "DOT-approved recovery cylinders have a gray body with a yellow top, which identifies them as recovery cylinders." },
  { id:"epa608_432", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué sucede cuando se mezclan refrigerantes de diferentes tipos en un mismo sistema?", opciones:["Se forman nuevos compuestos químicos de alta toxicidad inmediata","Las presiones operativas cambian de forma impredecible y peligrosa","El aceite lubricante se solidifica e impide el retorno al compresor","El evaporador se congela completamente deteniendo toda operación"], respuesta_correcta:1, explicacion:"Mezclar refrigerantes altera las propiedades termodinámicas, causando presiones y temperaturas impredecibles, reducción de eficiencia y posible daño al compresor." , question: "What happens when different types of refrigerant are mixed in the same system?", options: ["New chemical compounds of high immediate toxicity are formed", "Operating pressures change unpredictably and dangerously", "The lubricating oil solidifies and prevents oil return to the compressor", "The evaporator freezes completely, stopping all operation"], explanation: "Mixing refrigerants alters the thermodynamic properties, causing unpredictable pressures and temperatures, reduced efficiency, and possible compressor damage." },
  { id:"epa608_433", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de penalidades adicionales puede imponer la EPA además de multas civiles?", opciones:["Solo multas administrativas menores según el caso específico","Penalidades criminales incluyendo prisión para violaciones intencionales","Suspensión temporal de licencia comercial del negocio únicamente","Restricción de compra de equipos de refrigeración por un período"], respuesta_correcta:1, explicacion:"La EPA puede imponer penalidades criminales incluyendo multas penales y prisión para violaciones intencionales del Clean Air Act en materia de refrigerantes." , question: "What additional penalties can the EPA impose besides civil fines?", options: ["Only minor administrative fines depending on the specific case", "Criminal penalties including imprisonment for willful violations", "Temporary suspension of the business's commercial license only", "Restriction on purchasing refrigeration equipment for a period"], explanation: "The EPA can impose criminal penalties including criminal fines and imprisonment for willful violations of the Clean Air Act regarding refrigerants." },
  { id:"epa608_434", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el propósito de una prueba de vacío sostenido (standing vacuum test)?", opciones:["Verificar que la bomba de vacío funcione a su máxima capacidad operativa","Confirmar que el sistema mantiene el vacío sin fugas ni contaminación","Determinar la cantidad exacta de refrigerante necesaria para la carga","Calibrar el vacuómetro digital antes de realizar la evacuación final"], respuesta_correcta:1, explicacion:"La prueba de vacío sostenido verifica que el sistema no pierde vacío, lo que confirma la ausencia de fugas y que se eliminó la humedad adecuadamente." , question: "What is the purpose of a standing vacuum test?", options: ["To verify that the vacuum pump is functioning at its maximum operating capacity", "To confirm that the system holds vacuum without leaks or contamination", "To determine the exact amount of refrigerant needed for the charge", "To calibrate the digital vacuum gauge before performing the final evacuation"], explanation: "The standing vacuum test verifies that the system does not lose vacuum, confirming the absence of leaks and that moisture has been adequately removed." },
  { id:"epa608_435", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué refrigerante HCFC fue el más utilizado en sistemas de aire acondicionado residencial antes de su eliminación?", opciones:["El R-123 fue el HCFC más común en sistemas residenciales","El R-22 fue el HCFC más común en sistemas residenciales","El R-141b fue el HCFC más común en sistemas residenciales","El R-124 fue el HCFC más común en sistemas residenciales"], respuesta_correcta:1, explicacion:"El R-22 fue el refrigerante HCFC dominante en aire acondicionado residencial durante décadas hasta su prohibición de producción en 2020." , question: "What HCFC refrigerant was the most widely used in residential air conditioning systems before its phase-out?", options: ["R-123 was the most common HCFC in residential systems", "R-22 was the most common HCFC in residential systems", "R-141b was the most common HCFC in residential systems", "R-124 was the most common HCFC in residential systems"], explanation: "R-22 was the dominant HCFC refrigerant in residential air conditioning for decades until its production was banned in 2020." },
  { id:"epa608_436", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué sucede si un técnico ventila intencionalmente refrigerante a la atmósfera?", opciones:["Recibe una advertencia escrita y debe tomar un curso de actualización","Solo pierde su certificación EPA 608 temporalmente por seis meses","Puede enfrentar multas de hasta $44,539 por día y cargos criminales","Debe pagar una tarifa de remediación ambiental fija de $5,000 totales"], respuesta_correcta:2, explicacion:"La ventilación intencional de refrigerante viola la Sección 608 y puede resultar en multas civiles de hasta $44,539 por día por violación y cargos criminales." , question: "What happens if a technician intentionally vents refrigerant to the atmosphere?", options: ["They receive a written warning and must take a refresher course", "They only lose their EPA 608 certification temporarily for six months", "They can face fines of up to $44,539 per day and criminal charges", "They must pay a fixed environmental remediation fee of $5,000 total"], explanation: "Intentional venting of refrigerant violates Section 608 and can result in civil fines of up to $44,539 per day per violation and criminal charges." },
  { id:"epa608_437", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué gases no condensables causan problemas cuando están presentes en un sistema de refrigeración?", opciones:["Nitrógeno y oxígeno que elevan la presión del lado de baja presión","Aire y humedad que elevan las presiones del lado de alta del sistema","Hidrógeno y helio que reducen la capacidad del condensador del equipo","Argón y neón que interfieren con el flujo del refrigerante en tuberías"], respuesta_correcta:1, explicacion:"El aire y la humedad son los no condensables más comunes. El aire eleva las presiones del lado de alta y la humedad forma ácidos que dañan el sistema." , question: "What non-condensable gases cause problems when present in a refrigeration system?", options: ["Nitrogen and oxygen, which raise the low-side pressure", "Air and moisture, which raise the high-side pressures of the system", "Hydrogen and helium, which reduce the condenser capacity of the equipment", "Argon and neon, which interfere with refrigerant flow in the piping"], explanation: "Air and moisture are the most common non-condensable gases. Air raises high-side pressures and moisture forms acids that damage the system." },
  { id:"epa608_438", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el GWP del refrigerante R-134a utilizado comúnmente en refrigeración comercial?", opciones:["GWP de 675 veces el potencial del CO₂","GWP de 1430 veces el potencial del CO₂","GWP de 2088 veces el potencial del CO₂","GWP de 3922 veces el potencial del CO₂"], respuesta_correcta:1, explicacion:"El R-134a tiene un GWP de 1430, lo cual es alto comparado con alternativas nuevas como R-1234yf (GWP<1), por eso está en fase de reducción." , question: "What is the GWP of the refrigerant R-134a commonly used in commercial refrigeration?", options: ["GWP of 675 times the potential of CO2", "GWP of 1,430 times the potential of CO2", "GWP of 2,088 times the potential of CO2", "GWP of 3,922 times the potential of CO2"], explanation: "R-134a has a GWP of 1,430, which is high compared to newer alternatives like R-1234yf (GWP less than 1), which is why it is being phased down." },
  { id:"epa608_439", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué se debe cambiar el aceite lubricante al hacer un retrofit de R-22 a R-410A?", opciones:["Porque el R-410A opera a presiones más bajas que necesitan aceite más fino","Porque el R-22 usa aceite mineral y el R-410A requiere aceite POE compatible","Porque el aceite viejo tiene exceso de refrigerante disuelto no compatible","Porque el DOT requiere cambio de aceite en cada conversión de refrigerante"], respuesta_correcta:1, explicacion:"El R-22 usa aceite mineral, pero el R-410A requiere aceite POE (polioléster). Los aceites minerales no son miscibles con refrigerantes HFC como R-410A." , question: "Why must the lubricating oil be changed when performing a retrofit from R-22 to R-410A?", options: ["Because R-410A operates at lower pressures that require thinner oil", "Because R-22 uses mineral oil and R-410A requires compatible POE oil", "Because the old oil has excess dissolved refrigerant that is not compatible", "Because the DOT requires an oil change with every refrigerant conversion"], explanation: "R-22 uses mineral oil, but R-410A requires POE (polyol ester) oil. Mineral oils are not miscible with HFC refrigerants like R-410A." },
  { id:"epa608_440", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué información debe actualizarse en la etiqueta del sistema después de completar un retrofit de refrigerante?", opciones:["Solo la fecha del servicio y el nombre del técnico certificado","El tipo de refrigerante nuevo y el tipo de aceite lubricante usado","Solo el número de certificación EPA del técnico que realizó el trabajo","La presión de operación máxima y el voltaje del equipo únicamente"], respuesta_correcta:1, explicacion:"Después de un retrofit, la etiqueta debe actualizarse para indicar el nuevo tipo de refrigerante y el aceite lubricante utilizado para futuros servicios." , question: "What information must be updated on the system label after completing a refrigerant retrofit?", options: ["Only the service date and the name of the certified technician", "The new refrigerant type and the type of lubricating oil used", "Only the EPA certification number of the technician who performed the work", "The maximum operating pressure and the equipment voltage only"], explanation: "After a retrofit, the label must be updated to indicate the new refrigerant type and the lubricating oil used for future service." },
  { id:"epa608_441", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el ODP (potencial de destrucción de ozono) de los refrigerantes HFC como R-410A y R-134a?", opciones:["ODP de 0.05, muy bajo pero no cero para todos los HFC","ODP de 0, los HFC no contienen cloro ni destruyen ozono","ODP de 0.02, mínimo pero medible en concentraciones altas","ODP de 0.5, moderado comparado con los CFCs anteriores"], respuesta_correcta:1, explicacion:"Los refrigerantes HFC tienen ODP de cero porque no contienen cloro ni bromo. Su problema es el alto GWP (calentamiento global), no la destrucción de ozono." , question: "What is the ODP (Ozone Depletion Potential) of HFC refrigerants such as R-410A and R-134a?", options: ["ODP of 0.05, very low but not zero for all HFCs", "ODP of 0, HFCs do not contain chlorine and do not destroy ozone", "ODP of 0.02, minimal but measurable at high concentrations", "ODP of 0.5, moderate compared to the earlier CFCs"], explanation: "HFC refrigerants have an ODP of zero because they contain no chlorine or bromine. Their concern is high GWP (global warming), not ozone destruction." },
  { id:"epa608_442", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué método de detección de fugas utiliza ondas de sonido para localizar fugas en sistemas presurizados?", opciones:["Detector electrónico de refrigerante de corona caliente","Detector ultrasónico que capta sonido de alta frecuencia","Lámpara ultravioleta con tinte fluorescente inyectado","Detector de ionización de llama de haluro de cobre"], respuesta_correcta:1, explicacion:"Los detectores ultrasónicos captan el sonido de alta frecuencia producido cuando el gas escapa por una fuga bajo presión, sin necesidad de refrigerante específico." , question: "What leak detection method uses sound waves to locate leaks in pressurized systems?", options: ["Heated-diode electronic refrigerant detector", "Ultrasonic detector that picks up high-frequency sound", "Ultraviolet lamp with injected fluorescent dye", "Copper halide flame ionization detector"], explanation: "Ultrasonic detectors pick up the high-frequency sound produced when gas escapes through a leak under pressure, without requiring a specific refrigerant." },
  { id:"epa608_443", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué sustancias químicas de los refrigerantes CFC destruyen la capa de ozono estratosférico?", opciones:["Los átomos de flúor liberados por la radiación ultravioleta","Los átomos de cloro liberados por la radiación ultravioleta","Los átomos de hidrógeno liberados por la descomposición térmica","Los átomos de carbono liberados por la oxidación atmosférica"], respuesta_correcta:1, explicacion:"Los átomos de cloro de los CFCs son liberados por la radiación UV en la estratósfera y actúan como catalizadores destruyendo miles de moléculas de ozono." , question: "What chemical elements from CFC refrigerants destroy the stratospheric ozone layer?", options: ["Fluorine atoms released by ultraviolet radiation", "Chlorine atoms released by ultraviolet radiation", "Hydrogen atoms released by thermal decomposition", "Carbon atoms released by atmospheric oxidation"], explanation: "Chlorine atoms from CFCs are released by UV radiation in the stratosphere and act as catalysts, destroying thousands of ozone molecules." },
  { id:"epa608_444", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el requisito para el equipo de recuperación antes de que pueda ser utilizado comercialmente?", opciones:["Debe tener calibración anual por un laboratorio acreditado nacional","Debe estar certificado por un laboratorio aprobado por la EPA y ARI","Debe tener inspección mensual registrada por el técnico propietario","Debe pasar una prueba de presión del DOT cada dos años calendario"], respuesta_correcta:1, explicacion:"El equipo de recuperación debe estar certificado por un laboratorio aprobado por la EPA (como UL) cumpliendo los estándares ARI 740 para tasas de recuperación." , question: "What is the requirement for recovery equipment before it can be used commercially?", options: ["It must have annual calibration by an accredited national laboratory", "It must be certified by an EPA-approved and ARI laboratory", "It must have a monthly inspection logged by the owning technician", "It must pass a DOT pressure test every two calendar years"], explanation: "Recovery equipment must be certified by an EPA-approved laboratory (such as UL) meeting ARI 740 standards for recovery rates." },
  { id:"epa608_445", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué efecto tiene la capa de ozono en la protección de la Tierra?", opciones:["Absorbe la radiación infrarroja evitando el sobrecalentamiento global","Filtra la radiación ultravioleta dañina protegiendo la vida terrestre","Refleja los rayos gamma solares que causan mutaciones celulares","Bloquea los vientos solares que erosionarían la atmósfera gradualmente"], respuesta_correcta:1, explicacion:"La capa de ozono en la estratósfera filtra la radiación ultravioleta UV-B y UV-C del sol, protegiendo a los seres vivos del daño genético y cáncer de piel." , question: "What effect does the ozone layer have in protecting the Earth?", options: ["It absorbs infrared radiation, preventing global overheating", "It filters harmful ultraviolet radiation, protecting life on Earth", "It reflects solar gamma rays that cause cellular mutations", "It blocks solar winds that would gradually erode the atmosphere"], explanation: "The ozone layer in the stratosphere filters UV-B and UV-C ultraviolet radiation from the sun, protecting living organisms from genetic damage and skin cancer." },
  { id:"epa608_446", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cómo se deben desechar los cilindros desechables de refrigerante una vez vacíos?", opciones:["Rellenarlos con refrigerante reciclado para reutilización futura","Perforarlos para liberar presión residual y reciclar como chatarra metálica","Devolverlos al fabricante original para su recarga y redistribución","Almacenarlos indefinidamente en un área segura hasta disposición final"], respuesta_correcta:1, explicacion:"Los cilindros desechables vacíos deben ser inutilizados (perforados o cortada la válvula) para evitar rellenado ilegal, y luego reciclados como chatarra metálica." , question: "How should disposable refrigerant cylinders be disposed of once empty?", options: ["Refill them with recycled refrigerant for future reuse", "Puncture them to release residual pressure and recycle as scrap metal", "Return them to the original manufacturer for refilling and redistribution", "Store them indefinitely in a secure area until final disposal"], explanation: "Empty disposable cylinders must be rendered unusable (punctured or valve cut off) to prevent illegal refilling, then recycled as scrap metal." },
  { id:"epa608_447", categoria:"EPA608_UNIVERSAL", pregunta:"¿Es legal rellenar un cilindro desechable de refrigerante según las regulaciones del DOT?", opciones:["Sí, si se verifica que el cilindro está en buenas condiciones visibles","Sí, si un técnico certificado EPA supervisa el proceso de rellenado","No, es ilegal rellenar cilindros desechables según regulaciones del DOT","No, excepto si el cilindro tiene menos de cinco años de fabricado"], respuesta_correcta:2, explicacion:"Rellenar cilindros desechables es ilegal según el DOT. Estos cilindros no están diseñados para recarga y podrían fallar catastróficamente bajo presión." , question: "Is it legal to refill a disposable refrigerant cylinder according to DOT regulations?", options: ["Yes, if it is verified that the cylinder is in good visible condition", "Yes, if an EPA-certified technician supervises the refilling process", "No, it is illegal to refill disposable cylinders under DOT regulations", "No, except if the cylinder is less than five years old from manufacture"], explanation: "Refilling disposable cylinders is illegal under DOT regulations. These cylinders are not designed for recharging and could fail catastrophically under pressure." },
  { id:"epa608_448", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué relación existe entre la presión y la temperatura en un refrigerante saturado?", opciones:["Son inversamente proporcionales: mayor presión significa menor temperatura","Son directamente proporcionales: mayor presión significa mayor temperatura","No hay relación directa: depende solo del volumen del contenedor usado","La relación varía aleatoriamente según la composición del aceite presente"], respuesta_correcta:1, explicacion:"En un refrigerante saturado (líquido y vapor presentes), la presión y temperatura son directamente proporcionales. Esta relación es la base de las tablas P-T." , question: "What is the relationship between pressure and temperature in a saturated refrigerant?", options: ["They are inversely proportional: higher pressure means lower temperature", "They are directly proportional: higher pressure means higher temperature", "There is no direct relationship: it depends only on the container volume used", "The relationship varies randomly depending on the oil composition present"], explanation: "In a saturated refrigerant (both liquid and vapor present), pressure and temperature are directly proportional. This relationship is the basis of P-T charts." },
  { id:"epa608_449", categoria:"EPA608_UNIVERSAL", pregunta:"¿Para qué se utiliza un manifold de manómetros en el servicio de sistemas de refrigeración?", opciones:["Solo para medir la temperatura del refrigerante en ambos lados del sistema","Para medir presiones y facilitar la carga, recuperación y evacuación","Solo para verificar el nivel de aceite lubricante dentro del compresor","Para medir el flujo volumétrico de refrigerante a través del evaporador"], respuesta_correcta:1, explicacion:"El manifold de manómetros permite medir presiones de alta y baja, además de facilitar procedimientos de carga, recuperación, evacuación y diagnóstico." , question: "What is a gauge manifold used for in refrigeration system service?", options: ["Only for measuring the refrigerant temperature on both sides of the system", "For measuring pressures and facilitating charging, recovery, and evacuation", "Only for checking the lubricating oil level inside the compressor", "For measuring the volumetric refrigerant flow through the evaporator"], explanation: "The gauge manifold allows measurement of high-side and low-side pressures, and facilitates charging, recovery, evacuation, and diagnostic procedures." },
  { id:"epa608_450", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué causa el efecto invernadero y cómo contribuyen los refrigerantes a este problema?", opciones:["Los refrigerantes destruyen oxígeno, reduciendo la capacidad de enfriamiento global","Los refrigerantes son gases de efecto invernadero que atrapan calor infrarrojo","Los refrigerantes bloquean la luz solar causando un calentamiento por acumulación","Los refrigerantes reaccionan con el nitrógeno creando óxido nitroso atmosférico"], respuesta_correcta:1, explicacion:"Los refrigerantes con alto GWP son potentes gases de efecto invernadero que atrapan radiación infrarroja en la atmósfera, contribuyendo al calentamiento global." , question: "What causes the greenhouse effect and how do refrigerants contribute to this problem?", options: ["Refrigerants destroy oxygen, reducing the global cooling capacity", "Refrigerants are greenhouse gases that trap infrared heat", "Refrigerants block sunlight causing warming by accumulation", "Refrigerants react with nitrogen creating atmospheric nitrous oxide"], explanation: "Refrigerants with high GWP are potent greenhouse gases that trap infrared radiation in the atmosphere, contributing to global warming." },
  { id:"epa608_451", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuántas secciones tiene el examen EPA 608 para obtener la certificación Universal?", opciones:["Tiene 2 secciones: general y específica del tipo de sistema","Tiene 3 secciones: Tipo I, Tipo II y Tipo III solamente","Tiene 4 secciones: Core, Tipo I, Tipo II y Tipo III juntas","Tiene 5 secciones: Core, los 3 tipos y una sección práctica"], respuesta_correcta:2, explicacion:"La certificación Universal requiere aprobar las 4 secciones: Core (conocimiento general), Tipo I (aparatos pequeños), Tipo II (alta presión) y Tipo III (baja presión)." , question: "How many sections does the EPA 608 exam have to obtain Universal certification?", options: ["It has 2 sections: general and system-type specific", "It has 3 sections: Type I, Type II, and Type III only", "It has 4 sections: Core, Type I, Type II, and Type III together", "It has 5 sections: Core, the 3 types, and a hands-on section"], explanation: "Universal certification requires passing all 4 sections: Core (general knowledge), Type I (small appliances), Type II (high pressure), and Type III (low pressure)." },
  { id:"epa608_452", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el GWP del refrigerante R-32 que se propone como alternativa al R-410A?", opciones:["GWP de 466 veces el del dióxido de carbono","GWP de 675 veces el del dióxido de carbono","GWP de 750 veces el del dióxido de carbono","GWP de 1430 veces el del dióxido de carbono"], respuesta_correcta:1, explicacion:"El R-32 tiene un GWP de 675, significativamente menor que el R-410A (2088), y es uno de los componentes del propio R-410A (50% R-32 + 50% R-125)." , question: "What is the GWP of the refrigerant R-32, which is proposed as an alternative to R-410A?", options: ["GWP of 466 times that of carbon dioxide", "GWP of 675 times that of carbon dioxide", "GWP of 750 times that of carbon dioxide", "GWP of 1,430 times that of carbon dioxide"], explanation: "R-32 has a GWP of 675, significantly lower than R-410A (2,088), and is one of the components of R-410A itself (50% R-32 + 50% R-125)." },
  { id:"epa608_453", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué precaución se debe tomar al transportar cilindros de refrigerante en un vehículo?", opciones:["Transportarlos acostados y asegurados en la cajuela cerrada del vehículo","Mantenerlos en posición vertical, asegurados y en área bien ventilada","Transportarlos solo en remolque abierto sin techo para ventilación adecuada","Colocarlos directamente al sol para mantener la presión interna estable"], respuesta_correcta:1, explicacion:"Los cilindros deben transportarse en posición vertical, bien asegurados para evitar caídas, y en un área ventilada para prevenir acumulación de gas en caso de fuga." , question: "What precaution should be taken when transporting refrigerant cylinders in a vehicle?", options: ["Transport them lying down and secured in the closed trunk of the vehicle", "Keep them in an upright position, secured, and in a well-ventilated area", "Transport them only in an open roofless trailer for adequate ventilation", "Place them directly in the sun to maintain stable internal pressure"], explanation: "Cylinders must be transported in an upright position, properly secured to prevent falls, and in a ventilated area to prevent gas buildup in case of a leak." },
  { id:"epa608_454", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué nivel de vacío se requiere generalmente para evacuar un sistema con más de 200 lbs de refrigerante (alta presión)?", opciones:["0 psig para sistemas de alta presión con más de 200 libras","10 pulgadas de Hg vacío para sistemas con más de 200 libras","15 pulgadas de Hg vacío para sistemas con más de 200 libras","25 pulgadas de Hg vacío para sistemas con más de 200 libras"], respuesta_correcta:0, explicacion:"Para sistemas de alta presión con más de 200 lbs de refrigerante, el nivel de vacío requerido para recuperación es 0 psig (presión atmosférica)." , question: "What vacuum level is generally required to evacuate a high-pressure system with more than 200 lbs of refrigerant?", options: ["0 psig for high-pressure systems with more than 200 pounds", "10 inches of Hg vacuum for systems with more than 200 pounds", "15 inches of Hg vacuum for systems with more than 200 pounds", "25 inches of Hg vacuum for systems with more than 200 pounds"], explanation: "For high-pressure systems with more than 200 lbs of refrigerant, the required recovery vacuum level is 0 psig (atmospheric pressure)." },
  { id:"epa608_455", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué documento debe mantener un técnico como registro al recuperar refrigerante de un sistema?", opciones:["Solo el recibo de compra del cilindro de recuperación utilizado","Registro con tipo y cantidad de refrigerante recuperado y disposición","Solo una copia de su certificación EPA 608 vigente en archivo","El manual del fabricante del equipo de recuperación actualizado"], respuesta_correcta:1, explicacion:"Los técnicos deben mantener registros del tipo, cantidad de refrigerante recuperado y su disposición final (reciclado, reclamado o destruido) según la Sección 608." , question: "What document must a technician maintain as a record when recovering refrigerant from a system?", options: ["Only the purchase receipt for the recovery cylinder used", "A record with the type and quantity of refrigerant recovered and its disposition", "Only a copy of their current EPA 608 certification on file", "The updated manufacturer's manual for the recovery equipment"], explanation: "Technicians must maintain records of the type, quantity of refrigerant recovered, and its final disposition (recycled, reclaimed, or destroyed) per Section 608." },
  { id:"epa608_456", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué clasificación de seguridad ASHRAE 34 tiene el R-410A?", opciones:["Clasificación A1: baja toxicidad y no inflamable","Clasificación A2L: baja toxicidad y levemente inflamable","Clasificación B1: alta toxicidad y sin inflamabilidad","Clasificación B2L: alta toxicidad y levemente inflamable"], respuesta_correcta:0, explicacion:"El R-410A tiene clasificación ASHRAE A1: baja toxicidad y no inflamable, lo que facilitó su adopción masiva como reemplazo del R-22." , question: "What ASHRAE 34 safety classification does R-410A have?", options: ["Classification A1: low toxicity and non-flammable", "Classification A2L: low toxicity and mildly flammable", "Classification B1: higher toxicity and non-flammable", "Classification B2L: higher toxicity and mildly flammable"], explanation: "R-410A has an ASHRAE A1 classification: low toxicity and non-flammable, which facilitated its widespread adoption as a replacement for R-22." },
  { id:"epa608_457", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué clasificación de seguridad ASHRAE tiene el R-454B comparado con el R-410A?", opciones:["Clasificación A1, igual que el R-410A actualmente","Clasificación A2L, levemente inflamable a diferencia del R-410A","Clasificación A3, altamente inflamable a diferencia del R-410A","Clasificación B2, toxicidad mayor y moderadamente inflamable"], respuesta_correcta:1, explicacion:"El R-454B es clasificado A2L (levemente inflamable), a diferencia del R-410A que es A1 (no inflamable), lo que requiere precauciones adicionales de instalación." , question: "What ASHRAE safety classification does R-454B have compared to R-410A?", options: ["Classification A1, the same as the current R-410A", "Classification A2L, mildly flammable unlike R-410A", "Classification A3, highly flammable unlike R-410A", "Classification B2, higher toxicity and moderately flammable"], explanation: "R-454B is classified A2L (mildly flammable), unlike R-410A which is A1 (non-flammable), requiring additional installation precautions." },
  { id:"epa608_458", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué ya no se requiere el sistema de colores ARI para identificar tipos de refrigerante en cilindros?", opciones:["Porque los fabricantes no podían mantener consistencia en los colores del cilindro","Porque hay demasiados refrigerantes nuevos y no alcanzan los colores disponibles","Porque el sistema causaba confusión y mezclas entre refrigerantes de color similar","Porque el DOT prohibió pintar cilindros por interferir con las inspecciones visuales"], respuesta_correcta:2, explicacion:"ARI eliminó el sistema de colores porque con tantos refrigerantes nuevos, colores similares causaban confusión y mezclas. Ahora se usa cuerpo gris con etiqueta." , question: "Why is the ARI color-coding system for identifying refrigerant types on cylinders no longer required?", options: ["Because manufacturers could not maintain color consistency on cylinders", "Because there are too many new refrigerants and not enough available colors", "Because the system caused confusion and cross-contamination between similarly colored refrigerants", "Because the DOT prohibited painting cylinders as it interfered with visual inspections"], explanation: "ARI eliminated the color-coding system because with so many new refrigerants, similar colors caused confusion and mixing. Now a gray body with a label is used." },
  { id:"epa608_459", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el principal riesgo de exponer la piel directamente al refrigerante líquido?", opciones:["Quemaduras químicas por la acidez del refrigerante al contacto dérmico","Quemaduras por congelamiento debido a la rápida evaporación del líquido","Reacción alérgica severa que causa inflamación generalizada en la piel","Absorción transdérmica del refrigerante que causa toxicidad sistémica grave"], respuesta_correcta:1, explicacion:"El refrigerante líquido al contacto con la piel se evapora rápidamente absorbiendo calor, lo que puede causar quemaduras por congelamiento (frostbite) severas." , question: "What is the main risk of exposing skin directly to liquid refrigerant?", options: ["Chemical burns from the acidity of the refrigerant on contact with skin", "Frostbite burns due to the rapid evaporation of the liquid", "Severe allergic reaction causing generalized skin inflammation", "Transdermal absorption of the refrigerant causing serious systemic toxicity"], explanation: "Liquid refrigerant in contact with skin evaporates rapidly absorbing heat, which can cause severe frostbite burns." },
  { id:"epa608_460", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué indica una lectura de presión más alta de lo normal en el lado de alta de un sistema?", opciones:["Posible falta de refrigerante o restricción en el dispositivo de expansión","Posible exceso de refrigerante, no condensables o condensador sucio bloqueado","Posible falla del compresor con válvulas desgastadas que no comprimen","Posible evaporador sobreenfriado causando retorno de líquido al compresor"], respuesta_correcta:1, explicacion:"Presión alta en el lado de alta puede indicar sobrecarga de refrigerante, presencia de gases no condensables (aire), o condensador sucio que impide el rechazo de calor." , question: "What does a higher-than-normal pressure reading on the high side of a system indicate?", options: ["Possible low refrigerant charge or restriction in the expansion device", "Possible refrigerant overcharge, non-condensable gases, or a dirty blocked condenser", "Possible compressor failure with worn valves that are not compressing", "Possible overcooled evaporator causing liquid return to the compressor"], explanation: "High pressure on the high side can indicate refrigerant overcharge, presence of non-condensable gases (air), or a dirty condenser impeding heat rejection." },
  { id:"epa608_461", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué método de detección de fugas es el más simple y económico para localizar fugas accesibles?", opciones:["Detector electrónico de semiconductor de óxido de metal calentado","Inyección de tinte fluorescente ultravioleta al sistema de refrigeración","Aplicación de solución de jabón (burbujas) en las áreas sospechosas","Detector ultrasónico de alta frecuencia con auriculares especializados"], respuesta_correcta:2, explicacion:"La solución de burbujas de jabón es el método más simple y económico. Las burbujas se forman visiblemente donde hay fuga de refrigerante presurizado." , question: "What leak detection method is the simplest and most economical for locating accessible leaks?", options: ["Heated metal oxide semiconductor electronic detector", "Fluorescent ultraviolet dye injection into the refrigeration system", "Application of soap bubble solution to the suspected areas", "High-frequency ultrasonic detector with specialized earphones"], explanation: "Soap bubble solution is the simplest and most economical method. Bubbles form visibly where there is a leak of pressurized refrigerant." },
  { id:"epa608_462", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la responsabilidad ética principal de un técnico certificado EPA 608?", opciones:["Maximizar las ganancias del negocio usando refrigerantes más económicos disponibles","Minimizar las emisiones de refrigerante y proteger el medio ambiente activamente","Completar los trabajos lo más rápido posible para atender más clientes diarios","Usar siempre el refrigerante más nuevo aunque el sistema no sea compatible"], respuesta_correcta:1, explicacion:"La responsabilidad ética principal es minimizar emisiones de refrigerante, realizar recuperación adecuada y proteger la capa de ozono y el medio ambiente." , question: "What is the primary ethical responsibility of an EPA 608 certified technician?", options: ["To maximize business profits by using the most economical refrigerants available", "To minimize refrigerant emissions and actively protect the environment", "To complete jobs as quickly as possible to serve more clients daily", "To always use the newest refrigerant even if the system is not compatible"], explanation: "The primary ethical responsibility is to minimize refrigerant emissions, perform proper recovery, and protect the ozone layer and the environment." },
  { id:"epa608_463", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué sucede si se usa aceite mineral en un sistema diseñado para R-410A con aceite POE?", opciones:["El aceite mineral mejora la lubricación porque es más viscoso y estable","El aceite mineral no se mezcla con R-410A causando retorno pobre de aceite","El aceite mineral es compatible pero reduce la vida útil del filtro secador","El aceite mineral funciona igual pero requiere más cantidad que el aceite POE"], respuesta_correcta:1, explicacion:"El aceite mineral no es miscible con R-410A (HFC), causando pobre retorno de aceite al compresor, lubricación inadecuada y eventual falla del compresor." , question: "What happens if mineral oil is used in a system designed for R-410A with POE oil?", options: ["Mineral oil improves lubrication because it is more viscous and stable", "Mineral oil does not mix with R-410A, causing poor oil return", "Mineral oil is compatible but reduces the filter-drier service life", "Mineral oil works the same but requires a larger quantity than POE oil"], explanation: "Mineral oil is not miscible with R-410A (HFC), causing poor oil return to the compressor, inadequate lubrication, and eventual compressor failure." },
  { id:"epa608_464", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué nivel de vacío requerido para la recuperación en sistemas de alta presión con menos de 200 lbs?", opciones:["0 pulgadas de Hg vacío (presión atmosférica) para equipos menores a 200 lbs","10 pulgadas de Hg vacío para equipos de alta presión menores a 200 libras","15 pulgadas de Hg vacío para todos los equipos de alta presión sin excepción","25 pulgadas de Hg vacío para sistemas de alta presión menores a 200 libras"], respuesta_correcta:1, explicacion:"Para sistemas de alta presión con menos de 200 lbs de refrigerante, el nivel de vacío requerido para recuperación es 10 pulgadas de Hg." , question: "What vacuum level is required for recovery in high-pressure systems with less than 200 lbs?", options: ["0 inches of Hg vacuum (atmospheric pressure) for equipment under 200 lbs", "10 inches of Hg vacuum for high-pressure equipment under 200 pounds", "15 inches of Hg vacuum for all high-pressure equipment without exception", "25 inches of Hg vacuum for high-pressure systems under 200 pounds"], explanation: "For high-pressure systems with less than 200 lbs of refrigerant, the required recovery vacuum level is 10 inches of Hg." },
  { id:"epa608_465", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué efecto tiene la humedad dentro de un sistema de refrigeración con HFC y aceite POE?", opciones:["La humedad mejora la transferencia de calor del evaporador ligeramente","La humedad forma ácidos que corroen componentes y tapan la expansión","La humedad reduce la viscosidad del aceite mejorando el flujo del sistema","La humedad actúa como lubricante adicional protegiendo el compresor"], respuesta_correcta:1, explicacion:"La humedad en un sistema con aceite POE es especialmente problemática porque el POE es higroscópico. La humedad forma ácidos que corroen y causa congelamiento en la expansión." , question: "What effect does moisture have inside a refrigeration system with HFC refrigerant and POE oil?", options: ["Moisture slightly improves the evaporator's heat transfer", "Moisture forms acids that corrode components and plug the expansion device", "Moisture reduces oil viscosity, improving system flow", "Moisture acts as an additional lubricant protecting the compressor"], explanation: "Moisture in a system with POE oil is especially problematic because POE is hygroscopic. Moisture forms acids that corrode and causes freezing at the expansion device." },
  { id:"epa608_466", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el propósito de usar nitrógeno presurizado durante la soldadura (brazing) de tuberías de cobre?", opciones:["Para aumentar la temperatura de fusión del material de aporte utilizado","Para prevenir la formación de óxido de cobre dentro de las tuberías soldadas","Para probar fugas simultáneamente mientras se realiza la soldadura del sistema","Para enfriar rápidamente la junta soldada y evitar daño térmico al sistema"], respuesta_correcta:1, explicacion:"Se pasa un flujo bajo de nitrógeno durante la soldadura para desplazar el oxígeno y prevenir la formación de escamas de óxido de cobre dentro de la tubería." , question: "What is the purpose of using pressurized nitrogen during brazing of copper tubing?", options: ["To increase the melting temperature of the filler material being used", "To prevent the formation of copper oxide scale inside the tubing being brazed", "To simultaneously test for leaks while the brazing of the system is performed", "To rapidly cool the brazed joint and prevent thermal damage to the system"], explanation: "A low flow of nitrogen is passed during brazing to displace oxygen and prevent the formation of copper oxide scale inside the tubing." },
  { id:"epa608_467", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué debe hacer un técnico si sospecha que un compañero está ventilando refrigerante intencionalmente?", opciones:["Ignorar la situación porque no es su responsabilidad directa o legal","Reportar la violación a la EPA, pudiendo recibir recompensa hasta $10,000","Confrontar directamente al compañero y pedirle que deje de hacerlo","Documentar internamente pero no reportar para no causar conflicto laboral"], respuesta_correcta:1, explicacion:"Los técnicos pueden reportar violaciones a la EPA. El programa de recompensas ofrece hasta $10,000 por información que conduzca a sanciones exitosas." , question: "What should a technician do if they suspect a coworker is intentionally venting refrigerant?", options: ["Ignore the situation because it is not their direct or legal responsibility", "Report the violation to the EPA, potentially receiving a reward of up to $10,000", "Directly confront the coworker and ask them to stop doing it", "Document it internally but do not report to avoid workplace conflict"], explanation: "Technicians may report violations to the EPA. The reward program offers up to $10,000 for information leading to successful penalties." },
  { id:"epa608_468", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de aceite lubricante utilizan los sistemas con refrigerantes CFC como R-12?", opciones:["Aceite POE (polioléster) sintético de alta estabilidad térmica","Aceite PAG (polialquilenglicol) automotriz de alta viscosidad","Aceite mineral convencional compatible con los refrigerantes CFC","Aceite PVE (polivinil éter) de nueva generación sintética"], respuesta_correcta:2, explicacion:"Los refrigerantes CFC como R-12 son compatibles con aceite mineral convencional, que fue el lubricante estándar durante décadas en refrigeración." , question: "What type of lubricating oil do systems with CFC refrigerants such as R-12 use?", options: ["Synthetic high-thermal-stability POE (polyol ester) oil", "High-viscosity automotive PAG (polyalkylene glycol) oil", "Conventional mineral oil compatible with CFC refrigerants", "New-generation synthetic PVE (polyvinyl ether) oil"], explanation: "CFC refrigerants such as R-12 are compatible with conventional mineral oil, which was the standard lubricant in refrigeration for decades." },
  { id:"epa608_469", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué significa que el R-410A es una mezcla 'casi azeotrópica'?", opciones:["Que se comporta como un refrigerante puro con deslizamiento de temperatura mínimo","Que sus componentes se separan fácilmente requiriendo carga solo como vapor","Que debe cargarse siempre como gas porque los componentes tienen densidades distintas","Que pierde sus propiedades si la temperatura ambiente supera los 100 grados F"], respuesta_correcta:0, explicacion:"El R-410A es casi azeotrópico (50% R-32 + 50% R-125) con deslizamiento de temperatura mínimo (<0.3°F), comportándose casi como un refrigerante puro." , question: "What does it mean that R-410A is a 'near-azeotropic' mixture?", options: ["It behaves like a pure refrigerant with minimal temperature glide", "Its components separate easily, requiring charging as vapor only", "It must always be charged as gas because the components have different densities", "It loses its properties if the ambient temperature exceeds 100 degrees F"], explanation: "R-410A is near-azeotropic (50% R-32 + 50% R-125) with minimal temperature glide (less than 0.3 degrees F), behaving almost like a pure refrigerant." },
  { id:"epa608_470", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué es crítico no sobrecargar un cilindro de recuperación más allá del 80%?", opciones:["Porque el refrigerante extra causa corrosión acelerada del cilindro metálico","Porque la expansión térmica del líquido puede causar ruptura hidrostática","Porque se excede la presión máxima del regulador de la válvula interna","Porque el refrigerante pierde sus propiedades al estar muy comprimido"], respuesta_correcta:1, explicacion:"Si un cilindro se llena más del 80%, la expansión térmica del refrigerante líquido al calentarse puede generar presión hidrostática suficiente para ruptura catastrófica." , question: "Why is it critical not to overfill a recovery cylinder beyond 80%?", options: ["Because the extra refrigerant causes accelerated corrosion of the metal cylinder", "Because thermal expansion of the liquid can cause hydrostatic rupture", "Because it exceeds the maximum pressure of the internal valve regulator", "Because the refrigerant loses its properties when highly compressed"], explanation: "If a cylinder is filled beyond 80%, the thermal expansion of the liquid refrigerant as it warms can generate enough hydrostatic pressure for a catastrophic rupture." },
  { id:"epa608_471", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la mejor práctica para manejar refrigerante que ha estado en un sistema con quemadura de compresor?", opciones:["Reciclarlo en campo usando un filtro estándar y reutilizarlo inmediatamente","Enviarlo a un reclamador certificado debido a la alta contaminación con ácidos","Mezclarlo con refrigerante nuevo para diluir los contaminantes ácidos residuales","Almacenarlo en cilindros desechables normales para disposición posterior gradual"], respuesta_correcta:1, explicacion:"El refrigerante de un sistema con quemadura de compresor está contaminado con ácidos y partículas. Debe enviarse a un reclamador certificado, no reciclarse en campo." , question: "What is the best practice for handling refrigerant that was in a system with a compressor burnout?", options: ["Recycle it in the field using a standard filter and reuse it immediately", "Send it to a certified reclaimer due to the high contamination with acids", "Mix it with new refrigerant to dilute the residual acid contaminants", "Store it in normal disposable cylinders for gradual later disposal"], explanation: "Refrigerant from a system with a compressor burnout is contaminated with acids and particles. It must be sent to a certified reclaimer, not recycled in the field." },
  { id:"epa608_472", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué indica la Enmienda de Kigali al Protocolo de Montreal en relación con los HFC?", opciones:["Prohíbe todos los HFC inmediatamente a nivel mundial sin excepciones actuales","Establece una reducción gradual de HFC a nivel global por su alto impacto GWP","Permite el uso ilimitado de HFC siempre que se recuperen adecuadamente al servicio","Reemplaza completamente la AIM Act en los Estados Unidos como ley nacional"], respuesta_correcta:1, explicacion:"La Enmienda de Kigali (2016) al Protocolo de Montreal establece una reducción gradual global de HFC debido a su alto potencial de calentamiento global." , question: "What does the Kigali Amendment to the Montreal Protocol address regarding HFCs?", options: ["It bans all HFCs immediately worldwide without any current exceptions", "It establishes a gradual global phasedown of HFCs due to their high GWP impact", "It allows unlimited use of HFCs as long as they are properly recovered during service", "It completely replaces the AIM Act in the United States as national law"], explanation: "The Kigali Amendment (2016) to the Montreal Protocol establishes a gradual global phasedown of HFCs due to their high global warming potential." },
  { id:"epa608_473", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuántas micras de vacío se recomiendan como mínimo al evacuar un sistema de refrigeración antes de cargar?", opciones:["1,000 micras es el nivel aceptable para evacuación estándar del sistema","500 micras es el nivel recomendado para garantizar eliminación de humedad","250 micras es el estándar recomendado para una buena práctica de evacuación","100 micras es el único nivel aceptable para todo tipo de sistema comercial"], respuesta_correcta:1, explicacion:"Se recomienda evacuar a 500 micras o menos para asegurar la remoción adecuada de humedad. Niveles más bajos son mejores pero 500 es el estándar aceptado." , question: "How many microns of vacuum are recommended as a minimum when evacuating a refrigeration system before charging?", options: ["1,000 microns is the acceptable level for standard system evacuation", "500 microns is the recommended level to ensure moisture removal", "250 microns is the recommended standard for good evacuation practice", "100 microns is the only acceptable level for all types of commercial systems"], explanation: "Evacuation to 500 microns or less is recommended to ensure adequate moisture removal. Lower levels are better, but 500 is the accepted standard." },
  { id:"epa608_474", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué refrigerante reemplaza al R-134a en aplicaciones automotrices bajo las nuevas regulaciones?", opciones:["R-410A con menor GWP para automotriz","R-32 como alternativa en sistemas móviles","R-1234yf con GWP menor a uno para autos","R-454B de baja inflamabilidad para autos"], respuesta_correcta:2, explicacion:"El R-1234yf (HFO) con GWP menor a 1 reemplaza al R-134a (GWP 1430) en sistemas automotrices de aire acondicionado bajo las nuevas regulaciones ambientales." , question: "What refrigerant replaces R-134a in automotive applications under the new regulations?", options: ["R-410A with lower GWP for automotive use", "R-32 as an alternative in mobile systems", "R-1234yf with a GWP of less than one for automotive use", "R-454B with low flammability for automotive use"], explanation: "R-1234yf (HFO) with a GWP of less than 1 replaces R-134a (GWP 1,430) in automotive air conditioning systems under the new environmental regulations." },
  { id:"epa608_475", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de detector de fugas es más sensible para encontrar fugas extremadamente pequeñas de refrigerante?", opciones:["Detector de burbujas de jabón aplicado en conexiones","Detector ultrasónico de alta frecuencia estándar","Detector electrónico de semiconductor calentado","Detector de ionización de llama de haluro antiguo"], respuesta_correcta:2, explicacion:"Los detectores electrónicos de semiconductor calentado son los más sensibles, capaces de detectar fugas de 0.1 oz/año, más pequeñas que cualquier otro método portátil." , question: "What type of leak detector is the most sensitive for finding extremely small refrigerant leaks?", options: ["Soap bubble detector applied to connections", "Standard high-frequency ultrasonic detector", "Heated semiconductor electronic detector", "Older halide flame ionization detector"], explanation: "Heated semiconductor electronic detectors are the most sensitive, capable of detecting leaks as small as 0.1 oz/year, smaller than any other portable method." },
  { id:"epa608_476", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué ocurre con el ODP del R-22 comparado con los CFCs como el R-12?", opciones:["R-22 tiene ODP de 0, igual que todos los refrigerantes de nueva generación","R-22 tiene ODP de 0.055, mucho menor que el R-12 cuyo ODP es de 1.0","R-22 tiene ODP de 0.5, la mitad que el del R-12 cuyo ODP es de 1.0","R-22 tiene ODP de 1.0, exactamente igual que el R-12 y otros refrigerantes"], respuesta_correcta:1, explicacion:"El R-22 (HCFC) tiene ODP de 0.055, mucho menor que el R-12 (CFC) con ODP de 1.0. Esto se debe a que los HCFCs se descomponen parcialmente antes de llegar a la estratósfera." , question: "What is the ODP of R-22 compared to CFCs such as R-12?", options: ["R-22 has an ODP of 0, the same as all next-generation refrigerants", "R-22 has an ODP of 0.055, much lower than R-12 whose ODP is 1.0", "R-22 has an ODP of 0.5, half that of R-12 whose ODP is 1.0", "R-22 has an ODP of 1.0, exactly the same as R-12 and other refrigerants"], explanation: "R-22 (HCFC) has an ODP of 0.055, much lower than R-12 (CFC) with an ODP of 1.0. This is because HCFCs partially break down before reaching the stratosphere." },
  { id:"epa608_477", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la ventaja principal del equipo de recuperación self-contained sobre el system-dependent?", opciones:["Es significativamente más económico que el equipo system-dependent actualmente","Puede recuperar refrigerante aunque el compresor del sistema esté dañado","Es más pequeño y portátil que cualquier equipo system-dependent del mercado","No requiere cilindro de recuperación externo porque almacena internamente"], respuesta_correcta:1, explicacion:"El equipo self-contained tiene su propio compresor, por lo que puede recuperar refrigerante incluso cuando el compresor del sistema está averiado o inoperativo." , question: "What is the main advantage of self-contained recovery equipment over system-dependent equipment?", options: ["It is significantly more economical than system-dependent equipment currently", "It can recover refrigerant even when the system's compressor is damaged", "It is smaller and more portable than any system-dependent equipment on the market", "It does not require an external recovery cylinder because it stores internally"], explanation: "Self-contained equipment has its own compressor, so it can recover refrigerant even when the system's compressor is broken or inoperative." },
  { id:"epa608_478", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué refrigerantes se clasifican como CFC y fueron los primeros en ser eliminados?", opciones:["R-22, R-123, R-141b son todos CFC eliminados primero","R-410A, R-407C, R-134a son los CFC originales","R-12, R-11, R-502 son los CFC eliminados en 1996","R-32, R-125, R-1234yf fueron los primeros eliminados"], respuesta_correcta:2, explicacion:"R-12, R-11 y R-502 son refrigerantes CFC (clorofluorocarbonos) que fueron eliminados completamente en 1996 debido a su alto potencial de destrucción de ozono." , question: "What refrigerants are classified as CFCs and were the first to be phased out?", options: ["R-22, R-123, R-141b are all CFCs that were phased out first", "R-410A, R-407C, R-134a are the original CFCs", "R-12, R-11, R-502 are the CFCs eliminated in 1996", "R-32, R-125, R-1234yf were the first to be eliminated"], explanation: "R-12, R-11, and R-502 are CFC (chlorofluorocarbon) refrigerants that were completely eliminated in 1996 due to their high ozone depletion potential." },
  { id:"epa608_479", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué presión se usa típicamente para realizar una prueba de fugas con nitrógeno en un sistema de AC residencial?", opciones:["La presión de trabajo normal del lado de baja del sistema únicamente","La presión de trabajo del lado de alta sin exceder la presión máxima del sistema","El doble de la presión de diseño máximo del sistema según la placa del equipo","La mitad de la presión de prueba hidrostática indicada por el fabricante"], respuesta_correcta:1, explicacion:"Se presuriza con nitrógeno a la presión de trabajo del lado de alta del sistema sin exceder la presión de prueba máxima indicada por el fabricante." , question: "What pressure is typically used for performing a nitrogen leak test on a residential AC system?", options: ["The normal working pressure of the low side of the system only", "The high-side working pressure without exceeding the maximum system pressure", "Twice the maximum design pressure of the system per the equipment nameplate", "Half the hydrostatic test pressure indicated by the manufacturer"], explanation: "The system is pressurized with nitrogen to the high-side working pressure without exceeding the maximum test pressure indicated by the manufacturer." },
  { id:"epa608_480", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué significa 'glide' o deslizamiento de temperatura en mezclas zeotrópicas de refrigerante?", opciones:["La diferencia entre temperatura de entrada y salida del aire en el evaporador","La diferencia de temperatura entre el punto de burbuja y el punto de rocío","La variación de temperatura del compresor entre arranque y estado estable","La caída de temperatura del refrigerante al pasar por el dispositivo de expansión"], respuesta_correcta:1, explicacion:"El deslizamiento de temperatura es la diferencia entre la temperatura de burbuja (inicio de evaporación) y la de rocío (fin de evaporación) en mezclas zeotrópicas." , question: "What does 'glide' or temperature glide mean in zeotropic refrigerant blends?", options: ["The difference between the air inlet and outlet temperature at the evaporator", "The temperature difference between the bubble point and the dew point", "The compressor temperature variation between startup and steady state", "The refrigerant temperature drop when passing through the expansion device"], explanation: "Temperature glide is the difference between the bubble point temperature (start of evaporation) and the dew point temperature (end of evaporation) in zeotropic blends." },
  { id:"epa608_481", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué debe hacer un técnico si no puede identificar el tipo de refrigerante en un sistema sin etiqueta?", opciones:["Asumir que es R-22 si el sistema es antiguo y cargar directamente con R-22","Usar un identificador de refrigerante antes de recuperar o cargar el sistema","Recuperar directamente al cilindro más cercano disponible sin identificar","Ventilarlo al ambiente ya que sin identificación no tiene valor de reciclaje"], respuesta_correcta:1, explicacion:"Se debe usar un identificador de refrigerante para determinar el tipo antes de cualquier servicio. Nunca asumir el tipo ni mezclar refrigerantes desconocidos." , question: "What should a technician do if they cannot identify the type of refrigerant in an unlabeled system?", options: ["Assume it is R-22 if the system is old and charge directly with R-22", "Use a refrigerant identifier before recovering or charging the system", "Recover directly into the nearest available cylinder without identifying", "Vent it to the atmosphere since without identification it has no recycling value"], explanation: "A refrigerant identifier must be used to determine the type before any service. Never assume the type or mix unknown refrigerants." },
  { id:"epa608_482", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el principal riesgo de usar oxígeno o aire comprimido para presurizar un sistema de refrigeración?", opciones:["El oxígeno diluye el refrigerante reduciendo su capacidad de enfriamiento total","El oxígeno puede causar una explosión violenta al mezclarse con aceite y presión","El oxígeno corroe las tuberías de cobre causando fugas a largo plazo en el sistema","El oxígeno interfiere con el detector electrónico causando lecturas incorrectas"], respuesta_correcta:1, explicacion:"El oxígeno bajo presión mezclado con aceite lubricante puede causar una explosión violenta. Por eso solo se usa nitrógeno seco para presurizar sistemas." , question: "What is the main risk of using oxygen or compressed air to pressurize a refrigeration system?", options: ["Oxygen dilutes the refrigerant, reducing its total cooling capacity", "Oxygen can cause a violent explosion when mixed with oil and pressure", "Oxygen corrodes copper tubing, causing long-term leaks in the system", "Oxygen interferes with the electronic detector, causing incorrect readings"], explanation: "Oxygen under pressure mixed with lubricating oil can cause a violent explosion. That is why only dry nitrogen is used to pressurize systems." },
  { id:"epa608_483", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué tipo de aceite PVE (polivinil éter) se usa con algunos refrigerantes HFC alternativos?", opciones:["PVE es exclusivo para sistemas CFC antiguos como reemplazo del mineral","PVE es compatible con algunos HFC y es alternativa al POE en ciertos sistemas","PVE es el aceite estándar para todos los sistemas automotrices con R-1234yf","PVE es solo para sistemas de refrigeración industrial con amoníaco (R-717)"], respuesta_correcta:1, explicacion:"El aceite PVE es compatible con algunos refrigerantes HFC y se usa como alternativa al POE. Es menos higroscópico que el POE, lo cual es una ventaja en servicio." , question: "What type of PVE (polyvinyl ether) oil is used with some alternative HFC refrigerants?", options: ["PVE is exclusive to legacy CFC systems as a mineral oil replacement", "PVE is compatible with some HFCs and is an alternative to POE in certain systems", "PVE is the standard oil for all automotive systems with R-1234yf", "PVE is only for industrial refrigeration systems with ammonia (R-717)"], explanation: "PVE oil is compatible with some HFC refrigerants and is used as an alternative to POE. It is less hygroscopic than POE, which is an advantage during service." },
  { id:"epa608_484", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el nivel de vacío requerido para la recuperación en sistemas de baja presión como R-123?", opciones:["0 psig es el nivel de vacío para sistemas de baja presión sin excepción","10 pulgadas de Hg vacío para sistemas de baja presión como el R-123","25 pulgadas de Hg vacío para sistemas de baja presión como el R-123","29 pulgadas de Hg vacío para sistemas de baja presión como el R-123"], respuesta_correcta:2, explicacion:"Para sistemas de baja presión (como los que usan R-123), el nivel de vacío requerido para recuperación es 25 pulgadas de Hg vacío." , question: "What vacuum level is required for recovery in low-pressure systems such as R-123?", options: ["0 psig is the vacuum level for low-pressure systems without exception", "10 inches of Hg vacuum for low-pressure systems such as R-123", "25 inches of Hg vacuum for low-pressure systems such as R-123", "29 inches of Hg vacuum for low-pressure systems such as R-123"], explanation: "For low-pressure systems (such as those using R-123), the required recovery vacuum level is 25 inches of Hg." },
  { id:"epa608_485", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué precaución especial se debe tener al manejar refrigerantes clasificados A2L?", opciones:["Requieren guantes resistentes a ácidos por su alta corrosividad en piel","Requieren precauciones contra ignición por ser levemente inflamables en aire","Requieren máscaras de gas obligatorias por su alta toxicidad respiratoria","Requieren trajes especiales por ser absorbidos rápidamente por la piel"], respuesta_correcta:1, explicacion:"Los refrigerantes A2L (como R-32 y R-454B) son levemente inflamables, requiriendo precauciones contra fuentes de ignición durante manejo, carga y recuperación." , question: "What special precaution must be taken when handling refrigerants classified as A2L?", options: ["They require acid-resistant gloves due to their high corrosivity on skin", "They require precautions against ignition because they are mildly flammable in air", "They require mandatory gas masks due to their high respiratory toxicity", "They require special suits because they are rapidly absorbed through the skin"], explanation: "A2L refrigerants (such as R-32 and R-454B) are mildly flammable, requiring precautions against ignition sources during handling, charging, and recovery." },
  { id:"epa608_486", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la función del filtro secador (filter-drier) en un sistema de refrigeración?", opciones:["Regular el flujo de refrigerante al evaporador como dispositivo de expansión","Remover humedad y partículas sólidas del refrigerante en circulación activa","Separar el aceite del refrigerante antes de entrar al evaporador del sistema","Enfriar el refrigerante líquido antes del dispositivo de expansión del equipo"], respuesta_correcta:1, explicacion:"El filtro secador contiene desecante que absorbe humedad y un filtro que atrapa partículas sólidas, protegiendo el sistema de contaminación interna." , question: "What is the function of the filter-drier in a refrigeration system?", options: ["To regulate refrigerant flow to the evaporator as an expansion device", "To remove moisture and solid particles from the circulating refrigerant", "To separate oil from the refrigerant before it enters the system evaporator", "To cool the liquid refrigerant before the equipment's expansion device"], explanation: "The filter-drier contains desiccant that absorbs moisture and a filter that traps solid particles, protecting the system from internal contamination." },
  { id:"epa608_487", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué acción de la AIM Act diferencia su enfoque del Protocolo de Montreal original?", opciones:["La AIM Act prohíbe todos los refrigerantes sintéticos de forma inmediata","La AIM Act reduce gradualmente los HFC que no destruyen ozono pero calientan","La AIM Act solo aplica a refrigerantes en aplicaciones automotrices exclusivamente","La AIM Act reemplaza la certificación EPA 608 con una nueva certificación federal"], respuesta_correcta:1, explicacion:"La AIM Act se enfoca en reducir HFCs que no tienen ODP pero sí alto GWP, complementando el Protocolo de Montreal que se enfocó en sustancias que destruyen el ozono." , question: "What action of the AIM Act differentiates its approach from the original Montreal Protocol?", options: ["The AIM Act bans all synthetic refrigerants immediately", "The AIM Act gradually phases down HFCs that do not destroy ozone but do cause warming", "The AIM Act only applies to refrigerants in automotive applications exclusively", "The AIM Act replaces EPA 608 certification with a new federal certification"], explanation: "The AIM Act focuses on reducing HFCs that have no ODP but do have high GWP, complementing the Montreal Protocol which focused on ozone-depleting substances." },
  { id:"epa608_488", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la temperatura mínima a la que se debe evacuar un sistema para asegurar que la humedad se evapore?", opciones:["La temperatura ambiente debe ser al menos 0°F para evacuar correctamente","La temperatura ambiente debe ser al menos 32°F para evacuar correctamente","La temperatura ambiente debe ser al menos 50°F para evacuar correctamente","La temperatura ambiente no afecta el proceso de evacuación en lo absoluto"], respuesta_correcta:2, explicacion:"Se recomienda una temperatura ambiente mínima de 50°F (10°C) durante la evacuación para que la humedad se evapore eficientemente bajo vacío." , question: "What is the minimum ambient temperature at which a system should be evacuated to ensure that moisture evaporates?", options: ["The ambient temperature must be at least 0 degrees F to evacuate correctly", "The ambient temperature must be at least 32 degrees F to evacuate correctly", "The ambient temperature must be at least 50 degrees F to evacuate correctly", "The ambient temperature does not affect the evacuation process at all"], explanation: "A minimum ambient temperature of 50 degrees F (10 degrees C) is recommended during evacuation so that moisture evaporates efficiently under vacuum." },
  { id:"epa608_489", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué es el 'superheat' (sobrecalentamiento) y para qué sirve medirlo en un sistema de refrigeración?", opciones:["Es la temperatura del refrigerante por encima de su punto de condensación saturada","Es la temperatura del refrigerante por encima de su punto de ebullición saturada","Es la temperatura del refrigerante por debajo de su punto de congelación normal","Es la diferencia de temperatura entre el aire de retorno y el aire de suministro"], respuesta_correcta:1, explicacion:"El sobrecalentamiento es la temperatura del refrigerante por encima de su punto de ebullición saturada a esa presión. Se mide para verificar la carga correcta." , question: "What is 'superheat' and why is it measured in a refrigeration system?", options: ["It is the refrigerant temperature above its saturated condensing point", "It is the refrigerant temperature above its saturated boiling point", "It is the refrigerant temperature below its normal freezing point", "It is the temperature difference between the return air and the supply air"], explanation: "Superheat is the temperature of the refrigerant above its saturated boiling point at a given pressure. It is measured to verify the correct refrigerant charge." },
  { id:"epa608_490", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cómo debe cargarse un refrigerante zeotrópico como R-407C al sistema?", opciones:["Solo como vapor desde la parte superior del cilindro de refrigerante","Solo como líquido desde la parte inferior del cilindro para evitar fraccionamiento","Como vapor o líquido indistintamente según la preferencia del técnico","Solo como gas sobrecalentado usando un regulador de presión especial"], respuesta_correcta:1, explicacion:"Las mezclas zeotrópicas como R-407C deben cargarse como líquido para evitar fraccionamiento (separación de componentes) que ocurriría al cargar como vapor." , question: "How should a zeotropic refrigerant such as R-407C be charged into the system?", options: ["As vapor only from the top of the refrigerant cylinder", "As liquid only from the bottom of the cylinder to prevent fractionation", "As either vapor or liquid interchangeably per the technician's preference", "As superheated gas only using a special pressure regulator"], explanation: "Zeotropic blends such as R-407C must be charged as liquid to prevent fractionation (component separation) that would occur when charging as vapor." },
  { id:"epa608_491", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es la consecuencia de tener una restricción en el tubo capilar o válvula de expansión?", opciones:["Presión alta en ambos lados del sistema con sobrecalentamiento bajo del sistema","Presión baja en el lado de baja con sobrecalentamiento alto en la succión","Presión alta en el lado de baja y presión baja en el lado de alta del sistema","Presiones normales pero temperatura del compresor extremadamente baja del equipo"], respuesta_correcta:1, explicacion:"Una restricción reduce el flujo de refrigerante al evaporador, causando presión baja en succión y sobrecalentamiento alto porque poco refrigerante llega al evaporador." , question: "What is the consequence of having a restriction in the capillary tube or expansion valve?", options: ["High pressure on both sides of the system with low superheat", "Low pressure on the low side with high superheat at the suction line", "High pressure on the low side and low pressure on the high side of the system", "Normal pressures but extremely low compressor temperature on the equipment"], explanation: "A restriction reduces refrigerant flow to the evaporator, causing low suction pressure and high superheat because too little refrigerant reaches the evaporator." },
  { id:"epa608_492", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué acción se requiere si la prueba de vacío sostenido muestra pérdida de vacío después de esperar?", opciones:["Cargar el sistema normalmente ya que la pérdida mínima es siempre aceptable","Verificar y reparar fugas antes de continuar con la carga de refrigerante","Agregar más nitrógeno para compensar la pérdida de presión detectada ahora","Cambiar el vacuómetro porque seguramente está descalibrado y da lectura falsa"], respuesta_correcta:1, explicacion:"Si el vacío no se mantiene, hay una fuga o humedad residual. Se deben localizar y reparar las fugas antes de continuar con la evacuación y carga del sistema." , question: "What action is required if the standing vacuum test shows a loss of vacuum after waiting?", options: ["Charge the system normally since minimal loss is always acceptable", "Check for and repair leaks before continuing with the refrigerant charge", "Add more nitrogen to compensate for the pressure loss detected now", "Replace the vacuum gauge because it is surely out of calibration and giving a false reading"], explanation: "If the vacuum does not hold, there is a leak or residual moisture. Leaks must be located and repaired before continuing with evacuation and charging the system." },
  { id:"epa608_493", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué refrigerante natural tiene GWP de 1 y se usa en sistemas comerciales de CO₂ transcrítico?", opciones:["R-717 (amoníaco) con GWP de uno y uso comercial","R-290 (propano) con GWP de tres y uso comercial","R-744 (dióxido de carbono) con GWP de uno exactamente","R-600a (isobutano) con GWP de tres y uso comercial"], respuesta_correcta:2, explicacion:"El R-744 (CO₂) tiene un GWP de 1 (es la referencia) y ODP de 0. Se usa en sistemas transcríticos comerciales como alternativa de bajo impacto ambiental." , question: "What natural refrigerant has a GWP of 1 and is used in commercial transcritical CO2 systems?", options: ["R-717 (ammonia) with a GWP of one and commercial use", "R-290 (propane) with a GWP of three and commercial use", "R-744 (carbon dioxide) with a GWP of exactly one", "R-600a (isobutane) with a GWP of three and commercial use"], explanation: "R-744 (CO2) has a GWP of 1 (it is the reference) and an ODP of 0. It is used in commercial transcritical systems as a low environmental impact alternative." },
  { id:"epa608_494", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué regulación prohíbe específicamente la ventilación intencional de refrigerantes a la atmósfera?", opciones:["La Sección 602 del Clean Air Act sobre sustancias controladas","La Sección 608 del Clean Air Act sobre manejo de refrigerantes","La Sección 612 del Clean Air Act sobre sustitutos aceptables","La Sección 615 del Clean Air Act sobre estándares de emisión"], respuesta_correcta:1, explicacion:"La Sección 608 del Clean Air Act prohíbe la ventilación intencional de refrigerantes y establece los requisitos de certificación, recuperación y manejo." , question: "What regulation specifically prohibits the intentional venting of refrigerants to the atmosphere?", options: ["Section 602 of the Clean Air Act on controlled substances", "Section 608 of the Clean Air Act on refrigerant management", "Section 612 of the Clean Air Act on acceptable substitutes", "Section 615 of the Clean Air Act on emission standards"], explanation: "Section 608 of the Clean Air Act prohibits the intentional venting of refrigerants and establishes certification, recovery, and management requirements." },
  { id:"epa608_495", categoria:"EPA608_UNIVERSAL", pregunta:"¿Por qué es importante el 'subcooling' (subenfriamiento) en un sistema de refrigeración correctamente cargado?", opciones:["Garantiza que solo líquido llegue al compresor para proteger sus válvulas internas","Garantiza que solo vapor llegue al dispositivo de expansión mejorando eficiencia","Garantiza que solo líquido llegue al dispositivo de expansión para máxima eficiencia","Garantiza que solo vapor llegue al evaporador para mejorar la transferencia total"], respuesta_correcta:2, explicacion:"El subenfriamiento asegura que el refrigerante sea 100% líquido antes de llegar al dispositivo de expansión, maximizando la capacidad de enfriamiento del evaporador." , question: "Why is 'subcooling' important in a properly charged refrigeration system?", options: ["It ensures that only liquid reaches the compressor to protect its internal valves", "It ensures that only vapor reaches the expansion device, improving efficiency", "It ensures that only liquid reaches the expansion device for maximum efficiency", "It ensures that only vapor reaches the evaporator to improve total heat transfer"], explanation: "Subcooling ensures that the refrigerant is 100% liquid before reaching the expansion device, maximizing the cooling capacity of the evaporator." },
  { id:"epa608_496", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué procedimiento se sigue cuando se cambia de un refrigerante CFC a un HFC en un retrofit?", opciones:["Solo recuperar el CFC viejo y cargar el HFC nuevo directamente sin más cambios","Recuperar CFC, cambiar aceite a POE, reemplazar filtro, actualizar etiqueta y cargar","Solo cambiar el aceite y cargar el nuevo refrigerante HFC manteniendo todo igual","Vaciar el sistema, limpiar con R-141b, y cargar directamente el HFC sin aceite"], respuesta_correcta:1, explicacion:"Un retrofit completo incluye: recuperar el refrigerante CFC, cambiar aceite mineral a POE, reemplazar filtro secador, ajustar carga, y actualizar etiqueta del sistema." , question: "What procedure is followed when converting from a CFC to an HFC refrigerant in a retrofit?", options: ["Only recover the old CFC and charge the new HFC directly with no other changes", "Recover the CFC, change the oil to POE, replace the filter-drier, update the label, and charge", "Only change the oil and charge the new HFC refrigerant, keeping everything else the same", "Drain the system, flush with R-141b, and charge the HFC directly without oil"], explanation: "A complete retrofit includes: recovering the CFC refrigerant, changing mineral oil to POE, replacing the filter-drier, adjusting the charge, and updating the system label." },
  { id:"epa608_497", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué herramienta se debe usar para medir con precisión el nivel de vacío durante la evacuación?", opciones:["Manómetro compuesto estándar del manifold de servicio de baja presión","Vacuómetro electrónico de micras (micron gauge) de alta precisión","Termómetro digital de pinza colocado en la línea de succión del sistema","Medidor de flujo de refrigerante conectado en la línea de líquido directamente"], respuesta_correcta:1, explicacion:"Un vacuómetro electrónico de micras es necesario para medir con precisión el nivel de vacío. Los manómetros del manifold no son suficientemente precisos a niveles bajos." , question: "What tool should be used to accurately measure vacuum level during evacuation?", options: ["The standard compound gauge on the low-side service manifold", "An electronic micron vacuum gauge of high precision", "A digital clamp thermometer placed on the system suction line", "A refrigerant flow meter connected directly to the liquid line"], explanation: "An electronic micron gauge is necessary to accurately measure the vacuum level. Manifold gauges are not precise enough at low vacuum levels." },
  { id:"epa608_498", categoria:"EPA608_UNIVERSAL", pregunta:"¿Cuál es el riesgo principal de cargar refrigerante líquido directamente en la línea de succión?", opciones:["El líquido se congela en la línea de succión bloqueando completamente el flujo","El líquido puede causar golpe de líquido y dañar las válvulas del compresor","El líquido causa cavitación en la válvula de servicio de la línea de succión","El líquido diluye excesivamente el aceite del carter pero sin daño mecánico"], respuesta_correcta:1, explicacion:"Cargar líquido directamente en la succión puede causar golpe de líquido (liquid slugging) que daña válvulas, bielas y otros componentes mecánicos del compresor." , question: "What is the main risk of charging liquid refrigerant directly into the suction line?", options: ["The liquid freezes in the suction line, completely blocking flow", "The liquid can cause liquid slugging and damage the compressor valves", "The liquid causes cavitation in the suction line service valve", "The liquid excessively dilutes the crankcase oil but causes no mechanical damage"], explanation: "Charging liquid directly into the suction can cause liquid slugging, which damages valves, connecting rods, and other mechanical components of the compressor." },
  { id:"epa608_499", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué información mínima debe contener la tarjeta de certificación EPA 608 del técnico?", opciones:["Solo nombre completo y número de certificación del técnico certificado","Nombre, tipo de certificación obtenida y número de certificación único","Solo el número de certificación y la fecha de expiración de la tarjeta","Nombre, empresa empleadora actual y el tipo de refrigerante autorizado"], respuesta_correcta:1, explicacion:"La tarjeta EPA 608 debe incluir el nombre del técnico, el tipo de certificación (I, II, III o Universal) y un número de certificación único emitido por la organización de prueba." , question: "What minimum information must an EPA 608 certification card contain?", options: ["Only the full name and certification number of the certified technician", "The name, type of certification obtained, and a unique certification number", "Only the certification number and the card expiration date", "The name, current employer, and the authorized refrigerant type"], explanation: "The EPA 608 card must include the technician's name, the certification type (I, II, III, or Universal), and a unique certification number issued by the testing organization." },
  { id:"epa608_500", categoria:"EPA608_UNIVERSAL", pregunta:"¿Qué establece la regla de minimis (de minimis release) según la EPA en cuanto a fugas de refrigerante?", opciones:["Permite ventilación de hasta 5 libras de refrigerante durante el servicio normal","Permite fugas incidentales inevitables durante la conexión y desconexión de equipos","Permite liberar refrigerante si la cantidad es menor al uno por ciento de la carga","Permite ventilación controlada en cantidades pequeñas si se documenta formalmente"], respuesta_correcta:1, explicacion:"La excepción de minimis permite las pequeñas fugas incidentales inevitables durante la conexión y desconexión de mangueras y equipos de servicio, no ventilación intencional." , question: "What does the de minimis release rule according to the EPA establish regarding refrigerant leaks?", options: ["It allows venting up to 5 pounds of refrigerant during normal service", "It allows unavoidable incidental leaks during the connection and disconnection of equipment", "It allows releasing refrigerant if the amount is less than one percent of the charge", "It allows controlled venting in small quantities if formally documented"], explanation: "The de minimis exception allows the small, unavoidable incidental leaks that occur during the connection and disconnection of service hoses and equipment, not intentional venting." }
]; // fin EPA608_QUESTIONS

